# include <bits/stdc++.h>

using namespace std;

const int N = 1e3 + 5;
const long long inf = 1e18 + 7;

int n, a[N], used[N][N];
long long dp[N][N], par[N][N];
vector <int> ans, v, vec;

long long get(int l, int r){
      if(l > r) return -inf;
      if(l == r) {
            par[l][r] = l;
            return a[l];
      }
      if(1 < l && r < n){
            if((r - l) & 1) return -inf;
      }
      if(used[l][r]) return dp[l][r];

      used[l][r] = 1;

      dp[l][r] = -inf;

      get(l, r - 1);
      get(l + 1, r);

      if(l == 1 && r == n){
            if(get(l, r - 1) > a[r]){
                  dp[l][r] = get(l, r - 1);
                  par[l][r] = r;
            } else {
                  dp[l][r] = a[r];
                  par[l][r] = par[l][r - 1];
            }
            if(get(l + 1, r) > a[l]){
                  dp[l][r] = get(l + 1, r);
                  par[l][r] = l;
            } else {
                  dp[l][r] = a[l];
                  par[l][r] = par[l + 1][r];
            }
      } else if(l == 1){
            if(get(l, r - 1) > a[r] && r > l + 1){
                  dp[l][r] = get(l, r - 1);
                  par[l][r] = r;
            } else {
                  dp[l][r] = a[r];
                  par[l][r] = par[l][r - 1];
            }
      } else if(r == n){
            if(get(l + 1, r) > a[l] && l + 1 < r){
                  dp[l][r] = get(l + 1, r);
                  par[l][r] = l;
            } else {
                  dp[l][r] = a[l];
                  par[l][r] = par[l + 1][r];
            }
      }

      if((r - l) & 1) return dp[l][r];

      for(int i = l + 1; i < r; i ++){
            long long cur = get(l, i - 1) + get(i + 1, r);
            if(cur > dp[l][r]){
                  dp[l][r] = cur;
                  par[l][r] = i;
            }
      }

      return dp[l][r];
}

void f(int l, int r){
      if(l >= r) return ;
      v.push_back(par[l][r]);
      f(l, par[l][r] - 1);
      f(par[l][r] + 1, r);
}

int main(){
      cin >> n;

      for(int i = 1; i <= n; i ++){
            cin >> a[i];
            vec.push_back(i);
      }

      cout << get(1, n) << endl;

      f(1, n);

      for(int i = 0; i < v.size(); i ++){
            int pos = 0, cn = 0;
            for(int j = 0; j < vec.size(); j ++){
                  if(vec[j] == v[i]) pos = j + 1;
            }
            ans.push_back(pos);
            pos --;
            vector <int> vv;
            for(int j = 0; j < vec.size(); j ++){
                  if((pos + 1 == 1 && j == 0) || (pos + 1 == vec.size() && j == vec.size() - 1)) continue;
                  if((pos + 1 > 1 && pos + 1 < vec.size()) && (vec[j + 1] == v[i] || vec[j - 1] == v[i])) continue;
                  vv.push_back(vec[j]);
            }
            vec = vv;
      }

      cout << ans.size() << endl;

      for(int i : ans)
            cout << i << "\n";
}

