using namespace std;
const ll inf = -1e16;
vector<ll> vt;
ll n;
ll cc;
ll dp[1010][1010][2];
ll a[1010];
int check[1010];
ll func(ll lo, ll hi, ll ch) {
	if (lo > hi)return 0;
	if (lo == hi)return a[lo];
	ll &ret = dp[lo][hi][ch];
	if (ret != inf)return ret;
	ret = -1e12;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	if (lo % 2 == hi % 2) {
		ret = max(a[lo] + a[hi], ret);
		ll sum = 0;
		for (int i = lo; i <= hi; i += 2) {
			sum += a[i];
			ret = max(ret, sum + func(i+2,hi,0));
		}
	}
	return ret;
}
void func1(ll lo, ll hi, ll ch) {
	if (lo >= hi)return;
	ll ret = -1e12;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	if (lo % 2 == hi % 2) {
		ret = max(a[lo] + a[hi], ret);
		ll sum = 0;
		for (int i = lo; i <= hi; i += 2) {
			sum += a[i];
			ret = max(ret, sum + func(i + 2, hi, 0));
		}
	}
	if (ch) {
		if (ret == func(lo + 1, hi, ch)) {
			vt.push_back(1);
			cc++;
			check[lo] = 1;
			func1(lo + 1, hi, ch);
			return;
		}
		if (ret == func(lo, hi - 1, ch)) {
			check[hi] = 1;
			vt.push_back(n - ch);
			cc++;
			func1(lo, hi - 1, ch);
			return;
		}
	}
	if (lo % 2 == hi % 2) {
		int mm = 0;
		if (ret == a[lo] + a[hi]) {
			int mid = (lo + hi) / 2;
			for (int i = 1; i < lo; i++) {
				mm += check[i];
			}
			while (1) {
				if (mid == lo)break;
				vt.push_back(mid - mm);
				mid--;
			}
			for (int i = lo; i < hi; i++)
				check[i] = 1;
			return;
		}
		ll sum = 0;
		int oo = -1;
		for (int i = lo; i <= hi; i += 2) {
			sum += a[i];
			oo++;
			if (ret == sum + func(i + 2, hi, 0)) {
				for (int y = 0; y < lo; y++)
					mm += check[y];
				while (oo--) {
					vt.push_back(lo + 1 - mm);
				}
				for (int y = lo; y < i; y++) {
					check[y] = 1;
					mm += check[y];
				}
				func1(i + 2, hi, 0);
				if (i + 1 <= hi)
					vt.push_back(i + 1 - mm);
			}
		}
	}
}
