template <typename T>
vector<weight> shortest_path(vgraph<T>& g, int s) {
	int n = g.size();
	vector<weight> path(n, -1);
	if(g.isweighted()) { // dijkstra
		priority_queue<pair<weight, int>, vector<pair<weight, int>>, greater<pair<weight, int>>> q;
		path[s] = 0;
		q.push({0, s});
		while(!q.empty()) {
			weight cost = q.top().first;
			int p = q.top().second;
			q.pop();
			if(path[p] != cost) continue;
			for(auto e: g[p]) {
				if(path[e.to] == -1 || path[e.to] > cost + e.w) {
					path[e.to] = cost + e.w;
					q.push({path[e.to], e.to});
				}
			}
		}
	} else { // bfs
		queue<int> q;
		path[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int p = q.front();
			q.pop();
			for(auto e: g[p]) {
				if(path[e.to] == -1) {
					path[e.to] = path[p] + 1;
					q.push(e.to);
				}
			}
		}
	}
	return path;
}

vector<int> f(vector<bool> a, vector<int>& res) {
	int n = (int)a.size();
	bool b = false;
	REP(i, n) {
		b |= a[i];
		if(!a[i] && b) {
			if(i != n - 1 && a[i + 1]) {
				res.pb(2);
			} else if(i == n - 1) {
				res.pb(2);
			} else if(i == n - 2) {
				res.pb(3);
				res.pb(2);
				break;
			} else {
				res.pb(3);
				i++;
			}
		} else if(!a[i]) res.pb(1);
	}
	return res;
}

