void solve(Int N, vector<Int> a){
	vector<Int> dp(N+1);
	vector<int> prev(N+1);
	for(int i=0;i<N;i++){
		dp[i+1] = a[i];
		prev[i+1] = -2;
		if(i>0){
			//dp[i+1] = max(dp[i+1],dp[i]);
			if(dp[i+1]<dp[i]){
				dp[i+1] = dp[i];
				prev[i+1] = -1;
			}
		}
		for(int j=1;;j+=2){
			int t = i-j-1;
			if(t<0)break;
			Int u = dp[t+1] + a[i];
			if(u>dp[i+1]){
				dp[i+1] = u;
				prev[i+1] = t;
				// cut t+1 ... i-1
			}
		}
	}
	fout<<dp[N]<<endl;
	vector<int> ans;
	do{	
		bool end = false;
		int i = N-1;
		for(;!end and i>=0;i--){
			if(prev[i+1]==-1){
				ans.push_back(i);
			}else if(prev[i+1]==-2){
				REP(j,i){
					ans.push_back(j);
				}
				end = true;
			}else{
				break;
			}
		}
		if(end)break;
		assert(prev[i+1]!=-1 and prev[i+1]!=-2);
		while(!end){
			int t = prev[i+1];
			assert(t!=-1);
			if(t==-2){
				REP(j,i)ans.push_back(j);
				end = true;
			}
			if(end)break;
			// cut t+1 ... i-1
			int u = (t+i)/2;
			for(int j=u;j>=t+1;j--)ans.push_back(j);
			i=t;
		}
	}while(0);
	fout<<(int)ans.size()<<endl;
	REP(i,ans.size()){
		fout<<ans[i]+1<<endl;
	}
}

