    for (int i = 0;i < aa.size();i++) g[aa[i]] = 1;
    while (g.size() > 1) {
    	vector<int> h;
    	if (g[0] == 1) {
    		if (g[g.size() - 1] == 0) {
    			sol.push_back(g.size());
    			for (int j = 0;j < g.size() - 1;j++) h.push_back(g[j]);
    		}
    	    else {
    	    	bool ok = 0;
    	    	for (int j = 1;j < g.size() - 1 && ok == 0;j++) {
    	    		if (g[j - 1] == 0 && g[j] == 0 && g[j + 1] == 0) {
    	    			sol.push_back(j + 1);
    	    			for (int k = 0;k < g.size();k++) {
    	    				if (k != j - 1 && k != j + 1 && k != j) h.push_back(g[k]);
    	    				if (k == j) h.push_back(0);
    	    			}
    	    			ok = 1;
    	    		}
    	    		else if (g[j - 1] == 1 && g[j] == 0 && g[j + 1] == 1) {
    	    			sol.push_back(j + 1);
    	    			for (int k = 0;k < g.size();k++) {
    	    				if (k != j - 1 && k != j + 1 && k != j) h.push_back(g[k]);
    	    				if (k == j) h.push_back(1);
    	    			}
    	    			ok = 1;
    	    		}
    	    	}
    	    }
    	} else {
    		sol.push_back(1);
    		for (int j = 1;j < g.size();j++) h.push_back(g[j]);
    	}
        swap(g, h);
