				if (A[i] > 0)temp.pb(1);
				else temp.pb(0);
			}
			else temp.pb(0);
		}
	}

	while (temp.size() && temp[0] == 0) {
		ans.pb(1);
		temp.erase(temp.begin());
	}

	while (temp.size() >= 4) {
		if (temp[2])ans.pb(2);
		else ans.pb(3);
		temp.erase(temp.begin()+2);
		temp.erase(temp.begin()+2);
	}


	if (temp.size() == 3) {
		if (temp[2] == 1)ans.pb(2);
		else {
