const int INF=0x3f3f3f3f;
using namespace std;
const int MAXN=2005;
int f[MAXN][MAXN];
int n,a[MAXN];

inline int max(int x,int y){
  return (x>y)?x:y;
}
int root[MAXN][MAXN];

vector<int>vec;
int dp(int l,int r){
  if(~f[l][r])return f[l][r];
  //cout<<l<<' '<<r<<endl;
  if(l==r)return f[l][r]=a[r];
  int res= -INF;

  int step;
//  res=max(dp(l+1,r),dp(l,r-1));

  int s1=dp(l+1,r),s2=dp(l,r-1);
  if( s1< s2 ){
    step=l,res=s2 ;
  } else step=r,res=s1;

  for(int k=l+1;k<=r-1;++k){
    int tmp=dp(l,k-1)+dp(k+1,r);
    if(res< tmp ){
      step=k,res=tmp;
    }

  }

  root[l][r]= step;

  return f[l][r]=res;

}

void dfs(int l,int r){
  if(l>=r)return;
  int tmp=root[l][r];
  vec.push_back(tmp);
  if(root[l][r]==l||root[l][r]==r){
    if(root[l][r]==l)dfs(l+1,r);
    else dfs(l,r-1);
  }
  else{
    dfs(l,tmp-1);
    dfs(tmp+1,r);
  }
}

