int main(){
    int N;
    cin >> N;
    ll a[1010];
    for(int i = 0; i < N; i++){
        cin >> a[i];
    }

    for(int i = 0; i < N; i++){
        dp[i][i][0] = max(a[i], 0LL);
        dp[i][i][1] = max(a[i], 0LL);
        dp[i][i][2] = max(a[i], 0LL);
    }
    for(int i = 2; i < N; i+=2){
        for(int j = 0; j < N; j++){  // 範囲はjからi+j
            if(i + j >= N){
                break;
            }
            dp[j][i+j][0] = min(dp[j][i+j-2][0], dp[j][i+j-2][1] + a[i+j]);
            dp[j][i+j][0] = min(dp[j][i+j][0], dp[j+2][i+j][2]+a[j]);
            dp[j][i+j][1] = min(0LL, dp[j][i+j-2][1]+a[i+j]);      //右側がつながっているケース。
            dp[j][i+j][2] = min(0LL, dp[j+2][i+j][2]+a[j]);        //左側がつながっているケース
        }
    }

    for(int i = 0; i < N; i++){
        ll t = 0;
        for(int j = i; j < N; j+=2){
            t += a[j];
            s[i][j] = t;
        }
    }

    ll res = -LONG_LONG_MAX, res_i = -1, res_j = -1;
    for(int i = 0; i < N; i++){
        for(int j = i+2; j < N; j++){
            ll t;
            if(j-i == 2){
                t = a[i] + a[j];
            }
            else{
                t = s[i][j] - dp[i+2][j-2][0];
            }
            if(t > res){
                res = t;
                res_i = i;
                res_j = j;
            }
        }
    }

    vector<int> p;
    int remove_i = -1, remove_j = -1;
    ll mi = 0;
    int n_count = N;
    for(int i = res_i+2; i <= res_j-2; i+= 2){
        for(int j = i; j <= res_j-2; j += 2){
            if(s[i][j] < mi){
                mi = s[i][j];
                remove_i = i;
                remove_j = j;
            }
        }
    }
    if(remove_i != -1 || remove_j != -1){
        for(int i = 0; i < remove_j-remove_i+1; i++){
            p.push_back(remove_i);
            n_count -= 2;
        }
    }

    for(int i = 0; i < res_i; i++){
        p.push_back(1);
        n_count--;
    }
    for(int i = 0; i < N-res_j-1; i++){
        int size_p = (int)p.size();
        p.push_back(N-size_p);
        n_count--;
    }

    for(int i = n_count; i > 1; i-=2){
        p.push_back(2);
    }

    cout << res << endl;
    cout << p.size() << endl;
    for(auto p_e: p){
        cout << p_e << endl;
    }



    return 0;
}

