void go(vector<int> ind,int n){

    assert(ind.size()>0);
    int cur = n;
    int C = (ind[0]-1);
    vector<int> ret;

    while(C--){
        --cur;
        ret.push_back(1);
    }
    C = n- ind.back();

    while(C--){
        ret.push_back(cur);
        --cur;
    }
    for(int i=0;i<(int)ind.size()-1;++i){
        C = (ind[i+1]-ind[i])/2;
        while(C>0){
            ret.push_back(C+1);
            --C;
        }
    }

    cout<<ret.size()<<endl;
    for(int i=0;i<ret.size();++i)printf("%d\n",ret[i]);
}
