void minus_ans(const V<ll> &alist)
{
    ll ans = -(ll)pow(10LL, 18LL);
    ll ans_idx = -1LL;

    rep (idx, alist.size()) {
        ll a = alist[idx];
        if (a >= 0) return;
        if (a < ans) continue;
        ans = a;
        ans_idx = idx;
    }

    printf("%lld\n", ans);
    printf("%zu\n", alist.size()-1);
    rep (i, ans_idx) printf("1\n");
    rrep (i, alist.size() - ans_idx - 1LL) printf("%lld\n", i+2LL);

    exit(0);
}

void trim_edge(V<ll> &alist, V<ll> &anslist)
{
    for ( ; ; ) {
        if (alist[0] >= 0LL) break;
        anslist.pb(1LL);
        alist.erase(alist.begin());
    }

    for ( ; ; ) {
        ll a = alist[alist.size()-1];
        if (a >= 0) break;
        anslist.pb(alist.size());
        alist.erase(alist.end() - 1);
    }

    debug_printf("---- alist 2\n"); debug_print(alist);
    debug_printf("---- anslist\n"); debug_print(anslist);
}

void shrink_minus(V<ll> &alist, V<ll> &anslist)
{
    bool done = false;

    while (!done) {

        rep (i, alist.size()) {
            if (i == 0LL) continue;
            if (i == alist.size()-1LL) {
                done = true;
                break;
            }

            ll prev_a = alist[i-1];
            ll a = alist[i];
            ll next_a = alist[i+1];

            if (prev_a < 0LL && a < 0LL && next_a < 0LL) {
                anslist.pb(i + 1LL);
                alist.erase(alist.begin() + i + 1LL);
                alist.erase(alist.begin() + i - 1LL);
                break;
            }
        }
    }

    debug_printf("---- alist 3\n"); debug_print(alist);
    debug_printf("---- anslist\n"); debug_print(anslist);
}

ll calc_cand(const V<ll> &alist, ll skip)
{
    ll ret = 0LL;
    ll count = skip;

    rep (i, alist.size()) {
        ll a = alist[i];
        if (a >= 0) {
            ++count;
            if (count & 1LL) ret += a;
            continue;
        }

        assert(i < alist.size() - 1LL);
        ll next_a = alist[i+1LL];
        if (next_a < 0LL) i++;
        else ++count;
    }

    debug_printf("--- calc_cand = %lld\n", ret);
    return ret;
}

void make_ans(V<ll> &alist, V<ll> &anslist, ll skip)
{
    rep (count, skip) {
        anslist.pb(1LL);
        alist.erase(alist.begin());
    }

    while (alist[0] < 0LL) {
        anslist.pb(1LL);
        anslist.pb(1LL);
        alist.erase(alist.begin());
        alist.erase(alist.begin());
    }

    for ( ; alist.size() > 1; ) {
        if (alist.size() == 2) {
            anslist.pb(2LL);
            alist.erase(alist.end() - 1);
            continue;
        }
        if (alist.size() == 3) {
            debug_printf("---- alist YYY\n"); debug_print(alist);
            debug_printf("---- anslist YYY\n"); debug_print(anslist);
            if (alist[2] >= 0LL) {
                anslist.pb(2LL);
                alist[1] = alist[0] + alist[2];
                alist.erase(alist.end() - 1);
                alist.erase(alist.begin());
            }
            else {
                anslist.pb(3LL);
                anslist.pb(2LL);
                alist.erase(alist.end() - 1);
                alist.erase(alist.end() - 1);
            }
            continue;
        }

        debug_printf("---- alist XXX\n"); debug_print(alist);

        if (alist[2] >= 0LL) {
            debug_printf("yy1\n");
            anslist.pb(2LL);
            alist[1] = alist[0] + alist[2];
            alist.erase(alist.begin() + 2);
            alist.erase(alist.begin());
        }
        else {
            debug_printf("yy2\n");
            anslist.pb(3LL);
            alist.erase(alist.begin() + 3);
            alist.erase(alist.begin() + 1);
        }
    }

    debug_printf("---- alist 4\n"); debug_print(alist);
