int N, A[Maxn];
LL sum[2];
vector <int> vec, Ans;

inline void Judge ()
{
	int pos = 0;
	A[0] = INT_MIN;
	for (int i = 1; i <= N; ++i) if (A[i] > A[pos]) pos = i;
	if (A[pos] > 0) return ;
	for (int i = 1; i < pos; ++i) Ans.pb (1);
	int len = N - pos;
	for (int i = len; i >= 2; --i) Ans.pb (i);
	cout << A[pos] << endl;
	cout << Ans.size() << endl;
	for (int i = 0; i < Ans.size(); ++i) printf("%d\n", Ans[i]);
	exit(0);
}

inline void Solve ()
{
	Judge ();
	for (int i = 1; i <= N; ++i)
		sum[i & 1] += max (0, A[i]);
	int op = sum[0] > sum[1] ? 0 : 1;
	cout << sum[op] << endl;

	for (int i = 1; i <= N; ++i) if (A[i] > 0 && (i & 1) == op) vec.pb (i);

	for (int i = 1; i < vec[0]; ++i) Ans.pb (1);
	for (int i = 0; i < (int)vec.size() - 1; ++i)
	{
		int len = (vec[i + 1] - vec[i] + 2) / 2;
		for (int j = len; j >= 2; --j) Ans.pb (j);
	}
	int len = N - vec[(int)vec.size() - 1];
	for (int i = len; i >= 2; --i) Ans.pb (i);

	cout << Ans.size() << endl;
	for (int i = 0; i < Ans.size(); ++i) printf("%d\n", Ans[i]);
}

