			if (ma < a[i]) {
				ma = a[i];
				mai = i;
			}
		}
		if (ma <= 0) {
			OUT(ma)BR;
			OUT(n - 1)BR;
			std::vector<int> ans;
			int p = n - 1;
			while (mai < p) {
				ans.emplace_back(p);
				--p;
			}
			while (ans.size() < n - 1) ans.emplace_back(0);
			for (auto& x : ans) {
				OUT(x + 1)BR;
			}
			return 0;
		}
	}

	int ma1 = 0, ma2 = 0;
	{
		for (int i = 0; i < n; i += 2) {
			if (a[i] > 0) ma1 += a[i];
		}
	}
	{
		for (int i = 1; i < n; i += 2) {
			if (a[i] > 0) ma2 += a[i];
		}
	}
	int ma = ma1;
	std::vector<int> ans;
	auto query = [&](int i) {
		ans.emplace_back(i);
		if (i == 0) {
			--n;
			std::rotate(a.begin(), a.begin() + 1, a.end());
			a.resize(n);
			return;
		}
		if (i == a.size()-1) {
			--n;
			a.resize(n);
			return;
		}
		a[i - 1] += a[i + 1];
		std::rotate(a.begin() + i, a.begin() + i + 1, a.end());
		std::rotate(a.begin() + i, a.begin() + i + 1, a.end());
		n -= 2;
		a.resize(n);
	};

	if (ma1 < ma2) {
		ma = ma2;
		query(0);
	}
	while (a[0] < 0) {
		REP(_, 2) query(0);
	}
	while (n > 1) {
		if (n == 2) {
			query(1);
