    cin >> a[i];
  }
  int ar = -1;
  long long ans = -(long long) 1e18;
  vector<int> awho;
  for (int r = 0; r < 2; r++) {
    long long s = 0;
    vector<int> who;
    for (int x = r; x < n; x += 2) {
      s += max(a[x], 0);
      if (a[x] > 0) who.push_back(x);
    }
    if (s == 0) {
      s = -(long long) 1e18;
      for (int x = r; x < n; x += 2) {
        s = max(s, (long long) a[x]);
      }
      for (int x = r; x < n; x += 2) {
        if (s == a[x]) {
          who.push_back(x);
          break;
        }
      }
    }
    if (s > ans) {
      ans = s;
      ar = r;
      awho = who;
    }
  }
  cout << ans << '\n';
  vector<int> seq;
  auto Go = [&](int x) {
    seq.push_back(x);
    if (x == 0 || x == (int) a.size() - 1) {
      a.erase(a.begin() + x);
    } else {
      a[x] = a[x - 1] + a[x + 1];
      a.erase(a.begin() + x + 1);
      a.erase(a.begin() + x - 1);
    }
  };
  int L = 0, R = n - 1;
  while (awho.back() < R) {
    Go(R);
    --R;
  }
  while (awho[0] > 0) {
    Go(0);
    for (int& x : awho) --x;
  }
  while (true) {
    bool any = false;
    for (int i = 2; i < (int) a.size(); i += 2) {
      if (a[i] < 0) {
        Go(i);
        any = true;
        break;
      }
    }
    if (!any) break;
  }
  while (a.size() > 1) {
    Go(1);
  }
  cout << seq.size() << '\n';
  for (int x : seq) cout << x + 1 << '\n';
  return 0;
}

