typedef long long ll;
#define MAX 1100
int n;
ll a[MAX],dp[MAX][MAX],ph[MAX][MAX];

vector<ll> ans;
void dfs(int L,int R) {
  if( !(L < R) ) return ;
  if( R - L <= 1LL ) return;
  ll op = ph[L][R];
  assert( op != LLONG_MAX );
  if( op >= 0LL ) {
    --op;
    dfs(L,op-1);
    //cout << op-L+1 << endl;
    ans.push_back(op-L+1);
    dfs(op+1,R);
  } else {
    op *= -1LL;
    --op;
    ans.push_back(op-L+1);
    //cout << op-L+1 << endl;
    if( L == op ) ++L;
    else if( R-1 == op ) --R;
    else assert(false);
    //cout << L << " & " << R << " = "<< ph[L][R] << "," << dp[L][R] << endl;

    dfs(L,R);
  }
}

