#include <iostream>
#include <cmath>
using namespace std;
long long a[1010];
long long sum1,sum2;
long long x1,x2;
int p1,p2;
int n;
int sign,s;
int ans[101],sum;
void trans1()
{
	for(int i = 2;i <= n;i ++)
		a[i - 1] = a[i];
	n --;
}
void trans2()
{
	n --;
}
void trans3(int k)
{
	a[k - 1] += a[k + 1];
	for(int i = k + 2;i <= n;i ++)
		a[i - 2] = a[i];
	n -= 2;
}
void solution1()
{
	int p;
	if(sign) 
		p = p2; 
	else 
		p = p1;
	while(n >= 1)
	{
		if(p != 1)
		{ans[++ sum] = 1; p --; trans1(); continue;}
		if(p != n)
		{ans[++ sum] = n; trans2(); continue;}
	}
}
void solution2()
{
	while(n >= 1)
	{
		if(sign)
		{
			ans[++ sum] = 1; 
			trans1(); 
			sign = 0;
			/*if(a[1] < 0) {ans[++ sum] = 1; trans1(); sign = 0; continue;}
			if(n & 1 && a[n] < 0) {ans[++ sum] = n; trans2(); continue;}
			for(int i = 2;i < n;i += 2)
				if(a[i] < 0)
					{ans[++ sum] = i; trans3(i); continue;}
			for(int i = 3;i < n;i += 2)
				if(a[i - 1] >= 0 && a[i + 1] >= 0)
					{ans[++ sum] = i; trans3(i); continue;}*/
		}
		else
		{
			if(a[1] < 0) {ans[++ sum] = 1; trans1(); sign = 1; continue;}
			if((n & 1) ^ 1) {ans[++ sum] = n; trans2(); continue;}
			else if(a[n] < 0) {ans[++ sum] = n; trans2(); continue;}
			else ;
			for(int i = 2;i < n;i += 2)
				if(a[i - 1] >= 0 && a[i + 1] >= 0)
					{ans[++ sum] = i; trans3(i); continue;}
			for(int i = 3;i < n;i += 2)
				if(a[i] < 0)
					{ans[++ sum] = i; trans3(i); continue;}
		}
	}
}
int main()
{
	cin >> n;
	x1 = x2 = -1000000000007;
	for(int i = 1;i <= n;i ++)
	{
		cin >> a[i];
		if(i & 1)
		{
			if(a[i] > x1)
			{
				p1 = i;
				x1 = a[i];
			}
			if(a[i] > 0)
				sum1 += a[i];
		}
		else
		{
			if(a[i] > x2)
			{
				p2 = i;
				x2 = a[i];
			}
			if(a[i] > 0)
				sum2 += a[i];
		}
	}
	if(x1 <= 0 && x2 <= 0)
	{
		sign = s = x2 > x1; //sign为1时可以直接删除最左侧的
		solution1();
		if(s)
			cout << x2 << endl;
		else
			cout << x1 << endl;
	}
	else
	{
		sign = s = sum2 > sum1;
		solution2();
		if(s)
			cout << sum2 << endl;
		else
			cout << sum1 << endl;
	}
	cout << sum << endl;
	for(int i = 1;i <= sum;i ++)
		cout << ans[i] << endl;
	return 0;
}

