        for(int j = i + 2; j < n; j += 2){
            if(chmax(ans,ldp[i] + rdp[j])){
                ldx = i, rdx = j;
            }
        }
    }
    // cout << ans << endl;
    vector<int> res;
    int cnt = 0;
    int di = rdx - ldx;
    // cerr << ldx << " " << rdx << endl;
    while(ldx >= 2 and ldp[ldx] == a[ldx] + ldp[ldx-2]){
        ldx -= 2;
        cnt++;
    }
    int trdx = rdx, rcnt = 0;
    while(trdx + 2 < n and rdp[trdx] == a[trdx] + rdp[trdx+2]){
        trdx += 2;
        rcnt++;
    }
    // cerr << ldx << " " << rdx << endl;
    rrep(i, trdx + 1, n) res.emplace_back(i);
    rep(i, 0, rcnt) res.emplace_back(rdx + 1);
    rep(i, 0, ldx) res.emplace_back(0);
    rep(i, 0, cnt) res.emplace_back(1);
    rep(i, 0, (di - 2) / 2) res.emplace_back(2);
    res.emplace_back(1);
    cout << ans << endl;
    cout << res.size() << endl;
    for(auto& e: res) cout << e + 1 << endl;

    return 0;
}

