using namespace std;
using ll = int64_t;
using vecint = vector<int>;
using vecll = vector<ll>;
constexpr ll INF = 1e15;

pair<ll, vecint> solve(const vecll& a, int orig) {
  int n = a.size();
  ll sum = 0;
  vecint ans;
  bool found = false;
  ll mx = -INF;
  ll mxi = -1;
  int oldorig = orig;
  REP(i,n) {
    if (a[i] > mx) {
      mx = a[i];
      mxi = i;
    }
    if (a[i] >= 0) {
      sum += a[i];
      if (found) {
        ans.push_back(2);
        orig -= 2;
      } else {
        found = true;
      }
    } else {
      if (found) {
        ans.push_back(3);
        if (orig == 3) {
          ans.push_back(2);
        }
        orig -= 2;
      } else {
        ans.push_back(1);
        ans.push_back(1);
        orig -= 2;
      }
    }
  }
  if (mx < 0) {
    ans.clear();
    sum = mx;
    orig = oldorig;
    REP(i,mxi) {
      ans.push_back(1);
      --orig;
    }
  }
  while (orig > 1) {
    ans.push_back(orig);
    --orig;
  }
  return make_pair(sum, ans);
}

int main()
