    if (i%2 == 0) even.push_back(a[i]);
    else odd.push_back(a[i]);
  }
  auto ans_ev = solve(even, n);
  auto ans_od = solve(odd, n-1);
  if (ans_ev.first >= ans_od.first) {
    cout<<ans_ev.first<<"\n";
    cout<<ans_ev.second.size()<<"\n";
    for(auto&&e:ans_ev.second) {
      cout<<e<<"\n";
    }
  } else {
