	ios::sync_with_stdio(false);
	cin>>n;
	for (int i=1;i<=n;i++)cin>>f[i][i];
	for (int len=1;len<n;len++)
		for (int i=1;i+len<=n;i++){
			int j=i+len;
			if (i==1){
				f[i][j]=f[i+1][j];
				from[i][j]=i;
			}else
			if (i==n){
				f[i][j]=f[i][j-1];
				from[i][j]=j;
			}else{
				f[i][j]=f[i+2][j]+f[i][i];
				from[i][j]=i+1;
			}
			for (int k=i+1;k<j;k++){
				ll v=f[i][k-1]+f[k+1][j];
				if (v>f[i][j])f[i][j]=v,from[i][j]=k;
			}
			if (i==1){
				for (int k=i+1;k<j;k++){	
					ll v=f[k+1][j];
					if (v>f[i][j])f[i][j]=v,from[i][j]=k;
				}
			}
			if (j==n){
				for (int k=i+1;k<j;k++){	
					ll v=f[i][k-1];
