            maxi = i;
            maxv = a[i];
        }
    }
    if (maxv < 0) {
        cout << maxv << endl;
        cout << n - 1 << endl;
        for (int i = 0; i < n - 1 - maxi; i++) {
            cout << n - i << endl;
        }
        for (int i = 0; i < maxi; i++) {
            cout << 1 << endl;
        }
        return 0;
    }

    vector<int> b[2];
    ll sum[2] = {};
    int l[2] = {-1, -1}, r[2] = {-1, -1};
    for (int i = n - 1; i >= 0; i--) {
        if (a[i] >= 0) {
            sum[i % 2] += a[i];
            if (r[i % 2] == -1) r[i % 2] = i;
            l[i % 2] = i;
        } else {
            b[i % 2].push_back(i);
        }
    }

    int idx = (sum[0] >= sum[1] ? 0 : 1);
    cout << sum[idx] << endl;
