    for (int i = 0; i < (int)a.size() - 1 - r[idx]; i++) {
        ope.push_back(n);
        n--;
    }

    for (int i = 0; i < l[idx]; i++) {
        ope.push_back(1);
        n--;
    }

    for (int i : b[idx]) {
        if (i >= l[idx] && i <= r[idx]) {
            ope.push_back(i - l[idx] + 1);
            n -= 2;
        }
    }

