  }

  int best_l = 0, best_r = 1;
  int64_t best_sum = -(1LL << 50);

  for (int l = 0; l < n; l++) {
    int64_t sum = 0;
    for (int r = l + 1; r <= n; r += 2) {
      if (r > l + 1 and a[r - 1] <= 0) continue;
      sum += a[r - 1];

      if (sum > best_sum) {
        best_l = l;
        best_r = r;
        best_sum = sum;
      }
    }
  }

  cout << best_sum << endl;

  vector<int> seq;

  for (int i = 0; i < best_l; i++) {
    seq.push_back(1);
    a.erase(begin(a));
  }

  for (int i = 0; i < n - best_r; i++) {
    seq.push_back(a.size());
    a.pop_back();
  }

  while (a.size() > 1) {
    int idx;
    int64_t new_elem;

    for (int i = 1; i < a.size() - 1; i++) {
      if ((i % 2 == 1 and a[i - 1] > 0 and a[i + 1] > 0) or
          (i % 2 == 0 and a[i] <= 0)) {
        idx = i;
        new_elem = a[i - 1] + a[i + 1];
        break;
      }
    }
    seq.push_back(idx + 1);
    a.erase(a.begin() + (idx - 1), a.begin() + (idx + 2));
    a.insert(a.begin() + (idx - 1), new_elem);
  }

  cout << seq.size() << endl;
  for (int idx : seq) {
    cout << idx << endl;
  }

  return 0;
}

