using namespace std;
typedef long long int64;
typedef double db;
template<class T>
void read(T &res) {
    res = 0;char c = getchar();T f = 1;
    while(c < '0' || c > '9') {
	if(c == '-') f = -1;
	c = getchar();
    }
    while(c >= '0' && c <= '9') {
	res = res * 10 + c - '0';
	c = getchar();
    }
    res *= f;
}
template<class T>
void out(T x) {
    if(x < 0) {x = -x;putchar('-');}
    if(x >= 10) {
	out(x / 10);
    }
    putchar('0' + x % 10);
}
int N;
int64 a[MAXN],dp[MAXN];
int fr[MAXN];
int op[MAXN],tot;
void Solve() {
    read(N);
    for(int i = 1 ; i <= N ; ++i) read(a[i]);
    int64 ans = a[1];
    for(int i = 1 ; i <= N ; ++i) {
	dp[i] = a[i];fr[i] = 0;
	for(int j = 2 ; j <= i ; j += 2) {
	    if(dp[i - j] + a[i] > dp[i]) {
		dp[i] = dp[i - j] + a[i];
		fr[i] = i - j;
	    }
	}
	ans = max(ans,dp[i]);
    }
    out(ans);enter;
    int a = N;
    for(int i = N ; i >= 1 ; --i) {
	if(dp[i] == ans) {
	    for(int j = N ; j > i ; --j) {op[++tot] = j;--a;}
	    int t = i,c = 0;
	    while(t) {
		++c;int cnt = 0;
		for(int j = a - c ; j > fr[t] ; --j) {++cnt;op[++tot] = j;}
		a -= cnt;
		t = fr[t];
	    }
	    break;
	}
    }
    out(tot);enter;
    for(int i = 1 ; i <= tot ; ++i) {
	out(op[i]);enter;
    }
}
