    bool allneg = true;
    for (int i = 0; i < n; ++i) {
        li x;
        cin >> x;
        as[i] = x;
        allneg &= x <= 0;
        possums[i & 1] += max(x, 0LL);
    }

    if (allneg) {
        li maxpos = max_element(as.begin(), as.end()) - as.begin();
        cout << as[maxpos] << endl;
        cout << n - 1 << endl;
        for (int i = n - 1; i > maxpos; --i) {
            cout << i + 1 << endl;
        }
        for (int i = 0; i < maxpos; ++i) {
            cout << 1 << endl;
        }
        return 0;
    }

    vector<li> ops;
    vector<bool> want(n, false);
    auto omit = [&](int i) {
        ops.push_back(i);
        as.erase(as.begin() + i);
        want.erase(want.begin() + i);
    };


    li sums[2] = {};
    for (int i = 0; i < as.size(); ++i) {
        sums[i & 1] += as[i];
    }
    li mask = sums[0] < sums[1];
    for (int i = 0; i < as.size(); ++i) {
        want[i] = ((i & 1) == mask) && as[i] > 0;
    }

    while (!want.front()) {
        omit(0);
    }

    while (!want.back()) {
        omit(as.size() - 1);
    }

    while (as.size() > 1) {
        for (int i = 1; i < as.size() - 1; ++i) {
            if (want[i]) {
                continue;
            }
            if (want[i - 1] == want[i + 1]) {
                as[i - 1] += as[i + 1];
                as.erase(as.begin() + i + 1);
                want.erase(want.begin() + i + 1);
                omit(i);
                break;
            }
        }
    }

    cout << as.front() << endl;
    cout << ops.size() << endl;
    for (int i = 0; i < ops.size(); ++i) {
        cout << ops[i] + 1 << endl;
    }
    return 0;
}

