typedef long long llint;

const int MAXN = 1000;

int arr[MAXN];
llint dp[MAXN];
int nxt[MAXN];

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	int n, i, j;

	cin>>n;

	for (i = 0; i < n; ++i)
	{
		cin>>arr[i];

		dp[i] = 0;
		nxt[i] = -1;
		for (j = i - 2; j >= 0; j -= 2) if (dp[j] > dp[i])
		{
			dp[i] = dp[j];
			nxt[i] = j;
		}
		dp[i] += arr[i];
	}

	i = max_element(dp, dp + n) - dp;
	cout<<dp[i]<<'\n';

	vector<int> sol;
	while (i != n - 1)
	{
		if (i < n - 3)
		{
			sol.push_back(n - 2);
			n -= 2;
		}
		else
		{
			sol.push_back(n - 1);
			--n;
		}
	}
	while (nxt[i] != -1)
	{
		for (int k = i - nxt[i]; k >= 2; k -= 2)
		{
			sol.push_back(i - 2);
		}
		sol.push_back(i - 1);
		i = nxt[i];
	}
	while (i)
	{
		if (i > 2)
		{
			sol.push_back(1);
			i -= 2;
		}
		else
		{
			sol.push_back(0);
			--i;
		}
	}

	cout<<sol.size()<<'\n';
	for (int x: sol)
		cout<<1 + x<<'\n';
}

