const int MX = 1005;
ll n, a[MX], p[2], sr;
vi s[2], res;

void solve (vi s) {
	for (int i = n - 1; i > s.back(); i--)
		 res.pb(i);

	for (int i = int(s.size()) - 2; i >= 0; i--) {
		int m = (s[i] + s[i + 1]) / 2;
		forn (i, (s[i + 1] - s[i]) / 2)
			res.pb(m);
	}

	forn (i, s[0])
		res.pb(0);
}

