		p[0] = p[1] = a[ind];
		for (int i = n - 1; i > ind; i--) res.pb(i);
		forn (i, ind) res.pb(0);
	} else if (p[0] > p[1]) {
		solve(s[0]);
	} else {
		solve(s[1]);
	}

