ll f(int l, int r) {
  assert(l % 2 == r % 2);
  if (dp[l][r] != -INF)
    return dp[l][r];
  ll &res = dp[l][r];
  if (l == r)
    return res = a[l];
  if (a[r] > 0)
    return res = f(l, r - 2) + a[r];
  else
    return res = f(l, r - 2);
}

