  for (int i = 1; i <= N; i++)
    for (int j = i; j <= N; j += 2) {
      ll tmp = f(i, j);
      if (tmp > bst) {
        bst = tmp;
        bst_f = MP(i, j);
      }
    }
  assert(a[bst_f.S] > 0);
  VI op;
  for (int i = N; i > bst_f.S; i--)
