ll calc(deque<pii> &dq, vector<int> &step){
    ll sum = 0;
    while(dq.size() > 0){
        if(dq[0].second){
            sum += dq[0].first;
            dq.pop_front();
            break;

        }
        else{
            step.push_back(1);
        }
        dq.pop_front();
    }


    while(dq.size() > 0){
        if(dq.size() == 1){
            dq.pop_front();
            step.push_back(2);
        }
        else if(!dq[0].second && dq[1].second){
            sum += dq[1].first;
            dq.pop_front();
            dq.pop_front();
            step.push_back(2);
        }
        else if(dq.size() >= 3){
            if(!dq[0].second && !dq[1].second && !dq[2].second){
                dq.pop_front();
                dq.pop_front();
                step.push_back(3);
            }
        }
    }
    return sum;
}

