            l1 = i;
            break;
        }
    }

    for(int i=N-!(N&1);i>=1;i-=2){
        if(A[i] >= 0){
            r1 = i;
            break;
        }
    }

    std::vector<int> instr1;
    ll v1 = f(l1, r1, instr1);

    for(int i=2;i<=N;i+=2){
        if(A[i] >= 0){
            l2 = i;
            break;
        }
    }

    for(int i=N-(N&1);i>=2;i-=2){
        if(A[i] >= 0){
            r2 = i;
            break;
        }
    }    

    std::vector<int> instr2;
    ll v2 = f(l2, r2, instr2);

    if(v1 < v2){
        std::swap(v1, v2);
        std::swap(instr1, instr2);
    }

    std::cout << v1 << std::endl;
    std::cout << instr1.size() << std::endl;

    for(int i : instr1){
        std::cout << i << std::endl;
    }
}

