ll go(int o, int ch) {
	if (o >= n) {
		if (ch) return 0;
		return -1e17;
	}
	if (dp[o][ch] > -2e17) return dp[o][ch];

	ll mav = -1e17;

	ll t = go(o + 2, ch);
	if (mav < t) {
		mav = t;
		tr[o] = 0;
	}

	t = go(o + 2, 1) + vec[o];
	if (mav < t) {
		mav = t;
		tr[o] = 1;
	}

	return dp[o][ch] = mav;
}

