const long long INFLL = 1e18;

using namespace std;

const int MAXN = 1000;

ll dp[MAXN + 1][MAXN + 1];
int pr[MAXN + 1][MAXN + 1];
int a[MAXN + 1];
vector<int> p;

void go(int l, int r, int shift) {
    if (pr[l][r] == -1) {
        return;
    }
    p.push_back(pr[l][r] + 1);
    if (pr[l][r] == 0) {
        go(l + 1, r, shift);
    } else if (pr[l][r] == r - l) {
        go(l, r - 1, shift);
    } else {
        go(l, l + pr[l][r] - 1, shift);
        go(l + pr[l][r] + 1, r, shift + pr[l][r]);
    }
}

int main() {
    //ios_base::sync_with_stdio(false);
    //cin.tie(0);
    //freopen("input.txt", "r", stdin);
    //freopen("input.txt", "w", stdout);

    int n;
    cin >> n;

    ll sum = 0;

    for (int i = 0; i < n; i++) {
        cin >> a[i];

        a[i] = -a[i];

        sum += a[i];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            dp[i][j] = -INFLL;
            pr[i][j] = -1;
        }
    }

    for (int len = 1; len <= n; len++) {
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;

            if (len == 1) {
                dp[l][r] = 2 * a[l];
                continue;
            }

            for (int k = l; k <= r; k++) {
                if (k == l) {
                    if (dp[l][r] < dp[l + 1][r] + a[l]) {
                        dp[l][r] = dp[l + 1][r] + a[l];
                        pr[l][r] = 0;
                        if (len == 2) {
                            pr[l][r] = r - l;
                        }
                    }
                } else if (k == r) {
                    if (dp[l][r] < dp[l][r - 1] + a[r]) {
                        dp[l][r] = dp[l][r - 1] + a[r];
                        pr[l][r] = r - l;
                        if (len == 2) {
                            pr[l][r] = 0;
                        }
                    }
                } else {
                    if (dp[l][r] < dp[l][k - 1] + dp[k + 1][r] + a[k] - a[k - 1] - a[k + 1]) {
                        dp[l][r] = dp[l][k - 1] + dp[k + 1][r] + a[k] - a[k - 1] - a[k + 1];
                        pr[l][r] = k - l;
                    }
                }
            }

            //cout << l << " " << r << " " << dp[l][r] << "\n";
        }
    }

    cout << dp[0][n - 1] << "\n";

    go(0, n - 1, 0);

    cout << (int)p.size() << "\n";

    for (auto x : p) {
        cout << x << "\n";
    }
    return 0;
}

