		for(int i=1;i<=c[1]-1;i++)op[++tot]=1;top+=c[1]-1;
		for(int i=n;i>c[c[0]];i--)op[++tot]=i-top;
		for(int i=1;i<c[0];i++)work(c[i]+1,c[i+1]-1),top+=(c[i+1]-c[i]-2);
		for(int i=1;i<c[0];i++)op[++tot]=2;
		ans=now;
	}
	printf("%lld\n",ans);
	printf("%lld\n",tot);
	for(int i=1;i<=tot;i++)printf("%lld\n",op[i]);
}

