typedef long long ll;
using namespace std;
template <typename T>
inline void output(T a, int p = 0) {
    if(p) cout << fixed << setprecision(p)  << a << "\n";
    else cout << a << "\n";
}
// end of template

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    // source code
    int N;
    cin >> N;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];
    if(N < 3) {
        output(0);
        output(N);
        rep(i, N) output(1);
        return 0;
    }
    vector<vector<int>> B(2, vector<int>(N));
    rep(i, N){
        if(A[i] >= 0){
            B[i % 2][i] = 1;
        }
    }
    vector<ll> S(2);
    rep(i, 2){
        rep(j, N){
            if(B[i][j]){
                S[i] += A[j];
            }
        }
    }
    ll sum = max(S[0], S[1]);
    vector<int> C = S[0] > S[1] ? B[0] : B[1];
    vector<int> ret;
    int front = -1, last = N;
    rep(i, N){
        if(C[i]) {
            front = i;
            break;
        }
    }
    for(int i = N - 1; i >= 0; i--){
        if(C[i]) {
            last = i;
            break;
        }
    }
    for(int i = N - 1; i > front; i--){
        if(i > last){
            ret.pb(i + 1);
        }
        else {
            if(C[i - 1] && i >= 1){
                ret.pb(i + 1);
            }
            else if(C[i - 1] == 0 && C[i] == 0 && C[i + 1] == 0 && i >= 1 && i < N - 1){
                ret.pb(i + 1);
            }
        }
    }
    rep(i, front){
        ret.pb(i + 1);
    }
    output(sum);
    output(ret.size());
    for(auto i: ret){
        output(i);
    }



    return 0;
}

