LL get_sum(int l, int r)
{
	assert((r - l) % 2 == 0);
	LL res = s[r & 1][r];
	if (l > 2) res -= s[l & 1][l - 2];
	return res;
}

void go(int l, int r)
{
	vector<int> ans;
	FOR(i, 0, l) ans.PB(1);
	int zara = n - l;
	FOR(i, 0, r) ans.PB(zara), zara--;

	for(int i = l + 1; i < n - r; i += 2)
		ans.PB(2);

	cout << SZ(ans) << endl;
	for(auto i: ans) cout << i << endl;
}

int main()
{
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	cin >> n;
	FOR(i, 0, n) cin >> a[i];
	FOR(i, 0, n)
	{
		if (i) s[0][i] = s[0][i - 1], s[1][i] = s[1][i - 1];

		s[i & 1][i] += a[i];
	}

	PII best;
	LL ans = -LINF;

	FOR(i, 0, n - 1)
	{
		FOR(j, 0, n - 1)
		{
			int bude = n - i - j;
			if (bude <= 0) break;
			if (bude % 2 == 0) continue;

			LL tut = get_sum(i, n - j - 1);
			if (ans >= tut) continue;
			ans = tut;
			best = {i, j};
		}
	}

	cout << ans << endl;
	go(best.X, best.Y);

	cerr << "Time elapsed: " << clock() / (double)CLOCKS_PER_SEC << endl;
	return 0;
}

#include <bits/stdc++.h>
