#define REP(i, n) for (int i = 0; i < (n); ++i)
#define SIZE(a) ((int)(a).size())

const int N = 1005;

int n, a[N];
ll f[N];
int prv[N];

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> n;
	REP(i, n) cin >> a[i+1];
	for (int i = 1; i <= n; ++i) {
		f[i] = a[i]; prv[i] = 0;
		for (int j = 2; i-j > 0; j += 2) {
			if (f[i] < f[i-j] + a[i]) {
				f[i] = f[i-j] + a[i];
				prv[i] = i-j;
			}
		}
	}

	int ps = 0;

	for (int i = 1; i <= n; ++i) {
		if (f[i] > f[ps]) ps = i;
	}

	cout << f[ps] << '\n';

	deque<int> now(n);
	while (ps > 0) {
		now[ps-1] = 1;
		ps = prv[ps];
	}
	vector<int> out;

	while (SIZE(now) > 1) {
		if (now.front() == 0) {
			out.push_back(0);
			now.pop_front();
			continue;
		}
		if (SIZE(now) == 2) {
			out.push_back(1);
			now.pop_front();
			continue;
		}
		if (now[2]) {
			out.push_back(1);
			now.pop_front();
			now.pop_front();
			continue;
		}
		out.push_back(2);
		now.pop_front();
		now.pop_front();
		now.pop_front();
		now.push_front(1);
	}

	cout << SIZE(out) << '\n';
	for (auto& p : out) {
		cout << p+1 << '\n';
	}

	return 0;
}

