void solve() {
    int n;
    cin >> n;
    int a[n];

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vii ans_odd, ans_even;
    ll sum_odd = 0, sum_even = 0;

    for (int i = 0; i < n; i++) {
        if (i % 2) {
            if (a[i] > 0) {
                sum_odd += a[i];
                ans_odd.push_back(i);
            }
        } else {
            if (a[i] > 0) {
                sum_even += a[i];
                ans_even.push_back(i);
            }
        }
    }

    if (sum_even == 0 and sum_odd == 0) {
        int ans = -INF32;
        feach(i, a) ans = max(ans, i);
        cout << ans;
        return;
    }

    ll sum;
    vii ans;
    if (sum_odd > sum_even) {
        sum = sum_odd;
        ans = ans_odd;
    } else {
        sum = sum_even;
        ans = ans_even;
    }

    cout << sum << '\n';
    vii to_print;
    for (int i = n; i - 1 > ans.back(); i--)
        to_print.push_back(i);

    for (int i = ans.size() - 2; i >= 0; i--) {
        if (ans[i + 1] - ans[i] == 2)
            to_print.push_back(ans[i] + 2);
        else {
            for (int j = 0; j < (ans[i + 1] - ans[i] - 2) / 2; i++)
                to_print.push_back(ans[i] + 3);
            to_print.push_back(ans[i] + 2);
        }
    }

    for (int i = 1; i - 1 < ans.front(); i++)
        to_print.push_back(1);

    cout << to_print.size() << '\n';
    feach(i, to_print)
        cout << i << '\n';
}

