#include <bits/stdc++.h>
using i64 = long long;

int main() {
    int n;
    std::cin >> n;
    std::vector<int> even, odd, a;
    i64 maxi = 0, es = 0, os = 0;
    for (int i = 0; i < n; i++) {
        i64 in;
        std::cin >> in;
        a.push_back(static_cast<int>(in));
        if (a[maxi] < a[i]) maxi = i;
        if (in <= 0) continue;
        if (i % 2) { os += in; odd.push_back(i + 1); }
        else { es += in; even.push_back(i + 1); }
    }

    if (a[maxi] <= 0) {
        printf("%lld\n%d\n", a[maxi], n - 1);
        for (int i = n; i > maxi + 1; i--) printf("%d\n", i);
        for (int i = 0; i < maxi; i++) printf("%d\n", 1);
        return 0;
    }

    std::deque<int> r;
    auto &q = es > os ? even : odd;

    std::reverse(q.begin(), q.end());
    for (int i = n; i > q.front(); i--) r.push_back(i);
    for (int i = 0; i < q.size() - 1; i++) {
        for (int j = 0; j < (q[i] - q[i + 1]) / 2; j++) r.push_back((q[i] + q[i + 1]) / 2);
    }
    for (int i = 1; i < q.back(); i++) r.push_back(1);

    printf("%lld\n%ld\n", std::max(es, os), r.size());
    for (int i : r) printf("%d\n", i);

    return 0;
}

