void solve() {
  {
    int id = 0;
    for (int i = 0; i < n; ++i)
      if (a[id] < a[i]) id = i;
    if (a[id] < 0) {
      cout << a[id] << endl;
      for (int i = 0; i < id; ++i) res.push_back(1), --n;
      while (n > 1) res.push_back(n--);
      return;
    }
