    if (sum[(n - 1) & 1] < sum[n & 1]) {
      res.push_back(n);
      a.pop_back();
    }
  }
  n = a.size();
  bool ch = (n - 1) & 1;
  vector<long long> tmp;
  for (int i = 0; i < n; ++i) {
    if ((i ^ ch ^ 1) & 1) {
      if (a[i] >= 0)
        tmp.push_back(a[i]);
      else {
        res.push_back(tmp.size() + 1);
