LL n,ara[1010];
LL dp[1010][3][3];
bool visited[1010][3][3];
LL mxvl;
vector <LL> vec;
vector <LL> pr;
void input(){
    LL i,j;sl(n);
    for0(i,n){
        sl(ara[i]);
        if(i==0||ara[i]>mxvl){
            mxvl=ara[i];
        }
    }
}
LL re(LL st,LL parity,bool f){
//    if(st==1){
//        plll(st,parity,(LL)f);NL;
//    }
    if(st==n){return 0;}
    if(visited[st][parity][f]){return dp[st][parity][f];}
    visited[st][parity][f]=true;
    LL s1,s2,s3,s4;
    if(!f){
        s1=ara[st];
        s2=ara[st]+re(st+1,(parity+1)%2,true);
        s3=re(st+1,parity,f);
        return dp[st][parity][f]=max(s3,max(s1,s2));
    }
    else{
        if(parity%2==1){
            s1=re(st+1,(parity+1)%2,f);
            return dp[st][parity][f]=s1;
        }
        else{
            s1=ara[st];
            s2=ara[st]+re(st+1,(parity+1)%2,f);
            s3=re(st+1,(parity+1)%2,f);
            return dp[st][parity][f]=max(s1,max(s2,s3));
        }
    }
}
void bktrk(LL st,LL parity,bool f){
    if(st==n){return;}
    LL mx,s1,s2,s3,i,j;
    if(!f){
        s1=ara[st];
        s2=ara[st]+dp[st+1][(parity+1)%2][true];
        s3=dp[st+1][parity][f];
        mx=max(s1,max(s2,s3));
        if(s1==mx){vec.pub(st);return;}
        else if(s2==mx){
            vec.pub(st);
            bktrk(st+1,(parity+1)%2,true);
        }
        else if(s3==mx){
            bktrk(st+1,parity,f);
        }
    }
    else{
        if(parity%2==1){
            bktrk(st+1,(parity+1)%2,f);
        }
        else{
            s1=ara[st];
            s2=ara[st]+dp[st+1][(parity+1)%2][f];
            s3=dp[st+1][(parity+1)%2][f];
            mx=max(s1,max(s2,s3));
            if(s1==mx){
                vec.pub(st);return;
            }
            else if(s2==mx){
                vec.pub(st);
                bktrk(st+1,(parity+1)%2,f);
            }
            else if(s3==mx){
                bktrk(st+1,(parity+1)%2,f);
            }
        }
    }
}
void solve(){
    LL i,j,sz;
    mem(visited,false);
//    mem(dp,-1);
