        pl(mxvl);NL;
        pl(0LL);NL;return;
    }
//    pl(dp[1][0][0]);NL;
    pl(s);NL;
    vec.clear();
    bktrk(0LL,0LL,0);
    sz=vec.size();
//    pvec(vec);
    pr.clear();
    for(i=n-1;i>vec[sz-1];i--){
        pr.pub(i);
    }
//    pvec(pr);
    for(i=sz-1;i>=1;i--){
        for(j=vec[i]-2;j>vec[i-1];j--){
            pr.pub(j);
        }
    }
//    pvec(pr);
    for(i=0;i<=sz-2;i++){
        pr.pub(vec[0]+1);
    }
//    pvec(pr);
    for(i=0;i<vec[0];i++){
        pr.pub(0);
    }
//    pvec(pr);
    sz=pr.size();
    pl(sz);NL;
    for0(i,pr.size()){
        pl(pr[i]+1);NL;
    }
}
