}
void solution1(int v){
	int pos=0;
	for (int i=1;i<=n;i++)
		if (a[i]==v){
			pos=i;
			break;
		}
	for (int i=1;i<pos;i++)
		x[++ans]=1;
	for (int i=n;i>pos;i--)
		x[++ans]=i-pos+1;
}
int Next(int x){
	for (x++;!f[x]&&x<=n;x++);
	return x;
}
void solution2(int v){
	for (int i=1;i<=n;i++)
		if ((i&1)!=v)
			f[i]=0;
	int L=1,R=n;
	while (!f[L])
		x[++ans]=1,L++;
	while (!f[R])
		x[++ans]=(R--)-L+1;
	for (int i=L,j=Next(i);i<R;i=j,j=Next(i))
		for (int k=(j-i)/2;k>0;k--)
			x[++ans]=k+1;
}
