vector<int> solve(vector<LL> input) {
  vector<int> ret;
  LL best = -1000000000;
  int N = input.size();
  for (int z = 0; z < 2; z++) {
    vector<int> tmp;
    LL obj = 0;
    for (int i = z; i < N; i += 2) {
      if (input[i] > 0) {
        obj += input[i];
        tmp.push_back(i);
      }
    }
    if (best < obj) {
      best = obj;
      ret = tmp;
    }
  }
  return ret;
}

