    cin >> N;
    rep(i, 0, N) cin >> A[i];
    rep(i, 0, N) B[i % 2][i] = A[i];
    rep(d, 0, 2) rep(i, 1, N) B[d][i] += B[d][i - 1];
    rep(l, 0, N) rep(r, 0, N) memoF[l][r] = memoLF[l][r] = memoRF[l][r] = { -infl, 0 };

    ll ans = -infl; int opt_cent = -1;
    pair<ll, int> lft, rht;
    rep(cent, 1, N - 1) {
        pair<ll, int> al = LF(0, cent - 1);
        pair<ll, int> ar = RF(cent + 1, N - 1);

        pair<ll, int> bl, br;

        ll a = al.first + ar.first;

        ll b = -infl;
        if (0 <= cent - 2 and cent + 2 <= N - 1) {
            bl = F(0, cent - 2);
            br = F(cent + 2, N - 1);
            b = bl.first + br.first;
        }

        ll c = max(a, b);
        if (ans < c) {
            ans = c;
            opt_cent = cent;

            if (a < b) lft = bl, rht = br;
            else lft = al, rht = ar;
        }
    }

    cout << ans << endl;

    vector<int> buf;

    int a = lft.second / 1010;
    int b = lft.second % 1010;

    int c = rht.second / 1010;
