    rep(i, 0, a) {
        buf.push_back(0);
        a--; b--; c--; d--; N--; opt_cent--;
    }
    rep(i, 0, N - d - 1) buf.push_back(N - 1 - i);
    N = d;

    rep(i, 0, (b - a) / 2) buf.push_back(1);
    c -= b - a;
    d -= b - a;
    b = a;

    rep(i, 0, (d - c) / 2) buf.push_back(c + 1);
    c = d;

    int dlt = opt_cent - b;
