            buf.push_back(2);
            opt_cent -= 2;
            c -= 2; d -= 2; N -= 2;
        }

        fr = (c - opt_cent) / 2;
        rep(i, 0, fr) {
            buf.push_back(4);
            opt_cent -= 2;
            c -= 2; d -= 2; N -= 2;
        }

        buf.push_back(2);
        buf.push_back(1);
