void trim_edge(V<ll> &alist, V<ll> &anslist)
{
    for ( ; ; ) {
        if (alist[0] >= 0LL) break;
        anslist.pb(1LL);
        alist.erase(alist.begin());
    }

    for ( ; ; ) {
        ll a = alist[alist.size()-1];
        if (a >= 0) break;
        anslist.pb(alist.size());
        alist.erase(alist.end() - 1);
    }

    debug_printf("---- alist 2\n"); debug_print(alist);
    debug_printf("---- anslist\n"); debug_print(anslist);
}

void shrink_minus(V<ll> &alist, V<ll> &anslist)
{
    bool done = false;

    while (!done) {

        rep (i, alist.size()) {
            if (i == 0LL) continue;
            if (i == alist.size()-1LL) {
                done = true;
                break;
            }

            ll prev_a = alist[i-1];
            ll a = alist[i];
            ll next_a = alist[i+1];

            if (prev_a < 0LL && a < 0LL && next_a < 0LL) {
                anslist.pb(i + 1LL);
                alist.erase(alist.begin() + i + 1LL);
                alist.erase(alist.begin() + i - 1LL);
                break;
            }
        }
    }

    debug_printf("---- alist 3\n"); debug_print(alist);
    debug_printf("---- anslist\n"); debug_print(anslist);
}

ll calc_cand(const V<ll> &alist, ll skip)
{
    ll ret = 0LL;
    ll count = skip;

    rep (i, alist.size()) {
        ll a = alist[i];
        if (a >= 0) {
            ++count;
            if (count & 1LL) ret += a;
            continue;
        }

        assert(i < alist.size() - 1LL);
        ll next_a = alist[i+1LL];
        if (next_a < 0LL) i++;
        else ++count;
    }

    debug_printf("--- calc_cand = %lld\n", ret);
    return ret;
}

