    for (int i = 0; i < N; i++) {
        if (i%2 == 0) {
            evensum += max(A[i], 0LL);
            evenmax = max(evenmax, A[i]);
        }
        else {
            oddsum += max(A[i], 0LL);
            oddmax = max(oddmax, A[i]);
        }
    }

    if (evenmax <= 0 && oddmax <= 0) {
        ll mx = max(evenmax, oddmax);
        int pos;
        for (int i = 0; i < N; i++) {
            if (A[i] == mx) {
                pos = i+1;
                break;
            }
        }
        cout << mx << endl;
        cout << N-1 << endl;
        for (int i = N; i >= pos+1; i--) cout << i << endl;
        for (int i = 0; i < pos-1; i++) cout << 1 << endl;
        return 0;
    }
    else {
        vector<ll> ans;
        cout << max(oddsum, evensum) << endl;
        while (A[0] < 0) {
            A.erase(A.begin());
            ans.push_back(1);
            swap(oddsum, evensum);
        }
        if (oddsum > evensum) {
            ans.push_back(1);
            A.erase(A.begin());
        }
        while (A[0] < 0) {
            ans.push_back(1);
            ans.push_back(1);
            A.erase(A.begin(), A.begin()+2);
        }
        while (A.size() > 1) {
            if (A.size() == 2) {
                ans.push_back(2);
                A.erase(A.begin()+1);
            }else if (A.size() >= 4) {
                if (A[2] >= 0) {
                    ans.push_back(2);
                    A[0] += A[2];
                    A.erase(A.begin()+1, A.begin()+3);
                }else {
                    ans.push_back(3);
                    A[1] += A[3];
                    A.erase(A.begin()+2, A.begin()+4);
                }
            }else {
                if (A[2] >= 0) {
                    ans.push_back(2);
                    A[0] += A[2];
                    A.erase(A.begin()+1, A.begin()+3);
                }else {
                    ans.push_back(3);
                    A.erase(A.begin()+2, A.begin()+3);
                }
            }
        }
        cout << ans.size() << endl;
        for (int i = 0; i < (int)ans.size(); i++) {
            cout << ans[i] << endl;
        }
    }
    return 0;
}

