vector <int> ans;

void restore(int l, int r)
{
    if (l == r)
    {
        return;
    }
    else
    {
        if (type[l][r] == 1)
        {
            restore(l, opt[l][r] - 1);
            restore(opt[l][r] + 1, r);
            ans.push_back(opt[l][r]);
        }
        else if (type[l][r] == 2)
        {
            ans.push_back(l);
            restore(l + 1, r);
        }
        else
        {
            ans.push_back(r);
            restore(l, r - 1);
        }
    }
}

