    {
        for (int i = 0; i + len - 1 < n; i++)
        {
            int j = i + len - 1;
            if (len == 1)
            {
                dp[i][j] = a[i];
                opt[i][j] = i;
            }
            else
            {
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
                int opt_l = max(i + 1, (len >= 4 ? opt[i][j - 1] : i + 1));
                int opt_r = min((len >= 4 ? opt[i + 1][j] : j - 1), j - 1);
                ll best = -1e18;
                for (int t = opt_l; t <= opt_r; t++)
                {
                    if (dp[i][t - 1] + dp[t + 1][j] > best)
                    {
                        best = dp[i][t - 1] + dp[t + 1][j];
                        opt[i][j] = t;
                    }
                }
                if (best > dp[i][j])
                {
                    dp[i][j] = best;
                    type[i][j] = 1;
                }
                else
                {
                    if (dp[i + 1][j] == dp[i][j])
                    {
                        type[i][j] = 2;
                    }
                    else
                    {
                        type[i][j] = 3;
                    }
                }
            }
        }
    }
