vector <int> ans;

void restore(int l, int r, int a, int b)
{
    if (l == r)
    {
        return;
    }
    else
    {
        if (type[l][r][a][b] == 1)
        {
            restore(l, opt[l][r][a][b] - 1, a, 1);
            restore(opt[l][r][a][b] + 1, r, 1, b);
            ans.push_back(opt[l][r][a][b]);
        }
        else if (type[l][r][a][b] == 2)
        {
            ans.push_back(l);
            restore(l + 1, r, a, b);
        }
        else
        {
            ans.push_back(r);
            restore(l, r - 1, a, b);
        }
    }
}

