class RMQ{
private:
	int32 n;
	vector<PLL> node, lazy;
	vector<bool> lazyFlag;
public:
	RMQ(vector<int64> v){
		int sz = v.size();
		n = 1; while(n < sz) n *= 2;
		node.resize(2*n-1, PLL(-INF_LL, -1));
		lazyFlag.resize(2*n-1, false);
		for(int32 i = 0;i < sz;i++) node[i+n-1] = {v[i], i};
		for(int32 i = n-2;i >= 0;i--) node[i] = max(node[2*i+1], node[2*i+2]);
	}

	void update(int32 k, int64 x){
		k += n-1;
		node[k].fs = x;
		while(k > 0){
			k = (k-1)/2;
			node[k] = max(node[k*2+1], node[k*2+2]);
		}
	}

	PLL query(int32 a, int32 b, int32 k=0, int32 l=0, int32 r=-1){
		if(a >= b) return PLL(-INF_LL, -1);
		if(r < 0) r = n;

		if(b <= l || r <= a) return PLL(-INF_LL, -1);
		if(a <= l && r <= b) return node[k];

		return max(query(a, b, k*2+1, l, (l+r)/2), query(a, b, k*2+2, (l+r)/2, r));
	}
};

vector<int32> res;

int main(void){
	cin.tie(0);
