	REP(i, n)  cin >> a[i+2];
	RMQ rmq(a);
	FOR(i, 2, n+2){
		PLL ret = max(rmq.query(i-2, i-1), rmq.query(0, i-3));
		res[i] = ret.sc;
		rmq.update(i, ret.fs+a[i]);
	}
	int32 in = rmq.query(0, n+2).sc;
	vector<int32> pos;
	int32 cnt = 0;
	pos.push_back(n+1);
	while(in > 1){
		pos.push_back(in-1);
		in = res[in];
	}
	pos.push_back(0);
	REP(i, pos.size()-1){
		cnt += pos[i]-pos[i+1]-1;
	}
	cout << rmq.query(0, n+2).fs << endl;
	cout << cnt << endl;
	REP(i, pos.size()-1){
		for(int32 j = pos[i]-1;j > pos[i+1];j--){
			cout << j << endl;
		}
	}
}

