using namespace std;

static vector<int64_t> the_last(1004, INT64_MIN);
static vector<int> came_from(1004);
vector<int> elements;

int64_t solve_without_deleting(const int rhs){
	int tmp = rhs - 2;
	while (tmp >= 0) {
		if (the_last[tmp] + elements[rhs] > the_last[rhs]) {
			came_from[rhs] = tmp;
			the_last[rhs] = the_last[tmp] + the_last[rhs];
		}
		tmp -= 2;
	}
	return the_last[rhs];
}



void solve() {
	int n;
	cin >> n;
	elements.resize(n);
	for (size_t i = 0; i < elements.size(); ++i) {
		cin >> elements[i];
		the_last[i] = elements[i];
		came_from[i] = i;
	}
	int64_t max_result = INT64_MIN;
	int ind = 0;
	for (size_t i = 1; i < elements.size(); ++i) {
		int64_t res = solve_without_deleting(i);
		if (res > max_result) {
			max_result = res;
			ind = i;
		}
	}
	vector<int> way;
	while (came_from[ind] != ind) {
		way.push_back(ind);
		ind = came_from[ind];
	}
	way.push_back(ind);

	sort(way.begin(), way.end());
	vector<int> to_delete;
	for (size_t i = elements.size(); i > way.back() + 1; --i) {
		to_delete.push_back(i);
	}
	for (size_t i = 0; i < way.front(); ++i) {
		to_delete.push_back(1);
	}
	for (size_t i = 1; i < way.size(); ++i) {
		for (size_t j = 1; j < (way[i] - way[i - 1]) / 2; ++j) {
			to_delete.push_back(3);
		}
		to_delete.push_back(2);
	}
	cout << max_result << "\n";
	cout << to_delete.size() << "\n";
	for (int i : to_delete) {
		cout << i << "\n";
	}
	return;
}


int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	int t = 1;
	//cin >> t;
	while (t--)solve();
	return 0;
}

