int l1,r1,l2,r2;

int best(vector<int> v, int &l, int &r) {
    // smallest possible deletion
    int n = SZ(v);
    vector<int> ps(n+1);
    for (int i = 0; i<n; i++) {
        ps[i+1] = ps[i] + v[i];
    }
    ll best = 0;
    for (int i = 0; i<n; i++) {
        for (int j = i; j<n; j++) {
            if (ps[j+1] - ps[i] > best) {
                tie(l,r) = tie(i,j);
                best = ps[j+1] - ps[i];
            }
        }
    }
    return best;
}

