long long solve(vector<int> a, vector<int>& ope)
{
    int n = a.size();
    ope.clear();

    auto it = max_element(a.begin(), a.end());
    if(*it <= 0){
        int j = it - a.begin();
        for(int i=n-1; i>j; --i)
            ope.push_back(i);
        for(int i=0; i<j; ++i)
            ope.push_back(0);
        return *it;
    }

    vector<long long> sum(2, 0);
    for(int i=0; i<n; ++i)
        sum[i%2] += max(0, a[i]);
    if(sum[0] < sum[1]){
        ope.push_back(0);
        a.erase(a.begin());
        -- n;
    }
    if(n % 2 == 0){
        ope.push_back(n-1);
        a.erase(--a.end());
        -- n;
    }

    for(int i=n-1; i>=0; i-=2){
        if(a[i] < 0){
            ope.push_back(i);
            if(i == n - 1)
                ope.push_back(i-1);
            else if(i == 0)
                ope.push_back(0);
            n -= 2;
        }
    }

    while(n > 1){
        ope.push_back(1);
        n -= 2;
    }

    return max(sum[0], sum[1]);
}

