#include <bits/stdc++.h>

using namespace std;

long long a[1005];

int main() {
  int n;
  cin >> n;
  long long sum0 = 0, sum1 = 0;
  for (int ni = 0; ni < n; ni++) {
    cin >> a[ni];
    if (a[ni] > 0) {
      if (ni % 2 == 0) {
        sum0 += a[ni];
      } else {
        sum1 += a[ni];
      }
    }
  }
  long long val;
  vector<int> ans;
  if (sum0 <= 0 && sum1 <= 0) {
    int maxi = 0;
    for (int ni = 1; ni < n; ni++) {
      if (a[ni] > a[maxi]) {
        maxi = ni;
      }
    }
    val = a[maxi];
    for (int i = n - 1; i > maxi; i--) {
      ans.push_back(i);
    }
    for (int i = 0; i < maxi; i++) {
      ans.push_back(0);
    }
  } else {
    int st;
    if (sum0 >= sum1) {
      val = sum0;
      st = 0;
    } else {
      val = sum1;
      st = 1;
    }
    int fi = -1, li = -1;
    for (int ni = st; ni < n; ni += 2) {
      if (a[ni] > 0) {
        if (fi == -1) fi = ni;
        li = ni;
      }
    }
    for (int i = n - 1; i > li; i--) {
      ans.push_back(i);
    }
    for (int i = 0; i < fi; i++) {
      ans.push_back(0);
    }
    int offset = 0;
    for (int i = fi + 2; i < li; i += 2) {
      if (a[i] <= 0) {
        ans.push_back(i - offset - fi);
        offset += 2;
      }
    }
    for (int i = fi + 1; i < li - offset; i += 2) {
      ans.push_back(1);
    }
  }
  cout << val << endl;
  cout << ans.size() << endl;
  for (int x : ans) {
    cout << x + 1 << endl;
  }
  return 0;
}

