using namespace std;

int main(void) {
    int N;
    cin >> N;
    bool allneg = true;
    vector<int64_t> a(N);
    for(int i=0; i<N; i++) {
        cin >> a[i];
        if(a[i] > 0) allneg = false; 
    }

    if(allneg) {
        auto m = max_element(a.begin(), a.end());
        cout << *m << endl;
        cout << N-1 << endl;
        int d = distance(a.begin(), m);
        for(int i=N-1; i>=0; i--) {
            if(i > d) {
                cout << i+1 << endl;
            } else if(i == d) {
                break;
            }
        }
        for(int i=0; i<d; i++) {
            cout << 1 << endl;
        }
        return 0;
    }

    vector<int> odd, even;
    int64_t odd_ans = 0, even_ans = 0;
    for(int i=0; i<N; i++) {
        if(a[i] < 0) continue;
        if(i%2) {
            odd.emplace_back(i);
            odd_ans += a[i];
        } else {
            even.emplace_back(i);
            even_ans += a[i];
        }
    }

    vector<int> ans;
    if(odd_ans > even_ans) {
        cout << odd_ans << endl;
        for(int i=N-1; i>=0; i--) {
            if(i > odd.back()) ans.emplace_back(i);
            else if (i == odd.back()) break;
        }
        for(int i=0; i<N; i++) {
            if(i < odd.front()) ans.emplace_back(0);
            else if(i == odd.front()) break;
        }
        for(int i=N-1; i>=0; i--) {
            if(odd.front() < i && i < odd.back() && i%2 && a[i] < 0) ans.emplace_back(i - odd.front());
        }
        for(int j=0; j<odd.size()-1; j++) {
            ans.emplace_back(1);
        }
    } else {
        cout << even_ans << endl;
        for(int i=N-1; i>=0; i--) {
            if(i > even.back()) ans.emplace_back(i);
            else if (i == even.back()) break;
        }
        for(int i=0; i<N; i++) {
            if(i < even.front()) ans.emplace_back(0);
            else if(i == even.front()) break;
        }
        for(int i=N-1; i>=0; i--) {
            if(even.front() < i && i < even.back() && i%2 == 0 && a[i] < 0) ans.emplace_back(i - even.front());
        }
        for(int j=0; j<even.size()-1; j++) {
            ans.emplace_back(1);
        }
    }

    cout << ans.size() << endl;
    for(auto e: ans) {
        cout << e+1 << endl;
    }
    return 0;
}

