    int pos[2];
   // cout << i << ' ' << j << endl;
    for (int k = j; k >= i; k--) {
        if (k <= j - 2) {
            if (dp[i][j] == dp[i][k] + t[k % 2]) {
               // cout << "opa" << endl;
                restore(extra, i, k);
                int t = pos[k % 2] - k - 1;
