  }
  if(mem[x][y]!=-1)
    return mem[x][y];
  ll res=(-1e14);
  ll tmp2;
  for(int i=x+1; i<=y-1; ++i){
    tmp2=dp(x, i-1)+dp(i+1,y);
    if(tmp2>res){
      res=tmp2;
    }
  }
  if(x==1){
    if(a[y]>res){
      res=a[y];
    }
  }
  if(y==n){
    if(a[x]>res){
      res=a[x];
    }
  }
  if(x==1&&y==n){
    ll tmp1=-1;
    for(int i=x; i<=y; ++i){
      if(a[i]>res){
        res=a[i];
      }
    }
  }
  mem[x][y]=res;
  return res;
}
vector <int> an;
void dp2(int x, int y){
  if(x==y){
    return;
  }
  ll res=mem[x][y], tmp2;
  for(int i=x+1; i<=y-1; ++i){
    tmp2=dp(x, i-1)+dp(i+1,y);
    if(tmp2==res){
      dp2(x, i-1);dp2(i+1, y);
      an.push_back(i);
      return;
    }
  }
  if(x==1){
    if(a[y]==res){
      for(int i=x; i<y; ++i)
        an.push_back(i);
      return;
    }
  }
  if(y==n){
    if(a[x]==res){
      for(int i=y; i>=x+1; --i)
        an.push_back(i);
    }
  }
  if(x==1&&y==n){
    for(int i=x; i<=y; ++i){
      if(a[i]==res){
        for(int j=1; j<i; ++j){
          an.push_back(j);
        }
        for(int j=n; j>i; --j){
          an.push_back(j);
        }
        return;
      }
    }
  }
}
