    int pos[2];
   // cout << i << ' ' << j << endl;
    for (int k = j; k >= max(i, j - 70); --k) {
        if (k <= j - 2) {
            if (dp[i][j] == dp[i][k] + t[k & 1]) {
               // cout << "opa" << endl;
                restore(extra, i, k);
                int t = pos[k & 1] - k - 1;
