    int g=sum[0]>sum[1]?0:1;
    int addr=0,cs=0;
    string r="";
    lint cnt=0;

    while(addr<N){
        if(get[g][addr]){
            addr++;
            cs++;
        }else{
            if(cs==0){
                r=r+"1\n";
                addr++;
                cnt++;
            }else{
                int n;
                for(n=0;addr+n<N && !get[g][addr+n];n++) ;
                if(addr+n==N){
                    for(int i=0;i<n;i++){
                        r=r+to_string(cs+1)+"\n";
                        cnt++;
                    }
                    addr=N;
                }else{
                    for(int i=n/2+1;i>0;i--){
                        r=r+to_string(cs+i)+"\n";
                        cnt++;
                    }
                    addr+=n;
                    cs--;
                }
            }
        }
    }

    cout << sum[g] << endl << cnt << endl << r;

    return 0;
}

