	array<LL, 3> ma = { -INF, 0, 0 };
	inc(s, n) {
	inc(e, n) {
		if(s <= e && (e - s + 1) % 2 == 1) { setmax(ma, { calc(s, e), s, e }); }
	}
	}
	LL v = ma[0];
	LL s = ma[1];
	LL e = ma[2];

	cout << v << endl;
	calc(s, e);

	int c = n;
	inc(i, n) {
		if(inII(i, s, e) && (i - s) % 2 == 0 && a[i] > 0) { f[i] = true; c--; }
	}
	cout << c << endl;
	decID(i, s, n) {
		if(! f[i]) { cout << (i + 1) << "\n"; }
	}
	inc(i, s) {
		if(! f[i]) { cout << 1 << "\n"; }
	}

	return 0;
}

