int main() {
	int N; cin >> N;
	for (int i = 0; i < N; i++) cin >> vals[i];
	dp[N - 1] = vals[N - 1];
	for (int i = N - 2; i >= 0; i--) {
		for (int j = i + 2; j < N; j += 2) dp[i] = max(dp[i], dp[j]);
		dp[i] += vals[i];
	}
	int st = max_element(dp, dp + N) - dp;
	cout << dp[st] << endl;
	vector<int> nos;
	while (true) {
		nos.push_back(st);
		bool found = false;
		for (int j = st + 2; j < N; j+=2) if (dp[st] == dp[j] + vals[st]) {
			st = j;
			found = true;
			break;
		}
		if (!found) break;
	}
	// Remove all starting elements
	vector<int> pos;
	int rem = N;
	for (int i = 0; i < nos[0]; i++,rem--) pos.push_back(0);
	for (int i = N - 1; i > nos.back(); i--, rem--) pos.push_back(rem - 1);
	for (int i = 1; i < nos.size(); i++) {
		int st = nos[i - 1], ed = nos[i];
		int cnt = (ed - st) >> 1;
		for (int j = 0; j < cnt; j++) pos.push_back(cnt - j);
	}
	cout << pos.size() << endl;
	for (auto x : pos) cout << x+1 << endl;
}

