using namespace std;
typedef long long LL;

const int maxn = 1005;
int a[maxn], n, L, R, p;
LL mx = -1e9, sum1, sum2;
vector<int> ans;

void solve0(int p) {
	per (k, n, p+1) ans.push_back(k);
	rep (k, 1, p-1) ans.push_back(1);
}

void solve1(int p) {
	int i = p, cnt = 0;
	while (i >= 1) {
		if (a[i] >= 0) {
			if (!R) R = i;
			L = i;
		} 
		i -= 2;
	}
	per (k, n, R+1) ans.push_back(k);
	i = R;
	while (i >= L) {
		if (a[i] < 0) ans.push_back(i);
		else cnt++;
		i -= 2;
	}
	rep (k, 1, cnt-1) ans.push_back(L+1);
	rep (k, 1, L-1) ans.push_back(1);
}

int main() {
	scanf("%d", &n);
	rep (i, 1, n) {
		scanf("%d", &a[i]);
		if (a[i] > mx) mx = a[i], p = i;
		if (a[i] >= 0) {
			if (i&1) sum1 += a[i];
			else sum2 += a[i];
		}
	}
	if (mx <= 0) solve0(p);
	else if (sum1 > sum2) solve1(n&1?n:n-1);
	else solve1(n&1?n-1:n);
	mx = max(mx, max(sum1, sum2));
	printf("%lld\n%d\n", mx, ans.size());
	rep (k, 0, ans.size()-1)
		printf("%d\n", ans[k]);
	return 0;
}

