const int N = 1005;

ll a[N], f[N];
int pre[N];

ll dfs(int r) {
  if (~f[r]) return f[r];
  auto &res = f[r] = a[r];
  pre[r] = 0;
  if (r > 4 && dfs(r - 4) + a[r] > res) res = a[r] + dfs(r - 4), pre[r] = r - 4;
  if (r > 2 && dfs(r - 2) + a[r] > res) res = dfs(r - 2) + a[r], pre[r] = r - 2;
  return res;
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 1; i <= n; i++) {
    scanf("%lld", a + i);
  }
  ll res = -2e9, id = 0;
  memset(f, -1, sizeof f);
  for (int i = 1; i <= n; i++) {
    if (dfs(i) > res) res = dfs(i), id = i;
  }
  int num = n, lst = n;
  vector<int> opr;
  while (lst > id) opr.push_back(num), num--, lst--;
  while (id) {
    if (pre[id] == id - 2)
      opr.push_back(num - 1), num -= 2, lst = num;
    else if (pre[id] == id - 4) {
      opr.push_back(num - 2), num -= 2;
      opr.push_back(num - 1), num -= 2;
    }
    id = pre[id];
  }
  while (num > 1) opr.push_back(1);
  printf("%lld\n", res);
  printf("%d\n", int(opr.size()));
  for (auto &x : opr) printf("%d\n", x);
  return 0;
}

