const int N = 1000 + 7;

ll dp[N][N];
int opt[N][N];
int type[N][N];

vector <int> ans;

void restore(int l, int r)
{
    if (l == r)
    {
        return;
    }
    else
    {
        if (type[l][r] == 1)
        {
            restore(l, opt[l][r] - 1);
            restore(opt[l][r] + 1, r);
            ans.push_back(opt[l][r]);
        }
        else if (type[l][r] == 2)
        {
            ans.push_back(l);
            restore(l + 1, r);
        }
        else
        {
            ans.push_back(r);
            restore(l, r - 1);
        }
    }
}

int main()
{
#ifdef ONPC
    freopen("a.in", "r", stdin);
#endif
    int n;
    scanf("%d", &n);
    vector <int> a(n);
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
    }
    for (int len = 1; len <= n; len++)
    {
        for (int i = 0; i + len - 1 < n; i++)
        {
            int j = i + len - 1;
            if (len == 1)
            {
                dp[i][j] = a[i];
                opt[i][j] = i;
            }
            else
            {
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
                ll best = -1e18;
                for (int t = i + 1; t < j; t++)
                {
                    if (dp[i][t - 1] + dp[t + 1][j] > best)
                    {
                        best = dp[i][t - 1] + dp[t + 1][j];
                        opt[i][j] = t;
                    }
                }
                if (best > dp[i][j])
                {
                    dp[i][j] = best;
                    type[i][j] = 1;
                }
                else
                {
                    if (dp[i + 1][j] == dp[i][j])
                    {
                        type[i][j] = 2;
                    }
                    else
                    {
                        type[i][j] = 3;
                    }
                }
            }
        }
    }
    restore(0, n - 1);
    vector <int> p(n);
    for (int i = 0; i < n; i++)
    {
        p[i] = i;
    }
    cout << dp[0][n - 1] << '\n';
    cout << ans.size() << '\n';
    for (int x : ans)
    {
        int ind = -1;
        for (int j = 0; j < (int) p.size(); j++)
        {
            if (p[j] == x)
            {
                ind = j;
            }
        }
        cout << ind + 1 << '\n';
        p.erase(p.begin() + ind);
    }
}

