mt19937 rnd(228);

const int N = 1000 + 7;

ll dp[N][N];
int opt[N][N];
int type[N][N];

vector <int> ans;

void restore(int l, int r)
{
    if (l == r)
    {
        return;
    }
    else
    {
        restore(l, opt[l][r] - 1);
        restore(opt[l][r] + 1, r);
        ans.push_back(opt[l][r]);
    }
}

int main()
{
#ifdef ONPC
    freopen("a.in", "r", stdin);
#endif
    int n;
    scanf("%d", &n);
    vector <int> a(n);
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
    }
    for (int len = 1; len <= n; len++)
    {
        for (int i = 0; i + len - 1 < n; i++)
        {
            int j = i + len - 1;
            if (len == 1)
            {
                dp[i][j] = a[i];
                opt[i][j] = i;
            }
            else
            {
                ll best = -1e18;
                for (int t = i + 1; t < j; t++)
                {
                    if (dp[i][t - 1] + dp[t + 1][j] > best)
                    {
                        best = dp[i][t - 1] + dp[t + 1][j];
                        opt[i][j] = t;
                    }
                }
                if (best > dp[i][j])
                {
                    dp[i][j] = best;
                    type[i][j] = 1;
                }
                else
                {
                    if (dp[i + 1][j] == dp[i][j])
                    {
                        type[i][j] = 2;
                    }
                    else
                    {
                        type[i][j] = 3;
                    }
                }
            }
        }
    }
    int x = 0, y = 0;
    for (int i = 0; i < n; i++)
    {
        for (int j = i; j < n; j++)
        {
            if (dp[i][j] > dp[x][y] && (j - i + 1) % 2)
            {
                x = i, y = j;
            }
        }
    }
    restore(x, y);
    vector <int> p(n);
    for (int i = 0; i < n; i++)
    {
        p[i] = i;
    }
    int l = 0, r = n - 1;
    vector <int> res;
    while (l != x)
    {
        res.push_back(1);
        p.erase(p.begin());
        l++;
    }
    while (r != y)
    {
        res.push_back(p.size());
        r--;
        p.pop_back();
    }
    for (int x : ans)
    {
        int ind = -1;
        for (int i = 0; i < (int) p.size(); i++)
        {
            if (p[i] == x)
            {
                ind = i;
            }
        }
        res.push_back(ind + 1);
        p.erase(p.begin() + ind - 1);
        p.erase(p.begin() + ind);
    }
    cout << dp[x][y] << '\n';
    cout << res.size() << '\n';
    for (int x : res)
    {
        cout << x << '\n';
    }
    return 0;
}

