bool chmax(ll& a,ll b){
    if(a<b){
        a = b;
        return true;
    }
    return false;
}

void check(ll res,vec<ll> A,vec<int> op){
    for(auto& x:op){
        assert(0<=x && x<A.size());
        if(x==0) A.erase(A.begin());
        else if(x==(int) A.size()-1) A.pop_back();
        else{
            A[x] = A[x-1]+A[x+1];
            A.erase(A.begin()+x+1);
            A.erase(A.begin()+x-1);
        }
    }
    assert(A.size()==1);
    assert(res==A[0]);
}

void print(ll ans,vec<int> op){
    cout << ans << "\n";
    cout << op.size() << "\n";
    for(auto& x:op) cout << x+1 << "\n"; 
}

