using namespace std;

const int N = 1000000 + 5;

int n;
int a[N];

void solve()
{
    cin >> n;
    int pos = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        if (a[i] > a[pos]) {
            pos = i;
        }
    }
    if (a[pos] <= 0) {
        cout << a[pos] << endl;
        cout << n - 1 << endl;
        for (int i = 0; i < pos; i++) {
            cout << 1 << endl;
        }
        for (int i = n - pos; i >= 2; i--) {
            cout << i << endl;
        }
        return;
    }

    int rec = 0;
    long long best = 0;
    for (int st = 0; st < 2; st++) {
        long long value = 0;
        for (int i = st; i < n; i += 2) {
            if (a[i] >= 0) {
                value += a[i];
            }
        }
        if (value > best) {
            best = value;
            rec = st;
        }
    }

    cout << best << endl;
    vector<int> ops;
    int lst = -1;
    for (int i = rec; i < n; i += 2) {
        if (a[i] >= 0) {
            if (lst == -1) {
                for (int j = 0; j < i; j++) {
                    ops.push_back(1);
                }
            } else {
                for (int j = 0; j < (i - lst) / 2 - 1; j++) {
                    ops.push_back(3);
                }
                ops.push_back(2);
            }
            lst = i;
        }
    }
    for (int i = n - lst; i >= 2; i--) {
        ops.push_back(i);
    }
    cout << ops.size() << endl;
    for (auto u : ops) {
        cout << u << endl;
    }
}

int main()
{
    solve();
    return 0;
}

