typedef long long ll;

int main(void){
    int n;
    cin>>n;
    vector<ll> a(n+2);
    ll sum[2] = {}, mx = -1e10;
    int mx_pos = 0;
    rep1(i,n) {
        cin>>a[i];
        if (mx < a[i]) {
            mx = a[i];
            mx_pos = i;
        }
        if (a[i]>=0) sum[i%2] += a[i];
    }

    // 全て負
    if(mx < 0){
        cout<<mx<<endl<<n-1<<endl;
        for(int i=n; i>mx_pos; i--){
            cout<<i<<endl;
        }
        rep1(i,mx_pos-1){
            cout<<1<<endl;
        }
        return 0;
    }

    cout<<max(sum[0],sum[1])<<endl;
    vector<int> res;
    int pos = 1;
    while(a[pos] < 0){
        res.push_back(1);
        pos++;
    }

    // 最初の正の位置の偶奇 != 合計が大きい偶奇
    if (sum[pos%2] < sum[(pos+1)%2]) {
        res.push_back(1);
        pos++;
    }
    pos += 2;

    while(pos <= n+1){
        if (a[pos] < 0) {
            res.push_back(3);
        } else {
            res.push_back(2);
        }
        pos += 2;
    }
    cout<<res.size()<<endl;
    for(ll x : res){
        cout<<x<<endl;
    }
    return 0;
}

