LL n , a[ N ];
LL dp[ N ] , bk[ N ] , bst , bl , br , tk;
void init(){
  n = getint();
  for( LL i = 1 ; i <= n ; i ++ )
    a[ i ] = getint();
  bst = a[ 1 ];
  bl = br = 1;
  for( LL i = 1 ; i <= n ; i ++ ){
    dp[ i ] = a[ i ];
    bk[ i ] = 0;
    for( LL j = 1 ; j < i ; j ++ ){
      if( i % 2 != j % 2 ) continue;
      LL tdp = dp[ j ] + a[ i ];
      if( tdp > dp[ i ] ){
        dp[ i ] = tdp;
        bk[ i ] = j;
      }
    }
    if( dp[ i ] > bst ){
      bst = dp[ i ];
      tk = 0;
      br = i;
      LL now = i;
      while( now ){
        bl = now;
        tk ++;
        now = bk[ now ];
      }
    }
  }
}
vector<int> op;
void go( int nl , int nr ){
  if( nl == nr ) return;
  int dlt = (nr - bk[ nr ] - 1) / 2;
  while( dlt -- )
    op.push_back( bk[ nr ] - nl + 3 );
  go( nl , bk[ nr ] );
}
void solve(){
  printf( "%lld\n" , bst );
  for( LL i = n ; i > br ; i -- )
    op.push_back( i );
  for( LL i = 1 ; i < bl ; i ++ )
    op.push_back( 1 );
  go( bl , br );
  while( -- tk )
    op.push_back( 2 );
  printf( "%d\n" , (int)op.size() );
  for( int x : op )
    printf( "%d\n" , x );
}
int main(){
  build();
  //__ = getint();
  while( __ -- ){
    init();
    solve();
  }
}

