int N;
int A[1010];


ll calc(deque<pii> &dq, vector<int> &step){
    ll sum = 0;
    while(dq.size() > 0){
        if(dq[0].second){
            sum += dq[0].first;
            dq.pop_front();
            break;

        }
        else{
            step.push_back(1);
        }
        dq.pop_front();
    }

    while(dq.size() > 0){
        if(dq.size() == 1){
            dq.pop_front();
            step.push_back(2);
        }
        else if(!dq[0].second && dq[1].second){
            sum += dq[1].first;
            dq.pop_front();
            dq.pop_front();
            step.push_back(2);
        }
        else if(dq.size() == 2){
            dq.pop_front();
            dq.pop_front();
            step.push_back(3);
            step.push_back(2);
        }
        else if(dq.size() >= 3){
            if(!dq[0].second && !dq[1].second && !dq[2].second){
                dq.pop_front();
                dq.pop_front();
                step.push_back(3);
            }
        }
    }
    return sum;
}

int main(){

    bool all_neg = true;

    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> A[i];
        if(A[i] >= 0) all_neg = false;
    }
    if(all_neg){
        int max_v = -1000000001;
        int idx = -1;
        for(int i = 0; i < N; i++){
            if(A[i] > max_v){
                max_v = A[i];
                idx = i;
            }
        }

        vector<int> step;
        for(int i = N - 1; i > idx; i--){
            step.push_back(i + 1);
        }
        for(int i = 0; i < idx; i++){
            step.push_back(i + 1);
        }

        cout << max_v << endl;
        cout << step.size() << endl;
        for(int a: step){
            cout << a << endl;
        }

        return 0;
    }

    ll sum1 = 0;
    ll sum2 = 0;
    vector<int> step1, step2;

    {
        deque<pii> dq;
        for(int i = 0; i < N; i++){
            bool f = false;
            if(i % 2){
                if(A[i] >= 0){
                    f = true;
                }
            }
            dq.push_back(pii(A[i], f));
        }
        sum1 = calc(dq, step1);
    }
    {
        deque<pii> dq;
        for(int i = 0; i < N; i++){
            bool f = false;
            if(i % 2 == 0){
                if(A[i] >= 0){
                    f = true;
                }
            }
            dq.push_back(pii(A[i], f));
        }
        sum2 = calc(dq, step2);
    }

    if(sum1 > sum2){
        cout << sum1 << endl;
        cout << step1.size() << endl;
        for(int a: step1){
            cout << a << endl;
        }
    }
    else{
        cout << sum2 << endl;
        cout << step2.size() << endl;
        for(int a: step2){
            cout << a << endl;
        }
    }


    return 0;
}

