        scanf("%d", &a[i]);
    }
    long long ans = -1e18;
    int l = -1, r = -1;
    for(int i = 1;i <= n;i++){
        if(a[i] > ans){
            ans = a[i];
            l = i, r = i;
        } 
    }
    for(int i = 1;i <= n;i++){
        long long sum = 0;
        if(a[i] <= 0)
            continue;
        for(int j = i;j <= n;j += 2){
