void _main()
{
    ll n; llin(n);
    V<ll> alist; llina(alist, n);

    V<ll> sumlist_even;
    ll sum = 0LL;
    sumlist_even.pb(sum);
    rep (i, n+1LL) {
        ll idx = i * 2LL;
        if (idx >= n) break;
        sum += alist[idx];
        sumlist_even.pb(sum);
    }

    V<ll> sumlist_odd;
    sum = 0LL;
    sumlist_odd.pb(sum);
    rep (i, n+1LL) {
        ll idx = i * 2LL + 1LL;
        if (idx >= n) break;
        sum += alist[idx];
        sumlist_odd.pb(sum);
    }

    ll max_val = -1e18;
    ll max_left = -1LL;
    ll max_right = -1LL;
    bool even = true;

    rep (left, sumlist_even.size()) {
        srep (right, left+1, sumlist_even.size()) {
            ll val = sumlist_even[right] - sumlist_even[left];
            if (val > max_val) {
                max_val = val;
                max_left = left;
                max_right = right;
                even = true;
            }
        }
    }

    rep (left, sumlist_odd.size()) {
        srep (right, left+1, sumlist_odd.size()) {
            ll val = sumlist_odd[right] - sumlist_odd[left];
            if (val > max_val) {
                max_val = val;
                max_left = left;
                max_right = right;
                even = false;
            }
        }
    }

    V<ll> ops;

    if (even) {
        rep (i, n - max_right*2LL + 1LL) ops.pb(n-i);
        rep (i, max_left*2LL) ops.pb(1LL);
        rrep (i, max_right - max_left - 1LL) ops.pb(2LL);
    }
    else {
        rep (i, n - max_right*2LL) ops.pb(n-i);
        rep (i, max_left*2LL+1LL) ops.pb(1LL);
        rrep (i, max_right - max_left - 1LL) ops.pb(2LL);
    }

    cout << max_val << endl;
    cout << ops.size() << endl;
    for (auto op : ops) cout << op << endl;
}

