//この問題は
//・a[0],a[1],a[2],…,a[n-1]が与えられる。
//・,a[i], → +、a[i],→+、,a[i]→+のいずれかをおこなう。
//・+になってないa[i]の和がスコアになる。
//・スコアを最大化する。
//という問題。
//例を挙げると、
//a,b,c,d,e,f,g,h
//+ b,c,d,e,f,g,h
//+ b + d,e,f,g,h
//+ b + d,e + g,h
//+ b + d + + + h
//で, b + d + hがスコアになる感じ。
//
//こういうのは「ありえる状態」を考えると分かりやすい。状態の例として、
//exist[i] = a[i]がまだ+になっておらず残っている
//を考えると、連続する+は奇数個になるので、exist[i] = trueなるiの偶奇は全て等しくなる。
//逆に偶奇さえ等しければ、必ず残す方法が存在する。
//
//連続する+は奇数個の証明：
//・「隣り合う,の間の文字数が奇数」と仮定すると、3つの奇数の和は奇数なので、操作後も「」が成り立つ。
//・最初は「」が真なので、帰納法より常に「」が真。
//・連続する+は、もともと隣り合う,の間の文字だったので、「」より連続する+は奇数個
//
//よって、この問題は、
//・偶数番目について、a[i] >= 0なるiを残す
//・奇数番目について、a[i] >= 0なるiを残す
//の2パターンを考えて、スコアが大きい方を採用すると、解くことができる。
//復元は頑張る。必ず1個以上は要素を残す必要があることに注意する。

#include <iostream>
#include <algorithm>
#include <vector>
#define int long long
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int n;
int a[1000];

signed main() {
	int i, j;

	cin >> n;
	rep(i, n) cin >> a[i];

	int maxId = 0;
	rep(i, n) {
		if (a[maxId] < a[i]) maxId = i;
	}
	if (a[maxId] <= 0) {
		cout << a[maxId] << endl;
		cout << n - 1 << endl;
		rep(i, maxId) cout << 1 << endl;
		rep(i, n - 1 - maxId) cout << 2 << endl;
		return 0;
	}

	int sum[2] = {0};
	vector<int> vec[2];
	rep(i, n) {
		if (a[i] >= 0) {
			sum[i % 2] += a[i];
			vec[i % 2].push_back(i);
		}
	}

	vector<int> ids;
	if (sum[0] > sum[1]) ids = vec[0];
	else ids = vec[1];

	//復元(ids.size() > 0)
	vector<int> ans;
	rep(i, ids[0]) {
		ans.push_back(0);
	}
	rep(i, (int)ids.size() - 1) {
		int mid = (ids[i + 1] - ids[i]) / 2;
		rep(j, mid) {
			ans.push_back(mid - j);
		}
	}
	rep(i, n - ids[ids.size() - 1] - 1) ans.push_back(1);

	//答え
	cout << max(sum[0], sum[1]) << endl;
	cout << ans.size() << endl;
	rep(i, ans.size()) { cout << ans[i] + 1 << endl; }
	return 0;
}

