void solve(istream& in, ostream& out)
{
    int n;
    in >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)
    {
        in >> a[i];
    }
    ll even = 0, odd = 0;
    bool neg = true;
    for (int i = 0; i < n; i++)
    {
        if (a[i] > 0)
        {
            if (i % 2 == 0)
                even += a[i];
            else
                odd += a[i];
            neg = false;
        }
    }
    if (neg)
    {
        int mx = max_element(ALL(a)) - a.begin();
        vi ans;
        while (n - 1 > mx)
        {
            ans.PB(n - 1);
            n--;
        }
        for (int i = 0; i < mx; i++)
        {
            ans.PB(0);
        }
        out << a[mx] << "\n";
        out << SZ(ans) << "\n";
        for (auto x : ans)
        {
            out << x + 1 << "\n";
        }
        return;
    }
    vi ans;
    if (odd > even)
    {
        ans.PB(0);
        a.erase(a.begin());
        n--;
    }
    int pos = -1;
    for (int i = 0; i < n; i += 2)
    {
        if (a[i] > 0)
            pos = i;
    }
    while (n - 1 > pos)
    {
        ans.PB(n - 1);
        n--;
    }
    while (pos >= 2)
    {
        if (a[pos - 2] > 0)
        {
            ans.PB(pos - 1);
        }
        else
        {
            if (pos == 2)
                break;
            ans.PB(pos - 2);
        }
        pos -= 2;
    }
    for (int i = 0; i < pos; i++)
    {
        ans.PB(0);
    }
    out << max(odd, even) << "\n";
    out << SZ(ans) << "\n";
    for (auto x : ans)
    {
        out << x + 1 << "\n";
    }    
}

void check(istream& in, istream& out)
{
    int n;
    in >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)
    {
        in >> a[i];
    }
    ll ans;
    out >> ans;
    int m;
    out >> m;
    for (int i = 0; i < m; i++)
    {
        int x;
        out >> x;
        x--;
        assert(0 <= x);
        assert(x < SZ(a));
        if (x == 0)
            a.erase(a.begin());
        else if (x == SZ(a) - 1)
            a.pop_back();
        else
        {
            a[x] = a[x - 1] + a[x + 1];
            a.erase(a.begin() + x + 1);
            a.erase(a.begin() + x - 1);
        }
    }
    assert(SZ(a) == 1);
    assert(ans == a[0]);
}

