int main() {
    int n;
    std::cin >> n;
    std::vector<i64> even, odd, a;
    i64 maxi = 0, es = 0, os = 0;
    for (int i = 0; i < n; i++) {
        int in;
        std::cin >> in;
        a.push_back(in);
        if (a[maxi] < a[i]) maxi = i;
        if (i % 2) { odd.push_back(in); if (in > 0) os += in; }
        else { even.push_back(in); if (in > 0) es += in; }
    }

    if (a[maxi] <= 0) {
        printf("%lld\n%d\n", a[maxi], n - 1);
        for (int i = n; i > maxi + 1; i--) printf("%d\n", i);
        for (int i = 0; i < maxi; i++) printf("%d\n", 1);
        return 0;
    }

    std::deque<int> q, r;
    if (es > os) {
        for (int i = 0; i < even.size(); i++) {
            if (even[i] > 0) q.push_front(i * 2 + 1);
        }
    } else {
        for (int i = 0; i < odd.size(); i++) {
            // printf("%d %d\n", i, odd[i]);
            if (odd[i] > 0) q.push_front(i * 2 + 2);
        }
    }
    // for (auto i : q) printf("%d ", i); printf("\n%lld %lld\n", es, os);

    for (int i = n; i > q.front(); i--) r.push_back(i);
    for (int i = 0; i < q.size() - 1; i++) {
        for (int j = 0; j < (q[i] - q[i + 1]) / 2; j++) r.push_back((q[i] + q[i + 1]) / 2);
    }
    for (int i = 1; i < q.back(); i++) r.push_back(1);

    printf("%lld\n%ld\n", std::max(es, os), r.size());
    for (int i : r) printf("%d\n", i);

