using namespace std;
typedef long long li;

vector<li> calc_accum(vector<li>& xs) {
    vector<li> acc(xs.size() + 1);
    for (int i = 0; i < xs.size(); ++i) {
        acc[i + 1] = acc[i] + xs[i];
    }
    return acc;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    li n;
    cin >> n;
    vector<li> xs((n + 1) / 2), ys(n / 2);
    for (int i = 0; i < n; ++i) {
        li x;
        cin >> x;
        if (i & 1) {
            ys[i / 2] = x;
        } else {
            xs[i / 2] = x;
        }
    }
    vector<li> x_acc = calc_accum(xs), y_acc = calc_accum(ys);
    li x_max;
    li x_min;
    li y_max;
    li y_min;

    li x_maxsum = -1e9;
    li y_maxsum = -1e9;
    for (int i = 0; i < x_acc.size(); ++i) {
        for (int j = i + 1; j < x_acc.size(); ++j) {
            if (x_acc[j] - x_acc[i] > x_maxsum) {
                x_maxsum = x_acc[j] - x_acc[i];
                x_max = j;
                x_min = i;
            }
        }
    }
    for (int i = 0; i < y_acc.size(); ++i) {
        for (int j = i + 1; j < y_acc.size(); ++j) {
            if (y_acc[j] - y_acc[i] > y_maxsum) {
                y_maxsum = y_acc[j] - y_acc[i];
                y_max = j;
                y_min = i;
            }
        }
    }
    cout << max(x_maxsum, y_maxsum) << endl;

    li front, back, length;
    if (x_maxsum > y_maxsum) {
        front = x_min * 2;
        back = x_max * 2 - 2;
        length = x_max - x_min;
    } else {
        front = y_min * 2 + 1;
        back = y_max * 2 - 1;
        length = y_max - y_min;
    }
    vector<li> ops;
    for (int j = n - 1; j > back; --j) {
        ops.push_back(j);
    }
    for (int j = 0; j < front; ++j) {
        ops.push_back(0);
    }
    for (int k = 0; k < length - 1; ++k) {
        ops.push_back(1);
    }
    cout << ops.size() << endl;
    for (int i = 0; i < ops.size(); ++i) {
        cout << ops[i] + 1 << endl;
    }
    return 0;
}

