vector<int> solve(vector<LL> input) {
  vector<int> ret;
  LL best = -1000001000;
  int N = input.size();
  for (int z = 0; z < 2; z++) {
    if (N <= z) continue;
    vector<int> tmp;
    LL obj = 0;
    for (int i = z; i < N; i += 2) {
      if (input[i] > 0) {
        obj += input[i];
        tmp.push_back(i);
      }
    }
    if (tmp.empty()) {
      tmp.push_back(best - 1);
      obj = best - 1;
      for (int i = z; i < N; i += 2) {
        if (tmp[0] < input[i]) {
          tmp[0] = input[i];
          obj = input[i];
        }
      }
    }

    if (best < obj) {
      best = obj;
      ret = tmp;
    }
  }
  return ret;
}

int main() {
  int N;
  cin >> N;
  vector<LL> vals;
  for (int i = 0; i < N; i++) {
    LL a;
    cin >> a;
    vals.push_back(a);
  }
  vector<int> remain = solve(vals);
  LL best = 0;
  for (auto i : remain) best += vals[i];
  vector<int> diffs;
  adjacent_difference(remain.begin(), remain.end(), back_inserter(diffs));

  vector<int> output;
  for (int i = N - 1; i > remain.back(); i--) output.push_back(i);
  for (int i = 0; i < remain[0]; i++) output.push_back(0);
  for (int i = 1; i < diffs.size(); i++) {
    for (int j = 0; j < diffs[i] / 2 - 1; j++) {
      output.push_back(2);
    }
    output.push_back(1);
  }

  cout << best << endl << output.size() << endl;
  for (auto elem : output) {
    cout << elem + 1 << endl;
  }
  return 0;
}

