				tt = (i + flag) / 2;
				for (int j = 0; j < tt - i; j++)
					ans.push_back(tt + 1 - j);
				flag = i;
			}
		}
		else {
			if (visit[i]) flag = i;
			else ans.push_back(i + 1);
		}
	}

	for (int i = 0; i < n; i++) {
		if (visit[i]) break;
		ans.push_back(1);
	}

	printf("%d\n", sz(ans));
	for (int i = 0; i < sz(ans); i++)
		printf("%d\n", ans[i]);
}

