pair<ll, vector<int>> mss(vector<ll> v) {
  ll t = v[0];
  vector<int> ti;
  ti.push_back(0);

  ll res = t;
  vector<int> res_idx;

  for (int i = 1; i < (int)v.size(); i++) {
    if (t + v[i] > v[i]) {
      t = t + v[i];
      ti.push_back(i);
    } else {
      t = v[i];
      ti.clear();
      ti.push_back(i);
    }
    if (res < t) {
      res = t;
      res_idx = ti;
    }
  }
  return {res, res_idx};
}

