        for (int j = 1; j < i; j ++) {
            if ((i % 2) == (j % 2) && dp[j] + a[i] >= dp[i]) {
                dp[i] = dp[j] + a[i],pr[i] = j;
            }
        }
        if (mx <= dp[i])
            mx = dp[i],cur = i;
    }

    cout << mx << endl;

    if (cur != n) {
        if (n % 2 == cur % 2)
            v.pb(n);

        int md = (cur + n + 1) / 2;

        for (int i = md; i >= cur + 1; i --)
            v.pb(i);
    }

    while (1) {
        int o = pr[cur];
        int m = (cur + o) / 2;
        for (int i = m; i > o; i --)
            v.pb(i);
        if (cur == o)
            break;
        cur = o;
    }
    if (cur != 1) {
           cur --;
           int f = 1;
           if (cur % 2 != 1)
                v.pb(1),f = 2;

            int md = (cur + f) / 2;

        for (int i = md; i >= f; i --)
            v.pb(i);
    }
    cout << v.size() << endl;

    for (int i = 0; i < v.size(); i ++)
        cout << v[i] << endl;
}

