typedef long long ll;
const int maxn = 1000 + 10;
int N, A[maxn], q[maxn], pre[maxn][maxn]; ll f[maxn][maxn];

void work(int l, int r, int lft)
{
	if(l >= r) return; int lst = pre[l][r];
	if(lst == l) { q[++q[0]] = 1, work(l+1, r, lft); return; }
	if(lst == r) { q[++q[0]] = r-l+1, work(l, r-1, lft); return; }
	work(l, lst-1, lft), work(lst+1, r, lft+2);
	q[++q[0]] = lst - l + 1 + lft;
}

void Init()
{
	scanf("%d", &N);
	for(int i = 1; i <= N; ++i)
		scanf("%d", &A[i]), f[i][i] = A[i];
}

void Solve()
{
	for(int i = N-1; i >= 1; --i)
	{
		int lst = i;
		for(int j = i+1; j <= N; ++j)
		{
			int pos = 0;
			for(int k = max(i, lst-10); k <= min(j, lst+10); ++k)
				if(f[i][k-1]+f[k+1][j] > f[i][j])
					f[i][j] = f[i][k-1]+f[k+1][j], pos = k;
			lst = pos, pre[i][j] = pos;
		}
	}
	printf("%lld\n", f[1][N]), work(1, N, 0);
	for(int i = 0; i <= q[0]; ++i) printf("%d\n", q[i]);
}

int main()
{
