ll calc(int l, int r) {
    if (dp[l][r] != None) return dp[l][r];
    ll& ret = dp[l][r];
    int& cur = mem[l][r];
    if (r - l == 1) {
        cur = -1;
        return ret = a[l];
    }
    //  ret = max(calc(l, r-1), calc(l+1, r));
    if (calc(l, r - 1) < calc(l + 1, r)) {
        ret = calc(l + 1, r);
        cur = l;
    } else {
        ret = calc(l, r - 1);
        cur = r - 1;
    }
    REP(m, l + 1, r - 1) {
        //    ret = max(ret, calc(l, m) + calc(m+1, r));
        if (ret < calc(l, m) + calc(m + 1, r)) {
            ret = calc(l, m) + calc(m + 1, r);
            cur = m;
        }
    }
    return ret;
}



vector<int> v;
void dfs(int l, int r) {
    if (mem[l][r] < 0) return;
    int m = mem[l][r];
    // cout << m << " (" << l << " " << r << ") " << endl;
    v.push_back(st.order_of_key(m));
    if (m == l || m == r - 1) {
        st.erase(m);
    } else {
        auto pre = st.lower_bound(m);
        if (pre != st.begin()) {
            --pre;
            st.erase(pre);
        }
        auto pst = st.upper_bound(m);
        if (pst != st.end()) {
            st.erase(pst);
        }
    }
    if (m == l) {
        dfs(l + 1, r);
    } else if (m == r - 1) {
        dfs(l, r - 1);
    } else {
        dfs(l, m);
        dfs(m + 1, r);
    }
    // cout << m << " (" << l << " " << r << ") " << endl;
    // dumpV(st);
}

