using namespace std;
template<typename T>inline void read(T &x)
{
    T s=0,f=1;char k=getchar();
    while(!isdigit(k)&&(k^'-'))k=getchar();
    if(!isdigit(k)){f=-1;k=getchar();}
    while(isdigit(k)){s=s*10+(k^48);k=getchar();}
    x=s*f;
}
const int MAXN=2222;
static int n;
static long long dp[MAXN][MAXN],s[MAXN][MAXN],a[MAXN];
inline void init()
{
	memset(dp,0x3f,sizeof dp);
	read(n);
	Rep(i,1,n)read(a[i]);
	Rep(i,0,n)dp[i][i]=-a[i],s[i][i]=i;
	Rep(i,0,n-1)dp[i][i+1]=-max(a[i],a[i+1]),s[i][i+1]=a[i]>a[i+1]?i+1:i;
}
static int ans,q[MAXN];
static int laz;
void dfs(int l,int r)
{
	if(l>=r)return;
	dfs(l,s[l][r]-1);
	if(s[l][r]-ans>0)
	{
		q[ans+1]=s[l][r]-(2*ans-laz),++ans;
		if(s[l][r]-(2*ans-laz-2)==1)++laz;
	}
	dfs(s[l][r]+1,r);
}
inline void solve()
{
	Rep(i,3,n+1)Rep(j,0,n-i+1)Rep(k,s[j][j+i-2],s[j+1][j+i-1])
	{
		if(k==j)dp[j][k-1]=0;
		if(dp[j][k-1]>=dp[n+1][n+1]||dp[k+1][j+i-1]>=dp[n+1][n+1])continue;
		if(dp[j][j+i-1]>dp[j][k-1]+dp[k+1][j+i-1])
		{
			dp[j][j+i-1]=dp[j][k-1]+dp[k+1][j+i-1];
			s[j][j+i-1]=k;
		}
	}
	printf("%lld\n",-dp[0][n]);
	dfs(0,n);
	printf("%d\n",ans);
	Rep(i,1,ans)printf("%d\n",q[i]);
}
int main()
{
	init();
	solve();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
vector<ll> values;
int n;
vector<int> operations;
ll memo[2010];
bool done[2010];
ll dp(int a)
{
	if (done[a]) return memo[a];
	done[a] = 1;
	ll ans = 0;
	for (int i = a + 2; i < n; i+=2)
	{
		ans = max(ans, dp(i) + values[i]);
	}
	return memo[a] = ans;
}
void findoptimal(int a, int alreadygone)
{
	pair<ll, int> best = {0, 0};
	for (int i = a + 2; i < n; i+=2)
	{
		best = max(best, { dp(i) + values[i], i });
	}
	if (best.first)
	{
		int s = a-alreadygone;
		int e = best.second-alreadygone;
		while (s != e)
		{
			int mid = (s+e)/2;
			operations.push_back(mid+1);
			alreadygone+=2;
			e-=2;
		}
		findoptimal(best.second, alreadygone);
	}
	else
	{
		int sz = n-a;
		while (sz != 1)
		{
			operations.push_back(sz);
			sz--;
		}
	}
}
int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		ll a;
		scanf("%lld", &a);
		values.push_back(a);
	}
	pair<ll, ll> best = { -2e15, 0 };
	for (int i = 0; i < n; i++)
	{
		best = max(best, { dp(i) + values[i], i });
	}
	//printf("%lld %d\n", best.first, best.second);
	for (int i = 0; i < best.second; i++)
	{
		operations.push_back(1);
	}
	findoptimal(best.second, best.second);
	printf("%lld\n%d\n", best.first, operations.size());
	for (auto a : operations) printf("%d\n", a);
}

