        //remove center
        while(g[k]!=-1){
            int p=g[k];
            for(int i=p+((k-p)>>1); i>p; i--){
                    foo.push_back(i);
            }
            k=p;
        }
        //remove heading
        for(int i=0; i<k; i++)foo.push_back(0);
        printf("%d\n", SIZE(foo));
        for(const int p : foo){
            printf("%d\n", p+1);
        }
    }
