void solve(long long N, vector<long long> a)
{
    bool flag = true;
    for (auto i : a) {
        if (i > 0) {
            flag = false;
            break;
        }
    }
    if (flag) {
        int Max = a[0], p = 0;
        for (int i = 0; i < N; ++i) {
            if (a[i] > Max) {
                Max = a[i];
                p = i;
            }
        }
        printf("%d\n", Max);
        for (int i = 0; i < p; ++i) {
            printf("%d\n", 1);
        }
        for (int i = p + 1; i < N; ++i) {
            printf("%d\n", 2);
        }
        return;
    }
    LL x1 = 0;
    for (int i = 0; i < N; i += 2) {
        if (a[i] > 0)
            x1 += a[i];
    }
    LL x2 = 0;
    for (int i = 1; i < N; i += 2) {
        if (a[i] > 0)
            x2 += a[i];
    }
    vector<int> ans;
    vector<int> b;
    for (int i = 1; i <= N; ++i) {
        b.push_back(0);
    }
    if (x1 > x2) {
        printf("%lld\n", x1);
        for (int i = 0; i < N; i += 2) {
            if (a[i] > 0) {
                b[i] = 1;
            }
        }
    } else {
        printf("%lld\n", x2);
        for (int i = 1; i < N; i += 2) {
            if (a[i] > 0) {
                b[i] = 1;
            }
        }
    }
    for (int i = 0; i < b.size(); ++i) {
        if (b[i] == 0) {
            if (i == 0 || i == b.size() - 1 || (b[i - 1] == 0 && b[i + 1] == 0)) {
                ans.push_back(i + 1);
                if (i == 0 || i == b.size() - 1) {
                    b.erase(b.begin() + i);
                    --i;
                } else {
                    b.erase(b.begin() + i + 1);
                    b.erase(b.begin() + i - 1);
                    i -= 2;
                }
            }
        }
    }
    for (int i = 0; i < b.size(); ++i) {
        if (b[i] == 0 && b[i - 1] == 1 && b[i + 1] == 1) {
            ans.push_back(i + 1);
            b.erase(b.begin() + i + 1);
            b.erase(b.begin() + i);
            i --;
        }
    }
    printf("%d\n", int(ans.size()));
    for (auto i : ans) {
        printf("%d\n", i);
    }
}

