const int MAXN = 1050;

int n;
int a[MAXN];
long long sumOdd, sumEven;
int mxOdd, mxEven;

int main() {

    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    mxEven = a[0]; mxOdd = a[1];
    for (int i = 0; i < n; i++) {
        if (i & 1) {
            mxOdd = max(mxOdd, a[i]);
            if (a[i] >= 0) {
                sumOdd += a[i];
            }
        } else {
            mxEven = max(mxEven, a[i]);
            if (a[i] >= 0) {
                sumEven += a[i];
            }
        }
    }

    long long ansOdd = mxOdd;
    if (mxOdd >= 0) ansOdd = sumOdd;
    long long ansEven = mxEven;
    if (mxEven >= 0) ansEven = sumEven;

    vector<int> taken;
    if (ansOdd > ansEven) {
        for (int i = 1; i < n; i += 2) {
            if ((mxOdd >= 0 && a[i] >= 0) || (mxOdd < 0 && a[i] == mxOdd)) {
                taken.push_back(i);
            }
        }
    } else {
        for (int i = 0; i < n; i += 2) {
            if ((mxEven >= 0 && a[i] >= 0) || (mxEven < 0 && a[i] == mxEven)) {
                taken.push_back(i);
            }
        }
    }

    vector<int> ops;

    int last = taken.back();
    for (int i = n - 1; i >= last + 1; i--) {
        ops.push_back(i);
    }

    int removed = 0;
    for (int i = 0; i < taken[0]; i++) {
        ops.push_back(0);
        removed++;
    }

    for (int i = 0; i + 1 < sz(taken); i++) {
        for (int j = taken[i] + 2; j < taken[i + 1]; j += 2) {
            ops.push_back(taken[i] + 2 - removed);
        }
        ops.push_back(taken[i] + 1 - removed);
        removed += taken[i + 1] - taken[i];
    }

    cout << max(ansOdd, ansEven) << endl;
    cout << sz(ops) << endl;
    for (auto op : ops)
        printf("%d\n", op + 1);

    return 0;
}

