    vector<long long> dp(n + 1, -INF);
    dp[0] = 0;
    vector<pair<int, pair<int,int>>> pre(n + 1, make_pair(-1, make_pair(-1, -1))); 
    for (int i = 0; i < n; ++i) {
        long long sum = 0;
        long long& ans = dp[i + 1];
        for (int j = i; j >= 0; j -= 2) {
            sum += A[j];
            if (ans < sum) {
                ans = sum;
                pre[i + 1] = make_pair(0, make_pair(j + 1, i + 1));
            }
            if (j - 2 >= 0 && ans < sum + dp[j - 2 + 1]) {
                ans = sum + dp[j - 2 + 1];
                pre[i + 1] = make_pair(pre[j - 2 + 1].second.second, make_pair(j + 1, i + 1));
            }
        }
        if (i - 2 >= 0 && dp[i - 2 + 1] > ans) {
            ans = dp[i - 2 + 1];
            pre[i + 1] = pre[i - 2 + 1];
        }
    }
    long long res = *max_element(dp.begin() + 1, dp.end());
    cout << res << '\n';
    vector<pair<int,int>> segs;
    {
        int cur = 0;
        for (int i = 1; i <= n; ++i) {
            if (dp[i] == res) {
                cur = i;
                break;
            }
        }
        // cout << cur << endl;
        while (cur > 0) {
            int l = pre[cur].second.first;
            int r = pre[cur].second.second;
            segs.emplace_back(l, r);
            cur = pre[cur].first;
        }
    }
    reverse(segs.begin(), segs.end());
    int revs = 0;

    vector<int> ops;
    if (!segs.empty()) {
        for (auto& s : segs) {
            // cout << s.first << " - " << s.second << '\n';
        }
        for (int i = 1; i < segs[0].first; ++i) {
            ops.push_back(1);
        }
        for (int i = n, j = 0; i > segs.back().second; --i, ++j) {
            ops.push_back(n - segs[0].first + 1 - j);
        }
        for (int j = 0; j < segs.size(); ++j) {
            int l = j == 0 ? 1 : 3;
            int r = segs[j].second - segs[j].first + l;
            for (int x = 2; x < r; x += 2) {
                ops.push_back(2);
            }

            if (j < segs.size()) {
                int ll = 2;
                int rr = segs[j + 1].first - 1 - segs[j].second - 1 + ll;
                for (int x = 3; x < rr; x += 2) {
                    ops.push_back(3);
                }
            }

        }
    } else {
        assert(0);
    }

    cout << ops.size() << '\n';
    for (auto x : ops) {
        cout << x << '\n';
    }

    return 0;
}

