	tot += a[j];
      }
      ma2 = max(ma2, make_pair(a[j], j));
    }
    if (pop[i].size() == 0) {
      tot = ma2.first;
      pop[i].push_back(ma2.second);
    }
    ma = max(ma, make_pair(tot, i));
  }
  int ind = ma.second;
  VI arr = pop[ind];
  assert (arr.size() > 0);
  VI op;
  int fst = arr[0];
  int lst = arr[arr.size() - 1];
  for (int i = n - 1; i >= lst + 1; --i) {
    op.push_back(i);
  }
  REP(i, 0, fst) {
    op.push_back(0);
  }
  REP(i, 0, arr.size() - 1) {
    int intv = arr[i + 1] - arr[i];
    assert (intv % 2 == 0);
    for (int j = intv / 2; j >= 1; --j) {
      op.push_back(j);
    }
  }
  cout << ma.first << endl;
  cout << op.size() << endl;
  REP(i, 0, op.size()) {
    cout << op[i] + 1 << endl;
  }
}

