void sub(vi& killer) {
    int N = killer.size();
    assert(accumulate(ALL(killer),0) < N);

    vi ops;
    int left_x = 0, right_x = 0;
    for (int x=0; x<N; ++x) {
        if (killer[x]) left_x++;
        else break;
    }
    for (int x=N-1; x>=0; --x) {
        if (killer[x]) right_x++;
        else break;
    }

    rep(i, right_x) {
        ops.pb(N-1-i);
    }
    killer.erase(killer.begin()+N-right_x, killer.end());

    rep(i, left_x) {
        ops.pb(0);
    }
    killer.erase(killer.begin(), killer.begin()+left_x);

    N = killer.size();
    assert(killer[0] == 0 && killer[N-1] == 0);

    for (int i=0; i<N; ++i) {
        if (!killer[i]) { continue; }

        for (int j=i+1; j<N; ++j){
            if (killer[j]) continue;
            killer.erase(killer.begin()+i-1, killer.begin()+j);
            int w = j-i;
            N -= w+1;
            while (w > 1) {
                ops.pb(i+1);
                w -= 2;
            }
            assert(w == 1);
            ops.pb(i);
            break;
        }
        --i;
    }
    assert(N == 1);

    cout << ops.size() << endl;
    for (int ix : ops) {
        cout << 1+ix << endl;
    }
}

void solve(int N, vll& a) {
    vi killer(N, 1);

    ll peak = *max_element(ALL(a)), maxv;
    if (peak < 0) {
        int at = -1; rep(i,N) if (a[i] == peak) { at = i; break; }
        maxv = peak; killer[at] = 0;
    } else {
        ll e0 = estim(a, 0), e1 = estim(a, 1);
        if (e0 >= e1) {
            rep(i,N) if (i%2 == 0 && a[i] >= 0) killer[i] = 0;
            maxv = e0;
        } else {
            rep(i,N) if (i%2 == 1 && a[i] >= 0) killer[i] = 0;
            maxv = e1;
        }
    }

    cout << maxv << endl;
    sub(killer);
}
