int main(){
      scanf("%d", &n);

      for(int i = 1; i <= n; i ++){
            scanf("%d", &a[i]);
            dp[i] = a[i];
            par[i] = i;
      }

      for(int i = 1; i <= n; i ++){
            for(int j = i - 2; j >= 1; j -= 2){
                  if(dp[j] + a[i] > dp[i]){
                        dp[i] = dp[j] + a[i];
                        par[i] = j;
                  }
            }
      }

      for(int i = 1; i <= n; i ++){
            if(mx < dp[i]){
                  mx = dp[i];
                  ind = i;
            }
      }

      cout << mx << endl;

      for(int i = n; i > ind; i --){
            ans.push_back(i);
      }

      while(ind != par[ind]){
            int md = (ind + par[ind]) >> 1;
            for(int i = md; i > par[ind]; i --)
                  ans.push_back(i);
            ind = par[ind];
      }

      for(int i = 1; i < ind; i ++)
            ans.push_back(1);

      cout << ans.size() << endl;

      for(int i : ans)
            cout << i << endl;
