int get(int i, int j) {
	if(i == j) return a[i];
	int &ret = dp[i][j];
	if(vis[i][j]) return ret;
	vis[i][j] = true;
	ret = -1e15;
	for(int k=i+1; k<j; k++) {
		ret = max(ret, get(i, k-1) + get(k+1, j));
	} return ret;
}

void print(int i, int j) {
	//cout<<II(i, j)<<endl;
	assert(i != j-1);
	if(i == j) return;
	for(int k=i+1; k<j; k++) {
		if(get(i, k-1) + get(k+1, j) == get(i, j)) {
			print(i, k-1);
			print(k+1, j);
			v.push_back(k);
			break;
		}
	}
}

