ll ans[MAXN],cnt1,cnt2;
inline bool check_all()
{
	for(int i=1;i<=n;i++) if(a[i]>0) return 0;
	return 1;
}
int main()
{
	cin>>n;
	for(int i=1;i<=n;i++) cin>>a[i];
	if(check_all()){
		cout<<"0"<<endl<<n<<endl;
		for(int i=1;i<=n;i++) cout<<1<<endl;
		return 0;
	}
	for(int i=1;i<=n;i++){
		if(a[i]>0){
			if(i&1) cnt1+=a[i];
			else cnt2+=a[i];
		}
	}
	if(cnt1>cnt2){
		cout<<cnt1<<endl;
		flag=1;
	} else {
		cout<<cnt2<<endl;
		flag=2;
	}
	for(int i=flag;i<=n;i+=2) if(a[i]>0) pre[++cnt]=i;
		int now=pre[cnt];
		for(int i=n;i>=pre[cnt]+1;i--) ans[++num]=i;
		for(int i=cnt-1;i>=1;i--){
			int last=now; now=pre[i];
			int mid=last+now>>1;
			int k=last-now+1;
			while(k>1){
				ans[++num]=mid;
				k-=2;
