using namespace std;

typedef long long ll;

mt19937 rnd(228);

const int N = 1000 + 7;

ll dp[N][N][2][2];
int opt[N][N][2][2];
int type[N][N][2][2];

vector <int> ans;

void restore(int l, int r, int a, int b)
{
    if (l == r)
    {
        return;
    }
    else
    {
        if (type[l][r][a][b] == 1)
        {
            restore(l, opt[l][r][a][b] - 1, a, 1);
            restore(opt[l][r][a][b] + 1, r, 1, b);
            ans.push_back(opt[l][r][a][b]);
        }
        else if (type[l][r][a][b] == 2)
        {
            ans.push_back(l);
            restore(l + 1, r, a, b);
        }
        else
        {
            ans.push_back(r);
            restore(l, r - 1, a, b);
        }
    }
}

int main()
{
#ifdef ONPC
    freopen("a.in", "r", stdin);
#endif
    int n;
    scanf("%d", &n);
    vector <int> a(n);
    for (int i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
    }
    for (int len = 1; len <= n; len++)
    {
        for (int i = 0; i + len - 1 < n; i++)
        {
            for (int x = 0; x < 2; x++)
            {
                for (int y = 0; y < 2; y++)
                {
                    int j = i + len - 1;
                    if (len == 1)
                    {
                        dp[i][j][x][y] = a[i];
                        opt[i][j][x][y] = i;
                    }
                    else
                    {
                        dp[i][j][x][y] = -1e18;
                        if (x == 0)
                        {
                            dp[i][j][x][y] = max(dp[i][j][x][y], dp[i + 1][j][x][y]);
                        }
                        if (y == 0)
                        {
                            dp[i][j][x][y] = max(dp[i][j][x][y], dp[i][j - 1][x][y]);
                        }
                        ll best = -1e18;
                        for (int t = i + 1; t < j; t++)
                        {
                            if (dp[i][t - 1][x][1] + dp[t + 1][j][1][y] > best)
                            {
                                best = dp[i][t - 1][x][1] + dp[t + 1][j][1][y];
                                opt[i][j][x][y] = t;
                            }
                        }
                        if (best > dp[i][j][x][y])
                        {
                            dp[i][j][x][y] = best;
                            type[i][j][x][y] = 1;
                        }
                        else
                        {
                            if (!x && dp[i + 1][j][x][y] == dp[i][j][x][y])
                            {
                                type[i][j][x][y] = 2;
                            }
                            else
                            {
                                type[i][j][x][y] = 3;
                            }
                        }
                    }
                }
            }
        }
    }
    restore(0, n - 1, 0, 0);
    vector <int> p(n);
    for (int i = 0; i < n; i++)
    {
        p[i] = i;
    }
    cout << dp[0][n - 1][0][0] << '\n';
    cout << ans.size() << '\n';
    for (int x : ans)
    {
        int ind = -1;
        for (int j = 0; j < (int) p.size(); j++)
        {
            if (p[j] == x)
            {
                ind = j;
            }
        }
        cout << ind + 1 << '\n';
        p.erase(p.begin() + ind);
    }
}

