void solve(){
    ll N; cin >> N;
    vector<ll> a(N); for(auto& in:a) cin >> in;
    vector<int> flag(N);
    bool minusflag = true;
    for(int i = 0; i < N;i++){
        if(a[i] > 0) minusflag = false;
    }
    if(minusflag){
        ll idx = max_element(a.begin(), a.end()) - a.begin();
        flag[idx] = 1;
        cout << a[idx] << endl;
        cout << N-1 << endl;
        while(flag.size()!=1){
            if(flag[0] == 0){
                cout << 1 << endl;
                flag.erase(flag.begin());
            }else{
                cout << flag.size() << endl;
                flag.erase(flag.begin()+flag.size()-1);
            }
        }
    }else{
        ll even = 0,odd = 0;
        for(int i = 0; i < N;i++){
            if(a[i] > 0){
                if(i%2) odd += a[i];
                else even += a[i];
            }
        }
        if(even >= odd){
            for(int i = 0; i < N;i++){
                if(a[i] > 0){
                    if(i%2 == 0) flag[i] = 1;
                }
            }
        }else{
            for(int i = 0; i < N;i++){
                if(a[i] > 0){
                    if(i%2) flag[i] = 1;
                }
            }
        }

        cout << max(even,odd) << endl;
        vector<ll> com;
        while(*flag.begin() == 0){
            com.push_back(1);
            flag.erase(flag.begin());
        }
        while(*flag.rbegin() == 0){
            com.push_back(flag.size());
            flag.erase(flag.begin()+flag.size()-1);
        }

        while(true){
            bool update = false;
            for(int i = 1; i < flag.size()-1;i++){
                if(flag[i] == 0){
                    if(flag[i-1] == 1 && flag[i+1] == 1){
                        a[i-1] += a[i+1];
                        a.erase(a.begin()+i,a.begin()+i+2);
                        com.push_back(i+1);
                        flag.erase(flag.begin()+i,flag.begin()+i+2);
                        //flag.erase(flag.begin()+i);
                        update = true;
                        break;
                    }
                    if(flag[i-1] == 0 && flag[i+1] == 0){
                        a[i-1] += a[i+1];
                        a.erase(a.begin()+i,a.begin()+i+2);
                        com.push_back(i+1);
                        flag.erase(flag.begin()+i,flag.begin()+i+2);
                        //flag.erase(flag.begin()+i);
                        update = true;
                        break;
                    }
                }
            }
            if(update) continue;
            break;
        }

        cout << com.size() << endl;
        for(auto v :com){
            cout << v << endl;
        }
    }
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    solve();
    return 0;
}

