#define ll long long
using namespace std;

ll sumup(vector<pair<ll, int>> &v, vector<int> &u){
    ll res=v[0].first;
    u.push_back(v[0].second);
    for(int i=1; i<v.size(); ++i){
        if(v[i].first<=0) break;
        res += v[i].first;
        u.push_back(v[i].second);
    }
    return res;
}

int main() {
	int N;
	cin >> N;
	vector<ll> v(N);
	vector<pair<ll, int>> ev, od;
	for(int i=0; i<N; ++i){
	    cin >> v[i];
	    if(i%2==0) ev.push_back(make_pair(v[i], i));
	    else od.push_back(make_pair(v[i], i));
	}
	sort(ev.begin(), ev.end(), greater<pair<ll, int>>());
	sort(od.begin(), od.end(), greater<pair<ll, int>>());
	vector<int> e_ans, o_ans, ans, sol;
	ll e_sum=sumup(ev, e_ans), o_sum=sumup(od, o_ans);
	if(e_sum>o_sum){
	    cout << e_sum << endl;
	    ans.swap(e_ans);
	}
	else{
	    cout << o_sum << endl;
	    ans.swap(o_ans);
	}
	sort(ans.begin(), ans.end(), greater<int>());
	int now=0, num=N-1;
	while(num>=0){
	    if(num>ans[now]){
	        sol.push_back(num);
	        --num;
	    }
	    else if(now+1==ans.size()){
	        for(int i=0; i<num; ++i){
	            sol.push_back(0);
	        }
	        num=-1;
	    }
	    else if(ans[now+1]+2==num){
	        sol.push_back(num-1);
	        ++now;
	        num -= 2;
	    }
	    else{
	        sol.push_back(num-2);
	        ans[now] -= 2;
	        num -= 2;
	    }
	}
	cout << sol.size() << endl;
	for(int i=0; i<sol.size(); ++i) cout << sol[i]+1 << endl;
	return 0;
}

