long long MAX = -LONG_MAX;
pair<int,int> range = {0,1};
void set_max_even(){
  for(int r = 1;r <= n;r += 2){
    for(int l = 0;l < r;l += 2){
      if(chmax(MAX,even[r] - even[l])){
        range = {l,r};
      }
    }
  }
}

void set_max_odd(){
  for(int r = 2;r <= n;r += 2){
    for(int l = 1;l < r;l += 2){
      if(chmax(MAX,odd[r] - odd[l])){
        range = {l,r};
      }
    }
  }
}

