				L = i; R = j; mx = tmp; 
			}
		}
	}
	cout << mx << endl; 
	vector<int> E; 
	for(int i = N; i > R; i--) E.push_back(i); 
	for(int i = 1; i < L; i++) E.push_back(1);
	for(int i = 2; i < (R-L) / 2 + 2; i++) E.push_back(2); 
	cout << E.size() << endl; 
	for(int i = 0; i < E.size(); i++) cout << E.at(i) << endl;  
}

