	pii solve(ll &ans)
	{
		f[0]=-1000000007,g[0]=0;
		for(int i=1;i<=n;i++)
		{
			if(f[i-1]+s[i]>0)
			{
				f[i]=f[i-1]+s[i];
				g[i]=g[i-1];
			}
			else
			{
				f[i]=s[i];
				g[i]=i;
			}
		}

		pii ret(-1,-1);
		ans=-1000000007;
		for(int i=1;i<=n;i++)
			if(f[i]>ans)
			{
				ans=f[i];
				ret=pii(g[i],i);
			}

		return ret;
	}

