void make_op(int parity, int pos = -1){
	vector<int> mark(n, 0);

	if(pos == -1)
		for(int i = parity; i < n; i+=2){
			if(v[i] >= 0)
			mark[i] = 1;
		}
	else mark[pos] = 1;
	//cout << pos << endl;

	while(mark.size() > 1){

		for(int l = 0; l < mark.size(); l++){
			if(mark[l]) continue;
			if(l == 0 || l == mark.size()-1){
				ans.push_back(l+1);
				mark.erase(mark.begin() + l);
				continue;
			}
			if((mark[l-1] && mark[l+1]) || (!mark[l-1] && !mark[l+1])){
				ans.push_back(l+1);
				if(mark[l-1]) mark[l] = 1;
				mark.erase(mark.begin()+l+1);
				mark.erase(mark.begin()+l-1);
				break;
			}
		}

	}
	cout << ans.size() <<"\n";
	for(auto &u : ans){
		cout << u << "\n";
	}
}
