        last = i;
      } else {
        // nothing
      }
    }
    if(last >= 0) {
      REP(i, n-last-1) {
        hoge.push_back(rest);
        --rest;
      }
    }
    if(exist && cur > best) {
      best = cur;
      ans.swap(hoge);
    }
  }
  printf("%lld\n", best);
  printf("%d\n", (int)ans.size());
  REP(i, ans.size()) {
    printf("%d\n", ans[i]);
  }

  return 0;
}

