#define MAX_N 1000

using namespace std;

typedef long long lint;

lint sum[2];
lint v[MAX_N + 1];

int n, cate;

int stkLen;
int stk[MAX_N + 1];

int luat[MAX_N + 1];

void ops(int nr)
{
    int i;
    int cat = 0;
    for(i = 1; i <= nr; i ++)
        cat += 1 - luat[i];

    if(cat == 1 || cat == cate)
    {
        luat[nr] = 1;
        stk[++ stkLen] = cat;
        cate --;

       // cout << "OPS 1 " << cat << " " << cate << "\n";

        return;
    }

    int ant = nr - 1;
    int urm = nr + 1;
    while(luat[ant] == 1)
        ant --;

    while(luat[urm] == 1)
        urm ++;

    luat[ant] = 1;
    luat[urm] = 1;
    stk[++ stkLen] = cat;
    v[nr] = v[ant] + v[urm];
    cate -= 2;
      //  cout << "OPS 2 " << cat << " " << cate << "\n";
}

void doOps(int s2)
{
    int i;
    int cnt = 0;
    for(i = 1; i <= n; i ++)
    {
        if(luat[i] == 0)
            cnt ++;

        if(cnt == s2)
        {
            cnt = i;
            break;
        }
    }

    ops(cnt);
}

