{
    cin >> n;
    cate = n;

    int i;
    for(i = 1; i <= n; i ++)
    {
        cin >> v[i];
        sum[i & 1] += v[i] * (v[i] > 0);
    }

    int s2 = 0;
    int start = 0;
    if(sum[0] > sum[1])
        start = 2, s2 = 3;

    else
        start = 1, s2 = 2;

    for(i = start; i <= n; i += 2)
    {
        if(v[i] < 0)
            ops(i);
    }

    while(s2 + 1 <= cate)
    {
        doOps(s2);
    }

    for(i = 1; i < s2 - 1   ; i ++)
        doOps(1);

   // cout << cate << "\n";

    while(cate > 1)
    {
        doOps(cate);
        cate --;
    }

    cout << max(sum[0], sum[1]) << "\n";
    cout << stkLen << "\n";

    for(i = 1; i <= stkLen; i ++)
