#include <bits/stdc++.h>
using namespace std;

int n;
int64_t a[1010];
const int64_t INF = 1e18;
int64_t dp[1010][1010];
int memo[1010][1010];
vector<int> ans;

int64_t dfs(int l, int r) {
	if(l + 1 == r) return dp[l][r] = a[l];
	if(dp[l][r] != -INF) return dp[l][r];
	int64_t ret = -INF;
	int mem = -1;
	for(int i = l; i < r; ++i) {
		if(i == l) {
			int64_t nxt = dfs(l + 1, r);
			if(nxt > ret) {
				ret = nxt;
				mem = i;
			}
		} else if(i == r - 1) {
			int64_t nxt = dfs(l, r - 1);
			if(nxt > ret) {
				ret = nxt;
				mem = i;
			}
		} else {
			int64_t nxt = dfs(l, i) + dfs(i + 1, r);
			if(nxt > ret) {
				ret = nxt;
				mem = i;
			}
		}
	}
	memo[l][r] = mem;
	return dp[l][r] = ret;
}

void rec(int l, int r) {
	if(l >= r) return;
	if(memo[l][r] == -1) return;
	ans.push_back(memo[l][r] - l);
	rec(l, memo[l][r]);
	rec(memo[l][r] + 1, r);
}

int main() {
	cin >> n;
	for(int i = 0; i < n; ++i) {
		cin >> a[i];
	}
	for(int i = 0; i < 1010; ++i) {
		for(int j = 0; j < 1010; ++j) {
			dp[i][j] = -INF;
			memo[i][j] = -1;
		}
	}
	cout << dfs(0, n) << '\n';
	rec(0, n);
	cout << ans.size() << '\n';
	for(int i : ans) {
		cout << i + 1 << '\n';
	}
	return 0;
}

