  debug(a);

  auto find = [&] (auto&& a) {
    int n = a.size();
    std::partial_sum(all(a),a.begin());
    a.insert(a.begin(),0ll);
    debug(a);

    lint l = 0, r = 0, dif = -1;
    lint i = 0, x = a.at(i);
    rep(j,0,n+1) {
      lint y = a.at(j);
      if (cmx(dif, y - x)) {
        l = i, r = j;
      }
      if (cmn(x,y)) {
        i = j;
      }
    }
    r--;
