    lint i = 0, x = a.at(i);
    rep(j,0,n+1) {
      int y = a.at(j);
      if (cmx(dif, y - x)) {
        l = i, r = j;
      }
      if (cmn(x,y)) {
        i = j;
      }
    }
    r--;
    return std::make_tuple(l,r,dif);
