#include <bits/stdc++.h>
using namespace std;
#define ll long long

const int N = 1e3+3;
const ll minInf = -1e18;
ll dp[N][N];
bool dpComplete[N][N];
int par[N][N];
int A[N];

ll solveDp(int l,int r) {
    if(l==r) {
        return A[l];
    }
    if(r-l+1==2 || l>r) {
        return minInf;
    }
    ll &ret = dp[l][r];
    if(dpComplete[l][r]) {
        return ret;
    }
    ret = minInf;
    for(int i = l+1;i<r;++i) {
        ll tmp = solveDp(l,i-1) + solveDp(i+1,r);
        if(tmp>ret) {
            ret = tmp;
            par[l][r] = i;
        }
    }
    return ret;
}
void dfs(vector<int> &pos,int l,int r) {
    if(l==r) {
        return;
    }
    assert(r-l+1!=2 && l<=r);
    int p = par[l][r];
    pos.push_back(p);
    dfs(pos,l,p-1);
    dfs(pos,p+1,r);
}
int pen[N];
void update(int ind,int add) {
    while(ind<N) {
        pen[ind] += add;
        ind += ind&(-ind);
    }
}
int query(int ind) {
    int ret = 0;
    while(ind>0) {
        ret += pen[ind];
        ind = ind&(ind-1);
    }
    return ret;
}
void solve() {
    memset(dp,-1,sizeof(dp));
    int n;
    scanf("%d",&n);
    for(int i=1;i<=n;++i) {
        scanf("%d",&A[i]);
    }
    ll ret = minInf;
    int retL,retR;
    for(int l = 1;l<=n;++l) {
        for(int r= l;r<=n;++r) {
            ll tmp = solveDp(l,r);
            if(ret<tmp) {
                retL = l, retR = r;
                ret = tmp;
            }
        }
    }
    vector<int> pos;
    dfs(pos,retL,retR);
    for(int i=1;i<retL;++i) {
        pos.push_back(i);
    }
    for(int i=n;i>=retR+1;--i) {
        pos.push_back(i);
    }
    printf("%lld\n", ret);
    reverse(pos.begin(),pos.end());
    for(int i=1;i<=n;++i) {
        update(i,1);
    }
    printf("%d\n", (int)pos.size());
    for(int i=0;i<pos.size();++i) {
        int totalLen = query(n);
        int cur = query(pos[i]);
        if(cur==1 || cur==totalLen) {
            update(cur,-1);
        } else {
            update(cur,-2);
        }
        printf("%d\n", cur);
    }
}

