using namespace std;
typedef long long ll;
vector<ll> values;
vector<int> operations;
int main()
{
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		ll a;
		scanf("%lld", &a);
		values.push_back(a);
	}
	while (true)
	{
		pair<ll, pair<int, int> > best = { -2e15, { 0, 0 }};
		for (int i = 1; i < values.size()-1; i++)
		{
			ll sum = values[i-1] + values[i+1];
			best = max(best, { sum, { i, 0 } });
		}
		for (int i = 0; i < values.size(); i++)
		{
			best = max(best, { values[i], { i, 1 } }); 
		}
		if (best.second.second)
		{
			// found the best one
			printf("%lld\n", best.first);
			for (int i = 0; i < best.second.first; i++) operations.push_back(1);
			int sz = values.size() - best.second.first;
			while (sz != 1)
			{
				operations.push_back(sz);
				sz--;
			}
			break;
		} 
		else
		{
			operations.push_back(best.second.first+1);
			int a = best.second.first;
			values[a] = values[a-1] + values[a+1];
			values.erase(values.begin()+a+1);
			values.erase(values.begin()+a-1);
		}
	}
	printf("%d\n", operations.size());
	for (auto a : operations) printf("%d\n", a);
}

