#define FILE_NAME "a"

int n;
vll a;

bool read() {
    if (!(cin >> n)) {
        return 0;
    }

    a = vll(n);
    forn (i, n)
        cin >> a[i];

    return 1;
}

const int N = 1010;
ll dp[N][N];
int prev[N][N];

const int left = N;
const int right = N + 1;

bool alive[N];

int get_id (int x)
{
    assert(alive[x] == 1);
    int ans = count(alive, alive + x + 1, 1);
    alive[x] = 0;
    return ans;
}

void restore (int l, int r, vi &res)
{
    if (l == r)
        return;

    const int from = prev[l][r];
    if (from == left)
    {
        res.pb(get_id(l));
        restore(l + 1, r, res);
        return;
    }

    if (from == right)
    {
        res.pb(get_id(r));
        restore(l, r - 1, res);
        return;
    }

    assert(l < from && from < r);
    restore(l, from - 1, res);
    restore(from + 1, r, res);
    res.pb(get_id(from));
}

void solve() {
    memset(dp, -1, sizeof dp);
    memset(prev, -1, sizeof prev);

    {
        int pos_max = max_element(all(a)) - a.begin();
        if (a[pos_max] < 0)
        {
            cout << a[pos_max] << endl;
            cout << n - 1 << endl;
            forn (i, pos_max)
                cout << 1 << endl;
            forn (i, n - 1 - pos_max)
                cout << n - pos_max - i << endl;
            return;
        }
    }

    forn (len, n)
    {
        forn (l, n - len)
        {
            const int r = l + len;
            if (l == r)
                dp[l][r] = a[l];
            else
            {
                ll &ans = dp[l][r];
                int &from = prev[l][r];

                if (dp[l + 1][r] > ans)
                {
                    ans = dp[l + 1][r];
                    from = left;
                }

                if (dp[l][r - 1] > ans)
                {
                    ans = dp[l][r - 1];
                    from = right;
                }

                for (int m = l; m <= r - 2; m++)
                {
                    ll cur = dp[l][m] + dp[m + 2][r];
                    if (cur > ans)
                    {
                        ans = cur;
                        from = m + 1;
                    }
                }
            }
        }
    }

    ll ans = dp[0][n - 1];
    cout << ans << endl;

    memset(alive, 0, sizeof alive);
    fill(alive, alive + n, 1);
    vi result;
    restore(0, n - 1, result);

    cout << sz(result) << endl;
    for (int x : result)
        cout << x << endl;
}

int main() {
