    {
        cout << mx << "\n";

        return 0;
    }

    memset(luat, 0, sizeof(luat));

    int st = 1;
    while(v[st] < 0)
    {
        ops(1);
        luat[st] = 1;
        st ++;
    }

    int dr = n;
    while(v[dr] < 0)
    {
        ops(dr);
        luat[dr] = 1;
        dr --;
    }
    for(i = st; i <= dr; i ++)
    {
        int ant = i - 1;
        int urm = i + 1;
        if(luat[i] == 0 && v[i] < 0)
        {
            while(luat[ant] == 1)
                ant --;

            while(luat[urm] == 1)
                urm ++;

            ops(i);

            luat[ant] = 1;
            luat[urm] = 1;
            v[i] = v[ant] + v[urm];
        }
    }

    lint s[2];
    s[1] = s[0] = 0;
    int k = 0;
    for(i = 1; i <= n; i ++)
    {
