        last --;

    while(last > 1)
    {
        int ant = codes[last] - 1;
        int urm = codes[last] + 1;
        while(luat[ant] == 1)
            ant --;

        while(luat[urm] == 1)
            urm ++;

        luat[ant] = luat[urm] = 1;

        ops(last);
        last -= 2;
        k -= 2;
    }

