const long long LL_INF = (long long) 2e18 + 5;

int N;
vector<long long> A;
vector<int> ops;

void add_ops(int first, int second) {
    while (second - first > 2) {
        ops.push_back(first + 2);
        second -= 2;
    }

    ops.push_back(first + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    A.resize(N);

    for (auto &a : A)
        cin >> a;

    long long best = -LL_INF;
    vector<int> best_indices;

    for (int parity = 0; parity < 2; parity++) {
        long long sum = 0;
        vector<int> indices;
        vector<pair<long long, int>> values;

        for (int i = parity; i < N; i += 2)
            values.emplace_back(A[i], i);

        sort(values.rbegin(), values.rend());

        for (pair<long long, int> entry : values)
            if (indices.empty() || entry.first > 0) {
                sum += entry.first;
                indices.push_back(entry.second);
            }

        sort(indices.begin(), indices.end());

        if (sum > best) {
            best = sum;
            best_indices = indices;
        }
    }

    cout << best << '\n';

    for (int i = N - 1; i > best_indices.back(); i--)
        ops.push_back(i);

    for (int i = (int) best_indices.size() - 1; i > 0; i--)
        add_ops(best_indices[i - 1], best_indices[i]);

    for (int i = 0; i < best_indices.front(); i++)
        ops.push_back(0);

