{
	for (int i = 0; i <= 1000; i++)
		for (int y = 0; y <= 1000; y++)
			for (int z = 0; z < 2; z++)
				dp[i][y][z] = inf;
	scanf("%lld", &n);
	for (int i = 1; i <= n; i++)
		scanf("%lld", &a[i]);
	printf("%lld\n", func(1, n, 1));
	func1(1, n, 1);
	printf("%d\n", gap.size());
	for (int i = 0; i < gap.size(); i++) {
		printf("%d\n", gap[i]);
	}
}

