int erasePos(vector<bool> &list) {
    cerr << endl;
    forin(i, 0, list.size()) {
        if (list[i])
            continue;
        if (i == 0 || i == list.size() - 1) {
            list.erase(list.begin() + i);
            return i;
        } else {
            if ((list[i - 1] && list[i + 1]) ||
                (!list[i - 1] && !list[i + 1])) {
                if (list[i - 1])
                    list[i] = true;
                list.erase(list.begin() + i + 1);
                list.erase(list.begin() + i - 1);
                return i;
            }
        }
    }
    return 1;
}

