    int N;
    cin >> N;
    vector<ll> A(N);
    rep(i, N) cin >> A[i];
    bool allneg = true;
    int negind = -1;
    ll negmax = -inf;
    rep(i, N){
        if(A[i] >= 0) {
            allneg = false;
            break;
        }
        if(negmax < A[i]){
            negmax = max(negmax, A[i]);
            negind = i;
        }
    }
    if(allneg){
        output(negmax);
        output(N - 1);
        for(int i = N - 1; i > negind; i--){
            output(i + 1);
        }
        rep(i, negind){
            output(1);
        }
        return 0;
    }

    vector<vector<int>> B(2, vector<int>(N)); // 偶数番目をとるか、奇数番目をとるか
    rep(i, N){
        if(A[i] >= 0){
            B[i % 2][i] = 1;
        }
    }
    vector<ll> S(2); // 和
    rep(i, 2){
        rep(j, N){
            if(B[i][j]){
                S[i] += A[j];
            }
        }
    }
    ll sum = max(S[0], S[1]);
    vector<int> C = S[0] > S[1] ? B[0] : B[1]; // 和に含める数字(1: 含める, 0: 含めない)
    vector<int> ret;
    int left = -1, right = N; // 和に含める左端のindex、右端のindex
    rep(i, N){
        if(C[i]) {
            left = i;
            break;
        }
    }
    for(int i = N - 1; i >= 0; i--){
        if(C[i]) {
            right = i;
            break;
        }
    }
    if(left == -1 && right == N) {
        output(0);
        output(N);
        rep(i, N) output(1);
        return 0;
    }

    for(int i = N - 1; i > left; i--){
        if(i > right){
            ret.pb(i + 1);
        }
        else {
            if(C[i - 1] && i >= 1){
                ret.pb(i + 1);
            }
            else if(C[i - 1] == 0 && C[i] == 0 && C[i + 1] == 0 && i >= 1 && i < N - 1 && (i - left) % 2 == 0){
                ret.pb(i + 1);
            }
        }
    }
    rep(i, left){
        ret.pb(1);
    }
    output(sum);
    output(ret.size());
    for(auto i: ret){
        output(i);
    }


    return 0;
}

