long long srch(int ll, int rr)
{
	int i;
	if(memo[ll][rr] != Neg)
		return memo[ll][rr];
	if(ll == rr)
		return ai[ll];
	if(ll+1==rr)
		return Neg2;
	long long mx=Neg2;
	long long tmp1, tmp2;
	int mxi;
	for(i=ll+1; i<rr; i++){
		tmp1 = srch(ll, i-1);
		tmp2 = srch(i+1, rr);
		if(tmp1!=Neg2 && tmp2!=Neg2)
			if(mx < tmp1+tmp2){
				mx = tmp1+tmp2;
				mxi = i;
			}
	}
	memo[ll][rr] = mx;
	mm2[ll][rr] = mxi;
	return mx;
}

void srch2(int ll, int rr, int st)
{
	if(ll==rr)
		return ;
	int p = mm2[ll][rr];
	srch2(ll, p-1, st);
	srch2(p+1, rr, st+2);
	num[numL] = st+1;
	numL ++;
}

