	//for(i=1; i<N; i++){
	for(i=0; i<N; i++){
		for(j=i; j<N; j++){
			tmp = srch(i, j);
			if(tmp > res){
				res = tmp;
				l2 = i;
				r2 = j;
			}
		}
	}
	if(l2!=-1){
		numL = 0;
		//for(i=r2+1; i<N; i++){
		for(i=N-1; i>=r2+1; i--){
			num[numL] = i;
			numL ++;
		}
		for(i=0; i<l2; i++){
			num[numL] = 0;
			numL ++;
		}
		srch2(l2, r2, 0);
	}
	printf("%lld\n", res);
	printf("%d\n", numL);
	for(i=0; i<numL; i++)
		printf("%d\n", num[i]+1);
}

