using namespace std;
ll dp[1010][1010][4];
ll a[1010];
ll n;
ll check[1010];
vector<ll> gap;
ll func(int lo, int hi, int ch) {
	if (lo == hi)return a[lo];
	ll &ret = dp[lo][hi][ch];
	if (ret != -1)return ret;
	ret = 0;
	if (ch & 1)
		ret = max(func(lo + 1, hi, ch), ret);
	if (ch & 2)
		ret = max(func(lo, hi - 1, ch), ret);
	for (int i = lo + 1; i < hi; i++) {
		ret = max(ret, func(lo, i - 1, ch & 1)+ func(i + 1, hi, ch & 2));
	}
	return ret;
}
void func1(int lo, int hi, int ch) {
	if (lo == hi)return;
	ll ret = 0;
	if (ch & 1)
		ret = max(func(lo + 1, hi, ch), ret);
	if (ch & 2)
		ret = max(func(lo, hi - 1, ch), ret);
	for (int i = lo + 1; i < hi; i++) {
		ret = max(ret, func(lo, i - 1, ch & 1) + func(i + 1, hi, ch & 2));
	}
	if (ch & 1) {
		if (ret == func(lo + 1, hi, ch)) {
			func1(lo + 1, hi, ch);
			gap.push_back(1);
			check[lo] = 1;
			return;
		}
	}
	if (ch & 2) {
		if (ret == func(lo, hi - 1, ch)) {
			func1(lo, hi - 1, ch);
			int cnt = 0;
			for (int i = 1; i <= hi; i++) {
				if (check[i])cnt++;
			}
			gap.push_back(n - cnt);
			check[hi] = 1;
			return;
		}
	}
	for (int i = lo + 1; i < hi; i++) {
		if (ret == func(lo, i - 1, ch & 1) + func(i + 1, hi, ch & 2)) {
			func1(lo, i - 1, ch & 1);
			func1(i + 1, hi, ch & 2);
			int cnt = 0;
			for (int y = 1; y < i; y++)
				cnt += check[y];
			gap.push_back(i - cnt);
			if (hi - lo == 2)
			{
				check[i - 1] = 1;
				check[i + 1] = 1;
			}
			return;
		}
	}
}
