                a.erase(a.begin()+j);
                if (j != a.size()-2) a.erase(a.begin()+j-1);
            }
            continue;
        }
        if (ansi != 0) {
            out.push_back(1);
            a.erase(a.begin());
            ansi--;
            continue;
        }
        if (ansi != a.size()-1) {
            out.push_back(a.size());
            a.erase(a.begin()+a.size()-1);
            continue;
        }
    }
    cout << out.size() << endl;
    rep(i,out.size()) cout << out[i] << endl;
}

