void maxseq(vector<Int> X, Int &sum, Int &idx, Int &cnt)
{
    sum = idx = cnt = 0;
    Int from = 0, curr = 0;
    for (int i = 0; i < X.size(); i++) {
        curr += X[i];
        if (curr > sum) sum = curr, idx = from, cnt = i - from + 1;
        if (curr < 0) curr = 0, from = i + 1;
    }
}
