            if (f(i, j) == ans) {
                // [j, N)を削除する
                for (int k = N; k > j; --k)sousa.push_back(k);
                // [0, i)を削除する
                rep(k, i)sousa.push_back(1);

                bit = BIT(N);
                FOR(k, i, j) {
                    S.insert(k);
                    bit.add(k, 1);
                }
                g(i, j);
                return;
            }
        }
    }();

    cout << sz(sousa) << endl;
    each(yaru, sousa)cout << yaru << endl;
}

