void recordStep(vector<ll>& a, vector<int>& step, int k) {
  step.push_back(k + 1);
  if (k == 0 || k == a.size() - 1) {
    a.erase(a.begin() + k);
  } else {
    ll sum = a[k - 1] + a[k + 1];
    a.erase(a.begin() + k);
    a.erase(a.begin() + k);
    a[k - 1] = sum;
  }
}

pair<ll, vector<int>> solveOne(vector<ll> a, int s) {
  ll max_k = s;
  for (int i = s; i < a.size(); i += 2) {
    if (a[i] > a[max_k]) {
      max_k = i;
    }
  }
  vector<int> step;
  for (int t = 0; t < max_k; t++) {
    recordStep(a, step, 0);
  }
  while (a.size() > 1) {
    recordStep(a, step, a.size() - 1);
  }
  return make_pair(a[0], step);
}

pair<ll, vector<int>> solve(vector<ll> a, int s) {
  auto ansOne = solveOne(a, s);
  if (ansOne.first < 0) {
    return ansOne;
  }
  vector<int> step;
  while (s > 0) {
    recordStep(a, step, 0);
    --s;
  }
  while (a.size() > 2) {
    if (a[0] >= 0 && a[2] >= 0) {
      recordStep(a, step, 1);
    } else if (a[0] < 0) {
      recordStep(a, step, 0);
      recordStep(a, step, 0);
    } else if (a[2] < 0) {
      if (a.size() < 4) {
        break;
      }
      recordStep(a, step, 2);
    }
  }
  while (a.size() > 1) {
    recordStep(a, step, a.size() - 1);
  }
  return make_pair(a[0], step);
}

