        cout << memo[i] << endl;
    }
    for(int i = 0; i <=4; ++i){
        cout << ref[i] << endl;
    }
    */

    cout << ans << endl;
    vector<LL> flags(n);
    for(int i = n; i > 0; --i){
        //cerr << i << " : cur=" << cur << endl;
        if(cur != 1){
            flags[i-1] = 1;
        }
        cur = ref[cur][i];
    }

/*
