int main(){
    int n; cin>>n;
    vector<ll> a(n);
    rep(i,n) cin>>a[i];
    ll MX = -1e18;
    rep(i,n) MX = max(MX, a[i]);
    vector<bool> add(n,false);
    if(MX<0){ //要素全てが負の場合
        rep(i,n){
            if(a[i]==MX){
                add[i] = true;
                break;
            }
        }
    }else{ //偶奇で分けて答えを求める

        ll p=0,q=0;
        rep(i,n){
            if(i&1) p+=a[i];
            else q+=a[i];
        }
        for(int i=(p>q);i<n;i+=2)if(a[i]>0) add[i] = true;
    }

    vector<int> ans; //答え用の配列
    while(a.size()>1){
        int la = a.size();
        if(!add.front()){ //前がいらない
            a.erase(a.begin());
            add.erase(add.begin());
            ans.push_back(1);
        }else if(!add.back()){ //後ろがいらない
            a.erase(prev(a.end()));
            add.erase(prev(add.end()));
            ans.push_back(la);
        }else{ //間
            int p;
            for(int i=1;i<la-1;i+=2){
                if(add[i-1]&&!add[i]&&add[i+1]) p=i; //1&&0&&1
                if(!add[i-1]&&!add[i]&&!add[i+1]) p=i; //0&&0&&0
            }
            a.erase(a.begin() + p);
            add.erase(add.begin() + p);
            a.erase(a.begin() + p);
            add.erase(add.begin() + p);
            a[p-1] = a[p-1] + a[p+1];
            ans.push_back(p+1);
        }

    }

    cout << a[0] << endl;
    n = ans.size();
    cout << n << endl;
    rep(i,n) cout << ans[i] << endl;

    return 0;
}

