main()
{
	cin>>N;
	for(int i=0;i<N;i++)cin>>A[i];
	for(int i=0;i<N;i++)
	{
		dp[i][0]=max(0L,A[i]);
		ep[i]=max(0L,A[i]);
		for(int j=i-2;j>=0;j-=2)
		{
			dp[i][j]=max(dp[i][j],ep[j]+A[i]);
			if(ep[i]<dp[i][j])
			{
				ep[i]=dp[i][j];
				parent[i]=j;
			}
		}
	}
	int id=0;
	for(int i=1;i<N;i++)
	{
		if(ep[id]<ep[i])id=i;
	}
