int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }
    auto solve = [&](int x) {
        int sum = 0;
        vector<int> S, ans;
        for (int i = x; i <= n; i += 2) {
            if (a[i] >= 0) sum += a[i], S.push_back(i);
        }
        for (int i = n; i > S.back(); i--) {
            ans.push_back(i);
        }
        for (int i = (int)S.size() - 2; ~i; i--) {
            for (int j = (S[i] + S[i + 1]) / 2; j > S[i]; j--) {
                ans.push_back(j);
            }
        }
        for (int i = S[0] - 1; i; i--) {
            ans.push_back(i);
        }
        return make_pair(sum, ans);
    };
    auto p1 = solve(1), p2 = solve(2);
    if (p1.first < p2.first) swap(p1, p2);
