  vector<long long> pr_l(n, -1);
  for(int i=0; i<n; i++){
    dp_l[i] = max(dp_l[i], a[i]);
    pr_l[i] = i;
    for(int j=i-2; j>=0; j-=2){
      if( dp_l[i] < a[i] + dp_l[j] ){
        dp_l[i] = max(dp_l[i], a[i] + dp_l[j]);
        pr_l[i] = j;
      }
    }
  }

  reverse(a.begin(), a.end());
  vector<long long> dp_r(n, -(1ll<<50));
  vector<long long> pr_r(n, -1);
  for(int i=0; i<n; i++){
    dp_r[i] = max(dp_r[i], a[i]);
    pr_r[i] = n-1-i;
    for(int j=i-2; j>=0; j-=2){
      if( dp_r[i] < a[i] + dp_r[j] ){
        dp_r[i] = max(dp_r[i], a[i] + dp_r[j]);
        pr_r[i] = n-1-j;
      }
    }
  }

  reverse(a.begin(), a.end());
  reverse(dp_r.begin(), dp_r.end());
  reverse(pr_r.begin(), pr_r.end());

  enum class Mode{
    A,
    L,
    R,
    LR
  };

  Mode mode;

  long long ans = max({
    *max_element(a.begin(), a.end()),
    *max_element(dp_l.begin(), dp_l.end()),
    *max_element(dp_r.begin(), dp_r.end())
  });


  if( count(a.begin(), a.end(), ans) ){
    mode = Mode::A;
  }else if( count(dp_l.begin(), dp_l.end(), ans) ){
    mode = Mode::L;
  }else if( count(dp_r.begin(), dp_r.end(), ans) ){
    mode = Mode::R;
  }

  pair<int,int> ans_;
  for(int i=0; i<n; i++){
    for(int j=i+2; j<n; j+=2){
      long long tmp = dp_l[i] + dp_r[j];
      if( tmp > ans ){
        ans = max(tmp, ans);
        mode = Mode::LR;
        ans_ = {i,j};
      }
    }
  }

  println(ans);

  if(mode == Mode::A){
    vector<int> op;
    deque<long long> dq(a.begin(), a.end());
    while(dq.front() != ans){
      op.push_back(1);
      dq.pop_front();
    }
    while(dq.size() != 1){
      op.push_back(dq.size());
      dq.pop_back();
    }
