  for(int i=1; i<=n; i++){
    bit.add(i, 1);
  }

  vector<int> op;

  auto merge = [&](int i){
    int pos = bit.get_sum(i+1);
    int nx = bit.lower_bound(pos+1);
    bit.add(i+1, -1);
    bit.add(nx, -1);

    op.push_back(pos);
  };

  // [l,r] => single
  function<void(int, int)> del = [&](int l, int r){
    if( l==r ) return;
    for(int i=l+1; i<r; i+=2){
      merge(i);
    }
  };

  if(mode == Mode::L){
    int pos = find(dp_l.begin(), dp_l.end(), ans) - dp_l.begin();
    while( a.size() > pos+1 ){
      op.push_back( a.size() );
      bit.add(a.size(), -1);
      a.pop_back();
    }
    while(pos != pr_l[pos]){
      int pr = pr_l[pos];
      del(pr+1, pos-1);
      merge(pr+1);
      pos = pr;
    }
    while(pos){
      int at = bit.lower_bound(1);
      bit.add(at, -1);
      op.push_back(1);
      pos--;
    }

    println(op.size());
    println(join(op, "\n"));
    return 0;
  }

  if(mode == Mode::R){
    int pos = find(dp_r.begin(), dp_r.end(), ans) - dp_r.begin();
    for(int cnt=pos, i=1; cnt; cnt--, i++){
      op.push_back(1);
      bit.add(i, -1);
    }
    while(pos != pr_r[pos]){
      int pr = pr_r[pos];
      del(pos+1, pr-1);
      merge(pos+1);
      pos = pr;
    }
    for(int i=n-1; i>pos; i--){
      int at = bit.get_sum(i+1);
      op.push_back(at);
      bit.add(i+1, -1);
    }

    println(op.size());
    println(join(op, "\n"));
    return 0;
  }

  if(mode == Mode::LR){
    {
      int pos = ans_.first;
      while(pos != pr_l[pos]){
        int pr = pr_l[pos];
        del(pr+1, pos-1);
        merge(pr+1);
        pos = pr;
      }
      while(pos){
        int at = bit.lower_bound(1);
        bit.add(at, -1);
        op.push_back(1);
        pos--;
      }
    }
    {
      int pos = ans_.second;
      while(pos != pr_r[pos]){
        int pr = pr_r[pos];
        del(pos+1, pr-1);
        merge(pos+1);
        pos = pr;
      }
      for(int i=n-1; i>pos; i--){
        int pos = bit.get_sum(i+1);
        op.push_back(pos);
        bit.add(i+1, -1);
      }
    }

    del( ans_.first+1, ans_.second-1 );

    println(op.size());
    println(join(op, "\n"));

  }

  return 0;
}

