			if (a[i] > a[max_i])
				max_i = i;
		printf("%lld\n", a[max_i]);
		printf("%d\n", n - 1);
		for (int i{n - 1}; i >= 0; i--)
			if (i != max_i)
				printf("%d\n", i + 1);
		return 0;
	}
	for (int ini{}; ini < 2; ini++)
		for (int a_i{n - 1 - ini}; a_i >= 0; a_i -= 2)
			if (a[a_i] >= 0)
				sum[ini] += a[a_i];
	if (sum[1] > sum[0])
	{
		std::vector<int> erase;
		for (int i{n - 2}; i >= 0; i -= 2)
			if (a[i] <= 0)
				erase.push_back(i + 1);
			else
				erase.push_back(i + 2);
		if (n & 1) erase.push_back(1);
		printf("%lld\n", sum[1]);
		printf("%d\n", erase.size());
		for (auto& e: erase) printf("%d\n", e);
	}
	else
	{
		std::vector<int> erase;
		if (a.back() <= 0) erase.push_back(n);
		for (int i{n - 3}; i >= 0; i -= 2)
			if (a[i] <= 0)
				erase.push_back(i + 1);
			else
				erase.push_back(i + 2);
		if (~n & 1) erase.push_back(1);
		printf("%lld\n", sum[0]);
		printf("%d\n", erase.size());
		for (auto& e: erase) printf("%d\n", e);
	}

	return 0;
}

bool allMinus(std::vector<long long>& a)
{
	for (auto& e: a)
		if (e >= 0)
			return false;
	return true;
}

