void solve(vector<int> v) {
    int sz = v.size();
    for(int i = n; i >= v[sz-1]+1; i--)
        ans.emplace_back(i);
    for(int i = sz - 1; i >= 1; i--) {
        int st = v[i] + v[i-1];
        st/=2;
        int en = v[i-1]+2;
        if(v[i-1] == v[i] - 2)
            continue;
        for(int i = en; i >= st; i--)
            ans.emplace_back(i);
    }
    v[0]--;
    while(v[0]--)
        ans.emplace_back(1);
    sz--;
    while(sz--)
        ans.emplace_back(2);
}

int check() {
    for(auto& it:ans)
        it--;

    vector<int>tmp;
    for(int i = 1; i <= n; i++)
        tmp.emplace_back(arr[i]);

    for(auto it:ans) {
        int sz  = tmp.size();
        if(it == sz-1 || it == 0)
            tmp.erase(tmp.begin() + it);
        else {
            int x = tmp[it-1];
            int y = tmp[it+1];
            tmp[it] = x+y;
            tmp.erase(tmp.begin() + it + 1);
            tmp.erase(tmp.begin() + it - 1);
        }
    }
    return tmp[0];
}
