inline int output(int l,int r,int x)
{
	if (l>=r)
		return 0;
	for (int k=l+1;k<=r-1;k++)
		if (f[l][k-1]+f[k+1][r]==f[l][r])
		{
			int t1=output(l,k-1,x);
			int t2=output(k+1,r,x+1+k-l-t1);
			V.push_back(x+1+k-l-t1);
			return t1+t2+1;
		}
}

int main()
{
	scanf("%d",&n);
	for (i=1;i<=n;i++)
		scanf("%d",&g[i]);
	for (i=1;i<=n;i++)
		f[i][i]=g[i];
	for (i=n;i>0;i--)
		for (j=i+2;j<=n;j++)
			for (k=1;k<=50;k++)
				l=rand()%(j-i-1)+1,f[i][j]=max(f[i][j],f[i][i+l-1]+f[i+l+1][j]);
	s=-1000000000;
	for (i=n;i>0;i--)
		for (j=i;j<=n;j++)
			if (f[i][j]>s)
				s=f[i][j],k=i,l=j;
	printf("%lld\n",s);
	output(k,l,k-1);
	for (i=1;i<k;i++)
		V.push_back(1);
	for (i=l+1;i<=n;i++)
		V.push_back(2);
	printf("%d\n",V.size());
	for (it=V.begin();it!=V.end();it++)
		printf("%d\n",*it);
	return 0;
}

