    vector<ll> ldp(n, 0), rdp(n, 0);
    rep(i, 0, n){
        if(i < 2) ldp[i] = a[i];
        else ldp[i] = max(ldp[i-2] + a[i], a[i]);
    }
    reverse(ALL(a));
    rep(i, 0, n){
        if(i < 2) rdp[i] = a[i];
        else rdp[i] = max(rdp[i-2] + a[i], a[i]);
    }
    reverse(ALL(a));
    reverse(ALL(rdp));
    ll ans = 0;
    int ldx = 0, rdx = 0;
    rep(i, 0, n){
        rep(j, i, n){
            if(j == i){
                if(chmax(ans, ldp[i])) ldx = j, rdx = j;
                if(chmax(ans, rdp[i])) ldx = j, rdx = j;
                continue;
            }
            if((j-i)%2==0){
                if(chmax(ans, ldp[i] + rdp[j])) ldx = i, rdx = j;
            }
        }
    }
    cout << ans << endl;
    // cerr << ldx << " " << rdx << endl;
    vector<int> res;

    int tdx = rdx;
    while(tdx < n){
        vector<int> tm;
        while(tdx < n - 2 and rdp[tdx] == rdp[tdx+2] + a[tdx]){
            tm.push_back(tdx+1);
            tdx += 2;
        }
        tdx++;
        while(tdx < n){
            tm.push_back(tdx); tdx++;
        }
        reverse(ALL(tm));
        res.insert(res.end(), ALL(tm));
    }
    tdx = ldx;
    while(tdx >= 0){
        vector<int> tm;
        while(tdx >= 2 and ldp[tdx] == ldp[tdx-2] + a[tdx]){
            tm.push_back(tdx-1);
            tdx -= 2;
        }
        tdx--;
        while(tdx >= 0){
            tm.push_back(tdx); tdx--;
        }
        reverse(ALL(tm));
        int cnt = 0;
        for(auto& e: tm){
            e -= cnt++;
        }
        res.insert(res.end(), ALL(tm));
    }
    rep(i, 0, (rdx - ldx + 1) / 2) res.push_back(1);
    cout << res.size() << endl;
    for(auto e: res) cout << e + 1 << endl;

    return 0;
}

