vector<int> restore;

void build_restore(int i, int j) {
	if (i == j)
		return;
	int k = go[i][j];
	restore.push_back(k);
	if (k == i)
		build_restore(i + 1, j);
	else {
		if (k == j)
			build_restore(i, j - 1);
		else {
			build_restore(i, k - 1);
			build_restore(k + 1, j);
		}
	}
}

