	cin >> n;
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
		dp[i][i] = a[i];
	}
	for (int len = 2; len <= n; ++len) {
		for (int i = 0; i <= n - len; ++i) {
			int j = (i + len - 1);
			dp[i][j] = dp[i + 1][j];
			go[i][j] = i;
			if (dp[i][j - 1] > dp[i][j]) {
				dp[i][j] = dp[i][j - 1];
				go[i][j] = j;
			}
			ll new_val;
			for (int k = i + 1; k < j; ++k) {
				new_val = dp[i][k - 1] + dp[k + 1][j];
				if (new_val > dp[i][j]) {
					dp[i][j] = new_val;
					go[i][j] = k;
				}
			}
		}
	}
