long long dfs(int l,int r)
{
    if((r-l+1)%2==0)
        return -1000000001;
    if(r-l==0)
        return a[l];
    if(v[l][r])
        return dp[l][r];
    v[l][r]=1;
    long long ans;
    int f=0;
    for(int i=l+1;i<r;i++)
    {
        long long x=dfs(l,i-1),y=dfs(i+1,r);
        if(f==0)
        {
            ans=x+y,f=1;
            pre[l][r]=i;
        }
        else
        {
            if(x+y>ans)
            {
                ans=x+y;
                pre[l][r]=i;
            }
        }
    }
    return dp[l][r]=ans;
}
vector<int>opt;
void solve(int l,int r)
{
    if(r-l==0)
        return ;
    int mid=pre[l][r];
    solve(mid+1,r);
    opt.push_back(mid);
    solve(l,mid-1);
}
