    vector<vector<ll>>dp(N, vector<ll>(N, 0));
    for (int i = 0; i < N; ++i) {
        dp[i][i] = A[i];
    }

    for (int k = 1; k < N; ++k) {
        for (int i = 0; i < N - k; ++i) {
            dp[i][i+k] = max(dp[i][i+k-1], dp[i+1][i+k]);
        }
        if (k == 1) continue;
        for (int i = 0; i < N - k; ++i) {
            ll temp = max(dp[i][i+k-2] + A[i+k], dp[i+2][i+k] + A[i]);
            dp[i][i+k] = max(dp[i][i+k], temp);
        }
    }

    cout << dp[0][N-1] << "\n";

    vector<int>ans;
    int i = 0, j = N-1;
    while (1 < j - i) {
        if (dp[i][j] == dp[i][j-1]) {
            ans.push_back(j-i+1);
            j--;
        } else if (dp[i][j] == dp[i+1][j]) {
            ans.push_back(1);
            i++;
        } else if (dp[i][j] == dp[i][j-2] + A[j]) {
            ans.push_back(j-i);
            j -= 2;
        } else if (dp[i][j] == dp[i+2][j] + A[i]) {
            ans.push_back(2);
            i += 2;
        } else {
            assert(false);
        }
