	RMQ rmq[2];
	rmq[0] = RMQ(a[0]);
	rmq[1] = RMQ(a[1]);
	FOR(i, 2, n+2){
		PLL ret = rmq[i%2].query(0, i);
		res[i] = ret.sc;
		rmq[i%2].update(i, ret.fs+a[i%2][i]);
	}
	PLL in = max(rmq[0].query(2, n+2), rmq[1].query(2, n+2));
	int32 index = in.sc;
	vector<int32> pos;
