// 0-origin BIT
template <typename T>
class BIT{
public:
    vector<T> data;
    int n;
    BIT(){}
    BIT(int n_){
        n = n_;
        data.assign(n, T(0));
    }
    // v[a] += w
    void add(int a, T w){
        for (int x = a; x < n; x |= x + 1) data[x] += w;
    }
    // sum of v[i] for i in [0, a)
    T sum(int a){
        T ret = 0;
        for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += data[x];
        }
        return ret;
    }
};

int main(){
    cin >> N;

    BIT<ll> even_bit(N), odd_bit(N);
    for(int i=0;i<N;i++){
        cin >> a[i];
        if(i%2 == 0) even_bit.add(i, max(a[i], 0LL));
        else odd_bit.add(i, max(a[i], 0LL));
    }

    ll ans = -INF;
    int ans_l = -1, ans_r = -1;
    for(int l=0;l<N;l++){
        for(int r=l;r<N;r += 2){
            assert(l%2 == r%2);
            ll ans_this = a[l];
            if(r != l){
                ans_this += a[r];
                if(l%2 == 0) ans_this += even_bit.sum(r) - even_bit.sum(l + 1);
                else ans_this += odd_bit.sum(r) - odd_bit.sum(l + 1);
            }
            if(ans_this > ans){
                ans = ans_this;
                ans_l = l;
                ans_r = r;
            }
        }
    }

    cout << ans << endl;

    vector<int> op;
    for(int i=N-1;i>ans_r;i--){
        op.push_back(i + 1);
    }
    for(int i=0;i<ans_l;i++){
        op.push_back(1);
    }
    for(int i=ans_l+2;i<=ans_r;i+=2){
        if(i == ans_r || a[i] > 0){
            op.push_back(2);
        }else{
            op.push_back(3);
        }
    }

    cout << op.size() << endl;
    for(int o : op){
        cout << o << endl;
    }

    return 0;
}

