vi answer;
int was[N];
void Go(int l,int r) {
	if (l >= r) {
		return;
	}
	int k = F[l][r];
	if (k == l || k == r) {
		answer.pb(k - l + 1);
		was[k] = 1;
		if (k == l)
			Go(l + 1,r);
		else
			Go(l,r - 1);
		return;
	}
	Go(l,k - 1);
	Go(k + 1,r);
	answer.pb(2);
	was[k] = 1;
}
