#define ll long long
using namespace std;
ll dp[1010][1010][2];
const ll inf = -1e16;
ll a[1010];
int cc = 0;
ll n;
ll check[1010];
vector<ll> gap;
ll func(int lo, int hi, int ch) {
	if (lo>hi)return 0;
	if (lo == hi)return a[lo];
	ll &ret = dp[lo][hi][ch];
	if (ret != inf)return ret;
	ret = -99999999999;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	ll sum = a[lo];
	for (int i = lo + 2; i <= hi; i+=2) {
		sum += a[i];
		ret = max(ret, sum+ func(i + 2, hi, 0));
	}
	return ret;
}
void func1(int lo, int hi, int ch) {
	if (lo >= hi)return;
	ll ret = -99999999999;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	ll sum = a[lo];
	for (int i = lo + 2; i <= hi; i += 2) {
		sum += a[i];
		ret = max(ret, sum + func(i + 2, hi, 0));
	}
	if (ch) {
		if (ret == func(lo + 1, hi, ch)) {
			gap.push_back(1);
			cc++;
			check[lo] = 1;
			func1(lo + 1, hi, ch);
			return;
		}
		if (ret == func(lo, hi - 1, ch)) {
			gap.push_back(n - cc);
			cc++;
			check[hi] = 1;
			func1(lo, hi - 1, ch);
			return;
		}
	}
	sum = a[lo];
	int oo = 0;
	int mm = 0;
	for (int i = lo + 2; i <= hi; i += 2) {
		sum += a[i];
		oo++;
		if (ret == sum + func(i + 2, hi, 0)) {
			for (int y = 0; y < lo; y++) {
				mm += check[y];
			}
			while (oo--) {
				gap.push_back(lo + 1 - mm);
			}
			for (int y = lo; y <= i; y++) {
				if (y == lo + 1)continue;
				check[y] = 1;
				mm++;
			}
			func1(i + 2, hi, 0);
			if (i + 1 <= hi) {
				gap.push_back(i + 1-mm);
			}
			return;
		}
	}
}
int main()
{
	for (int i = 0; i <= 1000; i++)
		for (int y = 0; y <= 1000; y++)
			for (int z = 0; z < 2; z++)
				dp[i][y][z] = inf;
	scanf("%lld", &n);
	for (int i = 1; i <= n; i++)
		scanf("%lld", &a[i]);
	printf("%lld\n", func(1, n, 1));
	func1(1, n, 1);
	printf("%d\n", gap.size());
	for (int i = 0; i < gap.size(); i++) {
		printf("%d\n", gap[i]);
	}
}

