        printf("%d\n", n);
        rep(i, 0, n) printf("%d\n", buf[i] + 1);
        return;
    }

    ll sm[2] = { 0, 0 };
    rep(i, 0, N) if (0 < A[i]) sm[i % 2] += A[i];

    if (sm[0] < sm[1]) {
        ans = sm[1];
        buf.push_back(0);
        N--;
        A++;
    } else ans = sm[0];

    if (N % 2 == 0) {
        buf.push_back(N - 1);
        N--;
    }

    while (A[0] <= 0) {
        buf.push_back(0);
        buf.push_back(0);
        A += 2;
        N -= 2;
    }

    while (A[N - 1] <= 0) {
        buf.push_back(N - 1);
        N--;
        buf.push_back(N - 1);
        N--;
    }

    int pre = 0, cnt = 0;
    for (int i = 0; i < N; i += 2) {
        if (A[i] <= 0) {
            buf.push_back(i - pre);
            pre -= 2;
        } else cnt++;
    }

    rep(i, 0, cnt) {
        buf.push_back(1);
    }

    int n = buf.size();
    printf("%lld\n%d\n", ans,n);
    rep(i, 0, n) printf("%d\n", buf[i] + 1);
    printf("\n");
}

