const ll INF = 1e18;
const int MX = 100001;

int N, a[1000];
pair<ll,pi> dp[1000][1000];
pair<ll,pi> ori = {-INF,{-1,-1}}, bes = ori;
vi ans;
vl cur;

void rem(int x) {
    ans.pb(x+1);
    if (x == 0 || x == sz(cur)-1) cur.erase(cur.begin()+x);
    else {
        ll z = cur[x+1]+cur[x-1];
        cur[x] = z;
        cur.erase(cur.begin()+x+1);
        cur.erase(cur.begin()+x-1);
    }
}

void divi(int l, int r, int pre) {
    if (l == r) return;
    pi x = dp[r-l][l].s;
    divi(l,l+x.f,pre);
    divi(l+x.f+1,r-x.s-1,pre+1);
    divi(r-x.s,r,pre+2);
    rem(pre+1);
}

void solve() {
    pi l = {bes.s.s,bes.s.s+bes.s.f};
    F0R(i,l.f) rem(0);
    F0R(i,N-1-l.s) rem(sz(cur)-1);
    divi(l.f,l.s,0);
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> N;
    F0R(i,N) cin >> a[i];
    for (int i = 0; i < N; i += 2) F0R(j,N-i) {
        dp[i][j] = ori;
        if (i == 0) dp[i][j] = {a[j],{-1,-1}};
        else {
            pair<ll,int> cur = {-INF,-1};
            for (int k = i-2; k >= 0; k -= 2) {
                cur = max(cur,mp(dp[i-k-2][j+k+2].f,i-k-2));
                dp[i][j] = max(dp[i][j],mp(dp[k][j].f+cur.f,mp(k,cur.s)));
            }
        }
        bes = max(bes,mp(dp[i][j].f,mp(i,j)));
    }
    F0R(i,N) cur.pb(a[i]);
    solve();
    assert(cur[0] == bes.f);
    cout << bes.f << "\n";
    cout << sz(ans) << "\n";
    for (int i: ans) cout << i << "\n";
}

