	}

	VPLL arr;
	REP(i, N) if (a[i] >= 0) ((i & 1) ? eve : odd) += a[i];
	REP(i, N) arr.push_back({ a[i],i });

	bool prt = (eve > odd);

	while(N >= 2){
		if (arr[0].se % 2 == prt && arr[0].fi >= 0) break;
		arr = dec(arr, 0);
		c.push_back(1);
		N = arr.size();
	}

	while (N >= 2) {
		if (arr[N-1].se % 2 == prt && arr[N-1].fi >= 0) break;
		arr = dec(arr, N-1);
		c.push_back(N);
		N = arr.size();
	}

	for (int i = 0; i < N && N >= 2;) {
		if (arr[i].se % 2 != prt || arr[i].fi >= 0) {
			i += 2;
			continue;
		}
		else {
			arr = dec(arr, i);
			c.push_back(i + 1);
			N = arr.size();
		}
	}

	while (N >= 2) {
		if (arr[1].se % 2 == prt) continue;
		arr = dec(arr, 1);
		c.push_back(2);
		N = arr.size();
	}

	cout << arr[0].fi << endl;
	cout << c.size() << endl;
	REP(i, c.size()) cout << c[i] << endl;

	return 0;
}

