#define MAXN 100000

int n;
int a[MAXN];
int b[MAXN];
vector<int> op;

int input() {
	if (scanf("%d", &n) < 0) return 0;
	for (int i=0; i<n; i++) scanf("%d", &a[i]);
	return 1;
}

void init() {
}

vector<int> build(int *b) {
	vector<int> c(b, b+n), r;
	while (1) {
		int n=c.size();
		if (n==1) break;
		int p = -1;
		if (c[0]==0) p = 0;
		else if (c[n-1]==0) p = n-1;
		else {
			for (int i=1; i<n-1; i++)
				if (c[i]==0 && c[i-1] == c[i+1]) {
					p = i;
					break;
				}
		}
		//cout << p << ':' << c << endl;
		if (p<0) break;
		r.push_back(p);
		if (p==0 || p==n-1) {
			c.erase(c.begin()+p);
		}
		else {
			c[p] = c[p+1];
			c.erase(c.begin()+p+1);
			c.erase(c.begin()+p-1);
		}
	}
	return r;
}

long solve() {
	long ans = LONG_MIN;
	for (int k=0; k<2; k++) {
		memset(b, 0, sizeof(b));
		int maxi = k;
		long s = 0;
		for (int i=k; i<n; i+=2) {
			if (a[i] > a[maxi])
				maxi = i;
			if (a[i]>0) {
				s+= a[i];
				b[i] = 1;
			}
		}
		if (s==0) {
			s = a[maxi];
			b[maxi] = 1;
		}
		if (s>ans) {
			ans = s;
			op = build(b);
		}
	}
	return ans;
}

void output(long ans) {
	printf("%ld\n%d\n", ans, (int)op.size());
	for (auto x: op) {
		printf("%d\n", x+1);
	}
}

void cleanup() {
}

int main() {
	//int ca; scanf("%d", &ca);
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

