vector<int> priorities(const vector<int> &list) {
    vector<int> pris(list.size());
    forin(i, 0, list.size()) {
        if (i == 0 || i == list.size() - 1) {
            pris[i] = -list[i];
        } else {
            pris[i] = list[i - 1] + list[i + 1] - list[i];
        }
    }
    return pris;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    forin(i, 0, n)
        cin >> a[i];
    auto pris = priorities(a);
    vector<int> pos;
    while (pris.size() > 1) {
        auto max = pris[0];
        auto maxi = 0;
        forin(i, 0, pris.size()) {
            if (pris[i] > max) {
                max = pris[i];
                maxi = i;
            }
        }
        if (maxi == 0 || maxi == a.size() - 1) {
            if (maxi == 0)
                pris[1] = -a[1];
            else
                pris[maxi - 1] = -a[maxi - 1];
            pris.erase(pris.begin() + maxi);
            a.erase(a.begin() + maxi);
        } else {
            auto l = a[maxi - 1];
            auto r = a[maxi + 1];
            a[maxi] = l + r;
            if (maxi > 1) {
                pris[maxi - 2] += r;
            }
            if (maxi < pris.size() - 2) {
                pris[maxi + 2] += l;
            }
            if (maxi == 1 || maxi == pris.size() - 2) {
                pris[maxi] = -a[maxi];
            } else {
                pris[maxi] = a[maxi - 2] + a[maxi + 2] - a[maxi];
            }
            a.erase(a.begin() + maxi + 1);
            a.erase(a.begin() + maxi - 1);
            pris.erase(pris.begin() + maxi + 1);
            pris.erase(pris.begin() + maxi - 1);
        }
        pos.push_back(maxi);
    }
    cout << a[0] << endl;
    cout << pos.size() << endl;
    forin(i, 0, pos.size()) {
        cout << pos[i] + 1 << endl;
    }
}

