	} else {
		ans=LLONG_MIN; int bs=-1;
		REP(s,2) {
			ll cur=0; for(int i=s;i<n;i+=2) if(a[i]>=0) cur+=a[i];
			if(cur>ans) ans=cur,bs=s;
		}
		int cnt=0; nret=0;
		if(n%2==bs) ret[nret++]=n-1;
		for(int i=n-1-(n%2==bs?1:0);i>=bs;i-=2) {
			if(a[i]>=0) { ++cnt; continue; }
			ret[nret++]=i; if(cnt==0) ret[nret++]=i-1;
		}
		if(bs==1) ret[nret++]=0;
		REP(i,cnt-1) ret[nret++]=1;
	}
	printf("%lld\n",ans); printf("%d\n",nret); REP(i,nret) printf("%d\n",ret[i]+1); puts("");
}

