template<typename T> struct SegTree{
    using F=function<T(T, T)>;
    int sz=1;
    T et;
    F f, g;
    vector<T> node;

    SegTree(int sz_, T et_, F f_, F g_): et(et_), f(f_), g(g_){
        while(sz<sz_) sz<<=1;
        node.resize(sz<<1, et);
    }

    void update(int i, T x){
        i+=sz;
        node[i]=g(node[i], x);
        i>>=1;
        while(i){
            node[i]=f(node[i<<1], node[(i<<1)+1]);
            i>>=1;
        }
    }

    T query(int l, int r){
        T vl=et, vr=et;
        for(l+=sz, r+=sz; l<r; l>>=1, r>>=1){
            if(l&1) vl=f(vl, node[l++]);
            if(r&1) vr=f(node[--r], vr);
        }
        return f(vl, vr);
    }

    int lower_bound(T x, function<bool(T, T)> cmp){
        if(cmp(node[1], x)) return sz;
        int i=1;
        T L=et;
        while(i<sz){
            if(cmp(f(L, node[i<<1]), x)){
                L=f(L, node[i<<1]);
                i=(i<<1)+1;
            }
            else i<<=1;
        }
        return i-sz;
    }
};

