list<ll>::iterator search_max_itr(list<ll>& l){

  ll max_val = -10000000000;
  list<ll>::iterator max_itr=l.end();

  for(auto it=l.begin(); it!=l.end(); ++it){

    if( it == l.begin() or it == (--l.end()) ) continue;

    auto it_pv = it; it_pv--;
    auto it_nx = it; it_nx++;

    if( max_val < *it_pv+*it_nx and *it < *it_pv+*it_nx ){
      max_val = max(max_val, *it_pv+*it_nx);
      max_itr = it;
    }

  }

  if( max_val < l.front() ) return l.begin();
  if( max_val < l.back()  ) return --l.end();

  return max_itr;

}

