    if(allNegative){
        int MAX = -INF, idx = -1;
        rep(i, 0, n){
            if(MAX < a[i]){
                MAX = a[i]; idx = i;
            }
        }
        sum = MAX;
        rep(i, 0, idx) ans.push_back(i);
        for(int i = n - 1; i > idx; i--) ans.push_back(i);
    }else{
        rep(r, 0, 2){
            vector<int> cand;
            int now = 0;
            rep(i, 0, n){
                if(i % 2 != r) continue;
                if(a[i] >= 0){
                    now += a[i];
                    cand.push_back(i);
                }
            }
            if(sum < now){
                sum = now;
                ans.clear();
            }else{
                continue;
            }
            int pre = 0;
            rep(i, 0, cand[0]){
                ans.push_back(0);
                pre++;
            }
            for(int i = 0; i < cand.size() - 1; i++){
                int idx = (cand[i] + cand[i + 1]) / 2 - pre;
                int diff = cand[i + 1] - cand[i];
                for(int j = 0; j < diff / 2; j++){
                    ans.push_back(idx);
                    idx--;
                    pre += 2;
                }
            }
            for(int i = pre; i < n - 1; i++){
                ans.push_back(n - 1 - pre);
                pre++;
            }
        }
    }
    cout << sum << endl;
    cout << ans.size() << endl;
    rep(i, 0, ans.size()){
        cout << ans[i] + 1 << endl;
    }
}

