    ll n; llin(n);
    V<ll> alist; llina(alist, n);

    ll maxsum = -1e18;
    ll maxs = -1;
    ll maxl = -1;

    rep (si, n) {
        ll nowsum = 0;
        for (ll ii = si; ii < n; ii += 2LL) {
            nowsum += alist[ii];
            if (nowsum > maxsum) {
                maxsum = nowsum;
                maxs = si;
                maxl = ii;
            }
        }
    }

    V<ll> anslist;

    ll ei = n-1;
    rep (i, n - maxl - 1) anslist.pb(ei--);
    rep (i, maxs) anslist.pb(0);

    ll space_cnt = (maxl - maxs) / 2LL;
    rep (i, space_cnt) anslist.pb(1);

    cout << maxsum << endl;
    cout << anslist.size() << endl;
    for (auto ans : anslist) cout << ans+1 << endl;
}

