using namespace std;
typedef long long li;

vector<li> calc_accum(vector<li>& xs) {
    vector<li> acc(xs.size() + 1);
    for (int i = 0; i < xs.size(); ++i) {
        acc[i + 1] = acc[i] + xs[i];
    }
    return acc;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    li n;
    cin >> n;
    vector<li> xs((n + 1) / 2), ys(n / 2);
    for (int i = 0; i < n; ++i) {
        li x;
        cin >> x;
        if (i & 1) {
            ys[i / 2] = x;
        } else {
            xs[i / 2] = x;
        }
    }
    vector<li> x_acc = calc_accum(xs), y_acc = calc_accum(ys);
    auto x_max = max_element(x_acc.begin(), x_acc.end());
    auto x_min = min_element(x_acc.begin(), x_acc.end());
    auto y_max = max_element(y_acc.begin(), y_acc.end());
    auto y_min = min_element(y_acc.begin(), y_acc.end());

    li x_maxsum = *x_max - *x_min;
    li y_maxsum = *y_max - *y_min;
    cout << max(x_maxsum, y_maxsum) << endl;

    li front, back, length;
    if (x_maxsum > y_maxsum) {
        front = (x_min - x_acc.begin()) * 2;
        back = (x_max - x_acc.begin()) * 2 - 2;
        length = x_max - x_min;
    } else {
        front = (y_min - y_acc.begin()) * 2 + 1;
        back = (y_max - y_acc.begin()) * 2 - 1;
        length = y_max - y_min;
    }
    vector<li> ops;
    for (int j = n - 1; j > back; --j) {
        ops.push_back(j);
    }
    for (int j = 0; j < front; ++j) {
        ops.push_back(0);
    }
    for (int k = 0; k < length - 1; ++k) {
        ops.push_back(1);
    }
    cout << ops.size() << endl;
    for (int i = 0; i < ops.size(); ++i) {
        cout << ops[i] + 1 << endl;
    }
    return 0;
}

