using namespace std;
typedef long long ll;

int main(){
    int n; cin>>n;
    ll p=0,q=0;
    vector<int> a(n);
    bool AllNeg = true;
    rep(i,n){
        cin>>a[i];
        if(a[i]>=0) AllNeg = false;
        if(i&1){
            p += max(a[i],0);
        }else{
            q += max(a[i],0);
        }
    }

    if(AllNeg){ //１つ以外を端で消す
        ll MX = -1e18;
        int where = 0;
        rep(i,n){
            if(MX<a[i]){
                where = i;
                MX = a[i];
            }
        }
        vector<int> NegAns;
        rep(i,where){
            NegAns.push_back(1);
        }
        rep(i,n-where-1){
            NegAns.push_back(2);
        }
        cout << MX << endl;
        cout << NegAns.size() << endl;
        rep(i,NegAns.size()){
            cout << NegAns[i] << endl;
        }

        return 0;
    }

    vector<int> ans; //0-indexed
    cout << max(p,q) << endl;
    if(p>q){
        ans.push_back(1);
        a.erase(a.begin());
        if(n%2==1){
            ans.push_back(a.size());
            a.erase(a.begin()+a.size()-1);
        }
    }
    while(a.size()>1){
        while(a[0]<0){
            ans.push_back(1);
            a.erase(a.begin());
            if(a.size()>1){
                ans.push_back(1);
                a.erase(a.begin());
            }
        }

        for(int i=0;i<a.size();i+=2){
            if(i>0){
                if(a[i]>=0&&a[i-2]>=0){
                    a[i-1] = a[i] + a[i-2];
                    a.erase(a.begin()+i);
                    a.erase(a.begin()+i-2);
                    ans.push_back(i);
                    i -= 2;
                }else if(a[i]<0&&a[i-2]<0){
                    a[i-1] = a[i] + a[i-2];
                    a.erase(a.begin()+i);
                    a.erase(a.begin()+i-2);
                    ans.push_back(i);
                    i -= 2;
                }
            }
        }

        while(a[a.size()-1]<0){
            ans.push_back(a.size());
            a.erase(a.end());
            if(a.size()>1){
                ans.push_back(a.size());
                a.erase(a.end());
            }
        }
    }
    cout << ans.size() << endl;
    for(auto u : ans){
        cout << u << endl;
    }

    return 0;
}

