class UnionFind {
protected:
    int* par, * rank, * size;
public:
    UnionFind(unsigned int size) {
        par = new int[size];
        rank = new int[size];
        this->size = new int[size];
        rep(i, size) {
            par[i] = i;
            rank[i] = 0;
            this->size[i] = 1;
        }
    }
    int find(int n) {
        if (par[n] == n)return n;
        return par[n] = find(par[n]);
    }
    void unite(int n, int m) {
        n = find(n);
        m = find(m);
        if (n == m)return;
        if (rank[n] < rank[m]) {
            par[n] = m;
        }
        else {
            par[m] = n;
            if (rank[n] == rank[m])rank[n]++;
        }
    }
    bool same(int n, int m) {
        return find(n) == find(m);
    }
    int getsize(int n) {
        return size[find(n)];
    }
};
class PerpetualUnionFind :UnionFind {
    P* notparent;
    vector<P>* sizevec;
    int opcount = 0;
public:
    PerpetualUnionFind(unsigned int size) :UnionFind(size) {
        this->sizevec = new vector<P>[size];
        notparent = new P[size];
        rep(i, size) {
            par[i] = i;
            rank[i] = 0;
            sizevec[i].push_back(make_pair(-1, 1));
            notparent[i] = make_pair(INF, i);
        }
    }
    int find(int n, int t = INF) {
        if (opcount <= t) {
            if (par[n] == n)return n;
            return par[n] = find(par[n]);
        }
        if (notparent[n].first <= t)return find(notparent[n].second, t);
        return n;
    }
    void unite(int n, int m) {
        n = find(n);
        m = find(m);
        if (n == m) {
            opcount++;
            return;
        }
        if (rank[n] < rank[m]) {
            par[n] = m;
            notparent[n] = make_pair(opcount, m);
            sizevec[m].push_back(make_pair(opcount, sizevec[m].back().second + sizevec[n].back().second));
        }
        else {
            par[m] = n;
            notparent[m] = make_pair(opcount, n);
            sizevec[n].push_back(make_pair(opcount, sizevec[n].back().second + sizevec[m].back().second));
            if (rank[n] == rank[m])rank[n]++;
        }
        opcount++;
    }
    bool same(int n, int m, int t = INF) {
        return find(n, t) == find(m, t);
    }
    int getsize(int n, int t = INF) {
        n = find(n, t);
        auto ite = lower_bound(sizevec[n].begin(), sizevec[n].end(), make_pair(t, (int)0));
        if (ite == sizevec[n].end())ite--;
        if (t < (*ite).first)ite--;
        return (*ite).second;
    }
};
class RollingHash {
    string s;
    int n, m, base;
    deque<int> has;
public:
    RollingHash(string s, int m, int b) : n(s.size()), m(m), base(b) { init(s, m, b); }
    void init(string s, int m, int b) {
        n = s.size();
        has.resize(n);
        base = b;
        this->s = s;
        this->m = m;
        rep(i, n) {
            has[i] = (int)s[i];
            if (i)has[i] += base * has[i - 1] % m;
            has[i] %= m;
        }
    }
    operator int() const {
        return has.back();
    }
    void cut(int a, int b) {
        assert(!(a >= b || a < 0 || n < b));
        rep(i, a)has.pop_front();
        rep(i, n - b)has.pop_back();
        s = s.substr(a, b);
        int memo = modpow(modpow(base, n - b, m), m - 2, m);
        rep(i, b - a) {
            has[i] *= memo;
            has[i] %= mod;
        }
        n = b - a;
    }
    int query(int a, int b) {
        assert(!(a >= b || a < 0 || n < b));
        return (has[b - 1] - modpow(base, b - a, m) * (!a ? 0 : has[a - 1]) % m + m) % m;
    }
    int operator+(RollingHash t) {
        assert(m == t.m && base == t.base);
        return (has[n - 1] * modpow(base, t.n, m) % m + t.has[t.n - 1]) % m;
    }
    RollingHash& operator+=(string t) {
        s += t;
        has.resize(n + t.size());
        for (int i = n; i < n + t.size(); i++) {
            has[i] = (int)t[i] * base % m;
            has[i] += base * has[i - 1] % m;
            has[i] %= m;
        }
        n += t.size();
        return *this;
    }
};
template<typename T, typename U>
class SegTree {
    int n = 1;
    T* node = NULL;
    U* lazy = NULL;
    bool* lazyflag = NULL;
    T nodee;
    function<T(T, T)> nodef;
    function<U(U, U)> lazyf;
    function<T(int, T, U)> updf;
    void eval(int k, int l, int r) {
        if (lazyflag[k]) {
            node[k] = updf(r - l, node[k], lazy[k]);
            if (r - l > 1) {
                lazyflag[2 * k + 1] = lazyflag[2 * k + 2] = true;
                lazy[2 * k + 1] = lazyf(lazy[2 * k + 1], lazy[k]);
                lazy[2 * k + 2] = lazyf(lazy[2 * k + 2], lazy[k]);
            }
            lazyflag[k] = false;
        }
    }
public:
    SegTree(int m, int init, T nodee, function<T(T, T)> nodef, function<U(U, U)> lazyf, function<T(int, T, U)> updf) :nodee(nodee), nodef(nodef), lazyf(lazyf), updf(updf) {
        delete[] node;
        delete[] lazy;
        while (n < m)n *= 2;
        node = new T[2 * n], lazy = new U[2 * n], lazyflag = new bool[2 * n];
        rep(i, 2 * n) {
            node[i] = init;
            lazyflag[i] = false;
        }
    }
    ~SegTree() {
        delete[] node;
        delete[] lazy;
    }
    void update(int a, int b, U x, int k = 0, int l = 0, int r = -1) {
        if (r == -1)r = n;
        eval(k, l, r);
        if (b <= l || r <= a)return;
        if (a <= l && r <= b) {
            lazyflag[k] = true;
            lazy[k] = x;
            eval(k, l, r);
        }
        else {
            update(a, b, x, 2 * k + 1, l, (l + r) / 2);
            update(a, b, x, 2 * k + 2, (l + r) / 2, r);
            node[k] = nodef(node[2 * k + 1], node[2 * k + 2]);
        }
    }
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r == -1)r = n;
        eval(k, l, r);
        if (b <= l || r <= a)return nodee;
        if (a <= l && r <= b)return node[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return nodef(vl, vr);
    }
};
class Matrix {
    int n;
    vector<vector<int>> vec;
    void Measure() {
        rep(i, n) {
            rep(j, n) {
                if (i != j)vec[i][j] = 0;
                else vec[i][j] = 1;
            }
        }
    }
public:
    Matrix(int n) {
        this->n = n;
        vec.resize(n, vector<int>(n));
    }
    Matrix(int n, vector<int> vec) {
        if (vec.size() != n * n) {
            cerr << "Invalid construct of matrix" << endl;
            exit(1);
        }
        this->n = n;
        this->vec.resize(n, vector<int>(n));
        rep(i, n) {
            rep(j, n)this->vec[i][j] = vec[i * n + j];
        }
    }
    int operator[](int a) {
        return vec[a / n][a % n];
    }
    unsigned int size() { return n; }
    Matrix operator*(const Matrix a) {
        if (this->n != a.n) {
            cerr << "Invalid maltiply of matrix" << endl;
            exit(1);
        }
        vector<int> memo(n);
        rep(i, n) {
            rep(j, n) {
                rep(k, n) {
                    memo[j] += vec[i][k] * a.vec[k][j];
                }
            }
            vec[i] = memo;
            memo.clear();
            memo.resize(n);
        }
        return *this;
    }
    Matrix letmod(int m = mod) {
        rep(i, n) {
            rep(j, n)vec[i][j] %= m;
        }
        return *this;
    }
    static Matrix measure(int n) {
        Matrix res(n);
        res.Measure();
        return res;
    }
    static Matrix mypow(Matrix a, int b, int m = mod) {
        a.letmod(m);
        if (!b)return Matrix::measure(a.size());
        if (b % 2)return (mypow(a, b - 1, m) * a).letmod(m);
        Matrix memo = mypow(a, b / 2, m);
        return (memo * memo).letmod(m);
    }
};
