    for (int parity = 0; parity < 2; parity++) {
        vector<long long> half;

        for (int i = parity; i < N; i += 2)
            half.push_back(A[i]);

        int H = half.size();
        vector<long long> prefix(H + 1, 0);

        for (int i = 0; i < H; i++)
            prefix[i + 1] = prefix[i] + half[i];

        long long best = -LL_INF;
        long long minimum = 0;
        int min_index = 0;
        int _best_start = -1, _best_end = -1;

        for (int end = 1; end <= H; end++) {
            if (prefix[end] - minimum > best) {
                best = prefix[end] - minimum;
                _best_start = min_index;
                _best_end = end;
            }

            if (prefix[end] < minimum) {
                minimum = prefix[end];
                min_index = end;
            }
        }

        if (best > overall_best) {
            overall_best = best;
            best_parity = parity;
            best_start = _best_start;
            best_end = _best_end;
        }
