ll DFS(int le, int ri){
	if (f[le][ri] != -oo) return f[le][ri];
	if (le == ri) return f[le][ri] = a[le];
	ll pre[MAXN];
	int cl, cr;
	for (cr = le; cr < ri; cr += 2) {
		pre[cr] = -oo;
		if (cr - 2 >= le) pre[cr] = pre[cr - 2]; 
		cmax(pre[cr], DFS(le, cr));
	}
	for (cl = ri; cl > le; cl -= 2) {
		while (cr >= cl) cr -= 2;
		cmax(f[le][ri], pre[cr] + DFS(cl, ri));
	}
	return f[le][ri];
}

void Go(int le, int ri, int x){
	bool vaild = 0;
	for (int cr = le; cr <= ri; cr += 2) if (!vaild) 
		for (int cl = ri; cl > cr; cl -= 2) if (!vaild) {
			if (f[le][cr] + f[cl][ri] == f[le][ri]) {
				Go(cl, ri, x + cl - le); Go(le, cr, x + 2);
				for (int i = cr + 2; i <= cl - 2; i += 2) ss.push_back(x + 3);
				ss.push_back(x + 2);
				vaild = 1;	
			}	
		}
}

