void solve(int m)
{
    bool use[1010] = {false};
    for(int i = 0; i < N; i++){
        if(i % 2 == m && a[i] >= 0){
            use[i] = true;
        }
    }
    vector<int> ans;
    int l, r;
    for(int i = N - 1; i >= 0; i--){
        r = i;
        if(use[i])break;
        ans.pb(i + 1);
    }
    for(int i = 0; i < N; i++){
        l = i;
        if(use[i])break;
        ans.pb(1);
    }
    vector<pii> v;
    for(int i = l; i <= r; i++){
        if(use[i]){
            v.pb(mk(a[i], 1));
