                v[i - 1].se = 2;
                v[i + 1].se = 2;
                ans.pb(i + 1);
                flag = false;
                break;
            }
            else if(v[i - 1].se == 1 && v[i].se == 0 && v[i + 1].se == 1){
                v[i - 1].se = 2;
                v[i].fi = v[i - 1].fi + v[i + 1].fi;
                v[i].se = 1;
                v[i + 1].se = 2;
                ans.pb(i + 1);
                flag = false;
                break;
            }
        }
        if(flag)break;
        vector<pii> g;
        for(int i = 0; i < (int)v.size(); i++){
            if(v[i].se != 2){
                g.pb(v[i]);
            }
        }
        v = vector<pii>();
        for(int i = 0; i < (int)g.size(); i++){
            v.pb(g[i]);
        }
        /*for(int i = 0; i < (int)v.size(); i++){
            printf("v[%lld] (%lld, %lld)\n", i, v[i].fi, v[i].se);
        }*/
    }
    printf("%lld\n", (int)ans.size());
    for(int i = 0; i <(int)ans.size(); i++){
        printf("%lld\n", ans[i]);
    }
    return;
}

