			ll t = 0;
			for(int i = 0; i < n; i++) {
				if(i % 2 == bit && b[i] > 0) t += b[i], vis.pb(1);
				else vis.pb(0);
			}
			if(*max_element(all(vis)) == 0) continue;
			vi tOp;
			while(sz(vis) > 1) {
				vi siv;
				rep(i, 0, sz(vis)) {
					if(vis[i]) {
						siv.pb(vis[i]);
						continue;
					}
					if(i == 0 || i + 1 == sz(vis)) {
						tOp.pb(sz(siv) + 1);
					} else if(vis[i - 1] == vis[i + 1]) {
						tOp.pb(sz(siv) + 1);
						siv.pop_back(), siv.pb(vis[i - 1]);
						i++;
					}
				}
				swap(vis, siv);
			}
			if(ans < t) ans = t, ansOp = tOp;
		}
	}
	printf("%lld\n", ans);
	printf("%d\n", sz(ope) + sz(ansOp));
	for(auto & op : ope) printf("%d\n", op);
	for(auto & op : ansOp) printf("%d\n", op);
	return 0;
}

