	calc[l][r] = true;
	res = -INF;
	if (res < get(l + 1, r)) {
		res = get(l + 1, r);
		p[l][r] = l;
	}
	if (res < get(l, r - 1)) {
		res = get(l, r - 1);
		p[l][r] = r;
	}
	if (r - l >= 2 && res < a[l] + get(l + 2, r)) {
		res = a[l] + get(l + 2, r);
		p[l][r] = l + 1;
	}
	if (r - l >= 2 && res < a[r] + get(l, r - 2)) {
		res = a[r] + get(l, r - 2);
		p[l][r] = r - 1;
	}
	return res;
}

