const int maxn = 1e5 + 10;
typedef long long ll;
int n, nb, nc;
int a[maxn], b[maxn], c[maxn]; 
bool vis[maxn];
struct RET
{
	ll ans;
	int l, r;
};
RET solve(int *num, int m)
{
	ll preMin = 0, sum = 0, ret = 0;
	int l = 0, r = 0;
	for(int i = 1; i <= m; ++i)
	{
		sum += num[i];
		if(ret < sum - preMin)
		{
			ret = sum - preMin;
			r = i;
		}
		if(preMin > sum)
		{
			preMin = sum;
			l = i;
		}
	}
	return RET{ret, l, r};
}		
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; ++i) scanf("%d", &a[i]);
	for(int i = 1; i <= n; ++i)
		if(i & 1)
			b[++nb] = a[i];
		else
			c[++nc] = a[i];
	RET retb = solve(b, nb);
	RET retc = solve(c, nc);
	vector<int> o;
	if(retb.ans >= retc.ans)
	{
