pair<ll,int> memoLF[1010][1010], memoRF[1010][1010], memoF[1010][1010];
pair<ll, int> LF(int l, int r) {
    if (memoLF[l][r].first != -infl) return memoLF[l][r];
    if (l % 2 != r % 2) return LF(l + 1, r);

    ll sm = B[r % 2][r];
    if (l) sm -= B[l % 2][l - 1];
    pair<ll, int> res = { sm, l * 1010 + r };

    if(l < r) res = max(res, LF(l + 2, r));
    return memoLF[l][r] = res;
}
pair<ll, int> RF(int l, int r) {
    if (memoRF[l][r].first != -infl) return memoRF[l][r];
    if (l % 2 != r % 2) return RF(l, r - 1);

    ll sm = B[r % 2][r];
    if (l) sm -= B[l % 2][l - 1];
    pair<ll, int> res = { sm, l * 1010 + r };

    if (l < r) res = max(res, RF(l, r - 2));
    return memoRF[l][r] = res;
}
pair<ll, int> F(int l, int r) {
    if (memoF[l][r].first != -infl) return memoF[l][r];
    if (l % 2 != r % 2) {
        return memoF[l][r] = max(F(l + 1, r), F(l, r - 1));
    }

    ll sm = B[r % 2][r];
    if (l) sm -= B[l % 2][l - 1];
    pair<ll, int> res = { sm, l * 1010 + r };

    if (l < r) {
        chmax(res, F(l + 2, r));
        chmax(res, F(l, r - 2));
    }
    return memoF[l][r] = res;
}
