            bl = F(0, cent - 2);
            br = F(cent + 2, N - 1);
            b = bl.first + br.first;
        }

        ll c = max(a, b);
        if (ans < c) {
            ans = c;
            opt_cent = cent;

            if (a < b) lft = bl, rht = br;
            else lft = al, rht = ar;
        }
    }

    int ng = -1;
    rep(i, 0, N) if (ans < A[i]) {
        ans = A[i];
        ng = i;
    }

    if (0 <= ng) {
        cout << ans << endl;
        vector<int> buf;
        rep(i, 0, ng) buf.push_back(0);
        N -= ng;
        rep(i, 1, N) buf.push_back(1);
        int n = buf.size();
        printf("%d\n", n);
        rep(i, 0, n) printf("%d\n", buf[i] + 1);
        return;
    }

    cout << ans << endl;

    vector<int> buf;

    int a = lft.second / 1010;
    int b = lft.second % 1010;

    int c = rht.second / 1010;
    int d = rht.second % 1010;

    rep(i, 0, a) {
        buf.push_back(0);
        a--; b--; c--; d--; N--; opt_cent--;
    }
    rep(i, 0, N - d - 1) buf.push_back(N - 1 - i);
    N = d;

    rep(i, 0, (b - a) / 2) buf.push_back(1);
    c -= b - a;
    d -= b - a;
    b = a;

    rep(i, 0, (d - c) / 2) buf.push_back(c + 1);
    c = d;

    int dlt = opt_cent - b;
    if (dlt == 1) {
        buf.push_back(1);
    } else {
        if (dlt % 2 == 0) {
            buf.push_back(opt_cent);
            opt_cent--;
            c -= 2; d -= 2; N -= 2;
        }

        int fr = (opt_cent - b) / 2;
        rep(i, 0, fr) {
            buf.push_back(2);
            opt_cent -= 2;
            c -= 2; d -= 2; N -= 2;
        }

        fr = (c - opt_cent) / 2;
        rep(i, 0, fr) {
            buf.push_back(4);
            opt_cent -= 2;
            c -= 2; d -= 2; N -= 2;
        }

        buf.push_back(2);
        buf.push_back(1);
    }

    int n = buf.size();
    printf("%d\n", n);
    rep(i, 0, n) printf("%d\n", buf[i] + 1);
}

