int solve(int a,string st,int l,int r){
	assert(l<=r);
	if(a==0){
		if(l==r){
			return 2;
		}else if(l+1==r&&st[l]=='0'){
			return 1;
		}else{
			return 0;
		}
	}else if(a==1){
		if(l==r){
			return 2;
		}else if(l+1==r&&st[l]=='1'){
			return 1;
		}else{
			return 0;
		}
	}else{
		int sum=0;
		for(int m=l;m<=r;++m){
			int ans_l=solve(a-1,st,l,m);
			int ans_r=solve(a-2,st,m,r);

			sum+=ans_l*ans_r;
		}
		return sum;
	}
}
