int main() {
	int N; cin >> N;
	typedef vector<ll> vll;
	vll A(N);
	rep(i, N) cin >> A[i];
	vll dp(N + 10), next(N + 10);
	ll INFLL = (ll) INF * INF;
	rep(i, N + 10) dp[i] = -INFLL, next[i] = -1;
	function<ll(int)> solve=[&](int v){
		if (dp[v] > -INFLL) return dp[v];
		ll maxans = 0;
		for (int i = 2; v + i < N; i += 2) {
			ll ret = solve(v + i);
			if (ret > maxans) {
				maxans = ret;
				next[v] = v + i;
			}
		}
		return dp[v] = A[v] + maxans;
	};
	ll ans = -INFLL, root = -1;
	rep(i, N) {
		ll ret = solve(i);
		if (ret > ans) {
			ans = ret;
			root = i;
		}
	}
	pr(ans);
	pr(root);

	vint good;
	good.pb(root);
	for (int i = root; i = next[i], i >= 0; good.pb(i));
	pra(good);

	vint ope;
	for (int i = N - 1; i > good[good.size() - 1]; i--) ope.pb(i);
	while (good.size() > 1) {
		int tail = good[good.size() - 1];
		int tail2 = good[good.size() - 2];
		while (tail - tail2 > 2) {
			ope.pb(tail - 2);
			tail -= 2;
		}
		ope.pb(tail - 1);
		good.pop_back();
	}
	rep(i, good[0]) ope.pb(0);

	cout << ans << endl;
	cout << ope.size() << endl;
	rep(i, ope.size()) {
		cout << ope[i] + 1 << endl;
	}
	return 0;
}

