using namespace std;

int n;
int a[1000];

int main() {
	int i, j;

	cin >> n;
	rep(i, n) cin >> a[i];

	int maxId = 0;
	rep(i, n) if (a[maxId] < a[i]) maxId = i;
	if (a[maxId] < 0) {
		cout << a[maxId] << endl;
		cout << n - 1 << endl;
		for (i = n - 1; i > maxId; i--) cout << i + 1 << endl;
		for (i = 0; i < maxId; i++) cout << i + 1 << endl;
		return 0;
	}

	vector<int> pos[2];
	int sum[2] = {0};
	rep(i, n) {
		if (a[i] >= 0) {
			sum[i % 2] += a[i];
			pos[i % 2].push_back(i);
		}
	}
	vector<int> ids;
	if (sum[0] > sum[1]) ids = pos[0];
	else ids = pos[1];

	vector<int> ans;
	for (i = n - 1; i > *ids.rbegin(); i--) ans.push_back(i);
	for (i = 0; i < ids[0]; i++) ans.push_back(i);
	for (i = 0; i + 1 < ids.size(); i++) {
		int m = (ids[i + 1] - ids[i]) / 2;
		for (j = m; j > 0; j--) {
			ans.push_back(j);
		}
	}

	cout << max(sum[0], sum[1]) << endl;
	cout << ans.size() << endl;
	rep(i, ans.size()) cout << ans[i] + 1 << endl;
	return 0;
}

