const int N=1<<18;
int y[N],f[N];
long long dp[N],a[N];

int main()
{
	int n;
	scanf("%d",&n);
	for(int i=0;i<n;i++)
	{
		scanf("%lld",a+i);
	}
	for(int i=0;i<n;i++)
	{
		dp[i]=a[i];
		f[i]=-1;
		for(int j=i-2;j>=0;j-=2)if(dp[j]+a[i]>dp[i])
		{
			dp[i]=dp[j]+a[i];
			f[i]=j;
		}
	}
	int ans=0;
	for(int i=1;i<n;i++)
	{
		if(dp[i]>dp[ans])ans=i;
	}
	int m=0;
	for(int i=ans;i<n-1;i++)
	{
		y[m++]=ans+2;
	}
	for(int i=ans;~i;i=f[i])
	{
		if(f[i]==-1)
		{
			for(int j=0;j<i;j++)
			{
				y[m++]=1;
			}
		}
		else
		{
			for(int j=0;j<(i-f[i])/2;j++)
			{
				y[m++]=f[i]+2;
			}
		}
	}
	printf("%lld\n%d\n",dp[ans],m);
	for(int i=0;i<m;i++)
	{
		printf("%d\n",y[i]);
	}
	return 0;
}

