#define int long long
using namespace std;

int INF = 1e+15;
int n;
int a[1001];	//a[n] = 0
int dp[1002];	//dp[i] = 最後にa[i-1]を取ったときの〇の和の最大値, [消す]〇(取る)を1セットの遷移とする. dp[0]～dp[n]まで計算

signed main() {
	int i, j;

	cin >> n;
	for (i = 0; i < n; i++) cin >> a[i];
	for (i = 0; i <= n + 1; i++) dp[i] = -INF;

	dp[0] = 0;
	for (i = 0; i <= n; i++) {
		//[i, j)を取る
		for (j = i + 1; j <= n + 1; j++) {
			int eraseCnt = j - i - 1;
			if (i != 0 && j != n + 1 && eraseCnt % 2 == 0) continue;
			int tasu = a[j - 1];			//a[j - 1]を取る
			dp[j] = max(dp[j], dp[i] + tasu);
		}
	}

	int ans = dp[n + 1];

	//復元
	bool used[1002] = {false};
	int pos = n + 1;
	used[pos - 1] = true;

	while (pos > 0) {
		for (i = pos - 1; i >= 0; i--) {
			int eraseCnt = pos - i - 1;
			if (i != 0 && pos != n + 1 && eraseCnt % 2 == 0) continue;
			if (dp[i] + a[pos - 1] == dp[pos]) break;
		}
		pos = i;
		if (pos > 0) used[pos - 1] = true;
		//[i, pos-2]を消すので
	}

	cout << ans << endl;

	//復元パート
	vector<int> l, r;

	for (i = 0; i < n; i++) if (used[i]) break;
	l.push_back(0); r.push_back(i);
	i++;

	int yo = -1;
	for (; i <= n; i++) {
		if (used[i - 1] && !used[i]) yo = i;
		if (!used[i - 1] && used[i]) {
			l.push_back(yo);
			r.push_back(i);
		}
	}

	//復元パート
	vector<int> ope;
	int off = 0;
	for (i = 0; i < l.size(); i++) {
		//cout << l[i] << " " << r[i] << " " << off << endl;
		if (l[i] == 0) {
			for (j = 0; j < r[i]; j++) ope.push_back(j);
			off += r[i];
		}
		else if (r[i] >= n) {
			for (j = l[i]; j < r[i]; j++) ope.push_back(j - off);
			off += r[i] - l[i];
		}
		else {
			//cout << "neko*neko" << endl;
			for (j = 0; j < (r[i] - l[i] + 1) / 2; j++) ope.push_back(l[i] - off);
			off += (r[i] - l[i] + 1) / 2 * 2;
		}
	}

	cout << ope.size() << endl;
	for (i = 0; i < ope.size(); i++) {
		cout << ope[i] + 1 << endl;
	}
	return 0;
}

#include <iostream>
#include <vector>
using namespace std;
const int N = 1002;
typedef long long LL;
const LL INF = 1e13;
LL dp[N][N][2], a[N], ok[N]; 
int n, vis[N][N], bst[N][N][2]; // { 0 for L, 1 for R }
void dfs(int L, int R) {
    if (vis[L][R])
        return;
    vis[L][R] = 1;

    if (L == R) {
        dp[L][R][0] = a[L]; bst[L][R][0] = L; return; 
    }
    if (R - L == 1) {
        dp[L][R][0] = a[L]; bst[L][R][0] = L;
        dp[L][R][1] = a[R]; bst[L][R][1] = R; return;
    }
    dp[L][R][0] = dp[L][R][1] = - INF;
    for (int i = L; i < R; i ++) {
        dfs(L,i); dfs(i+1,R);
    }
    if ((R - L) % 2 == 1) {
        int bst_0 = -1, bst_1 = -1;
        for (int i = L; i < R; i ++) {
            if (dp[L][i][0] > dp[L][R][0])
                bst_0 = i, dp[L][R][0] = dp[L][i][0];
        }
        for (int i = R; i > L; i --) {
            if (dp[i][R][1] > dp[L][R][0])
                bst_1 = i-1, dp[L][R][1] = dp[i][R][1];
        }
        bst[L][R][0] = bst_0;
        bst[L][R][1] = bst_1;
    } else {
        int bst_0 = -1;
        dp[L][R][0] = a[L] + a[R]; bst[L][R][0] = (L+R)/2;

        for (int i = L; i < R; i ++) {
            if ((i - L) % 2 == 0) {// 左边长度为奇数
                if (dp[L][i][0] + dp[i+1][R][1] > dp[L][R][0]) {
                    bst_0 = i, dp[L][R][0] = dp[L][i][0] + dp[i+1][R][1];
                }
            } else {                  // 左边长度为偶数
                if (dp[L][i][0] + dp[i+1][R][0] > dp[L][R][0]) {
                    bst_0 = i, dp[L][R][0] = dp[L][i][0] + dp[i+1][R][0];
                }
            }
        }

        bst[L][R][0] = bst_0;
    }
}

void gao(int l, int r, int s) {
    if ((r - l) % 2 == 1) {
        int pos = bst[l][r][s];
        gao(l, pos, s), gao(pos+1, r, s);
    }
    if ((r - l) % 2 == 0) {
        int pos = bst[l][r][s];
        if (bst[l][r][0] == (l + r) / 2) {
            ok[(l+r)>>1] = 1;
        }
        if ((pos - l) % 2 == 1) {
            gao(l, pos, 0); gao(pos+1, r, s);
        } else {
            gao(l, pos, 0); gao(pos+1, r, 1);            
        }
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i ++) {
        scanf("%lld", &a[i]);
    }
    LL ans = -INF, bst_L = 1, bst_R = n;
    for (int i = 1; i <= n; i ++) {
        for (int j = i; j <= n; j ++) {
            dfs(i, j);
            if ((j-i)%2 == 0) {
                if (dp[i][j][0] > ans) {
                    ans = dp[i][j][0];
                    bst_L = i, bst_R = j;
                }
            }
        }
    }
    gao(bst_L, bst_R, 0);
    vector<int> v;
    for (int i = 1; i < bst_L; i ++) v.push_back(i);
