		if (i > 0) odd[i] += odd[i - 1], even[i] += even[i - 1];
		if (i % 2 == 0) even[i] += a[i];
		else odd[i] += a[i];
	}
	fill((LL*)dp, (LL*)(dp + 1000), -(1LL << 18));
	for (int len = 1; len <= N; len++) {
		for (int i = 0; i + len <= N; i++) {
			if (len > 1 && dp[i][i + len - 1] <= dp[i + 1][i + len - 1]) {
				dp[i][i + len - 1] = dp[i + 1][i + len - 1];
				nxt[i][i + len - 1] = 0;
			}
			if (len > 1 && dp[i][i + len - 1] <= dp[i][i + len - 2]) {
				dp[i][i + len - 1] = dp[i][i + len - 2];
				nxt[i][i + len - 1] = 1;
			}
			if (len % 2 == 1) {
				LL tmp = 0;
				if (i % 2 == 0) {
					tmp = even[i + len - 1];
					if (i > 0) tmp -= even[i - 1];
				}
				else {
					tmp = odd[i + len - 1];
					if (i > 0) tmp -= odd[i - 1];
				}
				if (dp[i][i + len - 1] <= tmp) {
					dp[i][i + len - 1] = tmp;
					nxt[i][i + len - 1] = 2;
				}
			}
		}
