			ans.push_back(1);
			l++;
		}
		else if (nxt[l][r] == 1) {
			ans.push_back(r - l + 1);
			r--;
		}
		else {
			for (int i = 0; i < (r - l) / 2; i++) ans.push_back(2);
			break;
		}
	}
	cout << ans.size() << endl;
	for (int i = 0; i < ans.size(); i++) {
		cout << ans[i] << endl;
	}
}

