const int N = 1010;
int n;
int a[N], b[N];
bool vis[N];
int main(){
	scanf("%d", &n);
	rep(i, 0, n) scanf("%d", a + i);
	vi ope, ansOp;
	ll ans = 0;
	if(*max_element(a, a + n) <= 0) {
		int p = max_element(a, a + n) - a;
		ans = a[p];
		rep(i, 0, p) ope.pb(1);
		for(int i = n - 1; i > p; i--) ope.pb(i - (p - 1));
	} else {
		int be = 0, ed = n;
		while(be < n && a[be] <= 0) {
			be++; ope.pb(1);
		}
		while(ed > 0 && a[ed - 1] <= 0) {
			ope.pb(ed - be); ed--;
		}
		n = ed - be;
		rep(i, be, ed) b[i - be] = a[i];
		//rep(i, 0, n) printf("%d\n", b[i]);
		for(int bit = 0; bit < 2; bit++) {
			vi vis;
			ll t = 0;
			for(int i = 0; i < n; i++) {
				if(i % 2 == bit && b[i] > 0) t += b[i], vis.pb(1);
				else vis.pb(0);
			}
			if(*max_element(all(vis)) == 0) continue;
			vi tOp;
			while(sz(vis) > 1) {
				vi siv;
		//		rep(i, 0, sz(vis)) printf("%d ", vis[i]);
		//		puts("");
				rep(i, 0, sz(vis)) {
					if(vis[i]) {
						siv.pb(vis[i]);
						continue;
					}
					if(sz(siv) == 0 || i + 1 == sz(vis)) {
						tOp.pb(sz(siv) + 1);
					} else if(vis[i - 1] == vis[i + 1]) {
						tOp.pb(sz(siv) + 1);
						siv.pop_back(); siv.pb(vis[i + 1]);
						i++;
					} else siv.pb(vis[i]);
				}
				swap(vis, siv);
			}
			if(ans < t) ans = t, ansOp = tOp;
		}
	}
	printf("%lld\n", ans);
	printf("%d\n", sz(ope) + sz(ansOp));
	for(auto & op : ope) printf("%d\n", op);
	for(auto & op : ansOp) printf("%d\n", op);
	return 0;
}

