map<P, ll> mp;
map<P, ll> mov;
vector<ll> a;
ll solve(ll l, ll r) {
	if (r - l == 1)
		return a[l];
	if ((r - l) % 2 == 0 || r - l <= 0)
		return -INF;
	if (mp.find(P(l, r)) != mp.end())
		return mp[P(l, r)];
	ll nowans = -INF;
	for (ll k = l + 1;k < r - 1;k++) {
		ll now = solve(l, k) + solve(k + 1, r);
		if (nowans < now) {
			nowans = now;
			mov[P(l, r)] = k;
		}
	}
	return mp[P(l, r)] = nowans;
}
vector<ll> ans2;
void solve2(ll l, ll r) {
	if (mov.find(P(l, r)) == mov.end())
		return;
	ans2.push_back(mov[P(l, r)]);
	solve2(l, mov[P(l, r)]);
	solve2(mov[P(l, r)] + 1, r);
}

