pair<ll, vector<int>> mss(vector<ll> v) {
  ll res = 0;
  vector<int> res_idx; 
  for (int i = 0; i < (int)v.size(); i++) {
    if (v[i] > 0) {
      res += v[i];
      res_idx.push_back(i);
    }
  }

  if (res_idx.size() == 0) {
    auto p = max_element(ALL(v));
    res = *p;
    res_idx.push_back(p - v.begin());
  }
  return {res, res_idx};
}

