		odd += A[i];
	for (int i = 2; i <= n; i += 2)
		even += A[i];
	while (n > 1)
	{
		if (odd >= even)
		{
			if (n % 2 == 0 || A[n] <= 0)
				((n & 1) ? (odd -= A[n]) : (even -= A[n])), Op[++ Op[0]] = n --;
			else if (A[n - 2] > 0)
				even -= A[n - 1], Op[++ Op[0]] = n - 1, A[n - 2] += A[n], n -= 2;
			else if (n > 3)
				Op[++ Op[0]] = n - 2, A[n - 3] += A[n - 1], A[n - 2] = A[n], n -= 2;
			else swap(odd, even), Op[++ Op[0]] = n - 2, A[n - 2] = A[n - 1], A[n - 1] = A[n], n --;
		}
		else
		{
			if (n % 2 == 1 || A[n] <= 0)
				((n & 1) ? (odd -= A[n]) : (even -= A[n])), Op[++ Op[0]] = n --;
			else if (n == 2)
				odd = even, even = 0, Op[++ Op[0]] = n - 1, A[n - 1] = A[n], n --;
			else if (A[n - 2] > 0)
				odd -= A[n - 1], Op[++ Op[0]] = n - 1, A[n - 2] += A[n], n -= 2;
			else Op[++ Op[0]] = n - 2, A[n - 3] += A[n - 1], A[n - 2] = A[n], n -= 2;
		}
	}
	printf("%lld\n", A[1]);
