    vector<int> C = S[0] > S[1] ? B[0] : B[1];
    vector<int> ret;
    int front = -1, last = N;
    rep(i, N){
        if(C[i]) {
            front = i;
            break;
        }
    }
    for(int i = N - 1; i >= 0; i--){
        if(C[i]) {
            last = i;
            break;
        }
    }
    if(front == -1 && last == N) {
        output(0);
        output(N);
        rep(i, N) output(1);
        return 0;
    }

    for(int i = N - 1; i > front; i--){
        if(i > last){
            ret.pb(i + 1);
        }
        else {
            if(C[i - 1] && i >= 1){
                ret.pb(i + 1);
            }
            else if(C[i - 1] == 0 && C[i] == 0 && C[i + 1] == 0 && i >= 1 && i < N - 1){
                ret.pb(i + 1);
            }
        }
    }
    rep(i, front){
        ret.pb(1);
    }
    output(sum);
    output(ret.size());
    for(auto i: ret){
        output(i);
    }


    return 0;
}

