int cc = 0;
ll n;
ll check[1010];
vector<ll> gap;
ll func(int lo, int hi, int ch) {
	if (lo>hi)return 0;
	if (lo == hi)return a[lo];
	ll &ret = dp[lo][hi][ch];
	if (ret != inf)return ret;
	ret = -99999999999;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	ll sum = 0;
	for (int i = lo; i <= hi; i+=2) {
		sum += a[i];
		ret = max(ret, sum + func(i + 2, hi, 0));
	}
	return ret;
}
void func1(int lo, int hi, int ch) {
	if (lo >= hi)return;
	ll ret = -99999999999;
	if (ch) {
		ret = max(func(lo + 1, hi, ch), ret);
		ret = max(func(lo, hi - 1, ch), ret);
	}
	ll sum = 0;
	for (int i = lo; i <= hi; i += 2) {
		sum += a[i];
		ret = max(ret, sum + func(i + 2, hi, 0));
	}
	if (ch) {
		if (ret == func(lo + 1, hi, ch)) {
			gap.push_back(1);
			cc++;
			check[lo] = 1;
			func1(lo + 1, hi, ch);
			return;
		}
		if (ret == func(lo, hi - 1, ch)) {
			gap.push_back(n - cc);
			cc++;
			check[hi] = 1;
			func1(lo, hi - 1, ch);
			return;
		}
	}
	sum = 0;
	int oo = -1;
	int mm = 0;	
	for (int i = lo ; i <= hi; i += 2) {
		sum += a[i];
		oo++;
		if (ret == sum + func(i + 2, hi, 0)) {
			if (i == lo) {
				for (int y = 0; y < lo; y++)
					mm += check[y];
				func1(i + 2, hi, 0);
				gap.push_back(i + 1 - mm);
			}
			else {
				for (int y = 1; y < lo; y++)
					mm += check[y];
				while (oo--)
					gap.push_back(lo + 1 - mm);
				for (int y = lo; y < i; y++) {
					check[y] = 1;
					mm += check[y];
				}
				func1(i + 2, hi, 0);
				if (i + 1 <= hi)
					gap.push_back(i + 1 - mm);
				for (int y = i + 1; y < hi; y++)
					check[y] = 1;
			}
			return;
		}
	}
}
