template<class Val>
struct BinaryIndexedTree {
    int n;
    vector<Val> t;
    BinaryIndexedTree() {}
    BinaryIndexedTree(int _n) :n(_n + 1), t(_n + 1) {}
    void add(int k, Val val) {
        k++;
        while (k < n) {
            t[k] += val;
            k += (k&-k);
        }
    }
    void set(int k, Val val) {
        add(k, -sum(k, k + 1));
        add(k, val);
    }
    Val sum(int k) {
        Val r = 0;
        while (k > 0) {
            r += t[k];
            k -= (k&-k);
        }
        return r;
    }
    Val sum(int l, int r) {
        return sum(r) - sum(l);
    }
};
typedef BinaryIndexedTree<int> BIT;

int N, A[1001];
ll dp[1001][1001];
BIT bit;
set<int> S;
const ll MI = LLONG_MIN / 3;

vi sousa;

ll f(int l, int r) {
    ll &res = dp[l][r];
    if (res != LLONG_MIN)return res;
    if (r - l == 1) return res = A[l];

    res = MI;

    FOR(i, l + 1, r - 1) {
        ll x = f(l, i), y = f(i + 1, r);
        if(x!=MI&&y!=MI)
            smax(res, x+y);
    }
    return res;
}

void g(int l, int r) {
    if (r - l == 1)return;
    assert(r - l != 2);

    FOR(i, l + 1, r - 1) {
        ll x = f(l, i), y = f(i + 1, r);
        if (x!=MI && y!=MI && x + y == f(l, r)) {
            g(l, i);
            g(i + 1, r);

            // iはbit.sum(i+1)番目の数
            sousa.push_back(bit.sum(i + 1));
            assert(bit.sum(l, r) == 3);

            // 前後2つの値を削除する
            auto a = S.lower_bound(i);
            auto b = a;
            ++a;
            --b;
            assert(l <= *b && *b < i);
            assert(i < *a && *a < r);
            bit.add(*a, -1);
            bit.add(*b, -1);
            S.erase(*a);
            S.erase(*b);
            return;
        }
    }
}


