	if(mx > 0) {
		ret += mx;
		nx[idx][f]=ni;
	}

	if(idx < n-1 && !f) {
		val = DP(idx+1, 0);
		if(val > ret) {
			ret=val;
			nx[idx][f]=idx+1;
		}
	}
	return ret;
}
vector<int> ans;
void trace(int idx,int f) {
	if(nx[idx][f] == -1) {
		for(int t=n-idx;t>=2;t--) ans.push_back(t);
		return;
	}
	if(nx[idx][f] == idx+1) {
		ans.push_back(1);
		trace(idx+1,0);
	}
	else {
		for(int l=(nx[idx][f]-idx)/2;l;l--) ans.push_back(l+1);
		trace(nx[idx][f],1);
	}
}

