pair<ll, vector<int>> solve(vpii v) {
    ll sum = 0;
    vector<int> ret;
    for (auto& [a, b]: v) {
        if (a > 0) {
            sum += a;
            ret.emplace_back(b);
        }
    }
    return make_pair(sum, ret);
}

void print_res(int N, vector<int> idx) {
    int sz = idx.size();
    vector<int> res;
    for (int i = N - 1; i > idx.back(); --i)    res.emplace_back(i + 1);
    for (int i = 0; i < idx.front(); ++i)       res.emplace_back(1);
    int margin = idx.front();
    for (auto& e: idx) e -= margin;
    vector<bool> inc(idx.back() + 1, false);
    for (auto& e: idx) inc[e] = true;
    for (int i = idx.back(); i >= 0; i -= 2) if (not inc[i]) res.emplace_back(i + 1);
    for (int i = 0; i < sz - 1; ++i) res.emplace_back(2);
    cout << res.size() << endl;
    for (auto& e: res) cout << e << endl;
}

