        if (i & 1) odd.emplace_back(A[i], i);
        else evn.emplace_back(A[i], i);
    }

    auto rodd = solve(odd);
    auto revn = solve(evn);

    if (rodd.fi >= revn.fi) {
        cout << rodd.fi << endl;
        print_res(N, rodd.se);
    } else {
        cout << revn.fi << endl;
        print_res(N, revn.se);
    }

}

