/*
端を消す
3つ消して左右の和を作る
結局使用するのは連続区間
長さ2k+1の連続区間でありこの時順番は変わら無い　そんなことなかった
k回の足し合わせが起こるンァーわかった
*/
signed main(){
  int n;cin>>n;
  vector<int> v(n);
  for(int i=0;i<n;i++)cin>>v[i];
  int ans=-LINF;
  int a,b;
  for(int i=0;i<n;i++){
    int res=v[i];
    for(int j=i+2;j<n;j+=2){
      if(ans<res+v[j]){
        ans=res+v[j];
        a=i,b=j;
      }
      if(v[j]>0)res+=v[j];
    }
  }
  int T=(b-a)>>1;
  cout<<ans<<endl;
  cout<<n-1-T<<endl;
  for(int i=0;i<a;i++)cout<<1<<endl;
  for(int i=a+2;i<b;i++){
    if(v[i]>0)cout<<2<<endl;
    else cout<<3<<endl;
  }
  for(int i=b;i<n;i++)cout<<2<<endl;
}

