int N;
ll A[1010];
ll INF = 1001001001001001001;
int mem;
vector<pll> V;
vector<int> ans;

void popfront()
{
    for(int i = 0; i < V.size() - 1; i++)V[i] = V[i + 1];
    V.pop_back();
    return;
}

void pop(int id)
{
    V[id - 1].se += V[id + 1].se;
    for(int i = id; i + 2 < V.size(); i++)V[i] = V[i + 2];
    V.pop_back();V.pop_back();
    return;
}

int main()
{
    scanf("%d",&N);
    for(int i = 0; i < N; i++)scanf("%lld",A + i);

    if(N == 1){printf("%lld\n",A[0]);return 0;}

    ll sum1 = 0,MAX1= -INF;
    for(int i = 0; i < N; i += 2)
    {
        MAX1 = max(MAX1,A[i]);
        if(A[i] >= 0)sum1 += A[i];
    }
    if(MAX1 < 0)sum1 = MAX1;
    ll sum2 = 0,MAX2 = -INF;
    for(int i = 1; i < N; i += 2)
    {
        MAX2 = max(MAX2,A[i]);
        if(A[i] >= 0)sum2 += A[i];
    }
    if(MAX2 < 0)sum2 = MAX2;

    if(sum1 >= sum2)mem = 0,printf("%lld\n",sum1);
    else mem = 1,printf("%lld\n",sum2),MAX1 = MAX2;

    for(int i = 0; i < N; i++)V.push_back(mk(i % 2,A[i]));

    bool up = true;
    int flag = 0;
    while(up)
    {
        up = false;
        flag = 0;
        for(int i = 0; i < V.size(); i++)
        {
            if(V[i].fi == mem && ((MAX1 >= 0 && V[i].se < 0) || (MAX1 < 0 && (V[i].se != MAX1 || flag++ != 0))))
            {
                if(i == 0)popfront();
                else if(i == V.size() - 1)V.pop_back();
                else pop(i);
                ans.push_back(i + 1);
                up = true;
                break;
            }
        }
    }
    if(V.size() > 1 && V[0].fi != mem)
    {
        popfront();
        ans.push_back(1);
    }
    while(V.size() != 1)
    {
        if(V.size() == 2)V.pop_back();
        else pop(1);
        ans.push_back(2);
    }

    printf("%d\n",ans.size());
    for(int i = 0; i < ans.size(); i++)printf("%d\n",ans[i]);
    return 0;
}

