				if(loc != 0){
					vec.erase(vec.begin()+loc-1,vec.begin()+loc+1);
					len -= 2;
					loc ++;
				}
				else {
					vec.erase(vec.begin(),vec.begin()+1);
					len --;
				}
			}
			else loc += 2;
		}
		if(loc&1){
			ans.push_back(0);
			len --;
		}
		while(len>1){
			ans.push_back(1);
			len -= 2;
		}
	}

