		v.PB(MP(tmp,i));
		if(ma < tmp)
		{
			ma = tmp;
			place = i;
		}
	}

	ll sumA = 0;
	ll sumB = 0;

	REP(i,n)
	{
		if(v[i].FI > 0)
		{
			if(i % 2 == 0)sumA += v[i].FI;
			else sumB += v[i].FI;
		}
	}

	ll botann = 0;
	if(sumA == 0 && sumB == 0)
	{
		ok[place] = true;
	}
	else
	{
		if(sumA < sumB)botann++;

		REP(i,n)if(i % 2 == botann && v[i].FI > 0)ok[i] = true;
	}

	vector<ll> sousa;

	while(v.size() > 1)
	{
		REP(i,v.size())
		{
			if(i == 0 || i == v.size() - 1)
			{
				if(ok[v[i].SE] == false)
				{
					sousa.PB(i);
					v.erase(v.begin() + i);
					break;
				}
			}
			else
			{
				if(ok[v[i].SE] == false &&(ok[v[i+1].SE] == ok[v[i-1].SE]))
				{
					v[i].FI = v[i-1].FI + v[i+1].FI;
					v[i].SE = v[i+1].SE;
					sousa.PB(i);
					v.erase(v.begin()+i-1);
					v.erase(v.begin()+i);
					break;
				}
			}
		}
	}

	cout << v[0].FI << endl;
	cout << sousa.size() << endl;

	REP(i,sousa.size())
	{
		cout << sousa[i]+1 << endl;
	}


	return 0;
}

