      who = i + 1;
      sum = a[i].first + a[i + 2].first;
      break;
    }
  }
  if (who != -1) {
    ret.push_back(who);
    a.erase(a.begin() + who + 1);
    a.erase(a.begin() + who - 1);
    a[who - 1].first = sum;
    a[who - 1].second = 1;
    return 1;
  }
  return 0;
}

