typedef pair<ll, vector<ll>> Result;

Result solve(ll start) {
  ll value = 0;
  vector<bool> use;
  pair<ll, ll> max = make_pair(-(1ll << 60), -1);
  vector<ll> picks;
  use.resize(N);
  for (ll i = start; i < N; i += 2) {
    if (max.first < A[i]) max = make_pair(A[i], i);
    if (A[i] > 0) {
      value += A[i];
      use[i] = true;
    }
  }
  ll imax = max.second;
  if (!use[imax]) {
    value += A[imax];
    use[imax] = true;
  }
  while (!use.front()) {
    picks.push_back(0);
    use.erase(use.begin());
  }
  while (!use.back()) {
    picks.push_back(use.size() - 1);
    use.erase(use.end() - 1);
  }
  assert(use.front() && use.back());
  while (use.size() > 1) {
    assert(use.front() && use.back());
    assert(use.size() % 2 == 1);
    if (use[2]) {
      picks.push_back(1);
      use.erase(use.begin() + 1);
      use.erase(use.begin() + 1);
    } else {
      picks.push_back(2);
      use.erase(use.begin() + 2);
      use.erase(use.begin() + 2);
    }
  }
  return make_pair(value, picks);
}
