inline VIL prefixSum(const VI &arr) {
    VIL prefix(arr.size() + 1);
    prefix[0] = 0;
    FOR(i, 1, SZ(prefix)) prefix[i] = prefix[i - 1] + arr[i - 1];
    return prefix;
}

pair<int, int> maxInterval(const VIL &prefix) {
    int i_max = 0, j_max = 0;
    Int maximum = INT64_MIN;
    for (int i = 0;i < SZ(prefix) - 1; ++i) {
        for (int j = i + 1; j < SZ(prefix); ++j) {
            Int t_max = prefix[j] - prefix[i];
            if (t_max > maximum) {
                i_max = i;
                j_max = j;
                maximum = t_max;
            }
        }
    }
    return MP(i_max, j_max);
}

