int main()
{

    int N;
    cin >> N;
    ll *a = new ll[N + 1];
    for (int i = 1; i <= N; i++){
        cin >> a[i];
    }

    // process exception first
    if (N == 1){
        cout << a[1] << endl;
        cout << 0 << endl;
    }
    assert (N > 1);

    bool *used = new bool[N + 1];
    fill(used, used+N+1, false);

    int rp = -1;
    int rs = -INF;
    for (int p = 1; p <= 2; p++){
        // find maximum index (mi) first
        int mi = p;
        for (int i = p; i <= N; i += 2){
            if (a[i] > a[mi]){
                mi = i;
            }
        }

        int sum = 0;
        if (a[mi] <= 0){ // if maximum element is negative, select only maximum element
            sum += a[mi];
            used[mi] = true;
        } else {
            for (int i = p; i <= N; i += 2){
                if (a[i] > 0){
                    sum += a[i];
                    used[i] = true;
                }
            }
        }

        //update if necessary
        if (sum > rs){
            rs = sum;
            rp = p;
        }
    }
    assert (rp != -1);

    vector<int> ret;
    int cnt;
    for (int i = rp + ((N - rp)/2) * 2 ; i > 0; i -= 2){
        if (used[i]){
            cnt++;
        } else {
            ret.push_back(i);
        }
    }

    if (rp != 1 || !used[1]){
        ret.push_back(1);
    }

    if ((N - rp) % 2 == 0 && used[N]){
        cnt--;
    }

    for (int i = 0; i < cnt; i++){
        ret.push_back(2);
    }

    cout << rs << endl;
    cout << ret.size() << endl;
    for (int i : ret){
        cout << i << endl;
    }

    return 0;
}

