        }
        break;
    }
    while(true){
        if(R % 2 != checker){
            ans.push_back(R - deleted);
            R--;
            continue;
        }
        if(a[R] < 0){
            ans.push_back(R - deleted);
            R--;
            continue;
        }
        break;
    }
    while(R != L){
        if(a[R - 2] < 0){
            ans.push_back(R - deleted - 2);
            R -= 2;
            continue;
        }
        ans.push_back(R - deleted - 1);
        R -= 2;
    }
    cout << ans.size() << endl;
    for(int i = 0; i < ans.size(); i++){
        cout << ans[i] << endl;
    }
    return 0;
}

