		for (int i = 0; i <= N - k; i++) {
			DP[i][i + k - 1] = max({ DP[i][i + k - 1], DP[i + 0][i + 0 + k - 2 - 1] + DP[i + 2][i + 2], DP[i + 0][i + 0] + DP[i + 2][i + 2], DP[i + 0][i + 0] + DP[i + 2][i + 2 + k - 2 - 1] });
		}
	}

	long long max_value = -1e18;
	int l, r;
	for (int k = 1; k <= K; k += 2) {
		for (int i = 0; i <= N - k; i++) {
			//cerr << DP[i][i + k - 1] << endl;
			if (max_value < DP[i][i + k - 1]) {
				max_value = DP[i][i + k - 1];
				l = i;
				r = i + k - 1;
			}
		}
