		tmp.push_back(b + 2);
		if (DP[l][r] == DP[l][r - 2] + DP[r][r]) {
			l = l;
			r = r - 2;
		}
		else if (DP[l][r] == DP[l][l] + DP[r][r]) {
			l = l + 1;
			r = r - 1;
			b += 1;
		}
		else if (DP[l][r] == DP[l][l] + DP[l + 2][r]) {
			l = l + 2;
			r = r;
			b += 2;
		}
	}
	reverse(tmp.begin(), tmp.end());
	for (int i = 0; i < tmp.size(); i++)cout << tmp[i] << endl;

	return 0;
}

