        }
        for (int i = 0; i < maxpos; ++i) {
            cout << i + 1 << endl;
        }
        return 0;
    }

    vector<li> ops;
    vector<bool> want(n, false);
    auto omit = [&](int i) {
        ops.push_back(i);
        as.erase(as.begin() + i);
        want.erase(want.begin() + i);
    };


    li sums[2] = {};
    for (int i = 0; i < as.size(); ++i) {
        sums[i & 1] += as[i];
    }
