    }

    while (!want.front()) {
        omit(0);
    }

    while (!want.back()) {
        omit(as.size() - 1);
    }

    while (as.size() > 1) {
        for (int i = 1; i < as.size() - 1; ++i) {
            if (want[i]) {
                continue;
            }
            if (want[i - 1] == want[i + 1]) {
                as[i - 1] += as[i + 1];
                as.erase(as.begin() + i + 1);
                want.erase(want.begin() + i + 1);
                omit(i);
                break;
            }
        }
    }

