int n;
vector<pii> in;

bool Compare(const int& f, const int& s){
  return in[f] > in[s];
}

vi even, odd;

pair<ll, vi> Take(const vi& from){
  ll sum = 0;
  vi use;

  if(in[from[0]].fi <= 0){
    sum = in[from[0]].fi;
    use = {from[0]};
    return mp(sum, use);
  }

  for(int e : from)
    if(in[e].fi >= 0)
      sum += in[e].fi,
      use.pb(e);

  return mp(sum, use);
}

int main(){
  scanf("%d", &n);
  in.resize(n);
  for(auto& e : in)
    scanf("%d", &e.fi),
    e.se = 0;

  for(int i = 0;i < n;i += 2)
    even.pb(i);
  for(int i = 1;i < n;i += 2)
    odd.pb(i);

  sort(all(even), Compare);
  sort(all(odd), Compare);

  auto ans = Take(even);
  if(!odd.empty()){
    auto cand = Take(odd);
    if(ans.fi < cand.fi)
      ans = cand;
  }

  cout << ans.fi << '\n';

  for(int e : ans.se)
    in[e].se = 1;

  vi ops;
  while(sz(in) > 1){
    if(!in[0].se){
      ops.pb(0);
      in.erase(in.begin());
      continue;
    }

    if(!in.back().se){
      ops.pb(sz(in) - 1);
      in.erase(in.end() - 1);
      continue;
    }

    bool success = false;
    for(int i = 0;i < sz(in);++i)
      if(!in[i].se && (i & 1) == (ans.se[0] & 1)){
        ops.pb(i);
        in.erase(in.begin() + i);
        in.erase(in.begin() + i);
        success = true;
        break;
      }
    if(success) break;

    ops.pb(1);
    in.erase(in.begin() + 1);
    in.erase(in.begin() + 1);
  }

  printf("%d\n", sz(ops));
  for(int e : ops)
    printf("%d\n", e + 1);

  return 0;
}

