signed main() {
	int i, j;

	cin >> n;
	rep(i, n) cin >> a[i];

	int maxId = 0;
	rep(i, n) {
		if (a[maxId] < a[i]) maxId = i;
	}
	if (a[maxId] <= 0) {
		cout << a[maxId] << endl;
		cout << n - 1 << endl;
		rep(i, maxId) cout << 1 << endl;
		rep(i, n - 1 - maxId) cout << 2 << endl;
		return 0;
	}

	int sum[2] = {0};
	vector<int> vec[2];
	rep(i, n) {
		if (a[i] >= 0) {
			sum[i % 2] += a[i];
			vec[i % 2].push_back(i);
		}
	}

	vector<int> ids;
	if (sum[0] > sum[1]) ids = vec[0];
	else ids = vec[1];
	ids.push_back(n);

	//復元
	vector<int> ans;
	rep(i, ids[0]) ans.push_back(0);
	rep(i, (int)ids.size() - 1) {
		int mid = (ids[i + 1] - ids[i]) / 2;
		rep(j, mid) {
			ans.push_back(mid - j);
		}
	}

	//答え
	cout << max(sum[0], sum[1]) << endl;
	cout << ans.size() << endl;
	rep(i, ans.size()) { cout << ans[i] + 1 << endl; }
	return 0;
}

