int N;
vector<int> a;

pair< int, vector<int> > solve(int mo) {
    priority_queue< pair<int, int> > que;
    for(int i=0; i<N; i++) {
        if(i % 2 == mo) que.push(make_pair(a[i], i));
    }

    // 何を取るか
    int ans = 0;
    vector<int> mark(N);
    pii cur = que.top(); que.pop();
    ans += cur.first;
    mark[ cur.second ] = 1;
    while(que.size()) {
        pii tmp = que.top(); que.pop();
        if(tmp.first < 0) break;
        ans += tmp.first;
        mark[ tmp.second ] = 1;
    }

    vector<int> operate, vec = mark;
    while(vec.size() != 1) {
        int idx = 0;
        while(idx < vec.size()) {
            bool is_edge = (idx == 0 || idx+1 == vec.size());
            if(is_edge) {
                // 削除する
                if(!vec[idx]) {
                    operate.push_back(idx + 1);
                    vec.erase(vec.begin() + idx);
                }
                else idx++;
            }
            else {
                // 両隣がいらないやつ or 両隣がいるやつ なら操作が必要
                bool match = !(vec[idx-1] ^ vec[idx+1]);
                if(match) {
                    operate.push_back(idx + 1);
                    vec[idx] = 1;
                    vec.erase(vec.begin() + idx + 1);
                    vec.erase(vec.begin() + idx - 1);
                }
                else idx++;
            }
        }
    }
    // printf("mo = %lld, ans = %lld\n", mo, ans);
    return make_pair(ans, operate);
}

