//  cerr << l << ' ' << r << ' ' << kk << '\n';
  ans[l][r] = kk;
  re ans[l][r];
}

void rec2(int l, int r, int toleft = 0) {
  if (l == r - 1) {
    re;
  }

  for (int i = l + 1; i < r - 1; i += 2) {
    ll k = rec(l, i) + rec(i + 1, r);
    if (k == ans[l][r]) {
      rec2(l, i, toleft);
      rec2(i + 1, r, toleft + 2);
      ops.pb(toleft + 2);
      return;
    }
  }
}

