		now[ps-1] = 1;
		ps = prv[ps];
	}
	vector<int> out;

	while (SIZE(now) > 1) {
		if (now.front() == 0) {
			out.push_back(0);
			now.pop_front();
			continue;
		}
		if (SIZE(now) == 2) {
			out.push_back(1);
			now.pop_front();
			continue;
