typedef long long nagai;

#define prev aeoutheoaut

vector<vector<int>> prev;

vector<int> restore(int i, int j)
{
	int cent = prev[i][j];
	if (cent == -1)
		return {};
	vector<int> ans1 = restore(i, cent), ans2 = restore(cent + 1, j);
	for (auto& x : ans2)
		ans1.push_back(x);
	ans1.push_back(cent);
	return ans1;
}

int main()
{
	ios::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<int> a(n);
	for (auto& x : a)
		cin >> x;
	nagai inf = 1e18;
	vector<vector<nagai>> dp(n, vector<nagai>(n + 1, -inf));
	prev.resize(n, vector<int>(n + 1, -1));
	nagai mx = -inf, mxi = -1, mxj = -1;
	for (int len = 1; len <= n; ++len)
		for (int i = 0; i + len <= n; ++i)
		{
			int j = i + len;
			if (len == 1)
				dp[i][j] = a[i];
			else
				for (int cent = i + 1; cent + 1 < j; ++cent)
				{
					nagai ans = dp[i][cent] + dp[cent + 1][j];
					if (ans > dp[i][j])
						dp[i][j] = ans, prev[i][j] = cent;
