ll dp(int x, int y){
  if(x==y){
    mem1[x][y]=1;
    return a[x];
  }
  if(mem[x][y]!=-1)
    return mem[x][y];
  ll res=(-1e14);
  vector <int> mx;
  int tmp=0,tmp2;
  for(int i=x+1; i<=y-1; ++i){
    tmp2=dp(x, i-1)+dp(i+1,y);
    if(tmp2>res){
      tmp=2;
      mx.clear();
      mx.push_back(i);
      res=tmp2;
    }
  }
  if(x==1){
