		add(i,1);
	dfs(1,n);
	printf("%d\n",dp[1][n]);
	rdfs(1,n);
	printf("%d\n",dfs_time);
	for(int i=1;i<=dfs_time;i++)
		printf("%d\n",ans[i]);
	return 0;
}

