		}
		if (res == func(beg, end - 1)) {
			ope.push_back(end - beg);
			--end;
			continue;
		}
		if (beg + 1 == end) {
			break;
		}
		for (int64_t i = beg + 1; i < end; i += 2)
		{
			if (a[i + 1] >= 0) {
				ope.push_back(2);
			}
			else {
				ope.push_back(3);
			}
		}
		break;
	}
	out << ope.size() << endl;
	for (auto& i : ope)
	{
		out << i << '\n';
	}
	out << std::flush;

	return 0;
}
