ll rec(int l,int r){
	if(r-l==1)return a[l];
	if(dp[l][r]!=-LLINF)return dp[l][r];
	ll ret = -LLINF;
	int las = -1;
	if(ret<rec(l+1,r)){
		ret = rec(l+1,r);
		las = l;
	}
	if(ret<rec(l,r-1)){
		ret = rec(l,r-1);
		las = r-1;
	}
	for(int i=l+1;i<r-1;i++){
		ll tmp = rec(l,i)+rec(i+1,r);
		if(ret<tmp){
			ret = tmp;
			las = i;
		}
	}
	last[l][r]=las;
	//cout << l << ' ' << r << ' ' << dp[l][r] << endl;
	return dp[l][r]=ret;
}
