const int MAXN = 1e3 + 5;
const ll INF = 1e18;

int N;
int a[MAXN];

void load() {
	scanf("%d", &N);
	for (int i = 0; i < N; i++)
		scanf("%d", a + i);
}

void solve() {
	ll sol = -INF;
	vector <int> opt;
	for (int k = 0; k < 2; k++) {
		vector <pii> v;
		for (int i = k; i < N; i += 2)
			v.push_back({a[i], i});
		sort(v.begin(), v.end(), greater <pii> ());
		ll sum = 0;
		vector <int> pref;
		for (auto it : v) {
			sum += it.first;
			pref.push_back(it.second);
			if (sum > sol) {
				opt = pref;
				sol = sum;
			}
		}
	}

	sort(opt.begin(), opt.end());

	vector <int> ans; 
	for (int i = 0; i < opt[0]; i++) 
		ans.push_back(0);

	for (int i = 0; i < N - opt.back() - 1; i++)
		ans.push_back(N - opt[0] - i - 1);

	for (int i = 1; i < opt.size(); i++)
		for (int j = 0; j < (opt[i] - opt[i - 1]) / 2; j++)
			ans.push_back(j + 1);

	printf("%lld\n%d\n", sol, ans.size());
	for (auto it : ans)
		printf("%d\n", it + 1);
}

int main() {
	load();
	solve();
	return 0;
}

