	}
	long long s;
	vector<int> v;
	if(corner) {
		s = a[max_i];
		for(int i=0;i<n;i++) use[i] = false;
		use[max_i] = true;
	} else {
		int parity = sum[0] > sum[1] ? 0 : 1;
		s = sum[parity];
		for(int i=0;i<n;i++) {
			use[i] = i%2 == parity && a[i] > 0;
		}
	}
	int i = n - 1;
	while(!use[i]) {
		v.push_back(i+1);
		i--;
	}
