vi even, odd;

pair<ll, vi> Take(const vi& from){
  ll sum = 0;
  vi use;

  if(in[from[0]].fi <= 0){
    sum = in[from[0]].fi;
    use = {from[0]};
    return mp(sum, use);
  }

  for(int e : from)
    if(in[e].fi >= 0)
      sum += in[e].fi,
      use.pb(e);

  return mp(sum, use);
}

