    even.pb(i);
  for(int i = 1;i < n;i += 2)
    odd.pb(i);

  sort(all(even), Compare);
  sort(all(odd), Compare);

  auto ans = Take(even);
  if(!odd.empty()){
    auto cand = Take(odd);
    if(ans.fi < cand.fi)
      ans = cand;
  }

  cout << ans.fi << '\n';

  for(int e : ans.se)
    in[e].se = 1;

  vi ops;
  while(sz(in) > 1){
    if(!in[0].se){
      ops.pb(0);
      in.erase(in.begin());
      continue;
    }

    if(!in.back().se){
      ops.pb(sz(in) - 1);
      in.erase(in.end() - 1);
      continue;
    }

    int want = 0;
    for(int i = 0;i < sz(in);++i)
      if(in[i].se) want = i;

    bool success = false;
    for(int i = 0;i < sz(in);++i)
      if(!in[i].se && (i & 1) == (want & 1)){
        ops.pb(i);
        in.erase(in.begin() + i);
        in.erase(in.begin() + i);
        success = true;
        break;
      }
    if(success) continue;

    ops.pb(1);
    in.erase(in.begin() + 1);
    in.erase(in.begin() + 1);
  }

  printf("%d\n", sz(ops));
  for(int e : ops)
    printf("%d\n", e + 1);

  return 0;
}

