    ll big = 1;
    if (sum[0] > sum[1]) big = 0;
    cout << sum[big] << endl;

    ll del = 0, front = true;
    // del = 削除した要素数
    // front = 今いるのが先頭か否か

    V<ll> step;
    ll i = 1;
    while (i <= N) {
