LL dp[1111][1111][2][2];
bool vis[1111][1111][2][2];

LL DP(int L, int R, int l, int r)
{
    if(vis[L][R][l][r]) return dp[L][R][l][r];
    vis[L][R][l][r] = 1;
    if(L == R) return dp[L][R][l][r] = a[L];

    LL res = -1e15;
    if(l == 0) res = max(res, DP(L + 1, R, l, r));
    if(r == 0) res = max(res, DP(L, R - 1, l, r));

    for(int i = L + 1; i <= R - 1; i++)
    {
        res = max(res, DP(L, i - 1, l, 1) + DP(i + 1, R, 1, r));
    }

    return dp[L][R][l][r] = res;
}

vector<int> step;

void dfs(int L, int R, int l, int r)
{
    if(L == R) return ;
    LL res = dp[L][R][l][r];

    if(l == 0 && res == dp[L + 1][R][l][r])
    {
        step.push_back(1);
        dfs(L + 1, R, l, r);
        return ;
    }
    if(r == 0 && res == dp[L][R - 1][l][r])
    {
        step.push_back(R - L + 1);
        dfs(L, R - 1, l, r);
        return ;
    }

    for(int i = L + 1; i <= R - 1; i++)
    {
        if(res == dp[L][i - 1][l][1] + dp[i + 1][R][1][r])
        {
            dfs(L, i - 1, l, 1);
            dfs(i + 1, R, 1, r);
            step.push_back(i - L + 1);
            return ;
        }
    }
}

