struct binomial_coefficient {
private:
	int m;
	vector<modint> fact;
public:
	binomial_coefficient(int m) : m(m) {
		fact.resize(m);
		fact[0] = 1;
		for(int i = 1; i < m; i++) fact[i] = fact[i - 1] * i;
	}
	modint combination(int n, int k) {
		if(n < 0 || k < 0 || n < k) return 0;
		return fact[n] / fact[n - k] / fact[k];
	}
};


// graph //
using weight = long long;
template <typename T> struct edge { int t; weight w; T v; };

template <typename T> struct vgraph {
protected:
	int n;
	bool weighted;
	vector<vector<edge<T>>> g;
public:
	vgraph(int n) : n(n), weighted(false), g(vector<vector<edge<T>>>(n)) { }
	int size() { return size; }
	bool isweighted() { return weighted; }
	void add_edge(int s, int t, T v, weight w = 1) {
		g[s].push_back({t, w, v});
		g[t].push_back({s, w, v});
		if(w != 1) weighted = true;
	}
	void add_dedge(int s, int t, T v, weight w = 1) {
		g[s].push_back({t, w, v});
		if(w != 1) weighted = true;
	}
	vector<edge<T>>& operator[] (int i) { return g[i]; }
};

struct ugraph : vgraph<void*> {
public:
	ugraph(int n) : vgraph<void*>(n) { }
	void add_edge(int s, int t, weight w = 1) {
		vgraph::add_edge(s, t, nullptr, w);
	}
	void add_dedge(int s, int t, weight w = 1) {
		vgraph::add_dedge(s, t, nullptr, w);
	}
};

template <typename T>
vector<weight> shortest_path(vgraph<T>& g, int s) {
	int n = g.size();
	vector<weight> path(n, -1);
	if(g.isweighted()) { // dijkstra
		priority_queue<pair<weight, int>, vector<pair<weight, int>>, greater<pair<weight, int>>> q;
		path[s] = 0;
		q.push({0, s});
		while(!q.empty()) {
			weight cost = q.top().first;
			int p = q.top().second;
			q.pop();
			if(path[p] != cost) continue;
			for(auto e: g[p]) {
				if(path[e.to] == -1 || path[e.to] > cost + e.w) {
					path[e.to] = cost + e.w;
					q.push({path[e.to], e.to});
				}
			}
		}
	} else { // bfs
		queue<int> q;
		path[s] = 0;
		q.push(s);
		while(!q.empty()) {
			int p = q.front();
			q.pop();
			for(auto e: g[p]) {
				if(path[e.to] == -1) {
					path[e.to] = path[p] + 1;
					q.push(e.to);
				}
			}
		}
	}
	return path;
}

vector<int> f(vector<int> a, vector<int>& res) {
	int n = (int)a.size();
	int pos = 1;
	REP(i, n) {
		if(i % 2 == 0 && a[i] < 0) res.pb(pos);
		else pos++;
	}
	pos--;
	REP(i, pos / 2) {
		if(a[0] >= 0) res.pb(i + 2);
		else res.pb(i + 1);
	}
	return res;
}

