ll solve() {
    ll N;
    cin >> N;
    vector<ll> A(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> A[i];
    }
    ll INF = 1LL<<60;
    int d = 2;
    vector<ll> dp(N+2*d,-INF), prev(N+2*d, -1);
    dp[0] = dp[1] = 0;
    for ( int i = d; i < N+2*d; i++ ) {
        for ( int j = 2; i-j >= 0; j+=2 ) {
            ll a = i-d < N ? A[i-d] : 0;
            ll x = dp[i-j] + a;
            if ( dp[i] < x ) {
                dp[i] = x;
                prev[i] = i-j;
            }
        }
    }
    int ci = dp[N+d] > dp[N+d+1] ? N+d : N+d+1;
    ll mx = dp[ci];
    vector<int> sel;
    while ( ci >= 0 ) {
        if ( ci-d >= 0 && ci-d < N ) {
            sel.push_back(ci-d);
        }
        ci = prev[ci];
    }
    vector<int> ans;
    for ( int i = N-1; i > sel[0]; i-- ) {
        ans.push_back(i);
    }
    for ( int i = 0; i < sel.size()-1; i++ ) {
        for ( int j = (sel[i]+sel[i+1])/2; j > sel[i+1]; j-- ) {
            ans.push_back(j);
        }
    }
    for ( int i = sel[sel.size()-1]-1; i >= 0; i-- ) {
        ans.push_back(0);
    }

    cout << mx << "\n";
    cout << ans.size() << "\n";
    for ( int i = 0; i < ans.size(); i++ ) {
        cout << ans[i] + 1 << "\n";
    }
    return 0;
}

