template <typename X>
inline size_t hash(const X& x) {
    return std::hash<X>{}(x);
}

template <typename X, typename Y>
inline size_t hash(const X& x, const Y& y) {
    auto a = ::hash(x);
    auto b = ::hash(y);
    return a ^ (b + 0x9e3779b9 + (a << 6u) + (a >> 2u));
};

template <typename X, typename Y, typename... Z>
size_t hash(const X& x, const Y& y, const Z&... z) {
    return ::hash(::hash(x, y), z...);
}

namespace Private {
    template<typename... X, size_t... I>
    inline size_t hash_tuple(const tuple<X...>& x, index_sequence<I...>) {
        return ::hash(get<I>(x)...);
    }

    template<typename X, size_t N, size_t... I>
    inline size_t hash_array(const array<X, N>& x, index_sequence<I...>) {
        return ::hash(x[I]...);
    }
}

namespace std {
    template<typename F, typename S>
    struct hash<pair<F, S>> {
        size_t operator()(const pair<F, S>& x) const {
            return ::hash(x.first, x.second);
        }
    };

    template<typename... X>
    struct hash<tuple<X...>> {
        size_t operator()(const tuple<X...>& x) const {
            return Private::hash_tuple(x, index_sequence_for<X...>{});
        }
    };

    template<typename X, size_t N>
    struct hash<array<X, N>> {
        size_t operator()(const array<X, N>& x) const {
            return Private::hash_array(x, make_index_sequence<N>{});
        }
    };

    template<typename X>
    struct hash<vector<X>> {
        size_t operator()(const vector<X>& x) const {
            size_t ans = 0;
            for (const auto& a : x) {
                ans = ::hash(ans, a);
            }
            return ans;
        }
    };
}

