Vi a;
vector<vector<pair<Long, int>>> memo;

pair<Long, int> f(int left, int right) {
    if (left == right) {
        return {0, -2};
    }
    if (right - left == 1) {
        return {a[left], -2};
    }
    auto& ans = memo[left][right];
    if (ans.second == -1) {
        for (int i = left; i < right; ++i) {
            Long value = f(left, i).first + f(i + 1, right).first;
            if (ans.second == -1 || ans.first < value) {
                ans = {value, i};
            }
        }
    }
    return ans;
}

vector<int> ans;

void print(int left, int right, int offset) {
    if (left == right) {
        return;
    }
    int i = f(left, right).second;
    if (i >= 0) {
        if (i > left) {
            print(left, i, offset);
            print(i + 1, right, offset + 2);
            ans.push_back(offset + 1);
        } else {
            print(i + 1, right, offset + 1);
            ans.push_back(offset);
        }
    }
}

