pair<LL, pair<int,int>> searchLevel(vector<LL> v)
{
	REP(i, v.size() - 1) {
		v[i + 1] += v[i];
	}
	LL minv = 0;
	LL maxv = -INF;
	int tmpl = -1;
	int l = -1;
	int r = 0;
	REP(i, v.size()) 
	{
		if (maxv < v[i] - minv) {
			l = tmpl;
			r = i;
			maxv = v[i] - minv;
		}
		if (minv > v[i]) {
			tmpl = i;
			minv = v[i];
		}
	}
	l++;
	return make_pair(maxv, make_pair(l, r));
}


