	else if (i == v.size() - 1) REP(j, v.size() - 1) ret.push_back(v[j]);
	else {
		REP(j,v.size()){
			if (j < i - 1 || i + 1 < j) ret.push_back(v[j]);
			if (j == i) ret.push_back({ v[i - 1].fi + v[i + 1].fi, v[i].se });
		}
	}
	return ret;
}

int main() {
	int N; cin >> N;
	ll eve = 0, odd = 0;
	VL a(N),c; REP(i, N) cin >> a[i];
	bool neg = true;
	REP(i, N) if (a[i] >= 0) neg = false;

	if(neg){
		int idx = distance(a.begin(), max_element(ALL(a)));
		cout << a[idx] << endl;
		cout << N - 1 << endl;
		for (int i = N; i > idx+1; --i) cout << i << endl;
		for (int i = 1; i < idx+1; ++i) cout << 1 << endl;
		return 0;
	}

	VPLL arr;
	REP(i, N) if (a[i] >= 0) ((i % 2 == 0) ? eve : odd) += a[i];
	REP(i, N) arr.push_back({ a[i],i });

	bool prt = !(eve > odd);

	while(N >= 2){
		if (arr[0].se % 2 == prt && arr[0].fi >= 0) break;
		arr = dec(arr, 0);
		c.push_back(1);
		N = arr.size();
	}

	while (N >= 2) {
		if (arr[N-1].se % 2 == prt && arr[N-1].fi >= 0) break;
		arr = dec(arr, N-1);
		c.push_back(N);
		N = arr.size();
	}

	if (N % 2 != 1) return 0;

	for (int i = 0; i < N && N >= 2;) {
		if (/*arr[i].se % 2 != prt ||*/ arr[i].fi >= 0) {
			i += 2;
			continue;
		}
		else {
			arr = dec(arr, i);
			c.push_back(i + 1);
			N = arr.size();
		}
	}

	while (N >= 2) {
		if (arr[1].se % 2 == prt) continue;
		arr = dec(arr, 1);
		c.push_back(2);
		N = arr.size();
	}

	cout << arr[0].fi << endl;
	cout << c.size() << endl;
	REP(i, c.size()) cout << c[i] << endl;



	return 0;
}

