int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  int n;
  cin >> n;
  vector<long long> a(n);
  for (int i = 0; i < n; i++) cin >> a[i];
  vector<int> opr;
  vector<bool> req(n, false);
  auto merge = [&] (int i) {
    opr.push_back(i);
    int n = a.size();
    assert(0 <= i && i < n);

    assert(!req[i]);
    req.erase(req.begin() + i);
    a.erase(a.begin() + i);

    if (0 < i && i < n - 1) {
      a[i - 1] += a[i];
      assert(req[i - 1] == req[i]);
      req.erase(req.begin() + i);
      a.erase(a.begin() + i);
    }
  };
  long long sum[2] = {};
  for (int i = 0; i < n; i++) {
    int crr = a[i];
    if (crr > 0) {
      sum[i % 2] += a[i];
    }
  }
  if (sum[0] < sum[1]) {
    merge(0);
    sum[0] = sum[1];
    n--;
  }
  long long ret = 0;
  for (int i = 0; i < n; i += 2) {
    if (a[i] > 0) {
      req[i] = true;
      ret += a[i];
    }
  }
  while ((int)a.size() >= 2) {
    if (!req[0]) merge(0);
    else if (!req.back()) merge(req.size() - 1);
    else if (req[2]) merge(1);
    else merge(2);
  }
  assert((int)a.size() == 1);
  assert(sum[0] == ret);
  assert(a[0] == ret);
  cout << ret << endl;
  cout << opr.size() << endl;
  for (auto e : opr) {
    cout << e << endl;
  }
  return 0;
}

