//[beg,end)
int64_t func(int32_t beg, int32_t end)
{
	if (beg == end) { return -INF; }
	if (used[beg][end]) { return dp[beg][end]; }
	used[beg][end] = true;

	int64_t res = std::max(func(beg + 1, end), func(beg, end-1));
	res = std::max(res,
		std::max(sum[0][end-1]- sum[0][beg - 1], sum[1][end - 1] - sum[1][beg - 1])
	);
	return dp[beg][end] = res;
}

