void go(int fr, int en, vi& vals) {
    if (fr == en) return;
    if (fr + 2 == en) {
        cout << fr + 1 + 1 << "\n";
        return;
    }

    int nfr = fr + 2, nen = en - 2;
    while (nfr <= nen && vals[nfr] <= 0)
        nfr += 2;
    while (nen >= nfr && vals[nen] <= 0)
        nen -= 2;

    if (nen < nfr) {
        TRACE(cout << "Clearing " << fr << " " << en << endl;)
        // clear everything between
        for (int reps = 0; reps < (en - fr) / 2 - 1; reps++) {
            cout << fr + 2 + 1 << "\n";
        }
        cout << fr + 1 + 1 << "\n";
        return;
    }

    TRACE(cout << "Handling " << fr << " " << en << endl;)

    // clear the back
    for (int reps = 0; reps < (en - nen - 1) / 2; reps++) {
        cout << nen + 2 + 1 << "\n";
    }

    TRACE(cout << "Descending to middle " << nfr << " " << nen << endl;)

    // condense the middle
    go(nfr, nen, vals);

    TRACE(cout << "Finishing " << nfr << " " << nen << endl;)

    // condense everything
    for (int reps = 0; reps < (nfr - fr) / 2 - 1; reps++) {
        cout << fr + 2 + 1 << "\n";
    }
    cout << fr + 1 + 1 << "\n";
    cout << fr + 1 + 1 << "\n";
}

