vector<int> vec;
ll solve(int x,int y)
{
	if(f[x][y])
		return dp[x][y];
	f[x][y] = 1;
	if(x==y)
		return dp[x][y] = a[x];
	if((y-x+1)%2==0)
		return -inf;
	ll res = -inf;
	for(int j=x+1;j<y;j++)
	{
		res = max(res,solve(x,j-1)+solve(j+1,y));
	}
	return dp[x][y] = res;
}
void reCon(int x,int y,int off)
{
	if(x==y)
		return;
	for(int j=x+1;j<y;j++)
	{
		ll z = solve(x,j-1)+solve(j+1,y);
		if(dp[x][y] == z)
		{
			reCon(x,j-1,off);
			reCon(j+1,y,off+2);
			vec.pb(off+2);
			break;
		}
	}
}
