    fill(odd_list, odd_list + N, false);
    fill(even_list, even_list + N, false);
    for (int i = 0; i < N; ++i) {
        if (a[i] > 0) {
            if (i % 2 == 0) {
                even += a[i];
                even_list[i] = true;
            } else {
                odd += a[i];
                odd_list[i] = true;
            }
        }
