        int real_i = 0;
        for (int i = 0; i < N; ++i) {
            if (!even_list[i]) {
                count += 1;
                real_i += 1;
                continue;
            }
            for (int j = 0; j < (count + 1) / 2; ++j) {
                ans.push_back(real_i - (count + 1) / 2 - j);
            }
            if (i == real_i) {
                real_i -= count;
            } else {
                real_i -= (count + 1);
            }
            count = 0;
        }
        for (int j = 0; j < count; ++j) {
            ans.push_back(real_i - j);
        }
    } else {
