        int real_i = 0;
        for (int i = 0; i < N; ++i) {
            if (!odd_list[i]) {
                count += 1;
                real_i += 1;
                continue;
            }
            if (count % 2 == 0) {
                ans.push_back(0);
                count -= 1;
                real_i -= 1;
            }
            for (int j = 0; j < (count + 1) / 2; ++j) {
                ans.push_back(real_i - (count + 1) / 2 - j);
            }
            if (i == real_i) {
                real_i -= count;
            } else {
                real_i -= (count + 1);
            }
            count = 0;
            real_i += 1;
        }
        real_i -= 1;
        for (int i = 0; i < count; ++i) {
            ans.push_back(real_i - i);
        }
    }
    cout << ans.size() << endl;
    for (int i = 0; i < ans.size(); ++i) {
        cout << ans[i] << endl;
