int n;
i64 a[1010];
i64 result = 0;
vector<int> ans;

int main(){
    cin >> n;
    rep(i,1,n) cin >> a[i];

    int MAX = 1;
    rep(i,2,n) if(a[MAX] < a[i]) MAX = i;

    if(a[MAX] <= 0){
        result = a[MAX];
        int sz = n;
        rep(i,1,MAX - 1){
            ans.push_back(1);
            sz--;
        }
        while(sz > 1){
            ans.push_back(sz);
            sz--;
        }
    }
    else{
        vector<int> select;
        vector<int> odd(n,0);
        vector<int> even(n,0);
        i64 odd_sum = 0;
        i64 even_sum = 0;
        for(int i = 1;i <= n;i+=2){
            if(a[i] > 0){
                odd_sum += a[i];
                odd[i - 1] = 1;
            }
        }
        for(int i = 2;i <= n;i+=2){
            if(a[i] > 0){
                even_sum += a[i];
                even[i - 1] = 1;
            }
        }


        if(odd_sum >= even_sum){
            select = odd;
            result = odd_sum;
        }
        else{
            select = even;
            result = even_sum;
        }

        //first
        while (select.front() == 0)
        {
            select.erase(select.begin());
            ans.push_back(1);
        }
        while(select.back() == 0){
            select.pop_back();
            ans.push_back(select.size() + 1);
        }

        //second
        for(int i = 1;i < select.size() - 1;i++){
            if(select[i - 1] == 0 && select[i] == 0 && select[i + 1] == 0){
                ans.push_back(i + 1);
                select.erase(select.begin() + i);
                i--;
            }
        }

        for(int i = 0;i < select.size();i++){
            if(select[i] == 0){
                ans.push_back(2);
            }
        }
    }

    cout << result << endl;
    cout << ans.size() << endl;
    for(int as : ans){
        cout << as << endl;
    }
}

