const int MAX_N = 1050;
int N;
long long a[MAX_N];
long long AC[MAX_N];

void exec(const int i) {
    if (i == 1) {
        for (int j = 1; j <= N-1; j++) {
            a[j] = a[j+1];
        }
        N--;
    } else if (i == N) {
        N--;
    } else {
        a[i-1] += a[i+1];
        for (int j = i; j + 2 <= N; j++) {
            a[j] = a[j+2];
        }
        N -= 2;
    }
}

int main(int argc, char **argv) {
    std::cin >> N;
    for (int i = 1; i <= N; i++) {
        std::cin >> a[i];
    }

    long long sum[2];
    long long max = a[1];
    int max_pos = 1;
    for (int i = 1; i <= N; i++) {
        if (0 <= a[i]) {
            sum[i%2] += a[i];
        }
        if (max < a[i]) {
            max = a[i];
            max_pos = i;
        }
    }

    std::vector<int> proc;

    if (sum[0] <= 0 && sum[1] <= 0) {
        for (int i = max_pos + 1; i <= N; i++) {
            proc.push_back(N);
            exec(N);
        }
        for (int i = 1; i < max_pos; i++) {
            proc.push_back(1);
            exec(1);
        }
    } else {
        if (sum[1] < sum[0]) {
            exec(1);
            proc.push_back(1);
        }

        while (a[1] <= 0) {
            exec(1);
            proc.push_back(1);
            exec(1);
            proc.push_back(1);
        }

        while (1 < N) {
            if (N == 2) {
                exec(2);
                proc.push_back(2);
            } else {
                if (0 < a[3]) {
                    exec(2);
                    proc.push_back(2);
                } else {
                    exec(3);
                    proc.push_back(3);
                }
            }
        }
    }

    std::cout << a[1] << std::endl;
    std::cout << proc.size() << std::endl;
    for (int i = 0; i < proc.size(); i++) {
        std::cout << proc[i] << std::endl;
    }

    return 0;

}

