struct RET
{
	ll ans;
	int l, r;
};
RET solve(int *num, int m)
{
	ll preMin = 0, sum = 0, ret = 0;
	int l = 0, r = 0;
	for(int i = 1; i <= m; ++i)
	{
		sum += num[i];
		if(ret < sum - preMin)
		{
			ret = sum - preMin;
			r = i;
		}
		if(preMin > sum)
		{
			preMin = sum;
			l = i;
		}
	}
	return RET{ret, l, r};
}		
