int64_t solve_without_deleting(const int rhs){
	int tmp = max(rhs - 2,0);
	while (tmp >= 0) {
		if (the_last[tmp] + elements[rhs] > the_last[rhs]) {
			came_from[rhs] = tmp;
			the_last[rhs] = the_last[tmp] + the_last[rhs];
		}
		tmp -= 2;
	}
	return the_last[rhs];
}



