ll dp[1001][1001];
bool vis[1001][1001];
map<pi,int>rv;
map<pi,int>flg;

ll rec(int st,int en,vector<int>&a){
  if(vis[st][en]){
    return dp[st][en];
  }
  if(en<st){
    return dp[st][en]=0;
  }
  if(en==st){
    return dp[st][en]=a[en];
  }
  ll ans=-1e18;
  for(int i=st;i<=en;i++){
    if(rec(st,i-1,a)+rec(i+1,en,a)>ans){
      ans=max(ans,rec(st,i-1,a)+rec(i+1,en,a));
      flg[{st,en}]=0;
      rv[{st,en}]=i;
    }
    if(ans<max({rec(st,i-1,a),rec(i+1,en,a),(ll)a[i]})){
      ans=max(ans,max({rec(st,i-1,a),rec(i+1,en,a),(ll)a[i]}));
      flg[{st,en}]=1;
      rv[{st,en}]=i;
    }
  }
  vis[st][en]=true;
  return dp[st][en]=ans;
}
