const ll MOD = 1e9 + 7;

const int mx = 1010;
ll n, a[mx], dp[mx][mx], go[mx][mx];
vector<int> restore;

void build_restore(int i, int j) {
	if (i == j)
		return;
	int k = go[i][j];
	restore.push_back(k - i);
	if (k == i)
		build_restore(i + 1, j);
	else {
		if (k == j)
			build_restore(i, j - 1);
		else {
			build_restore(i, k - 1);
			build_restore(k + 1, j);
		}
	}
}

const ll INF = 1e18;

int main() {
	cin >> n;
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
		dp[i][i] = a[i];
	}
	for (int len = 2; len <= n; ++len) {
		for (int i = 0; i <= n - len; ++i) {
			int j = (i + len - 1);
			dp[i][j] = -INF;
			ll new_val;
			for (int k = i + 1; k < j; ++k) {
				new_val = dp[i][k - 1] + dp[k + 1][j];
				if (new_val > dp[i][j]) {
					dp[i][j] = new_val;
					go[i][j] = k;
				}
			}
		}
	}
	ll pos_i = 0, pos_j = n - 1, ans = -INF;
	for (int i = 0; i < n; ++i) {
		for (int j = i; j < n; ++j) {
			if (dp[i][j] > ans) {
				ans = dp[i][j];
				pos_i = i;
				pos_j = j;
			}
		}
	}
	//cout << "pos " << pos_i << " " << pos_j << endl;
	build_restore(pos_i, pos_j);
	cout << dp[pos_i][pos_j] << endl;
	reverse(restore.begin(), restore.end());
	vector<int> real_restore;
	for (int i = 0; i < pos_i; ++i) {
		real_restore.push_back(i);
		//cout << "adding " << i << endl;
	}
	for (int i = n - 1; i > pos_j; --i) {
		real_restore.push_back(i - pos_i);
		//cout << "adding " << i << endl;
	}
	for (auto x : restore) {
		real_restore.push_back(x);
	}
	cout << real_restore.size() << endl;
	for (int i = 0; i < real_restore.size(); ++i) {
		cout << real_restore[i] + 1 << '\n';
	}
	cout << endl;
}

