#define fi first
#define se second
const int inf = 1e9;

int a[10100];
P solve1(int n){
	int res = 0, cnt = 0;
	repi(i,0,n){
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
		i++;
	}
	return P(res, cnt);
}
P solve2(int n){
	int res = 0, cnt = 0;
	repi(i,1,n){
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
		i++;
	}
	return P(res, cnt);
}
P solve3(int n){
	P p = P(-inf-1,0);
	rep(i,n){
		if(p.fi < a[i])p = P(a[i], i);
	}
	return p;
}

signed main(){
