		repi(i,k+2,n+1){
			if(a[i] > 0)ans.push_back(2);
			else ans.push_back(3);
			if(i == n-1 && a[i]<=0)ans.push_back(2);
			i++;
		}
		int m = ans.size();
		printf("%lld\n%lld\n",p.fi, m);
