			if(!use[i]){
				z[k++] = 0;
				c++;
			}else{
				left = i;
				break;
			}
		}
		for(i=n-1;i>=0;i--){
			if(!use[i]){
				z[k++] = i-c;
			}else{
				right = i;
				break;
			}
		}
		a = right;
		while(a >= left){
			if(!use[a-1] && !use[a] && !use[a+1] && a-1 >= 0){
				z[k++] = a-c;
				use[a] = true;
			}else if(use[a-1] && !use[a] && use[a+1] && a-1>=0){
				z[k++] = a-c;
				use[a] = true;
			}
			a--;
		}
		p(k);
		for(i=0;i<k;i++){
			p(z[i]+1);
		}
    }
    return 0;
}

