#include <iostream>
#include <vector>
using namespace std;
const int N = 1002;
typedef long long LL;
const LL INF = 1e13;
LL dp[N][N][2], a[N], ok[N]; 
int n, vis[N][N], bst[N][N][2]; // { 0 for L, 1 for R }
void dfs(int L, int R) {
    if (vis[L][R])
        return;
    vis[L][R] = 1;

    if (L == R) {
        dp[L][R][0] = a[L]; bst[L][R][0] = L; return; 
    }
    if (R - L == 1) {
        dp[L][R][0] = a[L]; bst[L][R][0] = L;
        dp[L][R][1] = a[R]; bst[L][R][1] = R; return;
    }
    dp[L][R][0] = dp[L][R][1] = - INF;
    for (int i = L; i < R; i ++) {
        dfs(L,i); dfs(i+1,R);
    }
    if ((R - L) % 2 == 1) {
        int bst_0 = -1, bst_1 = -1;
        for (int i = L; i < R; i ++) {
            if (dp[L][i][0] > dp[L][R][0])
                bst_0 = i, dp[L][R][0] = dp[L][i][0];
        }
        for (int i = R; i > L; i --) {
            if (dp[i][R][1] > dp[L][R][0])
                bst_1 = i-1, dp[L][R][1] = dp[i][R][1];
        }
        bst[L][R][0] = bst_0;
        bst[L][R][1] = bst_1;
    } else {
        int bst_0 = -1;
        dp[L][R][0] = a[L] + a[R]; bst[L][R][0] = (L+R)/2;

        for (int i = L; i < R; i ++) {
            if ((i - L) % 2 == 0) {// 左边长度为奇数
                if (dp[L][i][0] + dp[i+1][R][1] > dp[L][R][0]) {
                    bst_0 = i, dp[L][R][0] = dp[L][i][0] + dp[i+1][R][1];
                }
            } else {                  // 左边长度为偶数
                if (dp[L][i][0] + dp[i+1][R][0] > dp[L][R][0]) {
                    bst_0 = i, dp[L][R][0] = dp[L][i][0] + dp[i+1][R][0];
                }
            }
        }

        bst[L][R][0] = bst_0;
    }
}

void gao(int l, int r, int s) {
    if ((r - l) % 2 == 1) {
        int pos = bst[l][r][s];
        gao(l, pos, s), gao(pos+1, r, s);
    }
    if ((r - l) % 2 == 0) {
        int pos = bst[l][r][s];
        if (bst[l][r][0] == (l + r) / 2) {
            ok[(l+r)>>1] = 1;
        }
        if ((pos - l) % 2 == 1) {
            gao(l, pos, 0); gao(pos+1, r, s);
        } else {
            gao(l, pos, 0); gao(pos+1, r, 1);            
        }
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i ++) {
        scanf("%lld", &a[i]);
    }
    LL ans = -INF, bst_L = 1, bst_R = n;
    for (int i = 1; i <= n; i ++) {
        for (int j = i; j <= n; j ++) {
            dfs(i, j);
            if ((j-i)%2 == 0) {
                if (dp[i][j][0] > ans) {
                    ans = dp[i][j][0];
                    bst_L = i, bst_R = j;
                }
            }
        }
    }
    gao(bst_L, bst_R, 0);
    vector<int> v;
    for (int i = 1; i < bst_L; i ++) v.push_back(i);
    for (int i = n; i > bst_R; i --) v.push_back(i);
    for (int i = bst_L; i <= bst_R; i ++) if (ok[i]) v.push_back(i);
    printf("%lld\n", ans);
    printf("%d\n", v.size());
    sort(v.begin(), v.end());
    for (int i = 0; i < v.size(); i ++) {
        printf("%d\n", v[i]);
    }

}

