	for (int i = 0; i < N; i += 2) {
		if (A[i] > 0) {
			su1 += A[i];
			res1.push_back(i);
		}
	}
	int su2 = 0;
	for (int i = 1; i < N; i += 2) {
		if (A[i] > 0) {
			su2 += A[i];
			res2.push_back(i);
		}
	}
	int su;
	vector<int> res;
	if (su1 > su2) {
		su = su1;
		res = res1;
	}
	else {
		su = su2;
		res = res2;
	}
	cout << su << endl;
