	vector<int> resres;
	for (int i = N-1; i > res.front(); --i) {
		resres.push_back(i + 1);
	}
	for (int i = 0; i < res.size() - 1; ++i) {
		int cnt = (res[i] - res[i + 1]) / 2;
		int center = (res[i] + res[i + 1]) / 2;
		for (int j = 0; j < cnt; ++j) {
			resres.push_back(center - j + 1);
