    cin >> n;
    vl a(n);
    for (int i = 0; i < n;i++){
        cin >> a[i];
    }
    ll sum1 = 0;
    ll num1 = 0;
    ll sum2 = 0;
    ll num2 = 0;
    for (int i = 0; i < n; i += 2)
    {
        if(a[i]>0){
            sum1 += a[i];
            num1++;
        }
    }
    for (int i = 1; i < n; i += 2)
    {
        if(a[i]>0){
            sum2 += a[i];
            num2++;
        }
    }
    vi ans;
    if(sum1>sum2){
        cout << sum1 << endl;
    }
    else{
        cout << sum2 << endl;
        ans.push_back(1);
        n--;
        for (int i = 0; i < n ;i++){
            a[i] = a[i + 1];
        }
    }
    int k = 0;
    int d = 0;
    for (k = 0; k < n; k += 2)
    {
        if(a[k]>0){
            break;
        }
    }
    d += k;
    for (int i = 0; i < k; i++)
    {
        ans.push_back(1);
    }
    int e = 0;
    for (int i = 0; i < n; i += 2)
    {
        if (a[i] > 0)
        {
            e = i;
        }
    }
    for (int i = 0; i < n - e - 1; i++)
    {
        ans.push_back(e + 2 - d);
    }
