typedef long long ll;
typedef double db;
int n,A[1005],pre[1005],ans[1005],tot;
ll f[1005],Ans[1005];
bool flag;
void work(int pos)
{
	for(int i=pos;i<n;++i) Ans[i]=Ans[i+1];
	n--;
}
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;++i)
	{
		scanf("%d",&A[i]);
		if(A[i]>0) flag=1;
	}
	if(!flag)
	{
		printf("0\n%d\n",n);
		for(int i=1;i<n;++i) printf("1\n");
		return 0;
	}
	for(int i=1;i<=n;++i)
	{
		f[i]=A[i];
		int Max=0;
		for(int j=i-2;j>=1;j-=2) if(!Max||f[j]>f[Max]) Max=j;
		if(f[Max]>=0) f[i]+=f[Max],pre[i]=Max;
	}
	int Max=0;
	for(int i=1;i<=n;++i) if(f[i]>f[Max]) Max=i;
	int J=Max;
	while(J) Ans[J]=1,J=pre[J];
	while(n>1)
	{
		if(!Ans[n]) {work(n);ans[++tot]=n;continue;}
		if(!Ans[1]) {work(1);ans[++tot]=1;continue;}
		for(int i=2;i<n;++i)
		{
			if(Ans[i]) continue;
			if(Ans[i-1]==Ans[i+1])
			{
				ans[++tot]=i;
				work(i-1),work(i);
				Ans[i-1]=1;
				break;
			}
		}

	}
	printf("%lld\n%d\n",f[Max],tot);
	for(int i=1;i<=tot;++i) printf("%d\n",ans[i]);
	return 0;
}

