    int sizeE = 0, sizeO = 0;
    for(int i = 1; i <= n; i++){
        if(i%2){
            if(a[i]>=0) odd[++sizeO] = i;
            else if(maxnO==-1 || a[i]>a[maxnO]) maxnO = i;
        }
        else{
            if(a[i]>=0) even[++sizeE] = i;
            else if(maxnE==-1 || a[i]>a[maxnE]) maxnE = i;
        }
    }
    if(sizeE==0) even[++sizeE] = maxnE;
    if(sizeO==0) odd[++sizeO] = maxnO;
    long long sumE = 0, sumO = 0;
    for(int i = 1; i <= sizeE; i++) sumE += a[even[i]];
    for(int i = 1; i <= sizeO; i++) sumO += a[odd[i]];
    if(sumE>sumO){
        printf("%lld\n",sumE);
        printAnswer(sizeE,even,n);
