typedef long long i64;
const i64 inf = (i64)1.05e18;

pair<i64, int> compute(int pos, vector<i64>& xs, vector<pair<i64,int>>& memo)
{
	const int n = xs.size();
	if(pos >= n) return {0LL, n};
	auto& val = memo[pos];

	if(val.first != -inf)
		return val;

	val = {xs[pos], n};

	for(int p = pos + 2; p < n; p += 2) {
		auto t = compute(p, xs, memo);
		t.first += xs[pos];
		t.second = p;
		val = max(val, t);
	}

	return val;
}

int main()
{
	int n;
	vector<i64> as;

	scanf("%d", &n);
	as.resize(n);
	for(int i = 0; i < n; ++i)
		scanf("%lld", &as[i]);

	vector<pair<i64,int>> memo(n, pair<i64,int>(-inf, n));
	i64 best = 0;
	int start = n;

	for(int i = 0; i < n; ++i) {
		auto t = compute(i, as, memo);
		if(t.first > best) {
			best = t.first;
			start = i;
		}
	}

	int last = start;
	while(true) {
		int next = compute(last, as, memo).second;
		if(next >= n)
			break;
		last = next;
	}

	vector<int> op;

	for(int i = n - 1; i > last; --i)
		op.push_back(i + 1);
	for(int i = 0; i < start; ++i)
		op.push_back(1);

	int it = start;

	while(it < last) {
		int next = compute(it, as, memo).second;
		int diff = next - it;
		while(diff > 2) {
			op.push_back(3);
			diff -= 2;
		}
		op.push_back(2);
		it = next;
	}

	printf("%lld\n%d\n", best, (int)op.size());
	for(auto o : op)
		printf("%d\n", o);

	return 0;
}

