#define int long long

void solve(int n, vector<int> a, int &ans, vector<int> &res) {
	if (n % 2 == 0) {
		res.push_back(n - 1);
		n--;
		a.pop_back();
	}
	int any = 0;
	for (int i = n - 1; i >= 0; i -= 2) {
		any |= (a[i] >= 0);
	}
	if (!any) {
		ans = -1;
		return;
	}
	auto ers = [&] (int x) {
		res.push_back(x);
		if (x == 0 || x + 1 == (int)a.size()) {
			a.erase(a.begin() + x);
		} else {
			int v = a[x - 1] + a[x + 1];
			for (int i = 0; i < 3; i++) {
				a.erase(a.begin() + x - 1);
			}
			a.insert(a.begin() + x - 1, v);
		}
	};
	while (true) {
		if (a[0] < 0) {
			ers(0);
			ers(0);
		} else {
			break;
		}	
	}
	while ((int)a.size() > 1) {
		if (a[2] < 0) {
			if ((int)a.size() == 3) {
				ers(2);
				ers(1);
			} else {
				ers(2);
			}
		} else {
			ers(1);
		}
	}
	ans = a[0];
	return;
}

