		cin >> t;
	}
	if (*max_element(a.begin(), a.end()) < 0) {
		int v = max_element(a.begin(), a.end()) - a.begin();
		int pnt = n;
		cout << a[v] << '\n';
		cout << n - 1 << '\n';
		for (int i = 0; i < n - 1 - v; i++) {
			cout << pnt << '\n';
			pnt--;
		}
		for (int i = 0; i < v; i++) {
			cout << 1 << '\n';
		}
		return 0;
	}
	int fans = 0;
	vector<int> fv;
	solve(n, a, fans, fv);
	n--;
	a.erase(a.begin());
	int sans = 0;
	vector<int> sv = {0};
	solve(n, a, sans, sv);
	if (sans > fans) {
		swap(sans, fans);
		swap(fv, sv);
	}
	cout << fans << '\n';
	cout << fv.size() << '\n';
	for (auto t : fv) {
		cout << t + 1 << '\n';
	}
}

