typedef long long lint;

int n;
lint v[MAX_N + 1];
int luat[MAX_N + 1];

lint rez;

int stkLen;
int stk[MAX_N + 1];

int codes[MAX_N + 1];

void ops(int poz)
{
    stk[++ stkLen] = poz;
}

int main()
{
    cin >> n;

    int i;
    lint mx = -2000000000;
    for(i = 1; i <= n; i ++)
    {
        cin >> v[i];
        mx = max(mx, v[i]);
    }

    if(mx <= 0)
    {
        cout << mx << "\n";

        return 0;
    }

    int st = 1;
    while(v[st] < 0)
    {
        ops(1);
        luat[st] = 1;
        st ++;
    }

    int dr = n;
    while(v[dr] < 0)
    {
        ops(dr);
        luat[dr] = 1;
        dr --;
    }
    for(i = st; i <= dr; i ++)
    {
        int ant = i - 1;
        int urm = i + 1;
        if(luat[i] == 0 && v[i] < 0)
        {
            while(luat[ant] == 1)
                ant --;

            while(luat[urm] == 1)
                urm ++;

            int cat = 0;
            for(int j = 1; j <= i; j ++)
                cat += (1 - luat[j]);
            ops(cat);

            luat[ant] = 1;
            luat[urm] = 1;
            v[i] = v[ant] + v[urm];
        }
    }

    lint s[2];
    s[1] = s[0] = 0;
    int k = 0;
    for(i = 1; i <= n; i ++)
    {
        if(luat[i] == 0)
        {
            codes[++ k] = i;
            s[k & 1] += v[i];
        }
    }

    int win = (s[0] > s[1] ? 0 : 1);
    int last = k - 1;
    if(last % 2 == win)
        last --;

    while(last > 1)
    {
        int ant = codes[last] - 1;
        int urm = codes[last] + 1;
        while(luat[ant] == 1)
            ant --;

        while(luat[urm] == 1)
            urm ++;

        luat[ant] = luat[urm] = 1;

        ops(last);
        last -= 2;
        k -= 2;
    }

    mx = max(s[0], s[1]);

    int poz;
    if(win == 1)
        poz = 1;

    else
        poz = 2;

    int cnt = 0;
    for(i = 1; i <= n; i ++)
    {
        cnt += (1 - luat[i]);

        if(cnt == poz)
        {
            poz = i;
            break;
        }
    }

    for(i = 1; i < poz; i ++)
    {
        if(luat[i] == 0)
            ops(1), k --;
    }

    for(i = n; i > poz; i --)
    {
        if(luat[i] == 0)
            ops(k), k --;
    }


    cout << max(s[0], s[1]) << "\n";
    cout << stkLen << "\n";
    for(i = 1; i <= stkLen; i ++)
        cout << stk[i] << "\n";

    return 0;
}

