int N;
vector<ll> A;
vector<int> procedures;
ll result;
void prepare() {

  int pre = 0;
  for (int i = 0; i < N; i++) {
    if (A[i] <= 0) {
      pre++;
    } else {
      break;
    }
  }
  int post = 0;
  for (int i = N - 1; i >= 0; i--) {
    if (A[i] <= 0) {
      post++;
    } else {
      break;
    }
  }
  vector<ll> B;
  for (int i = 0; i < pre; i++) {
    procedures.push_back(i);
  }
  for (int i = 0; i < post; i++) {
    procedures.push_back(N - 1 - i);
  }
  for (int i = pre; i < N - post; i++) {
    B.push_back(A[i]);
  }
  // debug(B);
  A = move(B);
  // cerr << A.size() << endl;
}
bool special_case(){
  bool is_special = true;
  ll result = -LL_INF;
  for (auto &val : A){
    if (val > 0){
      is_special = false;
    }
    result = max(result, val);
  }
  if (not is_special){
    return false;
  }
  int idx = -1;
  for (int i = 0; i < A.size(); i++){
    if (A[i] == result){
      idx = i;
      break;
    }
  }
  cout << result << endl;
  cout << N - 1 << endl;
  for (int i = 0; i < idx; i++){
      cout << 1 << endl;
  }
  int rest = N - idx;
  // cerr << N << " " << idx << endl;
  while (rest > 1){
    cout << rest << endl;
    rest--;
  }
  return true;
}
int main() {
  cin >> N;
  A.resize(N);
  for (auto &val : A) {
    cin >> val;

  }
  //special case
  if (special_case()){
    return 0;
  }
  prepare();
  int loop_cnt = 0;
  while (A.size() != 1) {
    loop_cnt++;
    if (loop_cnt > 5){
      break;
    }
    // debug(A);
    ll max_val = -LL_INF;
    int idx = -1;

    for (int i = 0; i < A.size(); i++) {
      ll left, right;
      left = right = 0;
      if (i - 1 >= 0) {
        left = A[i - 1];
      }
      if (i + 1 < N) {
        right = A[i + 1];
      }
      ll updated_val = left + right - A[i];
      if (updated_val > max_val) {
        max_val = updated_val;
        idx = i;
      }
    }
    // cerr << "idx = " << idx << " " << max_val << endl;
    assert(idx >= 0);
    vector<ll> B;
    for (int i = 0; i < A.size(); i++) {
      if (i == idx - 1 or i == idx + 1) {
        continue;
      } else if (i == idx) {
        if (i != 0 or i != A.size() - 1){
          B.push_back(max_val + A[i]);
        }
      } else {
        B.push_back(A[i]);
      }
    }
    procedures.push_back(idx);
    A = move(B);
    N = A.size();
  }

  cout << A[0] << endl;
  cout << procedures.size() << endl;
  for (auto &val : procedures) {
    cout << val + 1 << endl;
  }
  return 0;
}

