#include <cstdio>

int N;
int ai[1010];
long long memo[1010][1010];
int mm2[1010][1010];
long long res;
long long Neg=-1000000000ll*1000000000;
long long Neg2=-2000000000ll*1000000000;
int num[1010];
int numL;

long long srch(int ll, int rr)
{
	int i;
	if(memo[ll][rr] != Neg)
		return memo[ll][rr];
	if(ll == rr)
		return ai[ll];
	if(ll+1==rr)
		return Neg2;
	long long mx=Neg2;
	long long tmp1, tmp2;
	int mxi;
	for(i=ll+1; i<rr; i++){
		tmp1 = srch(ll, i-1);
		tmp2 = srch(i+1, rr);
		if(tmp1!=Neg2 && tmp2!=Neg2)
			if(mx < tmp1+tmp2){
				mx = tmp1+tmp2;
				mxi = i;
			}
	}
	memo[ll][rr] = mx;
	mm2[ll][rr] = mxi;
	return mx;
}

void srch2(int ll, int rr, int st)
{
	if(ll==rr)
		return ;
	int p = mm2[ll][rr];
	srch2(ll, p-1, st);
	srch2(p+1, rr, st+2);
	num[numL] = st+1;
	numL ++;
}

void solve()
{
	int i, j;
	for(i=0; i<N; i++)
		for(j=0; j<N; j++)
			memo[i][j] = Neg;
	res = srch(0, N-1);
	if(res != Neg2){
		srch2(0, N-1, 0);
	}
	long long tmp;
	int l2=-1, r2;
	for(i=1; i<N; i++){
		for(j=i; j<N; j++){
			tmp = srch(i, j);
			if(tmp > res){
				res = tmp;
				l2 = i;
				r2 = j;
			}
		}
	}
	if(l2!=-1){
		numL = 0;
		//for(i=r2+1; i<N; i++){
		for(i=N-1; i>=r2+1; i--){
			num[numL] = i;
			numL ++;
		}
		for(i=0; i<l2; i++){
			num[numL] = 0;
			numL ++;
		}
		srch2(l2, r2, 0);
	}
	printf("%lld\n", res);
	printf("%d\n", numL);
	for(i=0; i<numL; i++)
		printf("%d\n", num[i]+1);
}

int main()
{
	//freopen("in.txt", "r", stdin);
	int i;
	scanf("%d", &N);
	for(i=0; i<N; i++)
		scanf("%d", &ai[i]);
	solve();
	return 0;
}

