void rm_back(int cnt) {
    while (cnt-- > 0) {
        moves.pb(n);
        n--;
    }
}

void combine(int l, int r) {
    for (int i = r - 1; i > l; i -= 2)
        moves.pb(i);
}

void rm_front(int cnt) {
    while (cnt-- > 0) {
        moves.pb(1);
    }
}

