ll estim(vll& a, int ofs){
    int N = a.size();
    ll sum = 0;
    for(int i=ofs; i<N; i+=2){
        if (a[i] > 0) sum += a[i];
    }
    return sum;
}

const int INF = 0x7fffffff;

void solve(vll& a, int ofs) {
    int N = a.size();
    vi ops;

    int last = N-1;
    if (last % 2 != ofs) --last;


    if (last == N-1) {
        if (a[N-1] < 0) {
            ops.pb(N-1);
            a.erase(a.begin()+N-1, a.begin()+N);
        }
    }
    for (int i=last-2; i>=1; i-=2) {
        if (a[i] < 0) {
            ops.pb(i);
            a.erase(a.begin()+i-1, a.begin()+i+1);
            a[i-1] = INF;
        }
    }
    if (ofs == 0) {
        if (a[0] < 0) {
            ops.pb(0);
            a.erase(a.begin(), a.begin()+1);
            ofs = 1;
        }
    }
    int n = a.size();
    last = n-1; if (last % 2 != (1-ofs)) --last;
    for (int i=last; i>=(1-ofs); i-=2) {
        ops.pb(i);
        if (i == n-1 || i == 0) {
            a.erase(a.begin()+i, a.begin()+i+1);
        } else {
            ll sum = a[i-1] + a[i+1];
            a.erase(a.begin()+i-1, a.begin()+i+1);
            a[i-1] = sum;
        }
    }

    cout << ops.size() << endl;
    for (int ix : ops) {
        cout << 1+ix << endl;
    }
}

void solve(int N, vll& a) {
    ll e0 = estim(a, 0), e1 = estim(a, 1);
    if (e0 >= e1) {
        cout << e0 << endl;
        solve(a, 0);
    } else {
        cout << e1 << endl;
        solve(a, 1);
    }
}
int main() {
    vll a;
    int N = loadvec(a);
    solve(N,a);
    return 0;
}

