	for(int i = 0; i < n; ++i) {
		cin >> a[i];
		if(a[i] > maxi) {
			maxi = a[i];
			idx = i;
		}
	}
	if(maxi < 0) {
		cout << maxi << '\n';
		cout << n - 1 << '\n';
		for(int i = 0; i < idx - 1; ++i) {
			cout << 1 << '\n';
		}
		for(int i = n - idx; i > 1; --i) {
			cout << i << '\n';
		}
		return 0;
	}
	int64_t sum[2] = {};
	vector<vector<bool>> idxs(2, vector<bool>(1010));
	for(int i = 0; i < n; ++i) {
		if(a[i] >= 0) {
			sum[i % 2] += a[i];
			idxs[i % 2][i] = true;
		}
	}
	int ii = (sum[0] < sum[1]);
	cout << sum[ii] << '\n';
	vector<int> ans;
	for(int i = n - 1; i >= 0; --i) {
		if(not idxs[ii][i]) {
			idxs[ii].erase(idxs[ii].end() - 1, idxs[ii].end());
			ans.push_back(i + 1);
		} else {
			break;
		}
	}
	for(int i = 0; i < n; ++i) {
		if(not idxs[ii][i]) {
			ans.push_back(1);
		} else {
			idxs[ii].erase(idxs[ii].begin(), idxs[ii].begin() + i);
			break;
		}
	}
	int r = -1;
	for(int i = (int)idxs[ii].size() - 1; i >= 0; --i) {
		if(idxs[ii][i]) {
			int l = i + 1;
			if(r != -1) {
				for(int j = (l + r) / 2; j >= l; --j) {
					ans.push_back(j + 1);
				}
			}
			r = i - 1;
		}
	}
	cout << ans.size() << '\n';
	for(int i : ans) {
		cout << i << '\n';
	}
	return 0;
}

