            }
            else {
                cur.erase(cur.begin() + 2);
                cur.erase(cur.begin() + 2);
            }
            continue;
        }
    }

    cout << ans.size() << "\n";
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i] << "\n";
    }
}

