ll solve(ll l, ll r) {
	if (r - l == 1)
		return a[l];
	if ((r - l) % 2 == 0 || r - l <= 0)
		return -INF;
	if (mp.find(P(l, r)) != mp.end())
		return mp[P(l, r)];
	ll nowans = -INF;
	for (ll k = l + 1;k < r - 1;k++) {
		ll now = solve(l, k) + solve(k + 1, r);
		if (nowans < now) {
			nowans = now;
			mov[P(l, r)] = k;
		}
	}
	return mp[P(l, r)] = nowans;
}
