#define REP(i,n) for (ll i = 0; i < n; ++i)
#define REPR(i,n) for (ll i = n-1; i >= 0; --i)
#define FOR(i,m,n) for (ll i = m; i < n; ++i)
#define FORR(i,m,n) for (ll i = n-1; i >= m; --i)
#define FORE(x,xs) for (const auto& x : xs)
#define PB push_back
#define MP make_pair
#define MT make_tuple
#define ALL(v) v.begin(), v.end()

int N;
vi A;

void solve() {
    ll mx = -1e10;
    ll odd = 0, even = 0;
    REP (i, N) {
        mx = max(mx, A[i]);
        if (i&1) odd += max(0ll, A[i]);
        else even += max(0ll, A[i]);
    }

    if (mx <= 0) {
        cout << mx << "\n" << N-1 << "\n";
        int idx = 0;
        while (A[idx] != mx) {
            cout << 1 << "\n";
            idx++;
        }
        while (idx < N-1) {
            cout << N-idx << "\n";
            idx++;
        }
        assert(N-idx == 1);
        return;
    }

    vi op;
    if (odd > even) {
        op.PB(1);
        A.erase(A.begin());
        N--;
    }
    if (A.size()%2 == 0) {
        op.PB(A.size());
        A.erase(--A.end());
    }

    while (A[0] <= 0) {
        op.PB(1); op.PB(1);
        A.erase(A.begin());
        A.erase(A.begin());
    }
    while (A[A.size()-1] <= 0) {
        op.PB(A.size()); A.erase(--A.end());
        op.PB(A.size()); A.erase(--A.end());
    }
    while (A.size() > 1) {
        assert(A.size() >= 3);
        assert(A.size()%2 == 1);
        if (A[2] > 0) {
            op.PB(2);
            A[0] += A[2];
        }
        else op.PB(3);
        A.erase(++A.begin());
        A.erase(++A.begin());
    }
    assert(A.size() == 1);
    assert(A[0] == max(odd, even));

    cout << A[0] << "\n" << op.size() << "\n";
    FORE (x, op) cout << x << "\n";
}

int main() {
    cin >> N; A = vi(N);
    REP (i, N) cin >> A[i];
    solve();
}

