ll solve(int l, int r) {
	ops.clear();
	int offset = -(l - 1);
	ll ans = a[l];
	for (int i = l + 1; i <= r; ++i) {
		if (i == r) {
			ops.pb(i + offset);
		} else if (a[i + 1] >= 0) {
			ans += a[i + 1];
			ops.pb(i + offset);
			offset -= 2;
			++i;
		} else if (i + 2 <= r) {
			ops.pb(i + 1 + offset);
			offset -= 2;
			i += 2;
		} else {
			ops.pb(i + 1 + offset);
			ops.pb(i + offset);
			break;
		}
	}
	return ans;
}

