	REP(i, eve.size()){
		FOR(j,i+1,eve.size()){
			if(maxi < eve[j] - eve[i]){
				l = i;
				r = j;
				prt = 0;
				maxi = eve[j] - eve[i];
			}
		}
	}
	REP(i, odd.size()) {
		FOR(j, i + 1, odd.size()) {
			if (maxi < odd[j] - odd[i]) {
				l = i;
				r = j;
				prt = 1;
				maxi = odd[j] - odd[i];
			}
