using ll = long long int;
const int INF = (1<<30);
const ll INFLL = (1ll<<60);
const ll MOD = (ll)(1e9+7);

#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

ll a[1010];
int bitree[1010],l[1010],r[1010];
std::vector<int> ans;
bool use[1010],erased[1010];

int query(int x){
	int ret = 0;
	while(x){
		ret += bitree[x];
		x -= (x&-x);
	}
	return ret;
}

void update(int x, int v){
	while(x<1010){
		bitree[x] += v;
		x += (x&-x);
	}
}

void erase(int x){
	int p,q;
	p = l[x];
	q = r[x];
	l[q] = p;
	r[p] = q;
	update(x,-1);
	erased[x] = true;
}

int main(void){
	int n,i,p;
	bool flag = false;
	ll s[2]={0ll,0ll};
	std::cin >> n;
	for(i=1; i<=n; ++i){
		l[i] = i-1; r[i] = i+1; update(i,1);
		std::cin >> a[i];
		if(a[i]>=0ll){
			flag = true;
		}
		s[i%2] += std::max(a[i],0ll);
	}
	if(flag){
		p = (s[0]<s[1]);
		for(i=1; i<=n; ++i){
			use[i] = (i%2==p && a[i]>=0ll);
		}
	}else{
		s[0] = -INFLL; s[1]=-INFLL;
		for(i=1; i<=n; ++i){
			s[i%2] = std::max(s[i%2],a[i]);
		}
		p = (s[0]<s[1]);
		for(i=1; i<=n; ++i){
			if(i%2==p && a[i] == s[i%2]){
				use[i] = true;
				break;
			}
		}
	}
	std::cout << std::max(s[0],s[1]) << std::endl;
	for(i=n; i>0; --i){
		if(use[i]){
			break;
		}
		ans.push_back(query(i));
		erase(i);
	}
	for(i=1; i<=n; ++i){
		if(use[i]){
			break;
		}
		ans.push_back(query(i));
		erase(i);
	}
	use[0] = true; use[n+1] = true;
	for(i=1; i<=n; ++i){
		if(erased[i]){
			continue;
		}
		if(!(use[l[i]]||use[i]||use[r[i]])){
			ans.push_back(query(i));
			erase(l[i]); erase(r[i]);
		}
	}
	use[0] = false; use[n+1] = false;
	for(i=1; i<=n; ++i){
		if(erased[i]){
			continue;
		}
		if(use[i]){
			continue;
		}
		if(use[l[i]]&&use[r[i]]){
			ans.push_back(query(i));
			erase(l[i]); erase(r[i]);
			use[i] = true;
		}
	}
	std::cout << ans.l_ength() << std::endl;
	for(i=0; i<ans.l_ength(); ++i){
		std::cout << ans[i] << std::endl;
	}
	return 0;
}

