            int r = l + len;
            if (r > n) break;

            rep(mid, l + 1, r - 1) {
                if (maxi(dp[l][r], dp[l][mid] + dp[mid + 1][r])) {
                    opt[l][r] = mid;
                }
            }
        }
    }

