		if (!bef) { For (i, 1, u - 1) ans.push(i); bef = u; continue ;}
		int gap = u - bef, cnt = 0;
		while (gap > 0) { ans.push(bef + (++ cnt)); gap -= 2; }
		bef = u;
	}
	For (i, bef + 1, n) ans.push(i);
	cout << ans.size() << endl;
	while (!ans.empty()) { printf ("%d\n", ans.top()); ans.pop(); }
