	  else
	    {
	      fun(mid+1,r,0,dp[mid+1][r]);
	      ans.pb(mid);
	    }
	}
    }
  else
    {
      if(a[r]==val)
	rep(i,l,r) ans.pb(i);
      else
	{
	  int mid=-1;
	  rep(i,l+1,r)
	    {
