	  assert(mid!=-1);
	  fun(mid+1,r,2,dp2[mid+1][r]);
	  if(dp2[mid+1][r]==val)
	    {
	      rep(i,l,mid+1) ans.pb(i);
	    }
	  else
	    {
	      fun(l,mid-1,0,dp[l][mid-1]);
	      ans.pb(mid);
	    }
	}
    }
