    if(sum1 >= sum2 && !v1.empty()) summ = sum1, v3 = v1;
    else summ = sum2, v3 = v2;
    cout << summ << "\n";
    vector<int> ans;
    for (int j = n; j > v3.back(); --j) {
        ans.emplace_back(j);
    }
    int d = v3[0]-1;
    for (int i = 1; i <= d; ++i) {
        ans.emplace_back(i);
    }
    for (int i = 0; i+1 < v3.size(); ++i) {
        int k = v3[i+1]-v3[i]-1;
        for (int j = 0; j < (k+1)/2; ++j) {
            ans.emplace_back(v3[i]+(k+1)/2-d-j);
        }
        d += k+1;
    }
    cout << ans.size() << "\n";
    for (auto &&l : ans) cout << l << "\n";
    return 0;
}

