long long get(int l, int r){
      if(l > r) return -inf;
      if(used[l][r]) return dp[l][r];
      used[l][r] = 1;
      if(a[l] > a[r]) dp[l][r] = a[l], par[l][r] = r;
      else dp[l][r] = a[r], par[l][r] = l;
      get(l, r - 1);
      get(l + 1, r);
      for(int i = l + 1; i < r; i ++){
            long long cur = get(l, i - 1) + get(i + 1, r);
            if(cur > dp[l][r]){
                  par[l][r] = i;
