vector<int> solve(vector<LL> input) {
  vector<int> ret;
  LL best = -1000001000;
  int N = input.size();
  for (int z = 0; z < 2; z++) {
    if (N <= z) continue;
    vector<int> tmp;
    LL obj = 0;
    for (int i = z; i < N; i += 2) {
      if (input[i] > 0) {
        obj += input[i];
        tmp.push_back(i);
      }
    }
    if (tmp.empty()) {
      tmp.push_back(z);
      obj = input[z];
      for (int i = z; i < N; i += 2) {
        if (obj < input[i]) {
          tmp[0] = i;
          obj = input[i];
        }
      }
    }

    if (best < obj) {
      best = obj;
      ret = tmp;
    }
  }
  return ret;
}

