  for (int i = 0; i < N; i++) {
    LL a;
    cin >> a;
    vals.push_back(a);
  }
  vector<int> remain = solve(vals);
  LL best = 0;
  for (auto i : remain) best += vals[i];
  vector<int> diffs;
  adjacent_difference(remain.begin(), remain.end(), back_inserter(diffs));

  vector<int> output;
  for (int i = N - 1; i > remain.back(); i--) output.push_back(i);
  for (int i = 0; i < remain[0]; i++) output.push_back(0);
  for (int i = 1; i < diffs.size(); i++) {
    for (int j = 0; j < diffs[i] / 2 - 1; j++) {
      output.push_back(2);
    }
    output.push_back(1);
  }

  cout << best << endl << output.size() << endl;
  for (auto elem : output) {
    cout << elem + 1 << endl;
  }
  return 0;
}

