void solve(vector<ll> &a,vector<ll> &dp,vector<ll> &prev){
  int n=a.size();
  for(int i=0;i<n;i++)prev[i]=-1;

  for(int i=0;i<n;i++){
    dp[i]=a[i];
    for(int j=i-2;j>=0;j-=2){
      if(dp[i] < dp[j]+a[i]){
        dp[i]=dp[j]+a[i];
        prev[i]=j;
      }
    }
  }
}

