int rem[1005];
vector<int> proc;

int main(void) {

	cin >> N;

	for (int i = 1; i <= N; i++) { cin >> a[i]; }

	long long int sum_even = 0;
	for (int i = 2; i <= N; i += 2) {
		if (a[i] >= 0) { sum_even += a[i]; }
	}

	long long int sum_odd = 0;
	for (int i = 1; i <= N; i += 2) {
		if (a[i] >= 0) { sum_odd += a[i]; }
	}

	long long int ans;

	if (sum_even > sum_odd) {
		ans = sum_even;
		for (int i = 2; i <= N; i += 2) { if (a[i] >= 0) { rem[i] = 1; } }
	}
	else {
		ans = sum_odd;
		for (int i = 1; i <= N; i += 2) { if (a[i] >= 0) { rem[i] = 1; } }
	}

	//cout << ans << endl;

	int M = 0;
	int I;
	for (I = N; I >= 1; I--) {
		if (rem[I] > 0) { break; }
		proc.push_back(I);
	}

	int min_rem;
	for (int i = 1; i <= N; i++) { if (rem[i] > 0) { min_rem = i; break; } }

	for (int i = I - 2; i >= min_rem; i -= 2) {
		if (rem[i] > 0) { proc.push_back(i+1); }
		else {
			proc.push_back(i);
			proc.push_back(i-1);
		}
	}

	for (int i = 1; i < min_rem; i++) {
		proc.push_back(i);
	}

	cout << ans << endl;
	cout<< proc.size() << endl;
	for (int i = 0; i < (int)proc.size(); i++) {
		cout << proc[i] << endl;
	}

	//system("pause");
	return 0;
}

