LL re(LL st,LL parity,bool f){
//    if(st==1){
//        plll(st,parity,(LL)f);NL;
//    }
    if(st==n){return 0;}
    if(visited[st][parity][f]){return dp[st][parity][f];}
    visited[st][parity][f]=true;
    LL s1=-INF,s2=-INF,s3=-INF,s4=-INF;
    if(!f){
        s1=ara[st];
        s2=ara[st]+re(st+1,(parity+1)%2,true);
        s3=re(st+1,parity,f);
        return dp[st][parity][f]=max(s3,max(s1,s2));
    }
    else{
        if(parity%2==1){
            s1=re(st+1,(parity+1)%2,f);
            return dp[st][parity][f]=s1;
        }
        else{
            s1=ara[st];
            s2=ara[st]+re(st+1,(parity+1)%2,f);
            s3=re(st+1,(parity+1)%2,f);
            return dp[st][parity][f]=max(s1,max(s2,s3));
        }
    }
}
void bktrk(LL st,LL parity,bool f){
    if(st==n){return;}
    LL mx,s1,s2,s3,i,j;
    if(!f){
        s1=ara[st];
        s2=ara[st]+dp[st+1][(parity+1)%2][true];
        s3=dp[st+1][parity][f];
        mx=max(s1,max(s2,s3));
        if(s1==mx){vec.pub(st);return;}
        else if(s2==mx){
            vec.pub(st);
            bktrk(st+1,(parity+1)%2,true);
        }
        else if(s3==mx){
            bktrk(st+1,parity,f);
        }
    }
    else{
        if(parity%2==1){
            bktrk(st+1,(parity+1)%2,f);
        }
        else{
            s1=ara[st];
            s2=ara[st]+dp[st+1][(parity+1)%2][f];
