vector <int> Do( int n , deque<int> dqAns )
{
    vector <int> ans ;
    deque<int> dq ;
    for(int i=1 ; i<=n ; i++) dq.push_back(i) ;
    while( dq.front() != dqAns.front() )
    {
        ans.pb(1) ;
        dq.pop_front() ;
    }
    while( dq.back() != dqAns.back() )
    {
        ans.pb( (int)dq.size() ) ;
        dq.pop_back() ;
    }

    if( dq.size() == 1 ) return ans ;

    while( dq.size() > 1 )
    {
        if( dq[2] == dqAns[1] )
        {
            ans.pb( 2 ) ;
            dq.pop_front() ;
            dq.pop_front() ;
            dqAns.pop_front() ;
            continue ;
        }
        else{
            ans.pb( 3 ) ;
            dq.pop_front() ;
            dq.pop_front() ;
            dq.pop_front() ;
            dq.push_front( dqAns.front() ) ;
        }
    }
    return ans ;
}

