vector<long long> f(vector<long long> &a, int id) {
  vector<long long> ret;
  if (id == 0) {
    for (int i = 1; i < a.size(); i++) {
      ret.push_back(a[i]);
    }
    return ret;
  }
  if (id == a.size() - 1) {
    for (int i = 0; i < a.size() - 1; i++) {
      ret.push_back(a[i]);
    }
    return ret;
  }
  for (int i = 0; i < id - 1; i++) {
    ret.push_back(a[i]);
  }
  ret.push_back(a[id - 1] + a[id + 1]);
  for (int i = id + 2; i < a.size(); i++) {
    ret.push_back(a[i]);
  }
  return ret;
}

int main() {
  int n;
  cin >> n;
  vector<long long> a(n);
  vector<int> ans;
  for (int i = 0; i < n; i++)
    cin >> a[i];
  while (a.size() > 1) {
    long long sum1 = 0, sum2 = 0;
    for (int i = 0; i < a.size(); i++) {
      if (i % 2 == 0) {
        if (a[i] > 0)
          sum1 += a[i];
      } else {
        if (a[i] > 0)
          sum2 += a[i];
      }
    }
    if (sum1 > sum2) {
      if (a[0] <= 0) {
        ans.push_back(1);
        a = f(a, 0);
        continue;
      }
      bool b = false;
      for (int i = 0; i < a.size() - 2; i += 2) {
        if (a[i] > 0 && a[i + 2] > 0) {
          ans.push_back(i + 2);
          a = f(a, i + 1);
          b = true;
          break;
        }
      }
      if (b) {
        continue;
      }
      if (a[a.size() - 1] <= 0 || a.size() % 2 == 0) {
        ans.push_back(a.size());
        a = f(a, a.size() - 1);
        continue;
      }
    } else {
      ans.push_back(1);
      a = f(a, 0);
    }
  }

  cout << a[0] << endl;
  cout << ans.size() << endl;
  for (int i = 0; i < ans.size(); i++)
    cout << ans[i] << endl;
  return 0;
}

