		cout << big << endl;
		for(int i = 0; i < n; i++) if(big == a[i]){
			for(int j = n - 1; j > i; j--) ops.push_back(j + 1);
			for(int j = 0; j < i; j++) ops.push_back(1);
			break;
		}
	} else {
		long long q[2] = {};
		for(int i = 0; i < n; i++) q[i&1] += max(a[i], 0ll);
		int id = q[1] > q[0];
		cout << q[id] << endl;
		vector<bool> wanted;
		for(int i = 0; i < n; i++) wanted.push_back((i&1) == id && a[i] > 0);
		while(wanted.size() > 1){
			if(!wanted[0]){
				ops.push_back(1);
				reverse(wanted.begin(), wanted.end());
				wanted.pop_back();
				reverse(wanted.begin(), wanted.end());
			} else if(!wanted.back()){
				ops.push_back(wanted.size());
				wanted.pop_back();
			} else {
				int len = wanted.size() - 1;
				int si = -1;
				for(int i = 1; i < len; i++){
					if(!wanted[i - 1] && !wanted[i + 1] && !wanted[i]){
						si = i;
						break;
					} else if(wanted[i - 1] && wanted[i + 1]) {
						si = i;
						break;
					}
				}
				assert(~si);
				vector<bool> nxt;
				ops.push_back(si + 1);
				for(int i = 0; i < len; i++) 
					if(i == si) nxt.push_back(wanted[i - 1]);
					else if(abs(i - si) != 1) nxt.push_back(wanted[i]);
				wanted = nxt;
			}
		}
	}
	cout << ops.size() << endl;
	for(int v : ops) cout << v << endl;
	return 0;
}

