unordered_map<ll,ll> pek;

ll dp(ll i, ll j){

    ll h = i*n+j;
    if(i > j)return 0;
    if(M.find(h) != M.end())return M[h];

    if(i == j)return A[i];

    //if(j-i == 1)return max(A[i],A[j]);
    //if(j-i == 2)return max(A[i+1],A[i]+A[j]);
    ll ans = -big*big;
    ll p = -1;
    for(int c1 = i; c1 <= j; c1++){
        ll temp = dp(i,c1-1) + dp(c1+1,j);
        if(temp > ans){
            ans = temp;
            p = c1;
        }
    }
    pek[h] = p;
    M[h] = ans;
    return ans;
}

vl sol;


void solve(ll i, ll j){
    if(i>=j)return;
    ll h = i*n+j;
    ll p = pek[h];
    assert(p != -1);
    solve(i,p-1);
    solve(p+1,j);
    sol.push_back(p);
    return;
}

