	if(pre[l][r]<0){
		solve(-pre[l][r]+2,r);
		s[++top]=-pre[l][r];
		solve(l,-pre[l][r]-2);
		s[++top]=l+1;
	}
	else{
		solve(pre[l][r]+1,r);
		solve(l,pre[l][r]-1);
		s[++top]=l+1;
	}
