Int solve(vector<Int> hoge){
	Int res = hoge[0];
	Int tmp = hoge[0];
	int l = 0, r = 1;
	int ltmp = 0, rtmp = 1;
	for(Int i = 1;i < hoge.size();i++){
		if(tmp < 0){
			ltmp = i, rtmp = i+1;
			tmp = hoge[i];
		}
		else{
			rtmp = i+1;
			tmp += hoge[i];
		}
		if(res < tmp){
			res = tmp;
			l = ltmp;
			r = rtmp;
		}
	}
	ll = l;
	rr = r;
	return res;
}

