vector<ll> ans_v;

signed main()
{
    cin >> N;
    bool isAllNeg = true;
    ll negAns = 1;
    REP(i, N) {
        cin >> A[i];
        if(A[i] > 0) { isAllNeg = false; }
        else { negAns = (negAns == 1) ? A[i] : max(negAns, A[i]); }
    }

    // 全部負の場合→最小のもの1つをとる
    if(isAllNeg) {
        printf("%lld\n", negAns);
