    }
    // 両端を削る
    while(1) {
        if(A2[0].first) { break; }
        ans_v.push_back(1);
        A2.erase(A2.begin());
    }
    while(1) {
        if(A2[A2.size()-1].first) { break; }
        ans_v.push_back(A2.size());
        A2.erase(A2.begin() + A2.size() - 1);
    }
    // 必要なものどうしの、ちょうど真ん中にあるものを足していく
    while(A2.size() > 1) {
        ll next;
        for(next = 1; next < A2.size(); ++next) {
            if(A2[next].first) { break; }
        }
        //printf("  next: %lld\n", next);
        ans_v.push_back(next / 2 + 1);
        if(next == 2) {
            A2.erase(A2.begin() + 2);
            A2.erase(A2.begin() + 1);
        } else {
            A2.erase(A2.begin() + (next / 2) + 1);
            A2.erase(A2.begin() + (next / 2) - 1);
        }
    }

    printf("%lld\n", max(odd_num, even_num));
    printf("%zu\n", ans_v.size());
    for(auto& a : ans_v) {
        printf("%lld\n", a);
    }


    return 0;
}

