#include <bits/stdc++.h>

#define MAX_N 1000

using namespace std;

typedef long long lint;

lint sum[2];
lint v[MAX_N + 1];

int n, cate;

int stkLen;
int stk[MAX_N + 1];

int luat[MAX_N + 1];

void ops(int nr)
{
    int i;
    int cat = 0;
    for(i = 1; i <= nr; i ++)
        cat += 1 - luat[i];

    if(cat == 1 || cat == cate)
    {
        luat[nr] = 1;
        stk[++ stkLen] = cat;
        cate --;

       // cout << "OPS 1 " << cat << " " << cate << "\n";

        return;
    }

    int ant = nr - 1;
    int urm = nr + 1;
    while(luat[ant] == 1)
        ant --;

    while(luat[urm] == 1)
        urm ++;

    luat[ant] = 1;
    luat[urm] = 1;
    stk[++ stkLen] = cat;
    v[nr] = v[ant] + v[urm];
    cate -= 2;
      //  cout << "OPS 2 " << cat << " " << cate << "\n";
}

void doOps(int s2)
{
    int i;
    int cnt = 0;
    for(i = 1; i <= n; i ++)
    {
        if(luat[i] == 0)
            cnt ++;

        if(cnt == s2)
        {
            cnt = i;
            break;
        }
    }

    ops(cnt);
}

void spec(lint mx)
{
    int i;
    int poz = 0;
    int cate = n;
    for(i = 1; i <= n; i ++)
    {
        if(v[i] == mx)
            poz = i;
    }

    cout << mx << "\n";
    cout << n - 1 << "\n";

    while(poz > 1)
    {
        cout << 1 << "\n";
        poz --;
        cate --;
    }

    while(cate > 1)
    {
        cout << cate << "\n";
        cate --;
    }
}

int main()
{
    cin >> n;

    int i;
    lint mx = -2000000000;
    for(i = 1; i <= n; i ++)
    {
        cin >> v[i];

        mx = max(mx, v[i]);
    }

    if(mx <= 0)
    {
        spec(mx);

        return 0;
    }

    int cat = 1;
    while(v[cat] < 0)
        cat ++;

    cat --;

    for(i = 1; i <= cat; i ++)
        stk[++ stkLen] = 1;

    for(i = 1; i + cat <= n; i ++)
        v[i] = v[i + cat];

    n -= cat;

    for(i = 1; i <= n; i ++)
        sum[i & 1] += v[i] * (v[i] > 0);

    cate = n;
    int s2 = 0;
    int start = 0;
    if(sum[0] > sum[1])
        start = 2, s2 = 3;

    else
        start = 1, s2 = 2;

    for(i = start; i <= n; i += 2)
    {
        if(v[i] < 0)
            ops(i);
    }

    while(s2 + 1 <= cate)
    {
        doOps(s2);
    }

    for(i = 1; i < s2 - 1   ; i ++)
        doOps(1);

   // cout << cate << "\n";

    while(cate > 1)
    {
        doOps(cate);
        cate --;
    }

    cout << max(sum[0], sum[1]) << "\n";
    cout << stkLen << "\n";

    for(i = 1; i <= stkLen; i ++)
        cout << stk[i] << "\n";

    return 0;
}

