        rep(i, n) if(a[i] == ma) j = i;
        for(int i = 0; i < j; ++ i) cout << i + 1 << endl;
        for(int i = n - 1; i > j; -- i) cout << i + 1 << endl;
        return;
    }
    static int dp[1010];
    vector<int> prev(n + 1, -1);
    rep(i, 1010) {
        dp[i] = 0;
    }
    rep(i, n) {
        dp[i + 1] = a[i];
        for(int j = i - 1; j >= 0; j -= 2) {
            if(chmax(dp[i + 1], dp[j] + a[i])) {
                prev[i + 1] = j;
            }
        }
    }
    int res = 0, k = -1;
    for(int i = 1; i <= n; ++ i) {
        if(chmax(res, dp[i])) {
            k = i;
