            op.push_back(b[i - 1] + x);
        }
    }
    for(int i = 0; i < b[0]; ++ i) {
        op.push_back(0);
    }
    cout << (int)op.size() << endl;
    rep(i, (int)op.size()) {
        cout << op[i] + 1 << endl;
    }
