vector<int> solve(bool odd)
{
	vector<int> ans;

	for(int i = odd; i < n; i += 2)
		if (a[i] > 0)
			bery[i] = 1;

	vector<int> x(n);
	FOR(i, 0, n) x[i] = bery[i];

	while(x.back() == 0)
	{
		ans.PB(SZ(x));
		x.pop_back();
	}

	while(x[0] == 0)
	{
		ans.PB(1);
		reverse(ALL(x));
		x.pop_back();
		reverse(ALL(x));
	}

	while (SZ(x) > 1) 
	{
		if (x[2] == 1)
		{
			ans.PB(2);
			reverse(ALL(x));
			x.pop_back();
			x.pop_back();
			reverse(ALL(x));
			continue;
		}

		ans.PB(3);
		reverse(ALL(x));
		x.pop_back();
		x.pop_back();
		x.pop_back();
		x.PB(1);
		reverse(ALL(x));
	}	

	return ans;
}

