int main() {
    scanner >> n;
    scanner.in(aa, aa + n);

    // todo: 全てがマイナス

    ll best = 0;

    vector<int> answer_pre;
    vector<int> answer;

    int choiceOdd = 0;
    {
        ll odd, even;
        odd = even = 0;
        repeat(i, n) {
            (i % 2 ? odd : even) += max(0ll, aa[i]);
        }
        choiceOdd = odd >= even;
        best = max(odd, even);
    }

    if (best == 0) {
        special();
        return 0;
    }


    int left = 0, right = n - 1, offset = 0;

    while (true) {
        if (left % 2 == choiceOdd && aa[left] > 0) {
            break;
        }
        answer_pre.push_back(left + offset + 1);
        offset -= 2;
        left += 1;
    }

    while (true) {
        if (right % 2 == choiceOdd && aa[right] > 0) {
            break;
        }
        answer_pre.push_back(right + offset + 1);
        right -= 1;
    }
    {
        iterate(i, left, right) {
            if (i % 2 != choiceOdd) continue;
            if (aa[i] <= 0) {
                answer_pre.push_back(i + offset + 1);
                offset -= 2;
            }
            else {
                answer.push_back(i + offset + 1);
            }
        }
    }


    printer << best << '\n';

    printer << ll(answer.size() + answer_pre.size()) << '\n';

    for (auto e : answer_pre)
        printer << e << '\n';

    for (auto e : answer)
        printer << e << '\n';


    return 0;
}

