const int MAXN=1005;
int n,tp,stt,tag,steps=0;
long long mx[2];
bool neg[2];
int a[MAXN],ans[MAXN];

int main()
{
    mx[0]=mx[1]=0;
    neg[0]=neg[1]=1;

    scanf("%d",&n);

    for (int i=0;i<n;++i)
    {
        scanf("%d",&a[i]);
        tp=i%2;
        if (a[i]>=0)
        {
            neg[tp]=0;
            mx[tp]+=a[i];
        }
    }

    if (neg[0]&&neg[1])
    {
        int pos=0;
        int sum=a[0];
        for (int i=1;i<n;++i)
            if (sum<a[i])
            {
                sum=a[i];
                pos=i;
            }
        printf("%d\n%d\n",sum,n-1);
        for (int i=n-1;i>pos;--i)
            printf("%d\n",i+1);
        for (int i=pos-1;i>=0;--i)
            printf("1\n");

        return 0;
    }

    mx[0]-=neg[0];
    mx[1]-=neg[1];
    tag=stt=mx[0]>mx[1]?0:1;
    while (stt+2<n) stt+=2;
    while (a[stt]<0) stt-=2;
    for (int i=n-1;i>stt;--i)
        ans[steps++]=i;

    while (1)
    {
        int i;
        for (i=stt-2;i>=0&&a[i]<0;i-=2)
        {
            ans[steps++]=i;
            if (i>0) stt-=2;
            else stt--;
            //printf("deleted:%d\n",i);
            i--;
        }
        if (i<0&&stt-2<0) break;
        for (;stt-2>=0&&a[stt-2]>=0;stt-=2)
        {
            ans[steps++]=stt-1;
            //printf("added:%d\n",stt);
        }
        if (stt-2<0) break;
    }
    if (stt==1) ans[steps++]=0;

    printf("%lld\n%d\n",mx[tag],steps);
    for (int i=0;i<steps;++i)
        printf("%d\n",ans[i]+1);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; scanf("%d", &n);
    vector<int> a(n);
    constexpr long long kInf = 1'000'000'000'000'000;
    vector<vector<long long>> dp(n, vector<long long>(n, -kInf));
    vector<vector<int>> fr(n, vector<int>(n));
    for (int i = 0; i < n; ++i) scanf("%d", &a[i]);
    for (int i = 0; i < n; ++i) dp[i][i] = a[i];
    for (int p = 1; p < n; ++p) {
        for (int i = 0; i + p < n; ++i) {
            int j = i + p;
            if (dp[i + 1][j] > dp[i][j]) {
                dp[i][j] = dp[i + 1][j];
                fr[i][j] = -1;
            }
            if (dp[i][j - 1] > dp[i][j]) {
                dp[i][j] = dp[i][j - 1];
                fr[i][j] = -2;
            }
            for (int k = i + 1; k < j; ++k) {
                if (dp[i][k - 1] + dp[k + 1][j] > dp[i][j]) {
                    dp[i][j] = dp[i][k - 1] + dp[k + 1][j];
                    fr[i][j] = k;
                }
            }
        }
    }
    printf("%lld\n", dp[0][n - 1]);

    vector<int> op;
    function<void(int, int)> Dfs = [&](int l, int r) {
        if (l == r) return;
        if (fr[l][r] == -1) {
            op.push_back(1);
            Dfs(l + 1, r);
        } else if (fr[l][r] == -2) {
            op.push_back(r - l + 1);
            Dfs(l, r - 1);
        } else {
            Dfs(l, fr[l][r] - 1);
            Dfs(fr[l][r] + 1, r);
            op.push_back(2);
        }
    };

    Dfs(0, n - 1);
    printf("%d\n", (int)op.size());
    for (int u : op) printf("%d\n", u);
}

