using namespace std; 
typedef long long ll;
const int N=1005;
int n;
ll a[N];
vector<int> op;
void del(int x){
	//printf("Del %d\n",x);
	op.pb(x);
	if(x==1||x==n){
		for(int i=1,t=0;i<=n;++i){
			if(i!=x)a[++t]=a[i];
		}
		--n;
	}else{
		a[x-1]+=a[x+1];
		for(int i=x;i+2<=n;++i)a[i]=a[i+2];
		n-=2;
	}
	rep(i,1,n)Pr("%lld ",a[i]);Pr("\n");
}
int main(){
	freopen("dat.in","r",stdin);
	freopen("my.out","w",stdout);
	scanf("%d",&n);
	rep(i,1,n)scanf("%lld",a+i);
	bool spec=true;
	rep(i,1,n)spec&=a[i]<=0;
	if(spec){
		int mx=1;
		rep(i,2,n)if(a[i]>a[mx])mx=i;
		int t1=mx-1,t2=n-mx;
		while(t1--)del(1);
		while(t2--)del(n);
	}else{
		ll odd=0,even=0;
		for(int i=1;i<=n;i+=2){
			odd+=a[i]>0?a[i]:0;
			if(i+1<=n)even+=a[i+1]>0?a[i+1]:0;
		}
		rep(i,1,n)Pr("%lld ",a[i]);Pr("QAQ\n");
		if(even>odd){
			del(1);
		}
		while(true){
			bool suc=false;
			for(int i=1;i<=n;i+=2){
				if(a[i]<0){
					del(i);
					suc=true;
					break;
				}
			}
			if(!suc)break;
		}
		while(n>1){
			del(2);
		}
	}
	printf("%lld\n", a[1]);
	printf("%d\n", (int)op.size());
	for(auto t : op) printf("%d\n", t);
	return 0;
}

