        if (cur[0] < 0) {
            ans.push_back(1);
            ans.push_back(1);
            cur.erase(cur.begin());
            cur.erase(cur.begin());
            continue;
        }
        if (cur.size() == 2) {
            ans.push_back(2);
            cur.erase(cur.begin() + 1);
            continue;
        }
        if (cur[2] > 0) {
            ans.push_back(2);
            cur[0] += cur[2];
            cur.erase(cur.begin() + 1);
            cur.erase(cur.begin() + 1);
