                ans.push_back(real_i - (count + 1) / 2 - j);
            }
            if (real_i <= 1) {
                real_i -= count;
            } else {
                real_i -= (count + 1);
            }
            count = 0;
            real_i += 1;
        }
        real_i -= 1;
        for (int j = 0; j < count; ++j) {
            ans.push_back(real_i - j);
        }
    } else {
