int n;
// odd : 0-indexedで奇数番目の要素のみ加算する累積
ll a[1010],odd[1010],even[1010];

void input(){

  cin >> n;
  for (size_t i = 0; i < n; i++)
  {
    cin >> a[i];
    odd[i+1] = odd[i] + (i % 2 == 1) * a[i];
    even[i+1] = even[i] + (i % 2 == 0) * a[i];
  }

}

// 0-indexedで偶数番目の要素のみ選ぶ場合
// cumurativeのindexは even[odd] - even[even]
long long MAX = -LONG_MAX;
pair<int,int> range = {0,1};
void set_max_even(){
  for(int r = 1;r <= n;r += 2){
    for(int l = 0;l < r;l += 2){
      if(chmax(MAX,even[r] - even[l])){
        range = {l,r};
      }
    }
  }
}

void set_max_odd(){
  for(int r = 2;r <= n;r += 2){
    for(int l = 1;l < r;l += 2){
      if(chmax(MAX,odd[r] - odd[l])){
        range = {l,r};
      }
    }
  }
}

void print_ans(){
  int l = range.first;
  int r = range.second;
  int cnt = 0;
  cout << MAX << '\n';
  vector<int> ans;
  for(int i = 0;i < l;i++){
    ans.push_back(1);
    cnt++;
  }
  for(int i = l + 1;i < r;i+=2){
    ans.push_back(2);
    cnt += 2;
  }
  for(int i = n - 1;i >= r;i--){
    ans.push_back(n - (cnt++));
  }
  cout << ans.size() << '\n';
  for (size_t i = 0; i < ans.size(); i++)
  {
    assert(ans[i] > 0);
    cout << ans[i] << '\n';
  }
}

int main(void){
  input();
  set_max_even();
  set_max_odd();
  print_ans();
  return 0; 
}

