int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;

    V<ll> a(N + 1);
    NREP(i, N) {
        cin >> a[i];
    }

    V<bool> pos(N + 1, false);
    bool allneg = true;
    V<ll> sum(2, 0);
    NREP(i, N) {
        if (a[i] >= 0) {
            pos[i] = true;
            allneg = false;
            sum[i % 2] += a[i];
        }
    }

    if (allneg) {
        ll maxid = 1;
        NREP(i, N) {
            if (a[maxid] < a[i]) maxid = i;
        }

        cout << a[maxid] << endl;
        cout << N - 1 << endl;

        REP(_, maxid - 1) {
            cout << 1 << endl;
            N--;
        }

        while (N > 1) {
            cout << N << endl;
            N--;
        }
        return 0;
    }

    ll big = 1;
    if (sum[0] > sum[1]) big = 0;
    cout << sum[big] << endl;

    ll del = 0, itr = 1;
    // del = 削除した要素数
    // itr = 「現在の配列」でa[i]が左から何番目か

    V<ll> step;
    ll i = 1;
    while (i <= N) {
        if (i % 2 == big && pos[i]) {
            // oxox...oxOxo...
            // 残して2つ先へ
            i += 2;
            itr += 2;

        } else {
            if (itr == 1) {
                // Xxx...xo...
                // 頭の要素を1個削除
                step.pb(itr);
                i++;
                del++;

            } else {
                // ...oxXxo...
                // 選択して両隣2つを削除
                step.pb(itr);
                i += 2;
                del += 2;
            }
        }
    }

    // 現時点でoxox...oxoかoxox...oxoxとなっているので
    // 残す要素の間に挟まったxを指定していく
    while (N - del > 1) {
        step.pb(2);
        del += 2;
    }

    cout << SIZE(step) << endl;
    for (ll s : step) {
        cout << s << endl;
    }
    return 0;
}

