    cout.tie(nullptr);

    #define int int64_t
    // code here.
    int n = input<int>();
    vector<int> a(n);
    input_seq(ALL(a));

    vector<int> dp(n);

    for (int i = 0; i != n; ++i) {
        int best_prev = 0;
        for (int j = i - 2; j >= 0; j -= 2)
            best_prev = max(best_prev, dp[j]);

        dp[i] = (a[i] + best_prev);
    }

    int pmx = std::max_element(ALL(dp)) - dp.begin();

    vector<int> seq;
    for (int cur = pmx; cur != -1;) {
        seq.push_back(cur);
        int next = -1;

        for (int j = cur - 2; j >= 0; j -= 2)
            if (dp[cur] == a[cur] + dp[j])
                next = j;

        cur = next;
    }

    std::reverse(ALL(seq));

    vector<int> ans;
    for (int i = n - 1; i > seq.back(); --i)
        ans.pb(i);

    for (int i = SZ(seq) - 2; i >= 0; --i) {
        int a = seq[i], b = seq[i + 1];

        while (b - a != 2) {
            ans.pb(b - 2);
            b -= 2;
        }

        ans.pb(a + 1);
    }

    for (int i = 0; i < seq[0]; ++i)
        ans.pb(0);

    cout << dp[pmx] << "\n";
    cout << SZ(ans) << "\n";
    for (auto elem: ans)
        cout << elem + 1 << "\n";

    return 0;
}

