    ll negAns = 1;
    REP(i, N) {
        cin >> A[i];
        if(A[i] > 0) { isAllNeg = false; }
        else { negAns = (negAns == 1) ? A[i] : max(negAns, A[i]); }
    }

    // 全部負の場合→最小のもの1つをとる
    if(isAllNeg) {
        printf("%lld\n", negAns);
        return 0;
    }

    // 偶数番目の集合の、正の整数だけ足したもの VS 奇数番目の同じもの
    ll odd_num = 0, even_num = 0;
    REP(i, N) {
        if(i % 2 == 0) {
            if(A[i] > 0) { even_num += A[i]; }
        } else {
            if(A[i] > 0) { odd_num += A[i]; }
        }
    }

    REP(i, N) {
        bool ness = false;
        if(odd_num > even_num) {
            if(i % 2 != 0 && A[i] > 0) { ness = true; }
        }
        A2.push_back(make_pair(ness, A[i]));
    }
