        if(A2[0].first) { break; }
        ans_v.push_back(1);
        A2.erase(A2.begin());
    }
    while(1) {
        if(A2[A2.size()-1].first) { break; }
        ans_v.push_back(A2.size());
        A2.erase(A2.begin() + A2.size() - 1);
    }
