    while(A2.size() > 1) {
        ll next;
        for(next = 1; next < A2.size(); ++next) {
            if(A2[next].first) { break; }
        }
        ans_v.push_back(next / 2 + 1);
        if(next == 2) {
            A2.erase(A2.begin() + 1);
            A2.erase(A2.begin() + 2);
        } else {
            A2.erase(A2.begin() + (next / 2) + 1);
            A2.erase(A2.begin() + (next / 2) - 1);
        }
    }

    printf("%lld\n", max(odd_num, even_num));
    printf("%lld\n", ans_v.size());
    for(auto& a : ans_v) {
        printf("%lld\n", a);
    }


    return 0;
}

