    ans.push_back(i - l);
    cnt += 2;
  }
  for(int i = n - 1;i >= r;i--){
    ans.push_back(i - cnt);
  }
  cout << ans.size() << '\n';
  for (size_t i = 0; i < ans.size(); i++)
  {
    cout << ans[i] + 1 << '\n';
  }

}

