void solve() {
	int N; cin >> N;
	vector<int> A(N); cin >> A;
	if (auto a = *max_element(ALL(A)) < 0) {
		int index = max_element(ALL(A)) - A.begin();
		cout << A[index] << endl << N - 1 << endl;;
		for (int i = 0; i < index; ++i) {
			cout << 0 << endl;
		}
		for (int i = index+1; i < N; ++i) {
			cout << 1 << endl;
		}
		return;
	}
	int su1 = 0;
	vector<int> res1, res2;
	for (int i = 0; i < N; i += 2) {
		if (A[i] > 0) {
			su1 += A[i];
			res1.push_back(i);
		}
	}
	int su2 = 0;
	for (int i = 1; i < N; i += 2) {
		if (A[i] > 0) {
			su2 += A[i];
			res2.push_back(i);
		}
	}
	int su;
	vector<int> res;
	if (su1 > su2) {
		su = su1;
		res = res1;
	}
	else {
		su = su2;
		res = res2;
	}
	cout << su << endl;
	reverse(ALL(res));
	vector<int> resres;
	for (int i = N-1; i > res.front(); --i) {
		resres.push_back(i + 1);
	}
	for (int i = 0; i < res.size() - 1; ++i) {
		int cnt = (res[i] - res[i + 1]) / 2;
		int center = (res[i] + res[i + 1]) / 2;
		for (int j = 0; j < cnt; ++j) {
			resres.push_back(center - j + 1);
		}
	}
	for (int i = res.back()-1; i >= 0; --i) {
		resres.push_back(1);
	}
	cout << resres.size() << endl;
	for (auto &a : resres) {
		cout << a << endl;
	}
}

