inline void getans(int cur)
{
	if (del[cur].x==1)
	{
		for (int i=1;i<=cur-1;i++) ans.pb(1);
		cnt=cur-1;
		return;
	}
	getans(del[cur].x-1);
	int len=del[cur].y-del[cur].x+1;
	for (int i=len/2+1;i>=1;i--)
		ans.pb(del[cur].x-cnt+i-1);
