using int64 = long long;

int64 even[1010];
int64 odd[1010];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    for (int i = 0; i < N; i++) {
        int64 a;
        cin >> a;
        if (i % 2 == 0) even[i] += a;
        else odd[i] += a;

        if (i > 0) {
            even[i] += even[i - 1];
            odd[i] += odd[i - 1];
        }
    }

    int64 ans = -(1LL << 60);
    int ansL = 0,
        ansR = 0;
    for (int L = 0; L < N; L++) {
        for (int R = L; R < N; R++) {
            if (L % 2 != R % 2) continue;
            int64 cost = 0;
            if (L % 2 == 0) cost = even[R] - (L > 0 ? even[L - 1] : 0);
            else cost = odd[R] - odd[L - 1];

            if (cost > ans) {
                ans = cost;
                ansL = L;
                ansR = R;
            }
            // cerr << "L: " << L << " R: " << R << " cost: " << cost << endl;
        }
    }
    cout << ans << endl;
    int length = N;
    vector<int> op;
    for (int i = 0; i < ansL; i++) {
        // cout << 1 << endl;
        op.push_back(1);
        length--;
    }

    // cerr << "length: " << length << endl;

    for (int i = 0; i < N - ansR - 1; i++) {
        // cout << length << endl;
        op.push_back(length);
        length--;
    }

    while (length > 1) {
        // cout << 2 << endl;
        op.push_back(2);
        length -= 2;
    }

    assert(length == 1);

    cout << op.size() << endl;
    for (int o : op) {
        cout << o << endl;
    }

    // cerr << "ansL: " << ansL << " ansR: " << ansR << endl;

    return 0;
}

