    bool get[2][1000];
    lint max=-10000000001;
    int mi;
    for(int i=0;i<N;i++){
        cin >> A[i];
        get[0][i]=get[1][i]=false;
        if(A[i]>=0){ sum[i%2]+=A[i]; get[i%2][i]=true; }
        if(A[i]>max){ max=A[i]; mi=i; }
    }
    int g=(sum[0]>sum[1]?0:1);
    if(max<0){
        g=mi%2;
        sum[g]=max;
        get[g][mi]=true;
    }

    int ocnt=0, at=0;
    int cnt=0;
    string r="";

    while(at<N){
        if(get[g][at]){
            ocnt++;
            at++;
        }else{
            if(ocnt==0){
                r=r+"1\n";
                cnt++;
                at++;
            }else{
                int xcnt;
                for(xcnt=0;at+xcnt<N && !get[g][at+xcnt];xcnt++);
                if(at+xcnt==N){
                    for(int i=xcnt;i>=1;i--) r=r+to_string(ocnt+i)+"\n";
                    at=N;
                    cnt+=xcnt;
                }else{
                    for(int i=xcnt/2+1;i>=1;i--) r=r+to_string(ocnt+i)+"\n";
                    at+=xcnt;
                    ocnt--;
                    cnt+=xcnt/2+1;
                }
            }
        }
    }

    cout << sum[g] << endl << cnt << endl << r;
    return 0;
}

