		if (dp[v] > -INFLL) return dp[v];
		ll maxans = 0;
		for (int i = 2; v + i < N; i += 2) {
			ll ret = solve(v + i);
			if (ret > maxans) {
				maxans = ret;
				next[v] = v + i;
			}
