main()
{
	cin>>N;
	for(int i=0;i<N;i++)cin>>A[i];
	for(int i=0;i<N;i++)
	{
		dp[i][0]=max(0L,A[i]);
		ep[i]=max(0L,A[i]);
		for(int j=i-2;j>=0;j-=2)
		{
			dp[i][j]=max(dp[i][j],ep[j]+A[i]);
			if(ep[i]<dp[i][j])
			{
				ep[i]=dp[i][j];
				parent[i]=j;
			}
		}
	}
	int id=0;
	for(int i=1;i<N;i++)
	{
		if(ep[id]<ep[i])id=i;
	}
	cout<<ep[id]<<endl;
	vector<int>x;
	long now=ep[id];
	do
	{
		now-=A[id];
		x.push_back(id);
		id=parent[id];
	}while(now!=0);
	reverse(x.begin(),x.end());
	vector<int>ans;
	for(int i=N-1;i>x[x.size()-1];i--)ans.push_back(i);
	for(int i=(int)x.size()-2;i>=0;i--)
	{
		int t=(x[i+1]-x[i])/2;
		for(;t>0;t--)
		{
			ans.push_back(x[i]+t);
		}
	}
	for(int i=x[0]-1;i>=0;i--)ans.push_back(0);
	cout<<ans.size()<<endl;
	for(int i:ans)cout<<i+1<<endl;
