void solve()
{
	ll N;  cin >> N;
	vector<ll> a = cinv<ll>(N);
	vll ans;
	ll ansnum;

	//全部負の時
	if (MaxE(a) < 0){
		ll pos = MaxI(a);
		ansnum = a[pos];
		dep(i, pos+1, N-1){
			ans.push_back(i);
		}
		REP(i, pos) ans.push_back(0);
	}

	//0以上がある時
	else{
		//奇数と偶数どちらを採用するか決める sum[0]:偶数和、[1]:奇数和
		vll sum(2);
		rep(i, 0, N-1){
			if (a[i]>0){
				sum[i%2] += a[i];
			}
		}
		if (sum[0]<sum[1]){
			ansnum = sum[1];
			ans.push_back(0);
			a.erase(a.begin());
		}
		else{
			ansnum = sum[0];
		}
		ll NN = Size(a);

		//先頭と末尾位置を得る lPos, rPos
		ll lPos=INF, rPos=-1;
		for (ll i=0; i<=NN-1; i+=2){
			if (a[i]>=0){
				chmin(lPos,i);
				chmax(rPos,i);
			}
		}

		//先頭削除と末尾削除操作を追加
		dep(i, rPos+1, NN-1){
			ans.push_back(i);
		}
		REP(i, lPos) ans.push_back(0);

		//先頭と末尾を削除した部分配列を作成
		vll b(a.begin()+lPos, a.begin()+rPos+1);

		//間削除コマンド追加
		vll buf;
		for (ll i=0; i<=Size(b)-1; i+=2){
			if (b[i]<0) buf.push_back(i);
		}
		ans.insert(ans.end(), RALL(buf));

		//奇数削除
		ll ks = (Size(b)/2) - Size(buf);
		REP(i, ks) ans.push_back(1);
	}

	//出力
	cout << ansnum << '\n';
	cout << Size(ans) << '\n';
	EACH(e, ans) e++;
	coutv(ans,'\n');
}


int main(){
	solve();
	return 0;
}

