void solve(ll i){
    if(dp[i] == x[i]){
        sitan(i);
        return;
    }else{
        for(int k=2;i-k>=0;k+=2){
            if(dp[i-k] + x[i] == dp[i]){
                ll point = (i - k / 2);
                for(int j=point;j>i-k;j--){
                    table_push(j);
                }
                solve(i-k);
                return;
            }
        }
    }
}

