int come[N][N];

vector<int> out;

void solve(int l, int r, int cnt)
{
    if (l == r)
    {
        return;
    }
    else
    {
        int k = come[l][r];
        solve(l, k - 1, cnt);
        solve(k + 1, r, cnt + 2);
        out.push_back(cnt + 1);
    }
}

