        rep(j, 0, n)
            dp[i][j] = -big;
    repb(i, n - 1, -1)
        rep(j, i, n)
        {
            if ((j - i + 1) % 2 == 0)
                continue;
            if (i == j)
            {
                dp[i][j] = a[i];
                come[i][j] = i;
            }
            else
            {
                int l = max(i + 1, come[i][j - 2]), r = min(j - 1, (i < n - 1 && j < n - 1 ? come[i + 1][j + 1] : n - 1));
                for (int k = l; k <= r; k += 2)
                {
                    if (dp[i][k - 1] + dp[k + 1][j] > dp[i][j])
                    {
                        dp[i][j] = dp[i][k - 1] + dp[k + 1][j];
                        come[i][j] = k;
                    }
                }
            }
        }
    int l = 0, r = 0;
    rep(i, 0, n)
        rep(j, i, n)
            if (dp[i][j] > dp[l][r])
            {
                l = i; r = j;
            }
    repb(i, n - 1, r)
        out.push_back(i);
    rep(i, 0, l)
        out.push_back(0);
    solve(l, r, 0);
    cout << dp[l][r] << "\n";
    cout << sz(out) << "\n";
    for (int i : out)
        cout << i + 1 << "\n";
    return 0;
}

