  ll bst = -INF;
  PII bst_f;
  for (int i = 1; i <= N; i++)
    for (int j = i; j <= N; j += 2) {
      ll tmp = f(i, j);
      if (tmp > bst) {
        bst = tmp;
        bst_f = MP(i, j);
      }
    }
  //assert(a[bst_f.S] > 0);
  VI op;
  for (int i = N; i > bst_f.S; i--)
    op.PB(i);
  for (int i = bst_f.S - 2; i > bst_f.F; i -= 2) {
    if (a[i] > 0)
      op.PB(i + 1);
    else
      op.PB(i);
  }
  if (bst_f.S != bst_f.F)
    op.PB(bst_f.F + 1);
  for (int i = 1; i < bst_f.F; i++)
    op.PB(1);
  printf("%lld\n", bst);
  printf("%d\n", SZ(op));
  for (int u : op)
    printf("%d\n", u);
  return 0;
}

