int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;

    V<ll> a(N + 1);
    NREP(i, N) {
        cin >> a[i];
    }

    V<bool> pos(N + 1, false);
    bool allneg = true;
    V<ll> sum(2, 0);
    NREP(i, N) {
        if (a[i] >= 0) {
            pos[i] = true;
            allneg = false;
            sum[i % 2] += a[i];
        }
    }

    if (allneg) {
        ll maxid = 1;
        NREP(i, N) {
            if (a[maxid] < a[i]) maxid = i;
        }

        cout << a[maxid] << endl;
        cout << N - 1 << endl;

        REP(_, maxid - 1) {
            cout << 1 << endl;
            N--;
        }

        while (N > 1) {
            cout << N << endl;
            N--;
        }
        return 0;
    }

    ll big = 1;
    if (sum[0] > sum[1]) big = 0;
    cout << sum[big] << endl;

    ll del = 0;
    bool front = true;
    // del = 削除した要素数
    // front = 今いるのが先頭か否か

    V<ll> step;
    ll i = 1;
    while (i <= N) {
        if ((i % 2 == big) && pos[i]) {
            if (front) {
                // Oxox...
                // 残して2つ先へ
                i += 2;
                front = false;

            } else {
                // oxOx...
                // 1つ前のxを指定して削る
                step.pb(2);
                i += 2;
                del += 2;
            }

        } else {
            if (front) {
                // Xxx...
                // 頭の要素を1個削除
                step.pb(1);
                i++;
                del++;

            } else {
                // oxXx...
                // 選択して両隣2つを削除
                step.pb(3);
                i += 2;
                del += 2;
            }
        }
    }

    // 現時点でoxとなっている場合、最後のxを消す
    if (N - del > 1) {
        step.pb(2);
    }

    cout << SIZE(step) << endl;
    for (ll s : step) {
        cout << s << endl;
    }
    return 0;
}

