        for (; a[(n-1)%2][(n-1)/2] < p[k].F; --n)
            go(n);
        for (int i = 0; i < n - 1; ++i)
            go(1);
    } else {
        for (--n; n > k; ) { 
            if (n%2 != k || a[n%2][n/2] < 0) {
                go(n+1);
                --n;
