typedef long long ll;

const int Maxn = 1005;

int n;
ll a[Maxn];
vector <int> res;
int my;

void Apply(int ind)
{
	res.push_back(ind);
	if (ind == 1) {
		for (int i = 1; i <= n - 1; i++)
			a[i] = a[i + 1];
		n--;
		my = 1 - my;
	} else if (ind == n) n--;
	else {
		a[ind - 1] += a[ind + 1];
		for (int i = ind; i <= n - 2; i++)
			a[i] = a[i + 2];
		n -= 2;
	}
}

void Solve()
{
	while (n > 1) {
		bool was = false;
		for (int i = 1; i <= n; i++)
			if (a[i] < 0 && i % 2 == my) { Apply(i); was = true; break; }
		if (was) continue;
		if (my == 0) Apply(1);
		else Apply(2);
	}
}

int main()
{
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		int num; scanf("%d", &num);
		a[i] = num;
	}
	bool spec = true;
	int mx = 1;
	for (int i = 1; i <= n && spec; i++) {
		spec = a[i] < 0;
		if (a[i] > a[mx]) mx = i;
	}
	if (spec) {
		cout << a[mx] << endl;
		for (int i = n; i > mx; i--)
			Apply(i);
		for (int i = 1; i < mx; i++)
			Apply(1);
		printf("%d\n", int(res.size()));
		for (int i = 0; i < res.size(); i++)
			printf("%d\n", res[i]);
		return 0;
	}
	ll res1 = 0;
	for (int i = 1; i <= n; i += 2) if (a[i] >= 0)
		res1 += a[i];
	ll res2 = 0;
	for (int i = 2; i <= n; i += 2) if (a[i] >= 0)
		res2 += a[i];
	if (res1 >= res2) my = 1;
	else my = 0;
	Solve();
	cout << a[1] << endl;
	printf("%d\n", int(res.size()));
	for (int i = 0; i < res.size(); i++)
		printf("%d\n", res[i]);
	return 0;
}

