using namespace std;
template<typename T>inline void read(T &x)
{
    T s=0,f=1;char k=getchar();
    while(!isdigit(k)&&(k^'-'))k=getchar();
    if(!isdigit(k)){f=-1;k=getchar();}
    while(isdigit(k)){s=s*10+(k^48);k=getchar();}
    x=s*f;
}
const int MAXN=2222;
static int n;
static long long a[MAXN];
inline void init()
{
	read(n);
	Rep(i,1,n)read(a[i]);
}
static long long f[MAXN],s[2],pre[MAXN],pr[2];
static int tp,gap[MAXN];
void solve(int pos)
{
	if(pre[pos]==0)
	{
		while(pos>1)pos--,gap[++tp]=1;
		return;
	}
	static int k;k=pos;
	while(k>pre[pos]+2)gap[++tp]=pre[pos]+2,--k;
	gap[++tp]=pre[pos]+1;
	solve(pre[pos]);
}
inline void solve()
{
	Rep(i,1,n)
	{
		f[i]=s[i&1]+a[i];
		pre[i]=pr[i&1];
		if(f[i]>s[i&1])
		{
			s[i&1]=f[i];
			pr[i&1]=i;
		}
	}
	static long long ans=-1ll<<60;
	static int pos;
	Rep(i,1,n)if(ans<f[i])ans=f[i],pos=i;
	printf("%lld\n",ans);
	Repe(i,n,pos+1)gap[++tp]=i;
	solve(pos);
	printf("%d\n",tp);
	Rep(i,1,tp)printf("%d\n",gap[i]);
}
int main()
{
	init();
	solve();
	return 0;
}

