struct edge {
    int to;
    int length;
    edge(int _to, int _length) {
        to = _to;
        length = _length;
    }
};
vector<int> djkstra(vector<vector<edge>> &road, int start) {
    vector<int> kyo(road.size(), inf);
    smallpriority_queue(P) q;
    q.push({0, start});
    kyo[start] = 0;
    while (q.size()) {
        int x = q.top().second;
        itn now = q.top().first;
        q.pop();
        if (kyo[x] < now) {
            continue;
        }
        for (auto &i : road[x]) {
            if (kyo[i.to] > now + i.length) {
                kyo[i.to] = now + i.length;
                q.push({kyo[i.to], i.to});
            }
        }
    }
    return kyo;
}
bool bubunmojiretsu(string& s,string& t){
    int now=0;
    rep(i,(int)s.size()){
        if (s[i]==t[now]) {
            now++;
        }
        if (now==(int)t.size()) {
            return 1;
        }
    }
    return 0;
}

