typedef long long ll;
const ll INF = 1<<30;

int main()
{

    int N;
    cin >> N;
    ll *a = new ll[N + 1];
    for (int i = 1; i <= N; i++){
        cin >> a[i];
    }

    // process exception first
    if (N == 1){
        cout << a[1] << endl;
        cout << 0 << endl;
    }
    assert (N > 1);

    bool *used = new bool[N + 1];
    fill(used, used+N+1, false);

    int rp = -1;
    ll rs = -INF;
    for (int p = 1; p <= 2; p++){
        // find maximum index (mi) first
        int mi = p;
        for (int i = p; i <= N; i += 2){
            if (a[i] > a[mi]){
                mi = i;
            }
        }

        ll sum = 0;
        if (a[mi] <= 0){ // if maximum element is negative, select only maximum element
            sum += a[mi];
            used[mi] = true;
        } else {
            for (int i = p; i <= N; i += 2){
                if (a[i] > 0){
                    sum += a[i];
                    used[i] = true;
                }
            }
        }

        //update if necessary
        if (sum > rs){
            rs = sum;
            rp = p;
        }
    }
    assert (rp != -1);

    vector<int> ret;
    int cnt;
    for (int i = rp + ((N - rp)/2) * 2 ; i > 0; i -= 2){
        if (used[i]){
            cnt++;
        } else {
            ret.push_back(i);
        }
    }

    if (rp != 1 || !used[1]){
        ret.push_back(1);
    }

    if ((N - rp) % 2 == 0 && used[N]){
        cnt--;
    }

    for (int i = 0; i < cnt; i++){
        ret.push_back(2);
    }

    cout << rs << endl;
    cout << ret.size() << endl;
    for (int i : ret){
        cout << i << endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll N;
vector<ll> A;
typedef pair<ll, vector<ll>> Result;

Result solve(ll start) {
  ll value = 0;
  vector<bool> use;
  pair<ll, ll> max = make_pair(-(1ll << 60), -1);
  vector<ll> picks;
  use.resize(N);
  for (ll i = start; i < N; i += 2) {
    if (max.first < A[i]) max = make_pair(A[i], i);
    if (A[i] > 0) {
      value += A[i];
      use[i] = true;
    }
  }
  use[max.second] = true;
  while (!use.front()) {
    picks.push_back(0);
    use.erase(use.begin());
  }
  while (!use.back()) {
    picks.push_back(use.size() - 1);
    use.erase(use.end() - 1);
  }
  assert(use.front() && use.back());
  while (use.size() > 1) {
    assert(use.front() && use.back());
    assert(use.size() % 2 == 1);
    if (use[2]) {
      picks.push_back(1);
      use.erase(use.begin() + 1);
      use.erase(use.begin() + 1);
    } else {
      picks.push_back(2);
      use.erase(use.begin() + 2);
      use.erase(use.begin() + 2);
    }
  }
  return make_pair(value, picks);
}
int main() {
  cin >> N;
  A.resize(N);
  for (ll i = 0; i < N; ++i) cin >> A[i];
  Result res = max(solve(0), solve(1));
  cout << res.first << endl;
  cout << res.second.size() << endl;
  for (ll pick : res.second) cout << pick + 1 << endl;
  return 0;
}

