int n, a[N], dp[N][N];

int back[N][N];
vector <int> s;

void output(int l, int r) {
	if(l == 1 && r == n)
		return;
	assert(l <= r);
	if(back[l][r] == 1) {
		s.pb(1);
		output(l - 1, r);
	}
	else if(back[l][r] == 2) {
		s.pb(2);
		output(l - 2, r);
	}
	else if(back[l][r] == 3) {
		s.pb(r - l + 1);
		output(l, r + 1);
	}
	else
		assert(0);
}

