int main() {
	int n; cin >> n;
	for (int i = 1; i <= n; ++i) {
		cin >> a[i];
	}
	ll best = -inf, best_p = -1;
	for (int i = 1; i <= n; ++i) {
		ll temp = solve(i, n);
		if (temp > best) {
			best = temp;
