long long a[1005];
int even[1005], odd[1005];

void printAnswer(int n,int seq[],int total){
    std::vector<int>step;
    for(int i = seq[n]+1; i <= total; i++) step.push_back(seq[n]+1);
    for(int i = 1; i <= seq[1]-1; i++) step.push_back(1);
    for(int i = 1; i < n; i++){
        int u = seq[i], v = seq[i+1];
        int len = v-u-1;
        for(int j = 0; j < (len-1)/2; j++) step.push_back(3);
        step.push_back(2);
    }
    printf("%d\n",(int)step.size());
    for(int u: step) printf("%d\n",u);
}

int main(){
    int n; 
    scanf("%d",&n);
    for(int i = 1; i <= n; i++) scanf("%lld",&a[i]);
    int maxnE = -1, maxnO = -1;
    int sizeE = 0, sizeO = 0;
    for(int i = 1; i <= n; i++){
        if(i%2){
            if(a[i]>=0) odd[++sizeO] = i;
            else if(maxnO==-1 || a[i]>a[maxnO]) maxnO = i;
        }
        else{
            if(a[i]>=0) even[++sizeE] = i;
            else if(maxnE==-1 || a[i]>a[maxnE]) maxnE = i;
        }
    }
    if(sizeE==0) even[++sizeE] = maxnE;
    if(sizeO==0) odd[++sizeO] = maxnO;
    long long sumE = 0, sumO = 0;
    for(int i = 1; i <= sizeE; i++) sumE += a[even[i]];
    for(int i = 1; i <= sizeO; i++) sumO += a[odd[i]];
    if(sumE>sumO){
        printf("%lld\n",sumE);
        printAnswer(sizeE,even,n);
    }
    else{
        printf("%lld\n",sumO);
        printAnswer(sizeO,odd,n);
    }
    return 0;
}

