typedef long long LL;
const int N=1005;
int n,a[N],f[N],ans=0,x[N];
LL solve(int v){
	LL ans=0;
	for (int i=1;i<=n;i++)
		if ((i&1)==v)
			if (a[i]>0)
				ans+=a[i],f[i]=1;
	if (ans>0)
		return ans;
	ans=-1e9;
	for (int i=1;i<=n;i++)
		if ((i&1)==v)
			ans=max(ans,(LL)a[i]);
	return ans;
}
void solution1(int v){
	int pos=0;
	for (int i=1;i<=n;i++)
		if (a[i]==v){
			pos=i;
			break;
		}
	for (int i=1;i<pos;i++)
		x[++ans]=1;
	for (int i=n;i>pos;i--)
		x[++ans]=i-pos+1;
}
int Next(int x){
	for (x++;!f[x];x++);
	return x;
}
void solution2(int v){
	for (int i=1;i<=n;i++)
		if ((i&1)!=v)
			f[i]=0;
	int L=1,R=n;
	while (!f[L])
		x[++ans]=1,L++;
	while (!f[R])
		x[++ans]=(R--)-L+1;
	for (int i=L,j=Next(i);i<R;i=j,j=Next(i))
		for (int k=(j-i)/2;k>0;k--)
			x[++ans]=k+1;
}
int main(){
	scanf("%d",&n);
	for (int i=1;i<=n;i++)
		scanf("%d",&a[i]);
	LL s0=solve(0),s1=solve(1);
	printf("%lld\n",max(s0,s1));
	if (max(s0,s1)<0)
		solution1(max(s0,s1));
	if (s0>s1)
		solution2(0);
	else
		solution2(1);
	printf("%d\n",ans);
	for (int i=1;i<=ans;i++)
		printf("%d\n",x[i]);
	return 0;
}

