    int n_count = N;
    for(int i = res_i+2; i <= res_j-2; i+= 2){
        for(int j = i; j <= res_j-2; j += 2){
            if(s[i][j] < mi){
                mi = s[i][j];
                remove_i = i;
                remove_j = j;
            }
        }
    }
    if(remove_i != -1 || remove_j != -1){
        for(int i = 0; i < remove_j-remove_i+1; i++){
            p.push_back(remove_i);
            n_count -= 2;
        }
    }

    for(int i = 0; i < res_i; i++){
        p.push_back(1);
        n_count--;
    }
    for(int i = 0; i < N-res_j-1; i++){
        int size_p = (int)p.size();
        p.push_back(N-size_p);
        n_count--;
    }

    for(int i = n_count; i > 1; i-=2){
        p.push_back(2);
    }

    cout << res << endl;
    cout << p.size() << endl;
    for(auto p_e: p){
        cout << p_e << endl;
    }



    return 0;
}

