const int N = 1 << 17;
int n;
int a[N];
LL s[2]; 
bool was[2];
bool bery[N];

vector<int> solve(bool odd)
{
	vector<int> ans;

	for(int i = odd; i < n; i += 2)
		if (a[i] > 0)
			bery[i] = 1;

	int l = 0;
	while(!bery[l]) ans.PB(1), l++;

	while(l < n - 1)
	{
		if (l + 2 < n && bery[l + 2])
		{
			ans.PB(2);
			l += 2;
		}
		else
		{
			ans.PB(3);
			l += 3;
		}
	}

	return ans;
}

