int n;
vector<ll> a;
bool vis[1001][1001];
ll dp[1001][1001];
vector<ll> ans;
int cut[1001][1001];
int at = 0;

ll calc(int l, int r){
  if(vis[l][r])return dp[l][r];
  vis[l][r] = true;
  ll res = - linf;
  if(r - l == 1){
    cut[l][r] = l;
    res = a[l];
  }
  else if(l == 0){
    if(r - l == 2){
      res = a[l+1];
      cut[l][r] = l + 1;
    }
    else{
      res = max(res, a[r - 1]);
      for(int j = l + 1; j < r - 1; j++){
        ll ansl = calc(l, j);
        ll ansr = calc(j + 1, r);
        ll tmp = max(ansr, ansl + ansr);
        if(tmp > res){
          cut[l][r] = j;
          res = tmp;
        }
      }
    }
  }else if(r == n){
    if(r - l == 2){
      res = a[l];
      cut[l][r] = l;
    }
    else{
      res = max(res, a[l]);
      for(int j = l + 1; j < r - 1; j++){
        ll ansl = calc(l, j);
        ll ansr = calc(j + 1, r);
        ll tmp = max(ansl, ansl + ansr);
        if(tmp > res){
          cut[l][r] = j;
          res = tmp;
        }
      }
    }
  }else{
    if(r - l == 2)res = - linf;
    else{
      for(int j = l + 1; j < r - 1; j++){
        ll ansl = calc(l, j);
        ll ansr = calc(j + 1, r);
        ll tmp = ansl + ansr;
        if(tmp > res){
          cut[l][r] = j;
          res = tmp;
        }
      }
    }
  }
  return dp[l][r] = res;
}

void calc2(int l, int r){
  //cout << l << " " << r << endl;
  if(r - l == 1)return;
  if(l == 0){
    if(r - l == 2){
      ans[at++] = l;
      return;
    }
    if(dp[l][r] == a[r-1]){
      for(int j = 0; j < r - 1; j++)ans[at++] = r - 2 - j;
      return;
    }
    int i = cut[l][r];
    if(dp[l][r] == calc(i+1, r)){
      ans[at++] = i;
      ans[at++] = cut[l][i];
    }else{
      ans[at++] = i;
    }
    calc2(l, i);
    calc2(i + 1, r);
  }else if(r == n){
    if(r - l == 2){
      ans[at++] = r - 1;
      return;
    }
    if(dp[l][r] == a[l]){
      for(int j = 1; j + l < r; j++)ans[at++] = j + l;
      return;
    }
    int i = cut[l][r];
    if(dp[l][r] == calc(l, i)){
      ans[at++] = i;
      ans[at++] = cut[i+1][r];
    }else{
      ans[at++] = i;
    }
    calc2(l, i);
    calc2(i+1, r);
  }else{
    int i = cut[l][r];
    ans[at++] = i;
    calc2(l, i);
    calc2(i+1, r);
  }
}

