void prepare() {

  int pre = 0;
  for (int i = 0; i < N; i++) {
    if (A[i] <= 0) {
      pre++;
    } else {
      break;
    }
  }
  int post = 0;
  for (int i = N - 1; i >= 0; i--) {
    if (A[i] <= 0) {
      post++;
    } else {
      break;
    }
  }
  vector<ll> B;
  for (int i = 0; i < pre; i++) {
    procedures.push_back(1);
    // cerr << procedures.back() << endl;
  }

  int rest = A.size() - pre;
  for (int i = 0; i < post; i++) {
    procedures.push_back(rest);
    rest--;
  }
  for (int i = pre; i < N - post; i++) {
    B.push_back(A[i]);
  }
  // debug(B);
  A = move(B);
  // cerr << A.size() << endl;
}
bool special_case(){
  bool is_special = true;
  ll result = -LL_INF;
  for (auto &val : A){
    if (val > 0){
