    }
    result = max(result, val);
  }
  if (not is_special){
    return false;
  }
  int idx = -1;
  for (int i = 0; i < A.size(); i++){
    if (A[i] == result){
      idx = i;
      break;
    }
  }
  cout << result << endl;
  cout << N - 1 << endl;
  for (int i = 0; i < idx; i++){
      cout << 1 << endl;
  }
  int rest = N - idx;
  // cerr << N << " " << idx << endl;
  while (rest > 1){
    cout << rest << endl;
    rest--;
  }
  return true;
}
