  if (special_case()){
    return 0;
  }
  prepare();
  int loop_cnt = 0;
  while (A.size() != 1) {
    loop_cnt++;
    // debug(A);
    if (loop_cnt > 5){
      break;
    }
    // debug(A);
    ll max_val = -LL_INF;
    int idx = -1;

    for (int i = 0; i < A.size(); i++) {
      ll left, right;
      left = right = 0;
      if (i - 1 >= 0) {
        left = A[i - 1];
      }
      if (i + 1 < N) {
        right = A[i + 1];
      }
      ll updated_val = left + right - A[i];
      if (updated_val > max_val) {
        max_val = updated_val;
        idx = i;
      }
    }
    // cerr << "idx = " << idx << " " << max_val << endl;
    assert(idx >= 0);
    vector<ll> B;
    for (int i = 0; i < A.size(); i++) {
      if (i == idx - 1 or i == idx + 1) {
        continue;
      } else if (i == idx) {
        if (i != 0 or i != A.size() - 1){
          B.push_back(max_val + A[i]);
        }
      } else {
        B.push_back(A[i]);
      }
    }
    procedures.push_back(idx + 1);
    A = move(B);
    N = A.size();
  }

  cout << A[0] << endl;
  cout << procedures.size() << endl;
  for (auto &val : procedures) {
    cout << val << endl;
  }
  return 0;
}

