VPLL dec(VPLL v,int i){
	VPLL ret;
	if (i == 0) FOR(j, 1, v.size()) ret.push_back(v[j]);
	else if (i == v.size() - 1) REP(j, v.size() - 1) ret.push_back(v[j]);
	else {
		REP(j,v.size()){
			if (j < i - 1 || i + 1 < j) ret.push_back(v[j]);
			if (j == i) ret.push_back({ v[i - 1].fi + v[i + 1].fi, v[i].se });
		}
	}
	return ret;
}

