            if(!vec[idx]) {
                operate.push_back(idx + 1);
                vec.erase(vec.begin() + idx);
            }
            else idx++;
        }
        else {
            // 両隣がいらないやつ or 両隣がいるやつ なら操作が必要
            bool match = !(vec[idx-1] ^ vec[idx+1]);
            if(match) {
                operate.push_back(idx + 1);
                vec[idx] = 1;
                vec.erase(vec.begin() + idx + 1);
                vec.erase(vec.begin() + idx - 1);
            }
            else idx++;
        }
    }
    // printf("mo = %lld, ans = %lld\n", mo, ans);
    return make_pair(ans, operate);
}

