int main()
{
    int N; cin >> N;
    vector<Int> A(N); for (auto &a : A) cin >> a;
    vector<Int> dp(N);
    for (int i = 0; i < N; i++) {
        if (i-2 >= 0) {
            dp[i] = max({dp[i-2], dp[i-2] + A[i], A[i]});
        } else {
            dp[i] = A[i];
        }
    }
    int k = max_element(begin(dp), end(dp)) - begin(dp);
    vector<bool> used(N);
    for (; k >= 0; k -= 2) {
        if (dp[k] == A[k]) { used[k] = true; break; }
        else if (k >= 2 && dp[k] == A[k] + dp[k-2]) used[k] = true;
        else assert(0);
    }
    int curr = 0;
    vector<int> ans;
    while (used[curr] == 0) curr++, ans.push_back(1);
    while (curr < N) {
        assert(used[curr] == 1);
        int n = 0;
        while (curr+n+1 < N && used[curr+n+1] == 0) n++;
        curr += n + 1;
        while (n >= 3) n -= 2, ans.push_back(3);
        if (n == 2) ans.push_back(3), ans.push_back(2);
        if (n == 1) ans.push_back(2);
    }
    cout << *max_element(begin(dp), end(dp)) << '\n';
    cout << ans.size() << '\n';
    for (auto a : ans) cout << a << '\n';
    return 0;
}

