    ll x[N];
    for(ll i = 0; i < N; i++) cin >> x[i];
    ll oidx = 1, eidx = 0;
    for(ll i = 0; i < N; i++){
        if(i & 1) if(x[oidx] < x[i]) oidx = i;
        if(!(i & 1)) if(x[eidx] < x[i]) eidx = i;
    }
    vector<ll> odd, even;
    ll osum = 0, esum = 0;
    for(ll i = 0; i < N; i++){
        if(i & 1){
            if(i == oidx || x[i] > 0){
                odd.push_back(i);
                osum += x[i];
            }
        }else{
            if(i == eidx || x[i] > 0){
                even.push_back(i);
                esum += x[i];
            }
        }
    }
    cout << max(osum, esum) << endl;
    vector<ll> v = (osum > esum ? odd : even);
    vector<ll> ans;
    ll idx = 0;
    ll rest = N;
    for(ll i = 0; i < N; i++){
        if(idx == 0 && i < v[idx]){
            ans.push_back(1);
            rest--;
        }else{
            if(idx == v.size() - 1){
                for(ll j = rest; j > 1; j--) ans.push_back(j);
