            }else{
                ll between = v[idx + 1] - v[idx];
                while(between > 2){
                    ans.push_back(3);
                    rest -= 2;
                    between -= 2;
                }
                ans.push_back(2);
                rest -= 2;
                idx++;
            }
        }
    }
