        }
        { // big expansion
            auto expand = [&](int p){
                long long sum = 0;
                int lp = p, rp = p;
                if(p + 1 <= br) sum += dp[p + 1][r[p + 1]], rp = r[p + 1];
                if(p - 1 >= bl) sum += dp[l[p - 1]][p - 1], lp = l[p - 1];
                if(dp[lp][rp] < sum){
