#define prev aeoutheoaut

vector<vector<int>> prev;

vector<int> restore(int i, int j)
{
	int cent = prev[i][j];
	if (cent == -1)
		return {};
	vector<int> ans1 = restore(i, cent), ans2 = restore(cent + 1, j);
	ans1.push_back(cent);
	for (auto& x : ans2)
		ans1.push_back(x);
	return ans1;
}

