vector<int> sim(int n,vector<int> Idx){
  vector<int> pos(n); iota(pos.begin(), pos.end(),0);

  auto minus=[&](int I){for(int i = I;i<n;i++) pos[i]--;};

  vector<int> ans;
  int len = n;
  for(int i=0;i<Idx[0];i++) ans.push_back(pos[i]), minus(i), len--;

  for(int i=0;i<(int)Idx.size()-1;i++){
    assert((Idx[i+1] - Idx[i])%2 == 0);
    int num = (Idx[i+1] - Idx[i])/2;
    int idx = (Idx[i+1] + Idx[i])/2;
    for(int i=0;i<num;i++) ans.push_back(pos[idx]), minus(idx), len -= 2;
    for(int i=0;i<num;i++) minus(idx);
  }

  for(int i=Idx.back()+1;i<n;i++) ans.push_back(len - 1), len--;
  return ans;  
}

int calc(vector<int> A,vector<int> ans){
  for(int a:ans){
    int n = A.size();
    if(a == 0) A.erase(A.begin());
    else if(a == n-1) A.erase(A.end()-1);
    else A[a] = A[a-1] + A[a+1], A.erase(A.begin() + a + 1), A.erase(A.begin() + a - 1);
  }
  return A[0];
}

