ll dfs(int r) {
  if (~f[r]) return f[r];
  auto &res = f[r] = a[r];
  pre[r] = 0;
  if (r > 4) res = a[r] + dfs(r - 4), pre[r] = r - 4;
  if (r > 2 && dfs(r - 2) + a[r] > res) res = dfs(r - 2) + a[r], pre[r] = r - 2;
  return res;
}

int main() {
