  for (int i = 1; i <= n; i++) {
    if (dfs(i) > res) res = dfs(i), id = i;
  }
  cout << 123 << endl;
  int num = n, lst = n;
  vector<int> opr;
  while (lst > id) opr.push_back(num), num--, lst--;
  while (id) {
    if (pre[id] == id - 2)
      opr.push_back(num - 1), num -= 2, lst = num;
    else if (pre[id] == id - 4) {
      opr.push_back(num - 2), num -= 2;
