P solve1(int n){
	int res = 0, cnt = 0;
	rep(i,n){
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
		i++;
	}
	return P(res, cnt);
}
P solve2(int n){
	int res = 0, cnt = 0;
	rep(i,n){
		i++;
		if(i == n)break;
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
	}
	return P(res, cnt);
}
P solve3(int n){
	P p = P(-inf,0);
	rep(i,n){
		if(p.fi < a[i])p = P(a[i], i);
	}
	return p;
}

