vector<int> num(int co) {
    vector<int> res;
    for(int j = co - 2; j >= 2; j -= 2) {
        res.push_back(j);
    }
    res.push_back(1);
    return res;
}

void solve() {
	int n; cin >> n;
    vector<int> a(n);
    int ma = -INF;
    rep(i, n) {
        cin >> a[i];
        chmax(ma, a[i]);
    }
    if(ma <= 0) {
        cout << ma << endl;
        cout << n - 1 << endl;
        int j = -1;
        rep(i, n) if(a[i] == ma) j = i;
        for(int i = n - 1; i > j; -- i) cout << i + 1 << endl;
        for(int i = 0; i < j; ++ i) cout << 1 << endl;
        return;
    }
    static int dp[1010];
    vector<int> prev(n + 1, -1);
    rep(i, 1010) {
        dp[i] = 0;
    }
    rep(i, n) {
        dp[i + 1] = a[i];
        for(int j = i - 1; j >= 0; j -= 2) {
            if(chmax(dp[i + 1], dp[j] + a[i])) {
                prev[i + 1] = j;
            }
        }
    }
    int res = 0, k = -1;
    for(int i = 1; i <= n; ++ i) {
        if(chmax(res, dp[i])) {
            k = i;
        }
    }
    cout << res << endl;
    static bool pos[1010];
    vector<int> b;
    rep(i, 1010) pos[i] = 0;
    int cur = k;
    b.push_back(cur - 1);
    pos[cur] = 1;
    while(prev[cur] != -1) {
        cur = prev[cur];
        pos[cur] = 1;
        b.push_back(cur - 1);
    }
    reverse(all(b));
    vector<int> op;
    int sz = (int)b.size();
    // rep(i, sz) cerr << b[i] << " ";
    // cerr << endl;
    for(int j = n - 1; j > b[sz - 1]; -- j) {
        op.push_back(j);
    }
    for(int i = sz - 1; i >= 1; -- i) {
        int co = b[i] - b[i - 1];
        for(int x: num(co)) {
            op.push_back(b[i - 1] + x);
        }
    }
    for(int i = 0; i < b[0]; ++ i) {
        op.push_back(0);
    }
    cout << (int)op.size() << endl;
    rep(i, (int)op.size()) {
        cout << op[i] + 1 << endl;
    }
}

