vector<ll> A;

ll naiveDp[1024][1024][4];
bool naiveF[1024][1024][4];

int BOTH = 0;
int LEFT = 1;
int RIGHT = 2;
int NONE = 3;

ll naive(int l, int r, int flg) {
    if (l + 1 == r) return A[l];
    if (naiveF[l][r][flg]) return naiveDp[l][r][flg];

    ll ans = (ll) -1e18;
    if (!(flg & RIGHT)) ans = max(ans, naive(l + 1, r, flg));
    if (!(flg & LEFT)) ans = max(ans, naive(l, r - 1, flg));

    for (int i = l + 1; i + 1 < r; i++) {
        ans = max(ans, naive(l, i, flg | LEFT) + naive(i + 1, r, flg | RIGHT));
    }
    naiveF[l][r][flg] = true;
    return naiveDp[l][r][flg] = ans;

    assert(0);
}


ll dp[1024][1024][4];
int best[1024][1024][4];

bool f[1024][1024][4];

ll dfs(int l, int r, int flg) {
    if (l + 1 == r) {
        best[l][r][flg] = l;
        return A[l];
    }
    if (f[l][r][flg]) return dp[l][r][flg];

    ll ans = (ll) -1e18;
    int ptr = -1;
    if (!(flg & RIGHT)) {
        if (ans < dfs(l + 1, r, flg)) {
            ans = dfs(l + 1, r, flg);
            ptr = best[l + 1][r][flg];
        }
    }

    if (!(flg & LEFT)) {
        if (ans < dfs(l, r - 1, flg)) {
            ans = dfs(l, r - 1, flg);
            ptr = best[l][r - 1][flg];
        }
    }

    if (l + 2 < r) { // length >= 3
        dfs(l, r - 1, flg);
        dfs(l + 1, r, flg);

        int le = max(l + 1, best[l][r - 1][flg] - 1);
        int ri = min(best[l + 1][r][flg] + 1, r - 2);
        for (int i = le; i <= ri; i++) {
            ll cost = dfs(l, i, flg | LEFT) + dfs(i + 1, r, flg | RIGHT);
            if (ans < cost) {
                ans = cost;
                ptr = i;
            }
        }
    }


    f[l][r][flg] = true;
    best[l][r][flg] = ptr;
    return dp[l][r][flg] = ans;
}

vector<int> ops;

void recover(int l, int r, int flg) {
    if (l + 1 == r) {
        return;
    }

    ll ans = dfs(l, r, flg);
    if (!(flg & RIGHT)) {
        if (ans == dfs(l + 1, r, flg)) {
            ops.push_back(l);
            recover(l + 1, r, flg);
            return;
        }
    }

    if (!(flg & LEFT)) {
        if (ans == dfs(l, r - 1, flg)) {
            ops.push_back(r);
            recover(l, r - 1, flg);
            return;
        }
    }

    if (l + 2 < r) { // length >= 3
        dfs(l, r - 1, flg);
        dfs(l + 1, r, flg);

        int le = max(l + 1, best[l][r - 1][flg] - 1);
        int ri = min(best[l + 1][r][flg] + 1, r - 2);
        for (int i = le; i <= ri; i++) {
            ll cost = dfs(l, i, flg | LEFT) + dfs(i + 1, r, flg | RIGHT);
            if (ans == cost) {
                recover(l, i, flg | LEFT);
                recover(i + 1, r, flg | RIGHT);
                ops.push_back(i);
                return;
            }
        }
    }
}


