	long long n, i, j, k, ans, ans1, ans2, nn;
	cin >> n;
	vector<long long> a(n), aa;
	vector<pair<long long, long long>> even, odd;

	for (i = 0; i < n; i++) {
		cin >> a[i];
		if (i % 2 == 0) even.push_back({ a[i], i });
		else odd.push_back({ a[i], i });
	}

	sort(even.begin(), even.end());
	sort(odd.begin(), odd.end());

	if (even[even.size() - 1].first < 0) ans1 = even[even.size() - 1].first;
	else {
		ans1 = 0;
		for (auto p : even) {
			if (p.first >= 0) ans1 += p.first;
		}
	}
	if (odd[odd.size() - 1].first < 0) ans2 = odd[odd.size() - 1].first;
	else {
		ans2 = 0;
		for (auto p : odd) {
			if (p.first >= 0) ans2 += p.first;
		}
	}

	vector<bool> keep(n, false), keep2;
	if (ans1 > ans2) {
		// use ans1
		if (even[even.size() - 1].first < 0) keep[even[even.size() - 1].second] = true; 
		else {
			for (auto p : even) {
				if (p.first >= 0) keep[p.second] = true; 
			}
		}
	}
	else {
		// use ans1
		if (odd[odd.size() - 1].first < 0) keep[odd[odd.size() - 1].second] = true;
		else {
			for (auto p : odd) {
				if (p.first >= 0) keep[p.second] = true;
			}
		}
	}

	ans = max(ans1, ans2);
	vector<long long> plist;

	while (a.size() > 1) {
		n = a.size();
		aa.clear();
		keep2.clear();

		if (!keep[0]) {
			plist.push_back(1);
			for (i = 1; i < n; i++) {
				aa.push_back(a[i]);
				keep2.push_back(keep[i]);
			}
		}
		else if (!keep[n - 1]) {
			plist.push_back(n);
			for (i = 0; i < n - 1; i++) {
				aa.push_back(a[i]);
				keep2.push_back(keep[i]);
			}
		}
		else for (i = 1; i < n - 1; i++) {
			if (keep[i - 1] == keep[i + 1]) {
				plist.push_back(i + 1);
				for (j = 0; j < i - 1; j++) {
					aa.push_back(a[j]);
					keep2.push_back(keep[j]);
				}
				aa.push_back(a[i - 1] + a[i + 1]);
				keep2.push_back(keep[i - 1]);
				for (j = i + 2; j < n; j++) {
					aa.push_back(a[j]);
					keep2.push_back(keep[j]);
				}
				break;
			}
		}

		swap(a, aa);
		swap(keep, keep2);
	}


	cout << ans << "\n";
	cout << plist.size() << "\n";
	for (auto p : plist) cout << p << "\n";

	return 0;
}

