inline void out(pair<int,int> sou){
	if(sou.first == sou.second)return;
	out({sou.first, ct[sou.first][sou.second]-1});
	out({ct[sou.first][sou.second]+1, sou.second}); 
	step.push_back(ct[sou.first][sou.second] - tree.query(ct[sou.first][sou.second]));
	tree.add(ct[sou.first][sou.second]);
