using namespace std;

int a[1000];

int main() {
    int n, x, m = -1e9 - 1, i;
    long long sum1 = 0, sum2 = 0, ans;
    vector <int> v;

    scanf("%d", &n);

    for (i = 0; i < n; i++) scanf("%d", &a[i]);

    for (i = 0; i < n; i++) {
        if (a[i] <= 0) {
            if (a[i] > m) {
                m = a[i];
                x = i + 1;
            }

            continue;
        }

        if (i % 2 == 0) {
            sum1 += a[i];
        } else {
            sum2 += a[i];
        }
    }

    if (sum1 == 0 && sum2 == 0) {
        ans = m;
        while (n > x) v.push_back(n--);
        for (i = 1; i < x; i++) v.push_back(1);
    } else {
        int c = 0, l = 0, r = n;

        ans = max(sum1, sum2);

        if (sum2 > sum1) {
            v.push_back(1);
            l++;
            n--;
        }

        if ((r - l) % 2 == 0) {
            v.push_back(n--);
            r--;
        }

        while (a[l] <= 0) {
            v.push_back(1);
            v.push_back(1);
            l += 2;
            n -= 2;
        }

        while (a[r - 1] <= 0) {
            v.push_back(n--);
            v.push_back(n--);
            r -= 2;
        }

        for (i = l; i < r; i += 2) {
            if (a[i] > 0) {
                c++;
            } else {
                v.push_back(c * 2 + 1);
            }
        }

        for (i = 1; i < c; i++) v.push_back(2);
    }

    printf("%lld\n", ans);
    printf("%d\n", (int)v.size());
    for (i = 0; i < v.size(); i++) printf("%d\n", v[i]);

    return 0;
}

