//dfs
long long dp[1111][1111];
int root[1111][1111];
int ans[1111],dfs_time=0;
long long num[1111];
long long dfs(int l,int r){
	long long lsl,lsr;
	if(r<l) return 0;
	if(dp[l][r]) return dp[l][r];
	if(r==l){
		root[l][r]=l;
		return dp[l][r]=num[l];
	}
	for(int i=l;i<=r;i++) {
		lsl=dfs(l,i-1);
		lsr=dfs(i+1,r);
		if(lsl+lsr>dp[l][r])
			dp[l][r]=lsl+lsr,root[l][r]=i;
	} 
	return dp[l][r];
}
void rdfs(int l,int r){
	if(r<l) return ;
	if(r==l){
		//ans[++dfs_time]=que(l);
		//add(l,-1);
		return ;
	}
	if(root[l][r]==l){
		ans[++dfs_time]=que(l);
		add(l,-1);
		rdfs(root[l][r]+1,r);
		return ;
	}
	if(root[l][r]==r){
		ans[++dfs_time]=que(r);
		add(r,-1);
		rdfs(l,root[l][r]-1);
		return ;
	}
	rdfs(l,root[l][r]-1);
	rdfs(root[l][r]+1,r);
	ans[++dfs_time]=que(root[l][r]);
	return ;
}

