long long solve(const vector<int>& a, vector<int>& ope)
{
    int n = a.size();
    ope.clear();

    auto it = max_element(a.begin(), a.end());
    if(*it < 0){
        int j = it - a.begin();
        for(int i=n-1; i>j; --i)
            ope.push_back(i);
        for(int i=0; i<j; ++i)
            ope.push_back(0);
        return *it;
    }

    vector<long long> sum(2, 0);
    for(int i=0; i<n; ++i)
        sum[i%2] += max(0, a[i]);

    int rest = n;
    int k = max_element(sum.begin(), sum.end()) - sum.begin();
    for(int i=n-1; i>=0; --i){
        if(i % 2 == k && a[i] < 0){
            ope.push_back(i);
            if(i == 0 || i == n - 1)
                -- rest;
            else
                rest -= 2;
        }
    }
    if(k == 1){
        ope.push_back(0);
        -- rest;
    }
    while(rest > 1){
        ope.push_back(1);
        rest -= 2;
    }

    return sum[k];
}

int main()
{
    int n;
    cin >> n;
    vector<int> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    vector<int> ope;
    cout << solve(a, ope) << endl;
    cout << ope.size() << endl;
    for(int x : ope)
        cout << (x + 1) << endl;

    return 0;
}

