        rep(i, N) output(1);
        return 0;
    }

    for(int i = N - 1; i > left; i--){
        if(i > right){
            ret.pb(i + 1);
        }
        else {
            if(C[i - 1] && i >= 1){
                ret.pb(i + 1);
            }
            else if(C[i - 1] == 0 && C[i] == 0 && C[i + 1] == 0 && i >= 1 && i < N - 1){
                ret.pb(i + 1);
            }
        }
    }
    rep(i, left){
        ret.pb(1);
    }
    output(sum);
    output(ret.size());
    for(auto i: ret){
        output(i);
    }


    return 0;
}

