	for(int i=0;i<n;i++) {
		if(a[i]<=0) continue;
		if(i&1) {
			s1+=a[i];
		}
		else s0+=a[i];
	}
	LL ans;
	if(s0==0 && s1==0) {
		ans=-INF;int p=-1;
		for(int i=0;i<n;i++) {
			if(a[i]>ans) {
				ans=a[i];p=i;
			}
		}
		vc.push_back(p+1);
	}
	else if(s0<s1) {
		ans=s1;
		for(int i=1;i<n;i+=2) {
			if(a[i]>0) {
				vc.push_back(i+1);
			}
		}
	}
	else {
		ans=s0;
		for(int i=0;i<n;i+=2) {
			if(a[i]>0) {
				vc.push_back(i+1);
			}
		}
	}
	printf("%lld\n",ans);
	int m=vc.size();
	int cnt=vc[0]-1+n-vc[m-1];
	cnt=cnt+(n-cnt)/2;
	printf("%d\n",cnt);
	int t=0;
	for(int i=1;i<vc[0];i++) {
		printf("1\n");
		t++;
	}
	for(int i=0;i<m-1;i++) {
		int c=vc[i+1]-vc[i]-1;
		for(int j=(c+1)/2;j>0;j--) {
			printf("%d\n",vc[i]-t+j);
		}
		t+=c+1;
	}
	for(int i=n;i>vc[m-1];i--) {
		printf("%d\n",i-t);
	}
}

