    F(i, 1, d[0]) ans.push_back(1);
    dF(i, n, d[tot-1]) ans.push_back(d[tot-1]-d[0]+2  );
    F2(i, 1, tot-1) {
        int st=d[i-1], ed=d[i];
        for (int j=st+1; j<ed; j+=2) ans.push_back(i+j-st);
    }
}
