void restore(int extra, int i, int j) {
    if (i == j) {
        return;
    }
    long long t[2] = {-1000000000000000000LL, -1000000000000000000LL};
    int pos[2];
   // cout << i << ' ' << j << endl;
    for (int k = j; k >= i; --k) {
        if (k <= j - 2) {
            if (dp[i][j] == dp[i][k] + t[k & 1]) {
               // cout << "opa" << endl;
                restore(extra, i, k);
                int t = pos[k & 1] - k - 1;
