                    g.push_back(3 + extra);
                }
                restore(extra + 2, pos[k & 1], j);
                g.push_back(2 + extra);
                return;
            }
        }
        if (t[k & 1] < dp[k][j]) {
            pos[k & 1] = k;
            t[k & 1] = dp[k][j];
        }
    }
}



