typedef long long ll;

template <typename S, typename T> ostream &operator<<(ostream &out, const pair<S, T> &p) {
  out << "(" << p.first << ", " << p.second << ")";
  return out;
}

template <typename T> ostream &operator<<(ostream &out, const vector<T> &v) {
  out << "[";
  REP(i, v.size()){
    if (i > 0) out << ", ";
    out << v[i];
  }
  out << "]";
  return out;
}

int main(int argc, char *argv[]) {
  int N;
  cin >> N;
  vector<ll> A(N);
  vector<ll> DP(N), PREV(N);
  REP(i, N) cin >> A[i];


  REP(i, N) {
    DP[i] = A[i];
    PREV[i] = -1;

    for (int j = i - 2; j >= 0; j -= 2) {
      if (A[i] + DP[j] > DP[i]) {
        DP[i] = A[i] + DP[j];
        PREV[i] = j;
      }
    }
  }

  int best_i = 0;
  REP(i, N) {
    if (DP[i] > DP[best_i]) {
      best_i = i;
    }
  }

  vector<int> operations;
  for (int i = N - 1; i > best_i; i--) {
    operations.push_back(i);
  }

  int curr_i = best_i;
  while (PREV[curr_i] >= 0) {
    int prev_i = PREV[curr_i];
    int mid_i = (curr_i + prev_i) / 2;
    int length = curr_i - prev_i;
    int operation_count = (length + 1) / 2;
    REP(i, operation_count) {
      operations.push_back(mid_i - i);
    }
    curr_i = prev_i;
  }
  REP(i, curr_i) {
    operations.push_back(0);
  }
  cout << DP[best_i] << endl;
  cout << operations.size() << endl;
  for (const int i: operations) {
    cout << i + 1 << endl;
  }
}

