#define int long long

int N;
vector<int> dp;
vector<int> a;
vector<int> nxt;
int now = N;

int dfs(int n) {
  if ( n >= N ) {
    return 0;
  }
  if ( dp[n] >= 0 ) return dp[n];

  int ret1 = 0;
  int ret2 = 0;
  ret1 = a[n]+dfs(n+2);    
  ret2 = dfs(n+1);

  int ret = max(ret1, ret2);
  if ( ret1 > ret2 ) {
    nxt[n] = n+2;
  }

  return dp[n]=ret;
}

signed main() {
  cin >> N;
  a.resize(N+10);
  dp.resize(N+10, -1);
  nxt.resize(N+10, -1);  

  for ( int i = 0; i < N; i++ ) cin >> a[i];

  cout << dfs(0) << endl;
  int s;
  for ( int i = 0; i < N; i++ ) {
    if ( nxt[i] == -1 ) continue;
    s = i; break;    
  }

  bool used[N] = {0};
  int cnt = 0;
  used[s] = true;
