int N;
ll A[1100];

ll f(int l, int r, std::vector<int> &instr){
    if(l == -1){
        int mx_i = std::max_element(A + 1, A + 1 + N) - A;

        for(int i=N;i>mx_i;--i){
            instr.emplace_back(i);
        }

        for(int i=0;i<mx_i-1;++i){
            instr.emplace_back(1);
        }

        return 0;
    }

    for(int i=N;i>r;--i){
        instr.emplace_back(i);
    }

    ll v = A[r];

    r -= 2;

    while(l <= r){
        if(A[r] >= 0){
            v += A[r];
            instr.emplace_back(r + 1);
        }else{
            instr.emplace_back(r - 1);
        }

        r -= 2;
    }

    for(int i=0;i<l-1;++i){
        instr.emplace_back(1);
    }

    return v;
}

