	ll goodl, goodr;
	for (ll l = 1;l <= N;l++)
		for (ll r = l + 1;r <= N + 1;r++) {
			ll temp = solve(l, r);
			if (ans < temp) {
				ans = temp;
				goodl = l;
				goodr = r;
			}
		}
	cout << ans << endl;
	solve2(goodl, goodr);
	for (int i = goodl - 1;i >= 1;i--)
		ans2.push_back(i);
	for (int i = goodr;i <= N;i++)
		ans2.push_back(i);
