        s2=ara[st]+dp[st+1][(parity+1)%2][true];
        s3=dp[st+1][parity][f];
        mx=max(s1,max(s2,s3));
        if(s1==mx){vec.pub(st);return;}
        else if(s2==mx){
            vec.pub(st);
            bktrk(st+1,(parity+1)%2,true);
        }
        else if(s3==mx){
            bktrk(st+1,parity,f);
        }
    }
    else{
        if(parity%2==1){
            bktrk(st+1,(parity+1)%2,f);
        }
        else{
            s1=ara[st];
            s2=ara[st]+dp[st+1][(parity+1)%2][f];
            s3=dp[st+1][(parity+1)%2][f];
            mx=max(s1,max(s2,s3));
            if(s1==mx){
                vec.pub(st);return;
            }
            else if(s2==mx){
                vec.pub(st);
                bktrk(st+1,(parity+1)%2,f);
            }
            else if(s3==mx){
                bktrk(st+1,(parity+1)%2,f);
            }
        }
    }
}
