#define FOR(i,a,b) for (int i = (a); i < (b); i++)
#define RFOR(i,b,a) for (int i = (b) - 1; i >= (a); i--)
#define ITER(it,a) for (__typeof(a.begin()) it = a.begin(); it != a.end(); it++)
#define FILL(a,value) memset(a, value, sizeof(a))

#define SZ(a) (int)a.size()
#define ALL(a) a.begin(), a.end()
#define PB push_back
#define MP make_pair

typedef long long LL;
typedef vector<int> VI;
typedef pair<int, int> PII;

const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL) INF;

pair<LL, VI> solve(VI A)
{
	VI res;
	LL sum = 0;
	int cnt = 0;

	bool left = false;

	for (int i = SZ(A) - 1; i >= 0; i -= 2)
	{
		if (A[i] >= 0)
		{
			sum += A[i];
			cnt++;
			left = true;
		}
		else
		{
			res.PB(i+1);
			if (!left) res.PB(i);
			else if (i == 0) res.PB(1);
		}
	}

	if (cnt == 0) return MP(-LINF, VI());

	if (SZ(A) % 2 == 0) res.PB(1);

	FOR (it, 0, cnt - 1) res.PB(2);

	return MP(sum, res);
}

int main(int argc, char* argv[])
{
	//ios::sync_with_stdio(false); cin.tie(0);

	int n;
	scanf("%d", &n);
	VI A(n);
	PII mx = MP(-INF, -INF);
	FOR (i, 0, n)
	{
		scanf("%d", &A[i]);
		mx = max(mx, MP(A[i], i));
	}
	int add = 0;

	if (mx.first < 0)
	{
		add = mx.first;
		A[mx.second] = 0;
	}

	pair<LL, VI> a = solve(A);
	A.pop_back();
	pair<LL, VI> b = solve(A);
	reverse(ALL(b.second));
	b.second.PB(n);
	reverse(ALL(b.second));

	if (a.first < b.first) swap(a, b);

	cout<<a.first + add<<endl;
	cout<<SZ(a.second)<<endl;
	FOR (i, 0, SZ(a.second))
	{
		cout<<a.second[i]<<endl;
	}

}

