    vector<vector<LL>> memo(5, vector<LL>(n+1, -10000000000000LL));
    memo[0][0] = 0;
    vector<vector<LL>> ref(5, vector<LL>(n+1));

    for(int i = 0; i < n; ++i){
        // erase head
        memo[0][i+1] = 0;
        ref [0][i+1] = 0;

        // not erase a[i]
        memo[1][i+1] = memo[0][i] + a[i];
        ref [1][i+1] = 0;
        if(memo[1][i+1] < memo[2][i] + a[i]){
            memo[1][i+1] = memo[2][i] + a[i];
            ref [1][i+1] = 2;
        }

        // erase seq odd
        memo[2][i+1] = memo[1][i];
        ref [2][i+1] = 1;
        if(memo[2][i+1] < memo[3][i]){
            memo[2][i+1] = memo[3][i];
            ref [2][i+1] = 3;
        }

        // erase seq even
        memo[3][i+1] = memo[2][i];
        ref [3][i+1] = 2;

        // erase tail
        memo[4][i+1] = memo[1][i];
        ref [4][i+1] = 1;
        if(memo[4][i+1] < memo[4][i]){
            memo[4][i+1] = memo[4][i];
            ref [4][i+1] = 4;
        }
