		for(int i=1;i<=n;++i) if(!Max||A[i]>A[Max]) Max=i;
		printf("%d\n%d\n",A[Max],n);
		for(int i=n;i>Max;--i) printf("%d\n",i);
		for(int i=1;i<Max;++i) printf("1\n");
		return 0;
