queue<int>s;
void solve(int n)
{
    if(n==1) return;
    if(!vis[1])
    {
        s.push(1);
        for(int i=1;i<n;i++)
            vis[i]=vis[i+1];
        solve(n-1);
        return;
    }
    if(!vis[n])
    {
        s.push(n);
        solve(n-1);
        return;
    }
    for(int i=2;i<n;i++)
        if(!vis[i]&&!vis[i-1]&&!vis[i+1])
    {
        s.push(i);
        for(int j=i;j<=n-2;j++)
            vis[j]=vis[j+2];
        solve(n-2);
        return;
    }
    for(int i=2;i<n;i++)
        if(!vis[i])
    {
        s.push(i);
        for(int j=i;j<=n-2;j++)
            vis[j]=vis[j+2];
        solve(n-2);
        return;
    }
}
int main()
{
    scanf("%d",&n);
    ll ans=-1e9;
    for(int i=1;i<=n;i++) scanf("%d",&a[i]),ans=max(ans,(ll)a[i]);
