        printf("%lld\n",ans);
        printf("%d\n",n-1);
        int x=1;
        for(int i=1;i<=n;i++)
            if(x==1)
        {
            if(a[i]!=ans) printf("%d\n",x);
            else x=n-i+1;
        }
        else printf("%d\n",x--);
        return 0;
    }
    ans=0;
    ll res=0;
    for(int i=1;i<=n;i++)
        if(i&1) ans=max(ans,ans+a[i]);
    else res=max(res,res+a[i]);
    if(ans>res)
    {
        printf("%lld\n",ans);
        for(int i=1;i<=n;i++)
            if((i&1)&&a[i]>=0)
                vis[i]=true;
        solve(n);
    }
    else
    {
        printf("%lld\n",res);
        for(int i=1;i<=n;i++)
            if(!(i&1)&&a[i]>=0)
                vis[i]=true;
        solve(n);
    }
    printf("%d\n",s.size());
