/*
1 つ飛ばししかありえません。
偶奇に分けて最大区間を探します。累積和です。
最小値の位置を保持しながら、最大値を更新です。
差が最大になる添字のペア l, r が見つかったら、[l,r[ * 2 + parity です。
*/

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n; std::cin >> n;
  std::vector<lint> a(n); std::cin>> a;
  debug(a);

  auto find = [&] (auto&& a) {
    int n = a.size();
    std::partial_sum(all(a),a.begin());
    a.insert(a.begin(),0);

    lint l = 0, r = 0, dif = -1;
    lint i = 0, x = a.at(i);
    rep(j,0,n+1) {
      int y = a.at(j);
      if (cmx(dif, y - x)) {
        l = i, r = j;
      }
      if (cmn(x,y)) {
        i = j;
      }
    }
    r--;
    return std::make_tuple(l,r,dif);
  };

  std::vector<std::vector<int>> b(2);
  rep(i,0,n) {
    b.at(i%2).emplace_back(a.at(i));
  }
  lint l0,r0,dif0,l1,r1,dif1;
  std::tie(l0,r0,dif0) = find(b.at(0));
  std::tie(l1,r1,dif1) = find(b.at(1));
  l0 = l0 * 2;
  r0 = r0 * 2;
  l1 = l1 * 2 + 1;
  r1 = r1 * 2 + 1;
  debug(l0,r0,dif0);
  debug(l1,r1,dif1);

  int par = dif0 < dif1;
  lint score = par ? dif1 : dif0;
  lint l = par ? l1 : l0;
  lint r = par ? r1 : r0;
  std::vector<int> use(n,false);
  assert(l <= r && (r - l) % 2 == 0);
