  }
  std::vector<int> ans;
  for (int i = n - 1; i >= 0; i--) {
    if (!use.at(i)) {
      ans.emplace_back(i);
    }
  }
  for (int & x : ans) x++;

  std::cout << score << std::endl;
  std::cout << ans.size() << std::endl;
  for (int x : ans) {
    std::cout << x << std::endl;
  }
  return 0;
}

