using namespace std;
using ll = long long;
template <class T> using vec = vector<T>;
template <class T> using vvec = vector<vec<T>>;

bool chmax(ll& a,ll b){
    if(a<b){
        a = b;
        return true;
    }
    return false;
}

void check(ll res,vec<ll> A,vec<int> op){
    for(auto& x:op){
        assert(0<=x && x<A.size());
        if(x==0) A.erase(A.begin());
        else if(x==(int) A.size()-1) A.pop_back();
        else{
            A[x] = A[x-1]+A[x+1];
            A.erase(A.begin()+x+1);
            A.erase(A.begin()+x-1);
        }
    }
    assert(A.size()==1);
    assert(res==A[0]);
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N;
