    for(int i=0;i<N;i++){
        cin >> A[i];
        S[i%2][i/2+1] = S[i%2][i/2]+A[i];
    }
    ll ans = -1e18;
    int ansl = -1,ansr = -1;
    for(int k=0;k<2;k++){
        for(int l=0;2*l+k<N;l++) for(int r=l+1;2*r+k<=N+1;r++){
            if(chmax(ans,S[k][r]-S[k][l])){
                ansl = 2*l+k,ansr = 2*r+k-1;
            }
        }
    }


    vec<int> op;
    for(int i=N-1;i>=ansr;i--) op.push_back(i);
    for(int i=ansr-2;i>=ansl+1;i-=2) op.push_back(i);
    for(int i=0;i<ansl;i++) op.push_back(0);

