    for (int i = 0; i < N; i++){
        cin >> a[i];
    }

    Container ret = {-1, -1, -INF};
    for (int p = 0; p < 2; p++){
        int size = (p == 0) ? (N+1)/2 : N/2;

        Container *dp = new Container[size];
        dp[0] = {p, 1, a[p]};
        for (int i = 1; i < size; i++){
            int idx = p + 2 * i;
            if (dp[i-1].sum > 0){
                dp[i] = {idx, dp[i-1].length+1, dp[i-1].sum+a[idx]};
            } else {
                dp[i] = {idx, 1, a[idx]};
            }
        }

        for (int i = 0; i < size; i++){
            if (dp[i].sum > ret.sum){
                ret = dp[i];
            }
        }
    }
    assert (ret.sum != -INF);

    int back = N - 1 - ret.idx; //idx is 0 origin
    int middle = 2 * ret.length - 1;
    int front = N - middle - back;
