#include<bits/stdc++.h>
using namespace std;

pair<int, vector<long long> > op(vector<long long> V)
{
  bool allneg = true;
  for(auto x: V) if(x > 0) allneg = false;
  if(allneg)
  {
    if(max_element(V.begin(), V.end()) == V.begin())
    {
      V.pop_back();
      return make_pair((int)V.size(), V);
    }
    else
    {
      vector<long long> nv(V.begin()+1, V.end());
      return make_pair(0, nv);
    }
  }

  long long oddsum = 0;
  long long evensum = 0;
  for(int i=0; i<(int)V.size(); ++i)
  {
    if(i%2==0) evensum += max(0LL, V[i]);
    else oddsum += max(0LL, V[i]);
  }
  if(oddsum >= evensum || V[0] <= 0)
  {
    vector<long long> nv(V.begin()+1, V.end());
    return make_pair(0, nv);
  }
  if(V.size()%2 == 0 || V.back() <= 0)
  {
    V.pop_back();
    return make_pair((int)V.size(), V);
  }

  //V[0] > 0, V.back() > 0, size >= 3
  if(V[2] < 0)
  {
    // 0 1 2 3 4 5
    //     0 p 4 5
    // size >= 5;
    vector<long long> nv(V.begin()+2, V.end());
    nv[0] = V[0]; nv[1] = V[1]+V[3];
    return make_pair(2, nv);
  }
  else 
  {
    // 0 1 2 3 4 5
    //     p 3 4 5 
    vector<long long>nv(V.begin()+2, V.end());
    nv[0] = V[0]+V[2];
    return make_pair(1, nv);
  }
}
