{
  int N; scanf("%d", &N);
  vector<long long> V; for(int i=0; i<N; ++i){ int t; scanf("%d", &t); V.push_back(t); }
  vector<int> ans;
  while(V.size() != 1)
  {
    int x; tie(x, V) = op(V);
    ans.push_back(x);
  }
  printf("%lld\n", V[0]);
  printf("%d\n", (int)ans.size());
  for(auto x: ans) printf("%d\n", x+1);
  return 0;
}

