    for(int i=0;i<n;i++){
        if(a[i]>=0){
            if(i&1)sum1+=a[i];
            else sum2+=a[i];
        }else {
            if(i&1)a1.P(i);
            else a2.P(i);
            cnt++;
        }
    }
    vi ans;
    if(cnt==n){
        sum1=INT_MIN;
        for(int i=0;i<n;i++){
            sum1=max(sum1,a[i]);
        }
        int i;
        for(i=0;i<n;i++){
            if(a[i]==sum1){
                break;
            }else{
                ans.P(0);
