        for(int j=n-1;j>i;j--){
            ans.P(j-i);
        }
        cout<<sum1<<"\n"<<ans.size()<<"\n";
        for(int i=0;i<ans.size();i++){
            cout<<ans[i]+1<<"\n";
        }
        return;
