        int cnt=0;
        ans.P(0);cnt++;
        for(int i=a1.size()-1;i>=0;i--){
            if(a1[i]==n-1)continue;
            if(a1[i]==1)continue;
            ans.P(a1[i]-1);cnt+=2;
