        }
        if(n-1!=1&&a[n-1]<0&&(n-1)%2==1){
            ans.P(n-cnt-1);ans.P(n-cnt-2);cnt+=2;
        }
        for(int i=0;i<((n-cnt)/2);i++){
            ans.P(1);
        }
        cout<<sum1<<"\n";
