void make_op(int parity, int pos = -1){
	vector<int> v1(v, v+n);
	vector<int> mark(n, 0);

	if(pos == -1)
		for(int i = parity; i < n; i+=2)
			mark[i] = 1;
	else mark[pos] = 1;
	//cout << pos << endl;

	while(v1.size() > 1){

		for(int l = 0; l < v1.size(); l++){
			if(mark[l]) continue;
			if(l == 0 || l == v1.size()-1){
				ans.push_back(l+1);
				mark.erase(mark.begin() + l);
				v1.erase(v1.begin() + l);
				continue;
			}
			if((mark[l-1] && mark[l+1]) || (!mark[l-1] && !mark[l+1])){
				ans.push_back(l+1);
				if(mark[l-1])mark[l] = 1;
				mark.erase(mark.begin()+l+1);
				mark.erase(mark.begin()+l-1);
				v1[l] = v1[l-1] + v1[l+1];
				v1.erase(v1.begin()+l+1);
				v1.erase(v1.begin()+l-1);
				break;
			}
		}

	}
	cout << ans.size() <<"\n";
	for(auto &u : ans){
