bool done[MR][MR][2][2];

LL go(int i, int j, bool before, bool after)
{
	if (done[i][j][before][after])
		return dp[i][j][before][after];

	done[i][j][before][after] = 1;
	dp[i][j][before][after] = -inf;

	if (i >= j)
		return dp[i][j][before][after];

	if(!after)
		dp[i][j][before][after] = a[i];
	if (!before)
		dp[i][j][before][after] = max(dp[i][j][before][after], (LL)a[j - 1]);

	if(!before)
		dp[i][j][before][after] = max(dp[i][j][before][after], go(i + 1, j, 0, after));
	if (!after)
		dp[i][j][before][after] = max(dp[i][j][before][after], go(i, j - 1, before, 0));

	dp[i][j][before][after] = max(dp[i][j][before][after], go(i + 2, j, 1, after) + a[i]);
	dp[i][j][before][after] = max(dp[i][j][before][after], go(i, j - 2, before, 1) + a[j - 1]);

	if (j - i > 1 && (j - i) % 2)
		dp[i][j][before][after] = max(dp[i][j][before][after], (LL)a[i] + a[j - 1]);

	return dp[i][j][before][after];
}

vector<int> res;
void getMoves(int i, int j, int before, int after)
{
	int dl = j - i;

	if (dl == 1)
		return;

	bool bb = before, ba = after;

	LL v = dp[i][j][bb][ba];

	if (v == a[i] && !after)
	{
		REP(k, dl - 1)
			res.push_back(before + dl - k);
		return;
	}

	if (v == a[j - 1] && !before)
	{
		REP(k, dl - 1)
			res.push_back(1);
		return;
	}

	if (!before && v == go(i + 1, j, 0, ba))
	{
		res.push_back(1);
		getMoves(i + 1, j, 0, after);
		return;
	}

	if (!after && v == go(i, j - 1, bb, 0))
	{
		res.push_back(before + dl);
		getMoves(i, j - 1, before, 0);
		return;
	}

	if (v == go(i + 2, j, 1, ba) + a[i])
	{
		getMoves(i + 2, j, before + 2, after);
		res.push_back(before + 2);
		return;
	}

	if (v == go(i, j - 2, bb, 1) + a[j - 1])
	{
		getMoves(i, j - 2, before, after + 2);
		res.push_back(before + 2);
		return;
	}

	assert(j - i > 1 && (j - i) % 2);

	getMoves(i + 1, j - 1, 1, 1);
	res.push_back(2);
}

int main()
{
	int N;
	scanf("%d", &N);
	REP(i, N)
		scanf("%d", &a[i]);

	printf("%lld\n", go(0, N, 0, 0));

	getMoves(0, N, 0, 0);
	printf("%d\n", res.size());
	for (int r : res)
		printf("%d\n", r);

	return 0;
}

