pair<LL, pair<LL,LL>> searchLevel(vector<LL> v)
{
	REP(i, v.size() - 1) {
		v[i + 1] += v[i];
	}
	LL minv = 0;
	LL maxv = -INF;
	LL tmpl = -1;
	LL l = -1;
	LL r = 0;
	REP(i, v.size()) 
	{
		if (maxv < v[i] - minv) {
			l = tmpl;
			r = i;
			maxv = v[i] - minv;
		}
		if (minv > v[i]) {
			tmpl = i;
			minv = v[i];
		}
	}
	l++;
	return make_pair(maxv, make_pair(l, r));
}


