void handleNegative(vector<ll>& v) {
  ll ret = -2e9;
  for(ll out: v) ret = max(ret, out);
  if(ret <= 0) {
    cout << ret << "\n";
    cout << v.size()-1 << "\n";
    while(v.back() != ret) {
      cout << v.size() << "\n";
      v.pop_back();
    }
    while(v.size() != 1) {
      cout << 1 << "\n";
      v.pop_back();
    }
    exit(0);
  }
}

vector<int> op;

void cleanse(vector<ll>& v) {
  while(v.size() > 1) {
    if(v[0] < 0) {
      op.push_back(1);
      v.erase(v.begin());
      op.push_back(1);
      v.erase(v.begin());
      continue;
    }
    if(v.back() <= 0) {
      op.push_back(v.size());
      v.pop_back();
      op.push_back(v.size());
      v.pop_back();
      continue;
    }
    bool found = false;
    for(int i = 1; i+1 < v.size(); i += 2) {
      if(v[i-1] >= 0 && v[i+1] >= 0) {
        v[i-1] += v[i+1];
        v.erase(v.begin() + i + 1);
        v.erase(v.begin() + i);
        op.push_back(i+1);
        found = true;
        break;
      }
    }
    if(found) continue;
    if(v.size() == 2) {
      if(v[0] > v[1]) {
        op.push_back(2);
        v.pop_back();
      }
      else {
        op.push_back(1);
        v.erase(v.begin());
      }
      continue;
    }
    assert(v.size() >= 4);
    op.push_back(3);
    v[1] += v[3];
    v.erase(v.begin() + 2);
    v.erase(v.begin() + 2);
  }
}

void solve() {
  int n;
  cin >> n;
  vector<ll> v;
  for(int i = 0; i < n; i++) {
    int t;
    cin >> t;
    v.push_back(t);
  }
  handleNegative(v);
  ll odd = 0;
  ll even = 0;
  for(int i = 0; i < n; i++) {
    (i%2 ? odd : even) += max(0LL, v[i]);
  }
  if(odd > even) {
    v.erase(v.begin());
    op.push_back(1);
    if(v.size()%2 == 0) {
      op.push_back(v.size());
      v.pop_back();
    }
  }
  else {
    if(v.size()%2 == 0) {
      op.push_back(v.size());
      v.pop_back();
    }
  }
  cleanse(v);
  cout << v[0] << "\n";
  cout << op.size() << "\n";
  for(int out: op) cout << out << "\n";
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << ":" << "\n";
    solve();
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  solve();
  // casesolve();
}

