        rep(i, N)FOR(j, i + 1, N + 1) {
            if (f(i, j) == ans) {
                // [j, N)を削除する
                FOR(k, j, N)sousa.push_back(j + 1);
                // [0, i)を削除する
                rep(k, i)sousa.push_back(1);

                bit = BIT(N);
                FOR(k, i, j) {
                    S.insert(k);
                    bit.add(k, 1);
                }
                g(i, j);
                return;
            }
        }
    }();

