#define rrep(i,n) repi(i,1,n+1)
typedef pair<int,int> P;
typedef pair<int, P> PP;
#define fi first
#define se second
const int inf = 1e9;

int a[1002];
P solve1(int n){
	int res = 0, cnt = 0;
	rep(i,n){
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
		i++;
	}
	return P(res, cnt);
}
P solve2(int n){
	int res = 0, cnt = 0;
	rep(i,n){
		i++;
		if(i == n)break;
		if(a[i] > 0){
			res += a[i];
			cnt++;
		}
	}
	return P(res, cnt);
}
P solve3(int n){
	P p = P(-inf,0);
	rep(i,n){
		if(p.fi < a[i]){
			p.fi = a[i];
			p.se = i;
		}
	}
	return p;
}

signed main(){
	int n,f;
	scanf("%lld", &n);
	rep(i,n)scanf("%lld",&a[i]);
	P t1 = solve1(n);
	P t2 = solve2(n);
	P t3 = solve3(n);
	P p;
	if(t1.fi > t2.fi){p = t1;f = 0;}
	else {p = t2;f = 1;}

	vector<int> ans;
	if(p.fi > 0){
		int k = 0;a[n] = 1;
		while(a[k]<=0){
			ans.push_back(1);
			k++;
		}
		if(f == 0 && k%2 == 1){ans.push_back(1);k++;}
		if(f == 1 && k%2 == 0){ans.push_back(1);k++;}
		repi(i,k+2,n+1){
			if(a[i] > 0)ans.push_back(2);
			else ans.push_back(3);
			i++;
		}
		printf("%lld\n%lld\n",p.fi, (int)ans.size());
		rep(i,ans.size())printf("%lld\n", ans[i]);
	}else{
		printf("%lld\n%lld\n", t3.fi, n-1);
		rep(i,t3.se)printf("%lld\n", i+1);
		drep(i,n-1,t3.se+1)printf("%lld\n", i+1);
	}
	return 0;
}

