using namespace std;

int main() {
	const int inf = (int) 1.01e9;
	int n;
	cin >> n;

	vector<int> a(n);

	int dp[1100][1100];
	int prev[1100][1100];
	memset(dp, -1, sizeof(dp));
	memset(prev, -1, sizeof(prev));

	for (int i = 0; i < n; ++i) {
		cin >> a[i];
	}

	if (n == 1) {
		cout << a[0] << '\n' << 0;
		return 0;
	}
	if (n == 2) {
		cout << max(a[0], a[1]) << '\n';
		if (a[0] > a[1]) {
			cout << "1\n2";
		} else {
			cout << "1\n1";
		}
		return 0;
	}
	for (int l = 0; l + 3 <= n; ++l) {
		dp[l][l + 3] = max(0, a[l] + a[l + 2]); 
	}
	for (int i = 0; i <= 2; ++i)  {
		for (int l = 0; l + i <= n; ++l) {
			dp[l][l + i] = 0;
		}
	}
	function<int(int, int)> get_dp = [&](int l, int r) {
		if (dp[l][r] != -1) {
			return dp[l][r];
		} 
		for (int m = l + 1; m <= r - 2; ++m) {
			if (dp[l][r] < get_dp(l, m - 1) + get_dp(m + 2, r) + a[m - 1] + a[m + 1]) {
				dp[l][r] = get_dp(l, m - 1) + get_dp(m + 2, r) + a[m - 1] + a[m + 1];
				prev[l][r] = m;			
			}	
		}
		if (dp[l][r] < 0) {
			dp[l][r] = 0;
			prev[l][r] = -1;
		}
		return dp[l][r];	
	};
	vector<int> answer;
	function<void(int, int, int)> f = [&](int l, int r, int delta) {
		int mid = prev[l][r];
		if (mid != -1) {
			answer.push_back(delta + mid - l);
			f(mid + 2, r, delta + mid - l);
			f(l, mid - 1, delta);
		}	
	};
	(void) get_dp(0, n);
	(void) f(0, n, 0);

	cout << dp[0][n] << '\n';

	for (int i = 0; i < (int) answer.size(); ++i) {
		int val = a[answer[i] - 1] + a[answer[i] + 1];
		a.erase(a.begin() + answer[i] + 1);
		a.erase(a.begin() + answer[i] - 1);
		a[answer[i] - 1] = val;	
	}
	int max_idx = 0;
	for (int i = 1; i < (int) a.size(); ++i) {
		if (a[i] > a[max_idx]) {
			max_idx = i;
		}	
	}
	int lhs = max_idx;
	int rhs = a.size() - max_idx;
	{
		for (int i = a.size() - 1; i > max_idx; --i) {
			answer.push_back(i);
		}
		for (int i = 0; i < lhs; ++i) {
			answer.push_back(0);
		}
	}
	cout << answer.size() << '\n';
	for (auto x : answer) {
		cout << x + 1 << '\n';
	}                    
	return 0;
}

