  if( !(L < R) ) return ;
  if( R - L <= 1LL ) return;
  ll op = ph[L][R];
  assert( op != LLONG_MAX );
  if( op >= 0LL ) {
    --op;
    dfs(L,op-1);
    //cout << op-L+1 << endl;
    ans.push_back(op-L+1);
    dfs(op+1,R);
  } else {
    op *= -1LL;
    --op;
    ans.push_back(op-L+1);
    //cout << op-L+1 << endl;
    if( L == op ) ++L;
