                    --i;
                } else {
                    b.erase(b.begin() + i + 1);
                    b.erase(b.begin() + i - 1);
                    i -= 2;
                }
            }
        }
    }
    for (int i = 0; i < b.size(); ++i) {
        if (b[i] == 0 && b[i - 1] == 1 && b[i + 1] == 1) {
            ans.push_back(i + 1);
            b.erase(b.begin() + i + 1);
            b.erase(b.begin() + i - 1);
            --i;
        }
    }
	printf("%d\n",int(ans.size()));
	for(auto i:ans) {
		printf("%d\n",i);
	}
}

