using namespace std;

//bit
long long n;
long long c[1111];
void add(long long x,long long r){
	for(;x<=n;x+=lowbit(x)) c[x]+=r;
	return ;
}
long long que(long long x){
	long long r=0;
	for(;x;x-=lowbit(x)) r+=c[x];
	return r;
}

//dfs
bool lp[1111][1111];
long long dp[1111][1111];
long long root[1111][1111];
long long ans[1111],dfs_time=0;
long long num[1111];
long long dfs(long long l,long long r){
	long long lsl,lsr;
	if(r<l) return 0;
	if(lp[l][r]) return dp[l][r];
	if(r==l){
		lp[l][r]=true;
		root[l][r]=l;
		return dp[l][r]=num[l];
	}
	for(long long i=l;i<=r;i++) {
		lsl=dfs(l,i-1ll);
		lsr=dfs(i+1ll,r);
		if(lsl+lsr>dp[l][r])
			dp[l][r]=lsl+lsr,root[l][r]=i;
	} 
	lp[l][r]=true;
	return dp[l][r];
}
void rdfs(long long l,long long r){
	if(r<l)  return ;
	if(r==l){
		//ans[++dfs_time]=que(l);
		//add(l,-1);
		return ;
	}
	if(root[l][r]==l){
		ans[++dfs_time]=que(l);
		add(l,-1ll);
		rdfs(root[l][r]+1ll,r);
		return ;
	}
	if(root[l][r]==r){
		ans[++dfs_time]=que(r);
		add(r,-1ll);
		rdfs(l,root[l][r]-1ll);
		return ;
	}
	rdfs(l,root[l][r]-1ll);
	rdfs(root[l][r]+1ll,r);
	ans[++dfs_time]=que(root[l][r]);
	return ;
}

