		add(i,1);
	dfs(1ll,n);
	printf("%lld\n",dp[1][n]);
	rdfs(1ll,n);
	printf("%lld\n",dfs_time);
	for(long long i=1ll;i<=dfs_time;i++)
		printf("%lld\n",ans[i]);
	return 0;
}

