int a[1050];
long long dp[1050][1050];
int pre[1050][1050];
int v[1050][1050];
long long dfs(int l,int r)
{
    if(r-l==0)
        return a[l];
    if(v[l][r])
        return dp[l][r];
    v[l][r]=1;
    long long ans;
    int f=0;
    for(int i=l+1;i<r;i++)
    {
        if((i-l)%2&&(r-i)%2)
        {
            long long x=dfs(l,i-1),y=dfs(i+1,r);
            if(f==0)
            {
                ans=x+y,f=1;
                pre[l][r]=i;
            }
            else
            {
                if(x+y>ans)
                {
                    ans=x+y;
                    pre[l][r]=i;
                }
            }
        }
    }
    return dp[l][r]=ans;
}
vector<int>opt;
void solve(int l,int r)
{
    if(r-l==0)
        return ;
    int mid=pre[l][r];
    solve(mid+1,r);
    opt.push_back(mid);
    solve(l,mid-1);
}
int main()
{
    int n;
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
        scanf("%d",a+i);
    long long ans=-1000000001;
    int l,r;
    for(int i=1;i<=n;i++)
        for(int j=i;j<=n;j++)
            if((j-i+1)%2&&dfs(i,j)>ans)
            {
                ans=dfs(i,j);
                l=i;
                r=j;
            }
    printf("%lld\n",ans);

//    printf("&&&&%d %d\n",l,r);

    for(int i=n;i>r;i--)
        opt.push_back(i);
    solve(l,r);
    for(int i=1;i<l;i++)
        opt.push_back(1);
    printf("%d\n",(int)opt.size());
    for(int i=0;i<opt.size();i++)
        printf("%d\n",opt[i]);
    return 0;
}

