			if(Ans[i-1]==Ans[i+1])
			{
				if(Ans[i-1]==1) flag=1;
				ans[++tot]=i;
				work(i-1);
				work(i);
				if(flag) Ans[i-1]=1;
				break;
			}
		}

	}
	printf("%lld\n%d\n",f[Max],tot);
	for(int i=1;i<=tot;++i) printf("%d\n",ans[i]);
	return 0;
}

