using namespace std;
using ll = int64_t;
using vecint = vector<int>;
using vecll = vector<ll>;
constexpr ll INF = 1e15;

pair<ll, vecint> solve(const vecll& vec, int orig) {
  int n = vec.size();
  ll mn = 0;
  ll mni = 0;
  ll sum = 0;
  ll rmx = -INF;
  ll rmxi = 0;
  ll rmxj = 0;
  REP(i,n) {
    sum += vec[i];
    if (sum - mn > rmx) {
      rmx = sum - mn;
      rmxi = i+1;
      rmxj = mni;
    }
    if (sum < mn) {
      mn = sum;
      mni = i+1;
    }
  }
  vecint ans;
  REP(i,2*rmxj) {
    ans.push_back(1);
    --orig;
  }
  REP(i,rmxi-rmxj-1) {
    ans.push_back(2);
    orig -= 2;
  }
  while (orig > 1) {
    ans.push_back(orig);
    --orig;
  }
  return make_pair(rmx, ans);
}

