vector<bool> mark(auto A) {
  vector<bool> need(A.size());
  auto sum = [&](auto j) {
    auto s = 0ll;
    for(auto i=j; i<A.size(); i+=2) s += max(0ll, A[i]);
    return s;
  };
  auto a = max_element(begin(A), end(A));
  if(*a <= 0) {
    cout << *a << endl;
    need[a - begin(A)] = true;
    return need;
  }
  auto b = sum(0);
  auto c = sum(1);
  cout << max(b, c) << endl;
  for(auto i=(b>c?0:1); i<A.size(); i+=2) need[i]=(0<=A[i]);
  return need;
}
