namespace hungary {
    const int N = 105;
    bool vis[N];
    int match[N];
    int n;
    bool e[N][N];
    bool dfs(int u) {
        for (int v = 1; v <= n; v++) {
            if(!e[u][v]) continue;
            if (vis[v]) continue;
            vis[v] = true;
            if (!match[v] || dfs(match[v])) {
                match[v] = u;
                return true;
            }
        }
        return false;
    }

    int hungary(int n) {
        memset(match, 0, sizeof(match));
        int res = 0;
        for (int i = 1; i <= n; i++) {
            memset(vis, 0, sizeof(vis));
            res += dfs(i);
        }
        return res;
    }
}

