inline std::pair<std::vector<int>, long long> calcAns(int start) {
    long long result = 0, max = start;
    std::vector<int> indexes;
    for (int i = start; i <= n; i += 2) {
        if (a[i] > 0LL) result += a[i], indexes.push_back(i);
        if (a[i] > a[max]) max = i;
    }
    if (!result) result = a[max], indexes.push_back(max);
    return {indexes, result};
}

std::vector<int> result;
bool d[MAXN];
inline void fill(std::vector<int> v) {
    for (auto i : v) d[i] = 1;
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
    auto l = calcAns(1), r = calcAns(2);

    if (l.second >= r.second) {
        printf("%lld\n", l.second);
        int m = 0;
        fill(l.first);
        while (n > l.first.back()) result.push_back(n - m), n--;
        for (int i = 1; i < l.first.front(); i++) result.push_back(i - m), m++;
        for (int i = l.first.front() + 1; i < l.first.back(); i += 2) {
            if (!(d[i - 1] ^ d[i + 1])) result.push_back(i - m), m += 2;
        }
        assert(n - m == 1);
    } else {
        printf("%lld\n", r.second);
        result.push_back(1);
        int m = 1;
        fill(r.first);
        while (n > r.first.back()) result.push_back(n - m), n--;
        for (int i = 2; i < r.first.front(); i++) result.push_back(i - m), m++;
        for (int i = r.first.front() + 1; i < r.first.back(); i++) {
            if(d[i])continue;
            if (!(d[i - 1] ^ d[i + 1])) result.push_back(i - m), m += 2, i++;
        }
        assert(n - m == 1);
    }
    printf("%lu\n", result.size());
    for (auto i : result) printf("%d\n", i);
    return 0;
}

