deque<int> A;

void merge(int& i) {
    if(i == 0) {
        A.pop_front();

    } else if(i == A.size()-1) {
        A.pop_back();
        i--;
    } else {
        A[i] = A[i-1] + A[i+1];
        A.erase(A.begin() + i+1);
        A.erase(A.begin() + i-1);
        i--;
    }
}

signed main()
{
    cin >> N;

    int l = 0, r = 0;
    A.resize(N);
    for(int i = 0; i < N; i++) {
        cin >> A[i];
        if(A[i] < 0) {
            continue;
        }
        if(i%2 == 0) {
            l += A[i];
        } else {
            r += A[i];
        }
    }

    cout << max(l, r) << endl;

    int startI = (l > r ? 0 : 1);

    vector<int> ope;

    //負の値を消す
    for(int i = 0; i < A.size(); i++) {
        if(A[i] >= 0) {
            continue;
        }
        if(i%2 == startI) {
            if(i == 0 || i == A.size()-1) {
                startI = (startI+1)%2;
            }
            ope.push_back(i+1);
            merge(i);   
        }
    }

    //足していく
    for(int i = 0; i < A.size(); i++) {
        if(i%2 != startI) {
            if(i == 0 || i == A.size()-1) {
                startI = (startI+1)%2;
            }
            ope.push_back(i+1);
            merge(i);
        }
    }

