    if(A.size() > 1) {
        if(startI == 0) {
            A.pop_back();
            ope.push_back(2);
        } else {
            A.pop_front();
            ope.push_back(1);
        }
    }

    cout << ope.size() << endl;
    for(int o : ope) {
        cout << o << endl;
    }

    return 0;
}

