#define REP(i, a, n) for(ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

const ll INF = (1LL << 60);

int main(void) {
  ll N;
  cin >> N;
  vector<ll> A(N);
  REP(i, 0, N) cin >> A[i];

  vector<ll> sum(2, 0), cnt(2, 0);
  REP(i, 0, N) {
    if(A[i] >= 0) {
      sum[i % 2] += A[i];
      cnt[i % 2]++;
    }
  }

  if(cnt[0] == 0 && cnt[1] == 0) {
    ll x = -INF, arg;
    REP(i, 0, N) {
      if(x < A[i]) {
        x = A[i];
        arg = i;
      }
    }

    vector<ll> op;
    for(ll i = N - 1; i >= 0; i--) {
      if(i > arg) {
        op.push_back(i);
      }
    }
    REP(i, 0, arg) op.push_back(0);

    cout << x << endl;
    cout << N - 1 << endl;
    for(ll i : op) cout << i + 1 << endl;
  } else {
    ll p;
    if(cnt[0] > 0 && cnt[1] > 0) p = sum[0] >= sum[1] ? 0 : 1;
    else if(cnt[0] > 0) p = 0;
    else if(cnt[1] > 0) p = 1;

    ll l = N, r = -1;
    REP(i, 0, N) {
      if(i % 2 == p && A[i] >= 0) {
        l = min(l, i);
        r = max(r, i);
      }
    }

    vector<ll> op;
    for(ll i = A.size() - 1; i >= 0; i--) {
      if(i > r) {
        op.push_back(i);
        A.erase(A.begin() + i);
      }
    }
    REP(i, 0, l) {
      op.push_back(0);
      A.erase(A.begin());
    }
    REP(i, 0, A.size()) {
      if(i % 2 == 0 && A[i] < 0) {
        op.push_back(i);
        A[i] = A[i - 1] + A[i + 1];
        A.erase(A.begin() + (i + 1));
        A.erase(A.begin() + (i - 1));
        i--;
      }
    }
    REP(i, 0, A.size() / 2) op.push_back(1);

    cout << sum[p] << endl;
    cout << op.size() << endl;
    for(ll i : op) cout << i + 1 << endl;
  }
}

