			else Op[++ Op[0]] = n - 2, A[n - 2] = A[n - 1], A[n - 1] = A[n], n --;
		}
		else
		{
			if (n % 2 == 1 || A[n] <= 0)
				Op[++ Op[0]] = n --;
			else if (n == 2)
				Op[++ Op[0]] = n - 1, A[n - 1] = A[n], n --;
			else if (A[n - 2] > 0)
				Op[++ Op[0]] = n - 1, A[n - 2] += A[n], n -= 2;
			else Op[++ Op[0]] = n - 2, A[n - 3] += A[n - 1], A[n - 2] = A[n], n -= 2;
		}
	}
	printf("%lld\n", A[1]);
	for (int i = 0; i <= Op[0]; i ++)
		printf("%d\n", Op[i]);
	return 0;
}

