void go(int fr, int en, auto& pref) {
    if (fr == en) return;
    if (fr + 2 == en) {
        cout << fr + 1 + 1 << "\n";
        return;
    }

    go(fr + 2, en - 2, pref);
    if (pref[en][en&1] - pref[fr+1][fr&1] > 0) {
        cout << fr + 1 + 1 << "\n";
        cout << fr + 1 + 1 << "\n";
    } else {
        cout << fr + 2 + 1 << "\n";
        cout << fr + 1 + 1 << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N;
    cin >> N;

    vector<array<ll, 2>> pref(N + 1);
    pref[0] = { 0, 0 };

    vi a(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        pref[i + 1] = pref[i];
        if (a[i] > 0) pref[i + 1][i&1] += a[i];
    }

    ll max = LLONG_MIN;
    int fr = -1, en = -1;

    for (int cf = 0; cf < N; cf++) {
        for (int cb = 0; cf + cb < N; cb++) {
            int re = N - cf - cb;
            if (re % 2 != 1) continue;

            ll tot = (re == 1) ? a[cf] : (a[cf] + a[cf + re - 1] +
                pref[cf + re - 1][cf & 1] - pref[cf + 1][cf & 1]);
            if (tot > max) {
                max = tot;
                fr = cf, en = cf + re - 1;
            }
        }
    }

    cout << max << endl;
    cout << N - (en - fr + 1) + (en - fr) / 2 << "\n";

    for (int i = en + 1; i < N; i++) {
        cout << N-- << "\n";
    }
    go(fr, en, pref);
    for (int i = 0; i < fr; i++) {
        cout << 1 << "\n";
    }

    return 0;
}

