#define MAXN 1010

class Solve {
private:
	auto get_max(const vector<long long>& a, int start) {
		pair<long long, vector<int>> rst{};

		int imax = start;
		for (size_t i = start; i < a.size(); i += 2) {
			if (a[i] > 0) {
				rst.first += a[i];
				rst.second.push_back(i);
			}
			if (a[i] > a[imax]) imax = i;
		}

		if (rst.second.empty()) {
			rst.first = a[imax];
			rst.second.push_back(imax);
		}

		return rst;
	}

	void solve() {
		int n;
		cin >> n;
		vector<long long> a = { 0 };
		a.reserve(n + 1);

		for (int i = 1; i <= n; i++) {
			long long tmp;
			cin >> tmp;
			a.push_back(tmp);
		}

		auto rst1 = get_max(a, 1);
		auto rst2 = get_max(a, 2);

		const auto& rst = rst1.first > rst2.first ? rst1 : rst2;
		const auto& use = rst.second;

		list<int> ops;
		for (int i = n; i > use.back(); i--) {
			ops.push_back(i);
		}
		for (int i = 1; i < use.front(); i++) {
			ops.push_back(1);
		}

		if (use.size() >= 2) {
			for (int i = 0; i < (int)use.size() - 1; i++) {
				int delta = use[i + 1] - use[i] - 1;
				for (int j = 0; j < delta / 2; j++) {
					ops.push_back(3);
				}
				ops.push_back(2);
			}
		}

		cout << rst.first << endl;
		cout << ops.size() << endl;
		for (auto op : ops) {
			cout << op << endl;
		}
	}

public:
	Solve() { solve(); }
};

int main(int argc, char* argv[]) {
	unique_ptr<Solve> solve = make_unique<Solve>();
	return 0;
}

