void openeg(V<ll> a) {
    ll MAX = -INF, id = 0;
    REP(i, SIZE(a)) {
        if (a[i] > MAX) {
            id = i;
            MAX = a[i];
        }
    }

    cout << MAX << endl;
    cout << SIZE(a) - 1 << endl;
    REP(i, id) {
        cout << 1 << endl;
    }

    REP(i, SIZE(a) - id - 1) {
        cout << SIZE(a) - id - i << endl;
    }
}

V<ll> ope(V<ll> a) {
    ll ans = 0;
    V<ll> step;
    ll itr = 0;

    if (SIZE(a) % 2 == 0) {
        step.pb(SIZE(a));
        a.pop_back();
    }

    while (itr < SIZE(a)) {
        if (a[itr] < 0) {
            if (itr == 0) {
                REP(_, 2) {
                    step.pb(1);
                    a.erase(a.begin());
                }
            } else {
                step.pb(itr + 1);
                a.erase(a.begin() + itr - 1, a.begin() + itr + 1);
            }
        } else {
            ans += a[itr];
            itr += 2;
        }
    }

    while (SIZE(a) > 1) {
        step.pb(2);
        a.erase(a.begin(), a.begin() + 2);
    }

    step.pb(ans);
    return step;
}

