    {
        for (int i = 0; i + len - 1 < n; i++)
        {
            for (int x = 0; x < 2; x++)
            {
                for (int y = 0; y < 2; y++)
                {
                    int j = i + len - 1;
                    if (len == 1)
                    {
                        dp[i][j][x][y] = a[i];
                        opt[i][j][x][y] = i;
                    }
                    else
                    {
                        dp[i][j][x][y] = -1e18;
                        if (x == 0)
                        {
                            dp[i][j][x][y] = max(dp[i][j][x][y], dp[i + 1][j][x][y]);
                        }
                        if (y == 0)
                        {
                            dp[i][j][x][y] = max(dp[i][j][x][y], dp[i][j - 1][x][y]);
                        }
                        ll best = -1e18;
                        for (int t = i + 1; t < j; t++)
                        {
                            if (dp[i][t - 1][x][1] + dp[t + 1][j][1][y] > best)
                            {
                                best = dp[i][t - 1][x][1] + dp[t + 1][j][1][y];
                                opt[i][j][x][y] = t;
                            }
                        }
                        if (best > dp[i][j][x][y])
                        {
                            dp[i][j][x][y] = best;
                            type[i][j][x][y] = 1;
                        }
                        else
                        {
                            if (!x && dp[i + 1][j][x][y] == dp[i][j][x][y])
