        ll cnt = a[i];
        for (int j = i-2; j >= 0; j -= 2) {
            if (a[j] > 0) cnt += a[j];
        }
        for (int j = i+2; j < n; j += 2) {
            if (a[j] > 0) cnt += a[j];
        }
        if (ans < cnt) {
            ans = cnt;
            ansi = i;
        }
    }
    cout << ans << endl;
    vector<int> out;
    while (a.size() != 1) {
        int j = ansi-2;
        if (j >= 0) {
            if (a[j] > 0) {
                out.push_back(j+2);
                a.erase(a.begin()+j);
                a.erase(a.begin()+j);
                ansi -= 2;
            } else {
                out.push_back(j+1);
                a.erase(a.begin()+j);
                ansi--;
                if (j != 0) { a.erase(a.begin()+j-1); ansi--; }
            }
            continue;
        }
        j = ansi+2;
        if (j < a.size()) {
            if (a[j] > 0) {
                out.push_back(j);
                a.erase(a.begin()+j-1);
                a.erase(a.begin()+j-1);
