            out.push_back(1);
            a.erase(a.begin());
            ansi--;
            continue;
        }
        if (ansi != a.size()-1) {
            out.push_back(a.size());
            a.erase(a.begin()+a.size()-1);
            ansi--;
            continue;
        }
    }
