vector <int> q;
void solve(vector <bool> mask) {
    #ifdef HOME
    cout << "solve: ";
    for (auto e : mask) cout << e << ' ';
    cout << '\n';
    #endif

    if (mask.size() == 1) return;
    if (!mask[0]) {
        q.push_back(1);
        vector <bool> t;
        for (int i = 1; i < (int)mask.size(); ++i) t.push_back(mask[i]);
        solve(t);
        return;
    }   
    if (!mask.back()) {
        q.push_back(mask.size());
        vector <bool> t;
        for (int i = 0; i < (int)mask.size() - 1; ++i) t.push_back(mask[i]);
        solve(t);
        return;
    }   
    int p = -1;
    for (int i = 0; i < (int)mask.size(); ++i) {
        if (!mask[i]) {
            p = i;
            break;
        }   
    }   
    if (!mask[p + 1]) ++p;
    q.push_back(p + 1);
    vector <bool> t;
    for (int i = 0; i < (int)mask.size(); ++i) {
        if (i != p && i != p + 1) {
            t.push_back(mask[i]);
        }   
    }    
    solve(t);
}   
