#define int long long
using namespace std;

int INF = 1e+15;
int n;
int a[1001];	//a[n] = 0
int dp[1002];	//dp[i] = 最後にa[i-1]を取ったときの〇の和の最大値, [消す]〇(取る)を1セットの遷移とする. dp[0]～dp[n]まで計算

signed main() {
	int i, j;

	cin >> n;
	for (i = 0; i < n; i++) cin >> a[i];
	for (i = 0; i <= n + 1; i++) dp[i] = -INF;

	dp[0] = 0;
	for (i = 0; i <= n; i++) {
		//[i, j)を取る
		for (j = i + 1; j <= n + 1; j++) {
			int eraseCnt = j - i - 1;
			if (i != 0 && j != n + 1 && eraseCnt % 2 == 0) continue;
			int tasu = a[j - 1];			//a[j - 1]を取る
			dp[j] = max(dp[j], dp[i] + tasu);
		}
	}

	int ans = dp[n + 1];
	cout << ans << endl;

	//復元
	bool used[1002] = {false};
	int pos = n + 1;
	used[pos - 1] = true;

	while (pos > 0) {
		for (i = pos - 1; i >= 0; i--) {
			int eraseCnt = pos - i - 1;
			if (i != 0 && pos != n + 1 && eraseCnt % 2 == 0) continue;
			if (dp[i] + a[pos - 1] == dp[pos]) break;
		}
		pos = i;
		if (pos > 0) used[pos - 1] = true;
		//[i, pos-2]を消すので
	}

	//復元パート
	vector<int> l, r;

	for (i = 0; i < n; i++) if (used[i]) break;
	l.push_back(0); r.push_back(i);
	i++;

	int yo = -1;
	for (; i <= n; i++) {
		if (used[i - 1] && !used[i]) yo = i;
		if (!used[i - 1] && used[i]) {
			l.push_back(yo);
			r.push_back(i);
		}
	}

	//復元パート
	vector<int> ope;
	int off = 0;
	for (i = 0; i < l.size(); i++) {
		//cout << l[i] << " " << r[i] << " " << off << endl;
		if (l[i] == 0) {
			for (j = 0; j < r[i]; j++) ope.push_back(0);
			off += r[i];
		}
		else if (r[i] >= n) {
			for (j = l[i]; j < r[i]; j++) { ope.push_back(n - 1 - off); off++; }
		}
		else {
			//cout << "neko*neko" << endl;
			for (j = 0; j < (r[i] - l[i] + 1) / 2; j++) ope.push_back(l[i] - off);
			off += (r[i] - l[i] + 1) / 2 * 2;
		}
	}

	cout << ope.size() << endl;
	for (i = 0; i < ope.size(); i++) {
		cout << ope[i] + 1 << endl;
	}
	return 0;
}

