using Int = long long;
void maxseq(vector<Int> X, Int &sum, Int &idx, Int &cnt)
{
    sum = idx = cnt = 0;
    Int from = 0, curr = 0;
    for (int i = 0; i < X.size(); i++) {
        curr += X[i];
        if (curr > sum) sum = curr, idx = from, cnt = i - from + 1;
        if (curr < 0) curr = 0, from = i + 1;
    }
}
int main()
{
    int N; cin >> N;
    vector<Int> A(N); for (auto &a : A) cin >> a;
    vector<Int> B, C;
    for (int i = 0; i < N; i++) {
        (i % 2 == 0 ? B : C).push_back(A[i]);
    }
    Int bsum, bidx, bcnt, csum, cidx, ccnt;
    maxseq(B, bsum, bidx, bcnt);
    maxseq(C, csum, cidx, ccnt);
    vector<int> ans;
    if (bsum >= csum) {
        for (int i = 0; i < bidx*2; i++) ans.push_back(1);
        for (int i = 0; i < bcnt-1; i++) ans.push_back(2);
        int rest = N - bidx*2 - 2*(bcnt-1);
        while (rest > 1) ans.push_back(rest--);
    } else {
        ans.push_back(1);
        for (int i = 0; i < cidx*2; i++) ans.push_back(1);
        for (int i = 0; i < ccnt-1; i++) ans.push_back(2);
        int rest = N - 1 - cidx*2 - 2*(ccnt-1);
        while (rest > 1) ans.push_back(rest--);
    }
    cout << max(bsum, csum) << '\n';
    cout << ans.size() << '\n';
    for (auto a : ans) cout << a << '\n';
