}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int Maxn = 1005;

int n;
ll a[Maxn];
vector <int> res;
int my;

void Apply(int ind)
{
	res.push_back(ind);
	if (ind == 1) {
		for (int i = 1; i <= n - 1; i++)
			a[i] = a[i + 1];
		n--;
		my = 1 - my;
	} else if (ind == n) n--;
	else {
		a[ind - 1] += a[ind + 1];
		for (int i = ind; i <= n - 2; i++)
			a[i] = a[i + 2];
		n -= 2;
	}
}

void Solve()
{
	while (n > 1) {
		bool was = false;
		for (int i = 1; i <= n; i++)
			if (a[i] < 0 && i % 2 == my) { Apply(i); was = true; break; }
		if (was) continue;
		if (my == 0) Apply(1);
		else Apply(2);
	}
}

