	for (int i = 1; i <= n; i += 2) if (a[i] >= 0)
		res1 += a[i];
	ll res2 = 0;
	for (int i = 2; i <= n; i += 2) if (a[i] >= 0)
		res2 += a[i];
	if (res1 >= res2) my = 1;
	else my = 0;
