int n, t;
ll os, es, res;
vl a, od, ev, need, ans;

void solve() {
	bool ud = true;
	while (need.size()>=2 && ud) {
		ud = false;
		while (!need[0]) ans.pb(1), need.erase(need.begin());
		while (!need[need.size()-1]) ans.pb(need.size()), need.erase(need.end()-1);
		rep(i,need.size()) {
			if (0<i && i<need.size()-2 && ((need[i-1] && need[i+1]) || (!need[i] && !need[i-1] && !need[i+1]))) {
				ud = true;
				if (need[i-1] && need[i+1]) need[i] = 1;
				need.erase(need.begin()+i+1), need.erase(need.begin()+i-1);
				ans.pb(i+1);
			}
		}
	}
}

