val INF = 2e12.toLong()

var a = LongArray( 0 )
var best = Array( 0, { LongArray( 0 ) } )
var prev = Array( 0, { IntArray( 0 ) } )

fun main(args: Array<String> ) {
    val st = StreamTokenizer( BufferedReader( InputStreamReader( System.`in` ) ) )
    val n = st.nextInt()
    a = LongArray( n, { st.nextInt().toLong() } )
    best = Array( n + 1, { LongArray( n - it + 1, { -INF } ) } )
    prev = Array( n + 1, { IntArray( n - it + 1, { -1 } ) } )
    for ( i in 0 until n ) {
        best[1][i] = a[i]
    }
    for ( len in 2 .. n ) {
        for ( pos in 0 .. n - len ) {
            if ( pos == 0 ) {
                best[len][pos] = a[len - 1]
                prev[len][pos] = 0
            }
            if ( pos + len == n ) {
                if ( a[pos] > best[len][pos] ) {
                    best[len][pos] = a[pos]
                    prev[len][pos] = n - 1
                }
            }
//            if ( len % 2 == 0 ) continue

            var l = 0
            var r = len / 2
            while ( l < r ) {
                val ml = ( l * 2 + r ) / 3
                val mr = ( l + r * 2 ) / 3
                val rl = best[ml * 2 + 1][pos] + best[len - ml * 2 - 2][pos + ml * 2 + 2]
                val rr = best[mr * 2 + 1][pos] + best[len - mr * 2 - 2][pos + mr * 2 + 2]
                if ( rl < rr ) {
                    l = ml + 1
                } else {
                    r = mr
                }
            }

            var bm = -1
            var bb = -INF
            for ( m in pos + Math.max( 1, l - 3 ) .. pos + Math.min( len - 2, l + 3 ) ) {
                val t = best[m - pos][pos] + best[len - ( m - pos ) - 1][m + 1]
                if ( t > bb ) {
                    bm = m
                    bb = t
                }
            }
            if ( bb > best[len][pos] ) {
                best[len][pos] = bb
                prev[len][pos] = bm
            }
        }
    }

    println( best[n][0] )
    val result = ArrayList<Int>( n )
    printRes( n, 0, 0, result )
    println( result.size )
    for ( r in result ) {
        println( r )
    }
}

