    if ( len <= 1 ) return
    val p = prev[len][pos]
    printRes( p - pos, pos, right, result )
    printRes( len - ( p - pos ) - 1, p + 1, right + 1 + if ( p > pos ) 1 else 0, result )
    result.add( right + 1 + if ( p > pos ) 1 else 0 )
}

