    int n = ni();
    int[] a = na(n);

    int[] p = new int[n / 2 + (n % 2 == 1 ? 1 : 0)];
    int[] q = new int[n / 2];

    for (int i = 0; i < n; i ++) {
      if (i % 2 == 0) {
        p[i / 2] = a[i];
      } else {
        q[i / 2] = a[i];
      }
    }

    long max1 = 0;
    long max2 = 0;
    for (int v : p) {
      if (v > 0) max1 += v;
    }
    for (int v : q) {
      if (v > 0) max2 += v;
    }

    List<Integer> list = new ArrayList<>();
    LinkedList<Integer> l = new LinkedList<>();
    for (int v : a) {
      l.add(v);
    }

    long max = max1;
    if (max1 < max2) {
      list.add(1);
      l.remove(0);
      max = max2;
    }

    boolean flg = true;
    while (flg) {
      flg = false;
      for (int i = 1; i < l.size(); i += 2) {
        if (l.get(i) < 0) {
          list.add(i + 1);
          l.set(i, l.get(i + 1) + l.get(i - 1));
          l.remove(i - 1);
          l.remove(i);
          flg = true;
          break;
        }
      }
    }

    while (l.size() > 2) {
      list.add(2);
      l.set(1, l.get(0) + l.get(2));
      l.remove(0);
      l.remove(1);
    }

    if (l.size() == 2) {
      if (l.get(0) > l.get(1)) {
        l.remove(1);
        list.add(2);
      } else {
        l.remove(0);
        list.add(1);
      }
    }

    System.out.println(max);
    System.out.println(list.size());
    for (int v : list) {
