/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            long[] a = in.nextLongArray(n);

            long max = Long.MIN_VALUE;
            int li = -1, ri = -1;
            for (int i = 0; i < n; i++) {
                long cur = 0;
                for (int j = i; j < n; j += 2) {
                    cur += a[j];
                    if (max < cur) {
                        max = cur;
                        li = i;
                        ri = j;
                    }
                }
            }
            List<Integer> ans = new ArrayList<>();
            for (int i = n - 1; i > ri; i--) {
                ans.add(i + 1);
            }
            for (int i = 0; i < li; i++) {
                ans.add(1);
            }
            for (int i = li; i < ri; i += 2) {
                ans.add(2);
            }
            out.println(max);
            out.println(ans.size());
            for (int i : ans) out.println(i);
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public long[] nextLongArray(final int n) {
            final long[] res = new long[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextLong();
            }
            return res;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        Ans answer = solve();
        pw.println( answer.value );
        pw.println( answer.way.size() );
        for (int each : answer.way) {
            pw.println(each);
        }
        pw.flush();
    }

    static Ans solve() {
        long even = 0;
        for (int i = 0; i < N; i++) {
            if( i % 2 == 0 && A[i] > 0) {
                even += A[i];
            }
        }

        long odd = 0;
        for (int i = 0; i < N; i++) {
            if( i % 2 == 1 && A[i] > 0 ) {
                odd += A[i];
            }
        }

        if( even <= 0 && odd <= 0 ) {
            return case_0();
        }

        List<Integer> ways = new ArrayList<>();
        LinkedList<Long> list = new LinkedList<>();
        for (int i : A) {
            list.add((long) i);
        }

        // 一つ取ってevenに合わせる
        if( odd > even ) {
            list.removeFirst();
            ways.add(0);
        }

        while(list.size() > 1 ) {
            if( list.size() == 2 ) {
                list.removeLast();
                ways.add(1);

            } else {
                // plusだけを残す
                // ので、minusの場合はいきなり消す
                if( list.getFirst() < 0 ) {
                    // 二回操作してる
                    ways.add(0);
                    ways.add(0);
                    list.removeFirst(); // minus分
                    list.removeFirst(); // odd分

                } else {
                    long nextEven = list.get(2);
                    if( nextEven >= 0 ) {
                        long first = list.getFirst();
                        ways.add(1);
                        list.set(1, first + nextEven);
                        list.remove(2);
                        list.remove(0);

                    } else {
                        if( list.size() == 3 ) {
                            // 0 1 2 -> 0 1
                            list.removeLast();
                            ways.add(2);
                        } else {
                            // 0 1 2 3 -> 0 1 1+3 3 -> 0 1+3
                            long second = list.get(1);
                            long forth = list.get(3);
                            ways.add(2);
                            list.set(2, second + forth); //　どうせ使わないあたいなのだけど一応
                            list.remove(3);
                            list.remove(1);
                        }
                    }
                }
            }
        }
        return new Ans(list.getFirst(), ways);
    }

    static Ans case_0() {
        int max = Integer.MIN_VALUE;
        int max_index = -1;

        for (int i = 0; i < N; i++) {
            if( A[i] > max ) {
                max = A[i];
                max_index = i;
            }
        }

        List<Integer> ways = new ArrayList<>();
        // max_index以外を全部すてる
        // -> max_index個前に存在するのでそれを捨てる(way=0)
        // + N-max_index-1個後ろに存在するのでそれを捨てる(way=size-1)
        for (int i = 0; i < max_index; i++) {
            ways.add(0);
        }
        for (int i = 0; i < N-max_index-1; i++) {
            int size = N - max_index - i;
            ways.add(size-1);
        }

        return new Ans(max, ways);
    }

    static class Ans {
        long value;
        List<Integer> way;

        public Ans(long value, List<Integer> way) {
            this.value = value;
            this.way = way;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

