        if(!allneg){
            boolean[][] mi = new boolean[2][n/2+1];
            long[] scr = new long[2];
            for(int i=0; i<2; i++){
                for(int j=i; j<n; j+=2){
                    if(a[j]<0){
                        mi[i][j/2] = true;
                    }else{
                        scr[i] += a[j];
                    }
                }
            }
            int idx = (scr[0] > scr[1])? 0:1;
            max = scr[idx];
            //
            int size = n;

            if(idx==1){
                ans.add(1);
                size -= 1;
            }

            if(size%2==0){
                ans.add(size);
                size -= 1;
            }

            for(int i=n/2; i>=0; i--){
                if(mi[idx][i]){
                    int t = i*2+1;
                    ans.add(t);
                    if(t == 1){
                        ans.add(t);
                    }else if(t == size){
                        ans.add(t-1);
                    }
                    size -= 2;
