class SupplyingIterator<T> implements Iterable<T>,Iterator<T>{
	int			t;
	Supplier<T>	supplier;

	SupplyingIterator(int t,Supplier<T> supplier){
		this.t=t;
		this.supplier=supplier;
	}

	@Override
	public Iterator<T> iterator(){
		return this;
	}

	@Override
	public boolean hasNext(){
		return t>0;
	}

	@Override
	public T next(){
		--t;
		return supplier.get();
	}

}
class Range implements Iterable<Integer>,PrimitiveIterator.OfInt{
	int to,cur,d;

	Range(int from,int to,int d){
		this.cur=from-d;
		this.to=to;
		this.d=d;
	}

	Range(int n){
		this(0,n-1,1);
	}

	@Override
	public Iterator<Integer> iterator(){
		return this;
	}

	@Override
	public boolean hasNext(){
		return cur+d==to||(cur!=to&&(cur<to==cur+d<to));
	}

	@Override
	public int nextInt(){
		return cur+=d;
	}

	static Range rep(int i){
		return new Range(i);
	}
	static Range rep(int f,int t,int d){
		return new Range(f,t,d);
	}
	static Range rep(int f,int t){
		return rep(f,t,1);
	}
	static Range rrep(int f,int t){
		return rep(f,t,-1);
	}

}

import java.io.*;
import java.util.*;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        N = sc.nextInt();
        A = sc.nextIntArray(N);
        Ans answer = solve();
        pw.println( answer.value );
        pw.println( answer.way.size() );
        for (int each : answer.way) {
            pw.println(each+1);
        }
        pw.flush();
    }

    static Ans solve() {
        long even = 0;
        for (int i = 0; i < N; i++) {
            if( i % 2 == 0 && A[i] > 0) {
                even += A[i];
            }
        }

        long odd = 0;
        for (int i = 0; i < N; i++) {
            if( i % 2 == 1 && A[i] > 0 ) {
                odd += A[i];
            }
        }

        if( even <= 0 && odd <= 0 ) {
            return case_0();
        }

        List<Integer> ways = new ArrayList<>();
        LinkedList<Long> list = new LinkedList<>();
        for (int i : A) {
            list.add((long) i);
        }

        // 一つ取ってevenに合わせる
        if( odd > even ) {
            list.removeFirst();
            ways.add(0);
        }

        while(list.size() > 1 ) {
            if( list.size() == 2 ) {
                list.removeLast();
                ways.add(1);

            } else {
                // plusだけを残す
                // ので、minusの場合はいきなり消す
                if( list.getFirst() < 0 ) {
                    // 二回操作してる
                    ways.add(0);
                    ways.add(0);
                    list.removeFirst(); // minus分
                    list.removeFirst(); // odd分

                } else {
                    long nextEven = list.get(2);
                    if( nextEven >= 0 ) {
                        long first = list.getFirst();
                        ways.add(1);
                        list.set(1, first + nextEven);
                        list.remove(2);
                        list.remove(0);

                    } else {
                        if( list.size() == 3 ) {
                            // 0 1 2 -> 0 1
                            list.removeLast();
                            ways.add(2);
                        } else {
                            // 0 1 2 3 -> 0 1 1+3 3 -> 0 1+3
                            long second = list.get(1);
                            long forth = list.get(3);
                            ways.add(2);
                            list.set(2, second + forth); //　どうせ使わないあたいなのだけど一応
                            list.remove(3);
                            list.remove(1);
                        }
                    }
                }
            }
        }
        return new Ans(list.getFirst(), ways);
    }

    static Ans case_0() {
        int max = Integer.MIN_VALUE;
        int max_index = -1;

        for (int i = 0; i < N; i++) {
            if( A[i] > max ) {
                max = A[i];
                max_index = i;
            }
        }

        List<Integer> ways = new ArrayList<>();
        // max_index以外を全部すてる
        // -> max_index個前に存在するのでそれを捨てる(way=0)
        // + N-max_index-1個後ろに存在するのでそれを捨てる(way=size-1)
        for (int i = 0; i < max_index; i++) {
            ways.add(0);
        }
        for (int i = 0; i < N-max_index-1; i++) {
            int size = N - max_index - i;
            ways.add(size-1);
        }

        return new Ans(max, ways);
    }

    static class Ans {
        long value;
        List<Integer> way;

        public Ans(long value, List<Integer> way) {
            this.value = value;
            this.way = way;
        }
    }

    static class FastScanner {

        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }

            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	int N;
	long[] a;
	long[] sum;
	int s = 0;

	ArrayList<Integer> ans = new ArrayList<>();

	//i=0,1,2
	void erase(int i) {
		ans.add(i);
		if (s + i == N - 1) {
			--N;
			return;
		}
		if (i == 0) {
			s += 1;
			return;
		} else if (i == 1) {
			a[s + 2] += a[s];
			s += 2;
		} else if (i == 2) {
			a[s + 3] += a[s + 1];
			a[s + 2] = a[s];
			s += 2;
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		N = sc.nextInt();
		a = new long[N];
		sum = new long[2];
		boolean[] f = new boolean[] { true, true };
		for (int i = 0; i < N; ++i) {
			a[i] = sc.nextLong();
			if (a[i] > 0)
				sum[i % 2] += a[i];
			f[i % 2] &= a[i] < 0;
		}
		if (f[0] && f[1]) {
			long max = -Long.MAX_VALUE / 3;
			int idx = -1;
			for (int i = 0; i < N; ++i) {
				if (max < a[i]) {
					idx = i;
					max = a[i];
				}
			}
			while (a[s] != max) {
				erase(1);
			}
			while (true) {
				if (s == N - 1)
					break;
				if (s == N - 2) {
					erase(1);
					break;
				}
				erase(2);
			}
			System.out.println(max);
		} else {
			if (sum[0] < sum[1]) {
				erase(0);
			}
			while (true) {
				if (s == N - 1)
					break;
				if (s == N - 2) {
					erase(1);
					break;
				}
				if (a[s] < 0) {
					erase(0);
					erase(0);
				} else if (a[s + 2] > 0) {
					erase(1);
				} else if (a[s + 2] <= 0) {
					erase(2);
				}
			}
			System.out.println(Math.max(sum[0], sum[1]));
		}
		System.out.println(ans.size());
		for (int v : ans) {
			System.out.println(v + 1);
		}
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.*;
import java.util.stream.Stream;

public class Main{

    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);

        int n = Integer.parseInt(sc.nextLine());
        int[] a = Stream.of(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

        boolean allneg = true;
        for(int i=0; i<n; i++){
            if(a[i]>=0) allneg = false;
        }

        ArrayList<Integer> ans = new ArrayList<>();
        long max = -10_000_000_000_000L;

        if(!allneg){
            boolean[][] mi = new boolean[2][n/2+1];
            long[] scr = new long[2];
            for(int i=0; i<2; i++){
                for(int j=i; j<n; j+=2){
                    if(a[j]<0){
                        mi[i][j/2] = true;
                    }else{
                        scr[i] += a[j];
                    }
                }
            }
            int idx = (scr[0] > scr[1])? 0:1;
            max = scr[idx];
            //
            int size = n;

            if(idx==1){
                ans.add(1);
                size -= 1;
            }

            if(size%2==0){
                ans.add(size);
                size -= 1;
            }

            for(int i=n/2; i>=0; i--){
                if(mi[idx][i]){
                    int t = i*2+1;
                    ans.add(t);
                    if(t == 1){
                        ans.add(t);
                    }else if(t == size){
                        ans.add(t-1)
                    }
                    size -= 2;
                }
            }

            while(size>1){
                ans.add(2);
                size -= 2;
            }
        }else{
            int idx = 0;
            for(int i=0; i<n; i++){
                if(a[i] > max){
                    max = a[i];
                    idx = i;
                }
            }
            for(int i=0; i<idx; i++){
                ans.add(1);
            }
            for(int i=n-idx; i>1; i--){
                ans.add(i);
            }
        }

        System.out.println(max);
        System.out.println(ans.size());
        for(int i=0; i<ans.size(); i++){
            System.out.println(ans.get(i));
        }
    }
}

import java.io.IOException;
