					s.set(p, s.get(p-1) + s.get(p+1));
					s.remove(p+1);
					s.remove(p-1);
					e.set(p, true);
					e.remove(p+1);
					e.remove(p-1);

					op.append(p+1+"\n");
					cnt++;
					p = Math.max(1, p-1);
				}
				else if(!e.get(p-1) && !e.get(p+1)){
