public class Main {
  private static void solve() {
    int n = ni();
    int[] a = na(n);

    int[] p = new int[n / 2 + (n % 2 == 1 ? 1 : 0)];
    int[] q = new int[n / 2];

    for (int i = 0; i < n; i ++) {
      if (i % 2 == 0) {
        p[i / 2] = a[i];
      } else {
        q[i / 2] = a[i];
      }
    }

    long max1 = 0;
    long max2 = 0;
    for (int v : p) {
      if (v > 0) max1 += v;
    }
    for (int v : q) {
      if (v > 0) max2 += v;
    }

    List<Integer> list = new ArrayList<>();
    LinkedList<Integer> l = new LinkedList<>();
    for (int v : a) {
      l.add(v);
    }

    long max = max1;
    if (max1 < max2) {
      list.add(1);
      l.remove(0);
      max = 2;
    }

    boolean flg = true;
