      flg = false;
      for (int i = 1; i < l.size(); i += 2) {
        if (l.get(i) < 0) {
          list.add(i + 1);
          l.set(i, l.get(i + 1) + l.get(i - 1));
          l.remove(i - 1);
          l.remove(i);
          flg = true;
          break;
        }
      }
    }

