        while (l < N && A[l] <= 0)
        {
            l += 2;
        }
        while (r >= 0 && A[r] <= 0)
        {
            r -= 2;
        }
        if (l > r)
        {
            return;
        }

        var L = l;
        var M = (r + 2 - l) / 2;
        var B = M.MakeArray(i => A[L + i * 2]);

        var gaps = new List<int>();
        {
            var gap = 0;
            sum += B[0];
            for (var i = 1; i < M; i++)
            {
                if (B[i] < 0)
                {
                    gap++;
                }
                else
                {
                    sum += B[i];
                    gaps.Add(gap);
                    gap = 0;
                }
            }
            Debug.Assert(gap == 0);
