    class BothSidesMerger
    {
        static List<int> hist = new List<int>();
        static int res = 0;

        public static void Main(string[] args)
        {
            Console.ReadLine();
            Search(Console.ReadLine().Split(' ').Select(str => int.Parse(str)).ToList());

            Console.WriteLine(res);
            Console.WriteLine(hist.Count);
            Console.WriteLine(string.Join("\r\n", hist));
        }

        static void Search(List<int> left)
        {
            if(left.Count > 3)
            {
                int max = 0;
                int ind = 0;
                for(int i = 1;left.Count - 1 > i; i++)
                {
                    int sum = left[i - 1] + left[i + 1];
                    if(i == 1 || sum > max)
                    {
                        max = sum;
                        ind = i;
                    }
                }

                left[ind] = max;
                left.RemoveAt(ind - 1);
                left.RemoveAt(ind);
                hist.Add(ind + 1);
                Search(left);
                return;
            }
            if(left.Count > 1)
            {
                int min = 0, ind = 0;
                for (int i = 0; left.Count > i; i++)
                {
                    if(i == 0 || left[i] < min)
                    {
                        min = left[i];
                        ind = i;
                    }
                }
                left.RemoveAt(ind);
                hist.Add(ind + 1);
                Search(left);
                return;
            }

            res = left[0];
        }
    }
}

