public sealed partial class Program
{
    Summary Summarize(long[] A, int index)
    {
        var N = A.Length;

        var s = new Summary()
        {
            Index = index,
            Count = N,
            Sum = 0L,
            Max = A[index],
            MaxIndex = index,
            AllNegative = true
        };

        for (var i = index; i < N; i += 2)
        {
            if (A[i] > 0)
            {
                s.Sum += A[i];
                s.AllNegative = false;
            }

            if (A[i] > s.Max)
            {
                s.Max = A[i];
                s.MaxIndex = i;
            }
        }

        return s;
    }

    List<int> Instr(long[] A, Summary summary)
    {
        var N = A.Length;
        var output = new List<int>();

        if (summary.AllNegative)
        {
            var len = N;

            for (var i = 0; i < summary.MaxIndex; i++)
            {
                output.Add(1);
                len--;
            }

            while (len >= 2)
            {
                output.Add(len);
                len--;
            }

            return output;
        }
        else
        {
            var i = 0;
            var len = N;

            while (i < summary.Index)
            {
                output.Add(1);
                len--;
                i++;
            }

            // 左端にある非負整数を消去する。
            while (i + 1 < N && A[i] <= 0)
            {
                output.Add(1);
                output.Add(1);
                len -= 2;
                i += 2;
            }

