                {
                    output.Add(2);
                    len -= 2;
                    i += 2;
                }
                else if (i + 3 < N && A[i + 2] <= 0)
                {
                    output.Add(3);
                    len -= 2;
                    i += 2;
                }
                else
                {
                    break;
                }
            }

            while (len > 1)
            {
                output.Add(len);
                len--;
            }
            return output;
        }
    }

