			var pn = n.Previous.Previous;
			if (!n.Value) { del.Add(i); l.RemoveLast(); }
			else if (pn.Value)
			{
				del.Add(i - 1);
				l.RemoveLast();
				l.RemoveLast();
			}
			else
			{
				del.Add(i - 2);
				if (l.Count == 3) l.RemoveFirst();
				else
				{
					l.RemoveLast();
					l.RemoveLast();
					l.Last.Value = true;
				}
			}
		}
		if (l.First.Value == l.Last.Value) throw new IOException();
		del.Add(l.First.Value ? 1 : 0);
		WriteLine(del.Count);
		foreach (var i in del) WriteLine(i + 1);
	}
}

