using MethodImplAttribute = System.Runtime.CompilerServices.MethodImplAttribute;
using MethodImplOptions = System.Runtime.CompilerServices.MethodImplOptions;

public static class P
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var a = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var b = Console.ReadLine().Split().Select(int.Parse).ToArray();
        //普通のxor+繰り上がり
        long res = 0;
        for (int i = 28; i >= 0; i--)
        {
            long dig = 0;
            long zeroCountA = a.Count(x => (x >> i & 1) == 0);
            long oneCountA = n - zeroCountA;
            long zeroCountB = a.Count(x => (x >> i & 1) == 0);
            long oneCountB = n - zeroCountB;
            dig ^= zeroCountA * oneCountB & 1;
            dig ^= zeroCountB * oneCountA & 1;
            //繰り上がり
            for (int j = 0; j < n; j++)
            {
                a[j] &= (1 << i) - 1;
                b[j] &= (1 << i) - 1;
            }
            Array.Sort(a);
            Array.Sort(b);
            int bInd = 0;
            for (int aInd = a.Length - 1; aInd >= 0; aInd--)
            {
                while (bInd < b.Length && a[aInd] + b[bInd] < (1 << i))
                    bInd++;
                dig ^= (n - bInd) & 1;
            }
            res ^= dig << i;
        }
        Console.WriteLine(res);
    }
}

