    readonly int mod = 1000000007;


    void solve()
    {
        int N = cin.nextint;
        var L = cin.scanlong.ToList();
        var SB = new StringBuilder();
        int cnt = 0;
        while (true)
        {
            if (L.Count == 1)
            {
                //cnt++;
                WriteLine(L[0]);
                break;
            }
            else if (L.Count == 2)
            {
                if (L[0] < L[1])
                {
                    SB.AppendLine("1");
                    L.RemoveAt(0);
                }
                else
                {
                    SB.AppendLine("2");
                    L.RemoveAt(1);
                }
                cnt++;
            }
            else
            {
                if (L[0] <= 0 && L[L.Count -1] <= 0)
                {
                    if (L[0] < L[L.Count - 1])
                    {
                        SB.AppendLine("1");
                        L.RemoveAt(0);
                    }
                    else
                    {
                        SB.AppendLine(L.Count.ToString());
                        L.RemoveAt(L.Count - 1);
                    }
                }
                else if(L[0] <= 0)
                {
                    SB.AppendLine("1");
                    L.RemoveAt(0);
                }
                else if (L[L.Count - 1] <= 0)
                {
                    SB.AppendLine(L.Count.ToString());
                    L.RemoveAt(L.Count - 1);
                }
                else
                {
                    int id = -1;
                    long value = 0;
                    for (int i = 1; i < L.Count - 1; i++)
                    {
                        var tmp = L[i - 1] + L[i + 1] - L[i];
                        if (tmp > value)
                        {
                            value = tmp;
                            id = i;
                        }
                    }
                    if (id == -1)
                    {
                        if (L[0] < L[L.Count - 1])
                        {
                            SB.AppendLine("1");
                            L.RemoveAt(0);
                        }
                        else
                        {
                            SB.AppendLine(L.Count.ToString());
                            L.RemoveAt(L.Count - 1);
                        }
                    }
                    else
                    {
                        L[id] = L[id - 1] + L[id + 1];
                        L.RemoveAt(id + 1);
                        L.RemoveAt(id - 1);
                        SB.AppendLine((id + 1).ToString());
                    }
                }
                cnt++;
            }
            //WriteLine(string.Join(" ", L.ToArray()));
        }
        WriteLine(cnt);
        Write(SB);
    }

}

class Scanner
{
    string[] s; int i;
    char[] cs = new char[] { ' ' };
    public Scanner() { s = new string[0]; i = 0; }
    public string[] scan { get { return ReadLine().Split(); } }
    public int[] scanint { get { return Array.ConvertAll(scan, int.Parse); } }
    public long[] scanlong { get { return Array.ConvertAll(scan, long.Parse); } }
    public double[] scandouble { get { return Array.ConvertAll(scan, double.Parse); } }
    public string next
    {
        get
        {
            if (i < s.Length) return s[i++];
            string st = ReadLine();
            while (st == "") st = ReadLine();
            s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
            i = 0;
            return next;
        }
    }
    public int nextint { get { return int.Parse(next); } }
    public long nextlong { get { return long.Parse(next); } }
    public double nextdouble { get { return double.Parse(next); } }
}

