    }
    void Calc(){
        int N = re.i();
        long max = -10000000000;
        int argmax = 0;
        long odd = 0;
        long even = 0;
        long count = 0;
        long[] A = re.la();
        for(int i=0;i<N;i++){
            if(max < A[i]){
                max = A[i];
                argmax = i;
            }
            if(i % 2 == 0){
                if(A[i] >= 0){
                    even += A[i];
                }
            }
            else{
                if(A[i] >= 0){
                    odd += A[i];
                }
            }
        }
        bool[] Get = new bool[N];
        if(max < 0){
            Get[argmax] = true;
            count = A[argmax];
        }
        else if(odd > even){
            for(int i=1;i<N;i+=2){
                if(A[i] >= 0){
                    Get[i] = true;
                    count += A[i];
                }
            }
        }
        else{
            for(int i=0;i<N;i+=2){
                if(A[i] >= 0){
                    Get[i] = true;
                    count += A[i];
                }
            }
        }
        Console.WriteLine(count);
        count = 0;
        int p = 0;
        for(;p<N;p++){
            if(!Get[p]){
                sb.Append("1\n");
                count++;
            }
            else{
                break;
            }
        }
        p++;
        for(;p<N;p+=2){
            if(p+1<N && !Get[p+1]){
                count++;
                sb.Append("3\n");
            }
            else{
                count++;
                sb.Append("2\n");
            }
        }
        Console.WriteLine(count);
    }
