{
    void Solve(long[] A, List<int> output, out int l, out int r, out long sum)
    {
        var N = A.Length;
        if (N % 2 == 0)
        {
            N--;
        }
        Debug.Assert(N % 2 == 1);

        sum = 0;
        // A の偶数番目の要素で最初に正のものの番号
        l = 0;
        // A の偶数番目の要素で最後に正のものの番号
        r = N - 1;
        while (l < N && A[l] <= 0)
        {
            l += 2;
        }
        while (r >= 0 && A[r] <= 0)
        {
            r -= 2;
        }
        if (l >= r)
        {
            return;
        }

        var L = l;

        var M = (r + 2 - l) / 2;
        var B = M.MakeArray(i => A[L + i * 2]);

        var gaps = new List<int>();
        {
            var gap = 0;
            sum += B[0];
            for (var i = 1; i < M; i++)
            {
                if (B[i] < 0)
                {
                    gap++;
                }
                else
                {
                    sum += B[i];
                    gaps.Add(gap);
                    gap = 0;
                }
            }
            Debug.Assert(gap == 0);
        }

        //Console.WriteLine($"l={l} r={r} M={M} B=({B.Intercalate(", ")}) gap=({gaps.Intercalate(", ")}) sum={sum}");

        {
            var len = A.Length;

            for (var i = 0; i < L; i++)
            {
                WriteLine(1);
                len--;
            }

            foreach (var g in gaps)
            {
                for (var i = 0; i < g; i++)
                {
                    output.Add(3);
                    len-=2;
                }

                output.Add(2);
                len-=2;
            }

            while (len > 1)
            {
                output.Add(2);
                len--;
            }
        }
    }

    public void EntryPoint()
    {
        var I = _scanner;
        var N = I.N();
