  var id = 0, mx = a[0];
  for(var i = 1; i < n; i++){
    if(mx < a[i])mx = a[i], id = i;
  }
  var ans = [mx,n-1];
  for(var i = n; i--;){
    if(i === id)continue;
    if(i < id)ans.push(1);
    else ans.push(i+1);
  }
  return ans.join("\n");
}

