func main() {
	var N int
	fmt.Scanf("%d", &N)
	a := make([]int, N + 1)
	a[N] = -1145141919
	for i := 0; i < N; i++ {
		fmt.Scanf("%d", &a[i])
	}
	ret, f := [...]uint64{0, 0}, [...]bool{true, true}
	s, sl := [...]int{0, 1}, [...]int{1 - N % 2, N % 2}
	maxmini := N
	for j := 0; j < 2; j++ {
		for i := 0; i < N / 2 + N % 2 * (1 - j); i++ {
			if a[2 * i + j] >= 0 {
				ret[j] += uint64(a[2 * i + j])
				if f[j] {
					f[j] = false
				}
			} else if f[j] {
				s[j] += 2
				if a[2 * i + j] > a[maxmini] {
					maxmini = 2 * i + j
				}
			}
		}
		for i := N / 2 + N % 2 * (1 - j) - 1; i >= 0 && a[2 * i + j] < 0; i-- {
			sl[j] += 2
		}
	}
	if f[0] && f[1] {
		fmt.Printf("%d\n", a[maxmini])
		fmt.Printf("%d\n", N - 1)
		for i := 0; i < N - 1 - maxmini; i++ {
			fmt.Printf("%d\n", N - i)
		}
		for i := 0; i < maxmini; i++ {
			fmt.Printf("1\n")
		}
		return
	}
	best := 0
	if ret[0] < ret[1] {
		best = 1
	}
	fmt.Printf("%d\n", ret[best])
	fmt.Printf("%d\n", sl[best] + s[best] + (N - sl[best] - s[best] - 1) / 2)
	for i := 0; i < sl[best]; i++ {
		fmt.Printf("%d\n", N - i)
	}
	for i := 0; i < s[best]; i++ {
		fmt.Printf("1\n")
	}
	for i := 0; i < (N - sl[best] - s[best] - 1) / 2; i++ {
		if a[s[best] + 2 * i + 2] >= 0 {
			fmt.Printf("2\n")
		} else {
			fmt.Printf("3\n")
		}
	}
	return
}

