func Solve() {
  var N int
  var A []int
  NextInt(&N)
  NextIntVec(&A)
  S := make([]int, 0)
  M := MaxInt(A...)
  if M <= 0 {
    Write(M)
    Write(N - 1)
    i := N - 1
    for ; A[i] < M; i-- { S = append(S, i + 1) }
    for j := 0; j < i; j++ { S = append(S, 1) }
    for _, s := range S { Write(s) }
    return
  }
  O, E := 0, 0
  for i := 0; i < N; i += 2 { O += MaxInt(A[i], 0) }
  for i := 1; i < N; i += 2 { E += MaxInt(A[i], 0) }
  F := func (s int) {
    i := s
    for ; i >= 0; i -= 2 {
      if A[i] >= 0 { continue }
      j := i
      for ; j >= 0 && A[j] < 0; j -= 2 { S = append(S, j + 1) }
      if j >= 0 {
        if i + 2 < len(A) { A[j] += A[i + 2] }
        S = append(S, j + 1)
      } else {
        S = append(S, 1)
      }
      A = append(A[:MaxInt(j, 0)], A[i + 2:]...)
      i = j
    }
    if i == -1 && (len(S) == 0 || S[len(S) - 1] != 1) {
      S = append(S, 1)
      A = A[1:]
    }
  }
  if O >= E {
    F(((N - 1) / 2) * 2)
  } else {
    F((N / 2) * 2 - 1)
  }
  for i := 0; i < len(A) / 2; i++ { S = append(S, 2) }
  Write(MaxInt(O, E))
  Write(len(S))
  for _, s := range S { Write(s) }
}

