func Solve() {
  var N int
  var A []int
  NextInt(&N)
  NextIntVec(&A)
  S := make([]int, 0)
  M := MaxInt(A...)
  if M <= 0 {
    Write(M)
    Write(N - 1)
    i := N - 1
    for ; A[i] < M; i-- { S = append(S, i + 1) }
    for j := 0; j < i; j++ { S = append(S, 1) }
    for _, s := range S { Write(s) }
    return
  }
  O, E := 0, 0
  for i := 0; i < N; i += 2 { O += MaxInt(A[i], 0) }
  for i := 1; i < N; i += 2 { E += MaxInt(A[i], 0) }
  n := N
  F := func (s int) {
    i := s
    for ; i >= 0; i -= 2 {
      if A[i] >= 0 { continue }
      j := i
      for ; j >= 0 && A[j] < 0; j -= 2 {
        S = append(S, j + 1);
        n--
        if j != 0 && j != n - 1 { n-- }
      }
      if j >= 0 {
        S = append(S, j + 2)
        n--
        if j != n - 1 { n-- }
      } else {
        S = append(S, 1)
        n--
      }
      i = j
    }
    if i == -1 && (len(S) == 0 || S[len(S) - 1] != 1) {
      S = append(S, 1)
      A = A[1:]
      n--
    }
  }
  if O >= E {
    F(((N - 1) / 2) * 2)
  } else {
    F((N / 2) * 2 - 1)
  }
  for i := 0; i < n / 2; i++ { S = append(S, 2) }
  Write(MaxInt(O, E))
  Write(len(S))
  for _, s := range S { Write(s) }
}

func main() {
  Solve()
  Output()
}

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt(A ...*int) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.Atoi(L[i])
  }
}
func NextIntVec(A *[]int) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]int, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.Atoi(l)
  }
}
func NextFloat(A ...*float64) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.ParseFloat(L[i], 64)
  }
}
func NextFloatVec(A *[]float64) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]float64, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}
func MaxInt(A ...int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}
func AbsInt(x int) int {
  if x < 0 { x = -x }
  return x
}

