        return one_based_accumulate(idx+1);
    }

private:
    T[] t;

    //1-based
    void one_based_add(size_t idx, in ref T v) {
        if(idx >= t.length) {
            return;
        }
        t[idx] = f(t[idx], v);
        one_based_add(idx + (idx & (-idx)), v);
    }
    T one_based_accumulate(size_t idx) {
        if(idx == 0) {
            return t[0];
        } else {
            return f(one_based_accumulate(idx - (idx & (-idx))), t[idx]);
        }
    }
}
