        as.maxElement.writeln;
        (N-1).writeln;
        long i = as.enumerate.maxElement!"a.value".index;
        foreach_reverse(j; i+1..N) {
            writeln(j+1);
        }
        foreach(j; 0..i) {
            writeln(0+1);
        }
        return;
    }

    long[] xs = as.enumerate.filter!"a.value>=0".map!"a.index".filter!"a%2==0".array.to!(long[]);
