//最大流、O(|V||E|^2)
template Flow_Dinic() {
    class Edge {
    public:
        this(long to, long capacity) {
            this.to = to;
            this.capacity = capacity;
        }
        long to;
        long capacity;
        Edge reverse;
    }

    //gを残余グラフにする
    void residualise(ref Edge[][] g) {
        foreach(u; iota(g.length)) {
            foreach(e; g[u]) {
                if(e.capacity != 0) {
                    e.reverse = new Edge(u, 0);
                    e.reverse.reverse = e;
                    g[e.to] ~= e.reverse;
                }
            }
        }
    }

    const long INF = long.max / 2;

    //gは残余グラフ
    //gは計算の結果書き換わる
    long solve(Edge[][] g, long s, long t) {
        long ret;
        while(true) {
            auto level = new long[](g.length);
            level[] = INF;
            auto q = DList!long(s);
            level[s] = 0;
            //level graph
            auto lg = new Edge[][](g.length, 0);
            while(!q.empty()) {
                auto u = q.front();
                q.removeFront();
                if(u == t) {
                    break;
                }
                foreach(e; g[u]) {
                    if(e.capacity > 0 && level[e.to] >= level[u] + 1) {
                        level[e.to] = level[u] + 1;
                        q.insertBack(e.to);
                        lg[u] ~= e;
                    }
                }
            }
            if(level[t] == INF) {
                break;
            }
            auto iter = new long[](g.length);
            long dfs(long u, long c_min) {
                if(u == t) {
                    return c_min;
                }
                foreach(i; iota(iter[u], lg[u].length)) {
                    iter[u] = i;
                    long f = dfs(lg[u][i].to, min(c_min, lg[u][i].capacity));
                    if(f > 0) {
                        lg[u][i].capacity -= f;
                        lg[u][i].reverse.capacity += f;
                        return f;
                    }
                }
                return 0;
            }
            while(true) {
                long f = dfs(s, INF);
                if(f == 0) {
                    break;
                }
                ret += f;
            }
        }
        return ret;
    }
}

enum real eps = 1e-10;

enum long mod = 1_000_000_000 + 7;

auto solve(long[] a, long m) {
  long[] ord;
  if(m == 0 && a[0] < 0) {
    ord ~= 0;
    a = a[1..$];
    m = 1;
  }
  long idx = m;
  while(idx < a.length) {
    if(a[idx] < 0) {
      ord ~= idx;
      if(idx == a.length) {
        a = a[0..$-1];
      } else {
        a = a[0..idx-1] ~ (a[idx-1] + a[idx+1]) ~ a[idx+2..$];
      }
    } else {
      idx += 2;
    }
  }
  long sum;
  foreach(i; iota(a.length)) {
    if(i % 2 == m) {
      sum += a[i];
    }
  }
  foreach(i; iota(1-m, a.length, 2).retro) {
    ord ~= i;
  }
  return tuple(sum, ord);
}

void main(){
  auto n = readLong();
  auto a = readLongs();
  auto ans = max(solve(a, 0), solve(a, 1));
  writeln(ans[0]);
  writeln(ans[1].length);
  ans[1].each!(x => writeln(x+1));
}

