enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

void main() {
    long N;
    scanln(N);
    long[] as = readln.split.to!(long[]);
    if (as.all!"a<0") {
        as.maxElement.writeln;
        (N-1).writeln;
        long i = as.enumerate.maxElement!"a.value".index;
        foreach_reverse(j; i+1..N) {
            writeln(j+1);
        }
        foreach(j; 0..i) {
            writeln(0+1);
        }
        return;
    }

    long[] xs = as.enumerate.filter!"a.value>=0".map!"a.index".filter!"a%2==0".array.to!(long[]);
    long[] ys = as.enumerate.filter!"a.value>=0".map!"a.index".filter!"a%2==1".array.to!(long[]);
    if (xs.map!(x => as[x]).sum < ys.map!(y => as[y]).sum) {
        xs = ys;
    }
    assert(!xs.empty);

    long[] ts;
    long[][] uss;
    foreach(i; 0..N) {
        if (i==xs.front) break;
        ts ~= i;
    }
    foreach_reverse(i; 0..N) {
        if (i==xs.back) break;
        ts ~= i;
    }
    foreach(i; 1..xs.length) {
        long x = xs[i-1];
        long y = xs[i];
        uss ~= [x, y];
    }

    xs.map!(x => as[x]).sum.writeln;
    writeln(ts.length + uss.map!(us => (us[1]-us[0])/2).sum);
    long[] bs = N.iota.array;
    foreach(t; ts) {
        long i = bs.countUntil(t);
        assert(i >= 0);
        writeln(i+1);
        if (i==0 || i==bs.length-1) {
            bs = bs[0..i] ~ bs[i+1..$];
        }
    }
    foreach(us; uss) {
        long x = us[0];
        long y = us[1];
        long ix = bs.countUntil(x);
        long iy = bs.countUntil(y);
        assert(ix>=0 && iy>=0);
        foreach_reverse(j; ix+1..(ix+iy)/2+1) {
            writeln(j+1);
        }
        bs = bs[0..ix] ~ bs[iy..$];
    }
}

