	foreach (i; 0..n) scanf("%d", &a[i]);
	int p = 0; long val = -1;
	foreach (parity; 0..2) {
		long sum = 0;
		foreach (i; 0..n) {
			if ((i&1) != parity) continue;
			if (a[i] >= 0) sum += a[i];
		}
		if (val < sum) {
			p = parity;
			val = sum;
		}
	}
	writeln(val);
	int[] ans;
	int len = n;
	bool last = ((n-1)&1) == p;
	foreach_reverse (i; 0..n) {
		if ((i&1) != p) continue;
		if (a[i] < 0) {
			ans ~= i+1;
			if (last || i == 0) len--;
			else len -= 2;
		} else last = false;
	}
	if (p) ans ~= 1, len--;
	foreach (i; 0..len/2) ans ~= 2;
	writeln(ans.length);
	foreach (i; ans) writeln(i);
}

