void main(){
  auto n = readLong();
  auto a = readLongs();

  long sum_max;
  long i_max, j_max;
  foreach(i; iota(n+1)) {
    long tmp;
    foreach(j; iota(n-i)) {
      if(j%2 == 0){ 
        tmp += a[i+j];
        if(sum_max < tmp) {
          i_max = i;
          j_max = j;
          sum_max = tmp;
        }
      }
    }
  }
  writeln(sum_max);
  long[] ans;
  foreach(i; iota(i_max + j_max+1, n).retro) {
    ans ~= i+1;
  }
  foreach(i; iota(j_max/2).retro) {
    ans ~= 1 + i_max + 1 + i*2;
  }
  foreach(i; iota(i_max).retro) {
    ans ~= i+1;
  }
  writeln(ans.length);
  foreach(ai; ans) {
    writeln(ai);
  }
}

