  auto ans = max(solve(a, 0), solve(a, 1));
  if(a.all!(x => x < 0)) {
    ans = solve_neg(a);
  }
  writeln(ans[0]);
  writeln(ans[1].length);
  ans[1].each!(x => writeln(x+1));
}

