import std.stdio, std.array, std.string, std.conv, std.algorithm;
import std.typecons, std.range, std.random, std.math, std.container;
import std.numeric, std.bigint, core.bitop, std.bitmanip;

void main() {
    immutable long INF = 1L << 59;
    auto N = readln.chomp.to!int;
    auto A = readln.split.map!(to!long).array;


    Tuple!(long, int[]) solve(long[] X) {
        int n = X.length.to!int;
        int[] ans;
        long val;

        if (X.map!(x => x <= 0).all) {
            long maxv = -INF;
            int maxi = -1;
            for (int i = 0; i < X.length.to!int; i += 2) {
                if (X[i] > maxv) maxv = X[i], maxi = i;
            }
            foreach_reverse (i; maxi+1..X.length.to!int) ans ~= i;
            foreach (i; 0..maxi) ans ~= 1;
            return tuple(maxv, ans);
        }

        for (int i = n - 1; i > 0; i -= 2) {
            if (X[i] > 0) break;
            ans ~= [i+1, i];
            X.popBack;
            X.popBack;
            n -= 2;
        }

        for (int i = 0; i < n - 1; ) {
            if (X[i] > 0) break;
            ans ~= [1, 1];
            X.popFront;
            X.popFront;
            n -= 2;
        }

        while (X.length > 1) {
            if (X[2] > 0) {
                X[0] += X[2];
                X = X.remove(1);
                X = X.remove(1);
                ans ~= 2;
            } else {
                X = X.remove(1);
                X = X.remove(1);
                ans ~= 3;
             }
        }

        return tuple(X[0], ans);
    }


    auto B = A.dup;
    auto C = A.dup;
    int[] ansB, ansC;

    if (N % 2 == 0) {
        B.popBack;
        C.popFront;
        ansB ~= N;
        ansC ~= 1;
    } else {
        C.popFront;
        C.popBack;
        ansC ~= N;
        ansC ~= 1;
    }

    auto retB = solve(B);
    auto retC = solve(C);
    auto ans = retB >= retC ? retB : retC;
    if (retB >= retC) ans[1] = ansB ~ ans[1];
    else  ans[1] = ansC ~ ans[1];

    ans[0].writeln;
    ans[1].length.writeln;
    ans[1].each!writeln;
}

import std.algorithm;
import std.array;
import std.conv;
import std.range;
import std.stdio;
import std.string;
import std.typecons;

void solve (int n)
{
	readln;
	auto a = readln.splitter.map !(to !(long)).array;
	long res = long.min;
	int best;
	foreach (b; 0..2)
	{
		auto list = a.drop (b).stride (2);
		auto filtered = list.filter !(q{a >= 0});
		auto cur = filtered.empty ? list.reduce !(max) : filtered.sum;
		if (res < cur)
		{
			res = cur;
			best = b;
		}
	}
	writeln (res);

	int [] history;
	auto list = a.drop (best).stride (2);
	auto filtered = list.filter !(q{a >= 0});
	if (filtered.empty)
	{
		auto m = list.reduce !(max);
		auto pos = a.countUntil (m).to !(int);
		foreach_reverse (i; pos + 1..n)
		{
			history ~= i;
		}
		foreach (i; 0..pos)
		{
			history ~= 0;
		}
	}
	else
	{
		if (best)
		{
			history ~= 0;
			a.popFront ();
		}
		while (a.front < 0)
		{
			history ~= 0;
			a.popFront ();
			history ~= 0;
			a.popFront ();
		}
		int pos = 0;
		while (true)
		{
			int cur = pos + 2;
			while (cur < a.length && a[cur] < 0)
			{
				cur += 2;
			}
			if (cur >= a.length)
			{
				while (a.length > pos + 1)
				{
					history ~= a.length.to !(int) - 1;
					a.popBack ();
				}
				break;
			}
			int mid = (pos + cur) / 2;
			while (mid != pos)
			{
				debug {writeln (pos, " ", mid, " ", cur);}
				debug {writeln (a);}
				history ~= mid;
				a = a[0..mid - 1] ~ (a[mid - 1] + a[mid + 1]) ~
				    a[mid + 2..$];
				mid -= 1;
			}
			pos = mid;
		}
	}
	debug {writeln (a);}
	writefln ("%s\n%(%s\n%)", history.length, history.map !(q{a + 1}));
}

void main ()
{
	int n;
	while (readf (" %s", &n) > 0)
	{
		solve (n);
	}
}

