auto solve(long[] a, long m) {
  long[] ord;
  if(m == 0 && a[0] < 0) {
    ord ~= 0;
    a = a[1..$];
    m = 1;
  }
  long idx = m;
  while(idx < a.length) {
    if(a[idx] < 0) {
      ord ~= idx;
      if(idx == a.length-1) {
        a = a[0..$-1];
      } else {
        a = a[0..idx-1] ~ (a[idx-1] + a[idx+1]) ~ a[idx+2..$];
      }
    } else {
      idx += 2;
    }
  }
  long sum;
  foreach(i; iota(a.length)) {
    if(i % 2 == m) {
      sum += a[i];
    }
  }
  foreach(i; iota(1-m, a.length, 2).retro) {
    ord ~= i;
  }
  return tuple(sum, ord);
}

auto solve_neg(long[] a) {
  long max = a.reduce!max;
  bool f;
  long[] ord;
  long idx = a.length - 1;
  while(a[idx] != max) {
    ord ~= idx;
    --idx;
  }
  foreach(i; iota(idx)) {
    ord ~= i;
  }
  return tuple(max, ord);
}

