        self.need = need
        self.left = left
        self.right = right


class CellList:

    def __init__(self, n, s):
        self.n = n
        self.s = s
        w = Cell(0 in s, None, None)
        self.base = w
        for i in range(1, n):
            w = self.add_cell(w, i)
        self.tail = w
        self.history = []

    def add_cell(self, w, i):
        elt = Cell(i in self.s, w, w.right)
        w.right = elt
        if elt.right is not None:
            elt.right.left = elt
        return elt

    def select_element(self):
        if self.n == 0:
            return None
        if self.base.need is False:
            self.history.append(1)
            return self.base
        if self.tail.need is False:
            self.history.append(self.n)
            return self.tail

        i = 2
        w = self.base.right
        while w.need or w.left.need is False or w.right.need is False:
            w = w.right
            i += 1

        self.history.append(i)
        return w

    def delete_cell(self):
        m = self.select_element()
        if m.left is None:
            self.base = m.right
            self.base.left = None
        elif m.right is None:
            self.tail = m.left
            self.tail.right = None
        else:
            m.need = True
            m.left = m.left.left
            m.right = m.right.right
            if m.left is None:
                self.base = m
            else:
                m.left.right = m
            if m.right is not None:
                m.right.left = m
            self.n -= 1
        self.n -= 1


