use std::cmp;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.read();
    let a: Vec<i64> = sc.read_vec(n);

    let mut odd = 0;
    let mut even = 0;
    for i in 0..n {
        if a[i] < 0 {
            continue;
        } else if i % 2 == 0 {
            even += a[i];
        } else {
            odd += a[i];
        }
    }

    let ans = cmp::max(odd, even);
    if ans == 0 {
        let mut max_pos = 0;
        for i in 0..n {
            if a[max_pos] < a[i] {
                max_pos = i;
            }
        }
        println!("{}", a[max_pos]);
        println!("{}", n - 1);
        for i in ((max_pos + 1)..n).rev() {
            println!("{}", i + 1);
        }
        for _ in 0..max_pos {
            println!("1");
        }
    } else {
        println!("{}", ans);
        let c = construct(&a, ans == even);
        println!("{}", c.len());
        for &c in &c {
            println!("{}", c + 1);
        }
    }
}

fn construct(a: &Vec<i64>, is_even: bool) -> Vec<usize> {
    let n = a.len();
    let mut indices = vec![];
    for i in 0..n {
        if is_even != (i % 2 == 0) {
            continue;
        }
        if a[i] < 0 {
            continue;
        }
        indices.push(i);
    }

    let m = indices.len();
    let mut ans = vec![];
    for i in ((indices[m - 1] + 1)..n).rev() {
        ans.push(i);
    }

    for i in (0..(m - 1)).rev() {
        let front = indices[i];
        let back = indices[i + 1];
        let d = back - front;
        for t in (1..(d / 2 + 1)).rev() {
            ans.push(front + t);
        }
    }

    for _ in 0..indices[0] {
        ans.push(0);
    }
    ans
}

