fn restore(l: usize, r: usize, dp: &[Vec<Dp>], ops: &mut Vec<usize>) {
    // dbg!((l, r));
    if l == r {
        return;
    }

    // dbg!(&dp[l][r]);
    let ans = &dp[l][r];
    restore(ans.end2, r, dp, ops);
