fn max_each_start(a: &Vec<i64>, start: usize) -> (usize, i64) {
    a.iter()
        .map(|e| *e)
        .skip(start)
        .enumerate()
        .filter(|&(i, _)| i % 2 == 0)
        .map(|(_, k)| k)
        .scan(0, |s, k| {
            *s += k;
            Some(*s)
        })
        .enumerate()
        .max_by(|&(_, k), &(_, l)| k.cmp(&l))
        .map(|(i, k)| (i + 1, k))
        .unwrap()
}

fn solve(a: &Vec<i64>) -> (i64, usize, usize) {
    let mut ret = (i64::min_value(), 0, 0);
    let n = a.len();

    // even
    let mut prev = -1;
    for i in 0..(n + 1) / 2 {
        let index = 2 * i;
        if prev < 0 {
            let v = max_each_start(a, index);
            if v.1 > ret.0 {
                ret.0 = v.1;
                ret.1 = index;
                ret.2 = v.0;
            }
        }
        prev = a[index];
    }

    // odd
    let mut prev = -1;
    for i in 0..n / 2 {
        let index = 2 * i + 1;
        if prev < 0 {
            let v = max_each_start(a, index);
            if v.1 > ret.0 {
                ret.0 = v.1;
                ret.1 = index;
                ret.2 = v.0;
            }
        }
        prev = a[index];
    }

    ret
}

fn main() {
    let n = read::<usize>();
    let a = read_vec::<i64>();
    assert_eq!(a.len(), n);

    let (m, start, len) = solve(&a);

    println!("{}", m);
    println!("{}", len - 1);
    for _ in 0..len-1 {
        // startの右を選ぶ
        // 1始まりに注意
        println!("{}", start + 2);
    }
}

