use std::cmp::max;

const INF: i64 = 1 << 50;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let odd = a
        .iter()
        .enumerate()
        .map(|(i, &a)| (max(a, 0), i))
        .filter(|t| t.1 % 2 == 1)
        .map(|t| t.0)
        .sum::<i64>();
    let even = a
        .iter()
        .enumerate()
        .map(|(i, &a)| (max(a, 0), i))
        .filter(|t| t.1 % 2 == 0)
        .map(|t| t.0)
        .sum::<i64>();

    let mut ans = vec![];
    if *a.iter().max().unwrap() < 0 {
        let i = a.iter().enumerate().max_by_key(|t| *t.1).unwrap().0;
        ans.push(i);
    } else if even > odd {
        for i in 0..n {
            if i % 2 == 0 && a[i] >= 0 {
                ans.push(i);
            }
        }
    } else {
        for i in 0..n {
            if i % 2 == 1 && a[i] >= 0 {
                ans.push(i);
            }
        }
    }

    assert!(ans.len() > 0);
    let mut operations = vec![];
    for i in 0..n {
        if i == ans[0] {
            break;
        }
        operations.push(0);
    }
    for i in 1..ans.len() {
        let prev = ans[i - 1];
        let cur = ans[i];
        let count = cur - prev - 1;
        assert_eq!(count % 2, 1);

        let t = (count + 1) / 2;
        for i in 0..t {
            operations.push(t - i);
        }
    }

    let count = n - (ans[ans.len() - 1] + 1);
    for i in 0..count {
        operations.push(count - i);
    }

    let sum = ans.iter().map(|&i| a[i]).sum::<i64>();
    println!("{}", sum);
    println!("{}", operations.len());
    for &o in operations.iter() {
        println!("{}", o + 1);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

