      aa: [i64; n],
    }

    let mut dp = vec![0; n];
    for i in 0..n {
        let a = aa[i];
        dp[i] = a;
        if i >= 1 {
            dp[i] = max(dp[i], dp[i-1]);
        }
        if i >= 2 {
            dp[i] = max(dp[i], dp[i-2] + a);
        }
    }

    let mut cur = n-1;
    let mut included = vec![false; n];
    loop {
        let a = aa[cur];
        if dp[cur] == a {
            included[cur] = true;
            break;
        }
        if dp[cur] == dp[cur-1] {
            cur -= 1;
            continue;
        }
        if dp[cur] == dp[cur-2] + a {
            included[cur] = true;
            cur -= 2;
            continue;
        }
        unreachable!();
    }
    puts!("{}\n", dp[n-1]);

    let mut left = 0;
    for i in 0..n {
        if included[i] {
            left = i;
            break;
        }
    }
    let mut right = 0;
    for i in 0..n {
        if included[i] {
            right = i;
        }
    }

    // debug!(left, right, included);

    let mut ops = vec![];
    for _ in 0..left {
        ops.push(1);
    }
    assert!((right-left)%2 == 0);
    for _ in 0..(right-left)/2 {
        ops.push(2);
    }
    for i in 0..(n-right-1) {
        ops.push(n-right-i);
    }

    puts!("{}\n", ops.len());
    for o in ops {
        puts!("{}\n", o);
    }
}

