fn stepping_sums(seq: &[i64], start: usize) -> Vec<i64> {
    seq.iter().enumerate()
        .map(|(i, &x)| if i % 2 == start { x } else { 0 })
        .lscan(0, |&acc, x| acc + x)
        .collect()
}

