fn main() {
    let n: usize = reads()[0];
    let a: Vec<i64> = reads();

    let (odd, odd_cnt, even, even_cnt) = {
        let mut odd = 0;
        let mut even = 0;
        let mut odd_cnt = 0;
        let mut even_cnt = 0;
        for i in 0..n {
            if i % 2 == 0 {
                even += max(0, a[i]);
                if a[i] > 0 {
                    even_cnt += 1;
                }
            } else {
                odd += max(0, a[i]);
                if a[i] > 0 {
                    odd_cnt += 1;
                }
            }
        }
        (odd, odd_cnt, even, even_cnt)
    };

    if even_cnt + odd_cnt == 0 {
        let m: i64 = *a.iter().max().unwrap();
        let mi = a.iter().position(|e| *e == m).unwrap();
        println!("{}", m);
        println!("{}", n - 1);
        for _ in 0..mi {
            println!("1");
        }
        for i in mi + 1..n {
            println!("{}", n - i + 1);
        }
        return;
    }

    let best = max(odd, even);
    let mut seq = vec![];

    let mut l = if (odd, odd_cnt) > (even, even_cnt) {
        seq.push(0);
        1
    } else {
        0
    };
    let mut r = n - 1;

    while a[l] < 0 {
        seq.push(0);
        seq.push(0);
        l += 2;
    }

    while l < r && ((r - l) % 2 != 0 || a[r] < 0) {
        seq.push(r - l);
        r -= 1;
    }

    assert!(l <= r);
    assert!((r - l) % 2 == 0);

    while l < r {
        if a[l + 2] >= 0 {
            seq.push(1);
            l += 2;
        } else {
            assert!(r - l >= 4);
            seq.push(2);
            l += 2
        }
    }

    println!("{}", best);
    println!("{}", seq.len());
    for s in seq {
        println!("{}", s + 1);
    }
}

