use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      aa: [i64; n],
    }

    let mut dp = vec![0; n];
    for i in 0..n {
        let a = aa[i];
        dp[i] = a;
        if i >= 1 {
            dp[i] = max(dp[i], dp[i-1]);
        }
        if i >= 2 {
            dp[i] = max(dp[i], dp[i-2] + a);
        }
    }

    let mut cur = n-1;
    let mut included = vec![false; n];
    loop {
        let a = aa[cur];
        if dp[cur] == a {
            included[cur] = true;
            break;
        }
        if dp[cur] == dp[cur-1] {
            cur -= 1;
            continue;
        }
        if dp[cur] == dp[cur-2] + a {
            included[cur] = true;
            included[cur-2] = true;
            cur -= 2;
            continue;
        }
        unreachable!();
    }
    puts!("{}\n", dp[n-1]);

    let mut left = 0;
    for i in 0..n {
        if included[i] {
            left = i;
            break;
        }
    }
    let mut right = 0;
    for i in 0..n {
        if included[i] {
            right = i;
        }
    }

    // debug!(left, right, included);

    let mut ops = vec![];
    for _ in 0..left {
        ops.push(1);
    }
    assert!((right-left)%2 == 0);
    for _ in 0..(right-left)/2 {
        ops.push(2);
    }
    for i in 0..(n-right-1) {
        ops.push(n-right-i);
    }

    puts!("{}\n", ops.len());
    for o in ops {
        puts!("{}\n", o);
    }
}

use std::cmp;
use std::collections::VecDeque;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.read();
    let a: Vec<i64> = (0..n).map(|_| sc.read()).collect();

    let mut odd = 0;
    let mut even = 0;
    for i in 0..n {
        if i % 2 == 0 {
            even += cmp::max(0, a[i]);
        } else {
            odd += cmp::max(0, a[i]);
        }
    }

    let mut all_negative = true;
    for i in 0..n {
        if a[i] >= 0 {
            all_negative = false;
        }
    }
    if all_negative {
        let mut max = 0;
        for i in 0..n {
            if a[max] < a[i] {
                max = i;
            }
        }

        println!("{}", a[max]);
        println!("{}", n - 1);
        let mut length = n;
        for i in 0..n {
            if i < max {
                println!("1");
                length -= 1;
            } else if i > max {
                println!("{}", length);
                length -= 1;
            }
        }
        return;
    }

    let mut ans = Vec::new();
    let mut q = VecDeque::from(a.clone());

    if odd > even {
        q.pop_front();
        ans.push(1);
    }

    loop {
        let head = q.pop_front().unwrap();
        if head >= 0 {
            q.push_front(head);
            break;
        } else {
            ans.push(1);
            ans.push(1);
            q.pop_front();
        }
    }

    while q.len() > 2 {
        let head = q.pop_front().unwrap();
        q.pop_front().unwrap();
        let next = q.pop_front().unwrap();
        if next >= 0 {
            ans.push(2);
            q.push_front(head + next);
        } else {
            ans.push(3);
            q.push_front(head);
        }
    }


    if q.len() == 2 {
        q.pop_back();
        ans.push(2);
    }

    let max = q.pop_front().unwrap();
    println!("{}", max);
    assert!(q.is_empty());
    assert_eq!(max, cmp::max(odd, even));
    println!("{}", ans.len());

    let mut check = VecDeque::from(a.clone());
    for v in &ans {
        let v = *v;
        println!("{}", v);
        assert!(v <= 3);
        if v == 1 {
            check.pop_front();
        } else if v == 2 {
            if check.len() == 2 {
                check.pop_back();
            } else {
                let a1 = check.pop_front().unwrap();
                check.pop_front();
                let a2 = check.pop_front().unwrap();
                check.push_front(a1 + a2);
            }
        } else if v == 3 {
            if check.len() == 3 {
                check.pop_back();
            } else {
                let a1 = check.pop_front().unwrap();
                let a2 = check.pop_front().unwrap();
                check.pop_front().unwrap();
                let a4 = check.pop_front().unwrap();

                check.push_front(a2 + a4);
                check.push_front(a1);
            }
        }
    }

    assert_eq!(check.len(), 1);
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use std::cmp::max;

const INF: i64 = 1 << 50;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let odd = a
        .iter()
        .enumerate()
        .map(|(i, &a)| (max(a, 0), i))
        .filter(|t| t.1 % 2 == 1)
        .map(|t| t.0)
        .sum::<i64>();
    let even = a
        .iter()
        .enumerate()
        .map(|(i, &a)| (max(a, 0), i))
        .filter(|t| t.1 % 2 == 0)
        .map(|t| t.0)
        .sum::<i64>();

    let mut ans = vec![];
    if max(even, odd) < 0 {
        let i = a.iter().enumerate().max_by_key(|t| *t.1).unwrap().0;
        ans.push(i);
    } else if even > odd {
        for i in 0..n {
            if i % 2 == 0 && a[i] >= 0 {
                ans.push(i);
            }
        }
    } else {
        for i in 0..n {
            if i % 2 == 1 && a[i] >= 0 {
                ans.push(i);
            }
        }
    }

    assert!(ans.len() > 0);
    let mut operations = vec![];
    for i in 0..n {
        if i == ans[0] {
            break;
        }
        operations.push(0);
    }
    for i in 1..ans.len() {
        let prev = ans[i - 1];
        let cur = ans[i];
        let count = cur - prev - 1;
        assert_eq!(count % 2, 1);

        let t = (count + 1) / 2;
        for i in 0..t {
            operations.push(t - i);
        }
    }

    let count = n - (ans[ans.len() - 1] + 1);
    for i in 0..count {
        operations.push(count - i);
    }

    let sum = ans.iter().map(|&i| a[i]).sum::<i64>();
    println!("{}", sum);
    println!("{}", operations.len());
    for &o in operations.iter() {
        println!("{}", o + 1);
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

