use std::io::*;
use std::str::FromStr;

const INF: i64 = 1e+14 as i64;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn select(moves: &mut Vec<usize>, aseq: &mut Vec<i64>, index: usize) {
    moves.push(index);
    // println!("{:?} {}", aseq, index);
    if index == 0 || index == aseq.len() - 1 {
        aseq.remove(index);
    } else {
        aseq[index] = aseq[index - 1] + aseq[index + 1];
        aseq.remove(index + 1);
        aseq.remove(index - 1);
    }
}

fn solve(n: usize, aseq: &Vec<i64>, offset: usize) -> (i64, Vec<usize>) {
    let mut ans = -INF;
    let mut moves = vec![];
    if n == 1 && offset == 1 { return (ans, moves); }
    {
        // all minus case
        let mut all_minus = true;
        let mut ans = -INF;
        let mut pos = 0;
        for i in 0..n {
            if i % 2 != offset { continue; }
            if aseq[i] > 0 { all_minus = false; }
            if ans < aseq[i] { 
                ans = aseq[i];
                pos = i;
            }
        }
        if all_minus {
            for i in (pos+1..n).rev() {
                moves.push(i);
            }
            for i in 0..pos {
                moves.push(i);
            }
            return (ans, moves);
        }
    }
    ans = 0;
    for i in 0..n {
        if i % 2 != offset { continue; }
        if aseq[i] > 0 { ans += aseq[i]; }
    }
    let mut aseq = aseq.clone();
    if offset == 1 {
        select(&mut moves, &mut aseq, 0)
    }
    if aseq.len() % 2 != 1 {
        let index = aseq.len() - 1;
        select(&mut moves, &mut aseq, index);
    }
    while *aseq.first().unwrap() < 0 {
        select(&mut moves, &mut aseq, 0);
        select(&mut moves, &mut aseq, 0);
    }
    while *aseq.last().unwrap() < 0 {
        let index = aseq.len() - 1;
        select(&mut moves, &mut aseq, index);
        select(&mut moves, &mut aseq, index - 1);
    }
    while aseq.len() != 1 {
        assert!(aseq.len() >= 3);
        if aseq[2] > 0 {
            select(&mut moves, &mut aseq, 1);
        } else {
            assert!(aseq.len() >= 5);
            select(&mut moves, &mut aseq, 2);
        }
    }
    return (ans, moves);
}

