fn main() {
    input!(n: usize, a: [i64; n]);
    if a.iter().all(|&x| x <= 0) {
        let i = a.iter().enumerate().max_by_key(|(_, &x)| x).unwrap().0;
        let steps: Vec<_> = (i + 1..n)
            .rev()
            .chain(std::iter::repeat(0).take(i))
            .collect();
        println!("{}", a[i]);
        println!("{}", steps.len());
        for x in steps {
            println!("{}", x + 1);
        }
    } else {
        let (ans, seq) = (0..2)
            .map(|parity| {
                let mut seq = vec![];
                let mut ans = 0;
                for (i, x) in a
                    .iter()
                    .copied()
                    .enumerate()
                    .filter(|&(i, x)| i % 2 == parity && 0 < x)
                {
                    ans += x;
                    seq.push(i);
                }
                (ans, seq)
            })
            .max()
            .unwrap();

        println!("{}", ans);
        let steps: Vec<_> = (*seq.last().unwrap() + 1..n)
            .rev()
            .chain(
                (0..seq.len() - 1)
                    .rev()
                    .map(|i| {
                        let l = seq[i];
                        let r = seq[i + 1];
                        assert!((r - l) % 2 == 0);
                        (l + 2..r)
                            .filter(move |&i| (i - l) % 2 == 0)
                            .rev()
                            .chain(std::iter::once(l + 1))
                    })
                    .flatten(),
            )
            .chain(std::iter::repeat(0).take(*seq.first().unwrap()))
            .collect();
        println!("{}", steps.len());
        for x in steps {
            println!("{}", x + 1);
        }
    }
}

