    let mut odd = 0;
    let mut even = 0;
    for i in 0..n {
        if i % 2 == 0 {
            even += cmp::max(0, a[i]);
        } else {
            odd += cmp::max(0, a[i]);
        }
    }

    let mut all_negative = true;
    for i in 0..n {
        if a[i] >= 0 {
            all_negative = false;
        }
    }
    if all_negative {
