        for i in 0..n {
            if a[max] < a[i] {
                max = i;
            }
        }

        println!("{}", a[max]);
        println!("{}", n - 1);
        let mut length = n;
        for i in 0..n {
            if i < max {
                println!("1");
                length -= 1;
            } else if i > max {
                println!("{}", length);
                length -= 1;
            }
        }
        return;
    }

    let mut ans = Vec::new();
    let mut started = false;
    let mut pos = 0;
    if odd > even {
        pos = 1;
        ans.push(1);
    }
    while pos < n {
        if a[pos] < 0 {
            if !started {
                ans.push(1);
                ans.push(1);
            } else {
                if pos >= n - 2 {
                    ans.push(3);
                    ans.push(2);
                } else {
                    ans.push(3);
                }
            }
        } else {
            if !started {
                started = true;
            } else {
                ans.push(2);
            }
        }
        if pos + 2 == n {
            ans.push(2);
        }
        pos += 2;
    }
    println!("{}", cmp::max(odd, even));
    println!("{}", ans.len());
    for an in &ans {
        println!("{}", *an);
    }

    let mut validation = VecDeque::new();
    for i in 0..n {
        validation.push_back(a[i]);
    }
    for i in &ans {
        let x = *i;
        assert!(x <= 3);
        if x == 1 {
            validation.pop_front();
        } else if x == 2 {
            let a1 = validation.pop_front().unwrap();
            let a2 = validation.pop_front().unwrap();
            if validation.is_empty() {
                validation.push_front(a1);
            } else {
                let a3 = validation.pop_front().unwrap();
                validation.push_front(a1 + a3);
            }
        } else if x == 3 {
            assert_eq!(validation.len(), 3);
            validation.pop_back();
        }
    }

    assert_eq!(validation.len(), 1);
    assert_eq!(validation.pop_front().unwrap(), cmp::max(odd, even));
}

