use std::cmp::{max, min};

fn read_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_owned()
}

fn reads<T>() -> Vec<T>
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    read_line()
        .split_whitespace()
        .map(|w| w.parse().unwrap())
        .collect()
}

fn main() {
    let n: usize = reads()[0];
    let a: Vec<i64> = reads();

    let (odd, odd_cnt, even, even_cnt) = {
        let mut odd = 0;
        let mut even = 0;
        let mut odd_cnt = 0;
        let mut even_cnt = 0;
        for i in 0..n {
            if i % 2 == 0 {
                even += max(0, a[i]);
                if a[i] > 0 {
                    even_cnt += 1;
                }
            } else {
                odd += max(0, a[i]);
                if a[i] > 0 {
                    odd_cnt += 1;
                }
            }
        }
        (odd, odd_cnt, even, even_cnt)
    };

    if even_cnt + odd_cnt == 0 {
        let m: i64 = *a.iter().max().unwrap();
        let mi = a.iter().position(|e| *e == m).unwrap();
        println!("{}", m);
        println!("{}", n - 1);
        for _ in 0..mi {
            println!("0");
        }
        for _ in mi + 1..n {
            println!("1");
        }
        return;
    }

    let best = max(odd, even);
    let mut seq = vec![];

    let mut l = if (odd, odd_cnt) > (even, even_cnt) {
        seq.push(0);
        1
    } else {
        0
    };
    let mut r = n - 1;

    while a[l] < 0 {
        seq.push(0);
        seq.push(0);
        l += 2;
    }

    while l < r && ((r - l) % 2 != 0 || a[r] < 0) {
        seq.push(r - l);
        r -= 1;
    }

    assert!(l <= r);
    assert!((r - l) % 2 == 0);

    while l < r {
        if a[l + 2] >= 0 {
            seq.push(1);
            l += 2;
        } else {
            assert!(r - l >= 4);
            seq.push(2);
            l += 2
        }
    }

    println!("{}", best);
    println!("{}", seq.len());
    for s in seq {
        println!("{}", s + 1);
    }
}

#[allow(unused_imports)]
use std::cmp::*;
#[allow(unused_imports)]
use std::collections::*;
use std::io::{Write, BufWriter};
// https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
