fn calc(mut a: Vec<(i64, usize)>) -> (i64, Vec<usize>) {
    a.sort();
    a.reverse();
    if a[0].0 < 0 {
        return (a[0].0, vec![a[0].1]);
    }
    let mut sum = 0;
    let mut idx = vec![];
    for a in a {
        if a.0 > 0 {
            sum += max(a.0, 0);
            idx.push(a.1);
        }
    }
    idx.sort();
    (sum, idx)
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [i64; n],
    }
    let mut ma = (i64::min_value(), vec![]);
    for i in 0..2 {
        let mut v = vec![];
        for j in 0..n {
            if j % 2 == i {
                v.push((a[j], j));
            }
        }
        ma = max(ma, calc(v));
    }
    puts!("{}\n", ma.0);
    let m = ma.1.len();
    let mut ops = vec![];
    for i in (ma.1[m - 1] + 1..n).rev() {
        ops.push(i + 1);
    }
    for i in (0..m - 1).rev() {
        let d = (ma.1[i + 1] - ma.1[i]) / 2;
        for _ in 0..d - 1 {
            ops.push(ma.1[i] + 3);
        }
        ops.push(ma.1[i] + 2);
    }
    for _ in 0..ma.1[0] {
        ops.push(1);
    }
    puts!("{}\n", ops.len());
    for o in ops {
        puts!("{}\n", o);
    }
}

