use std::cmp;
use std::collections::VecDeque;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.read();
    let a: Vec<i64> = (0..n).map(|_| sc.read()).collect();

    let mut odd = 0;
    let mut even = 0;
    for i in 0..n {
        if i % 2 == 0 {
            even += cmp::max(0, a[i]);
        } else {
            odd += cmp::max(0, a[i]);
        }
    }

    let mut all_negative = true;
    for i in 0..n {
        if a[i] >= 0 {
            all_negative = false;
        }
    }
    if all_negative {
        let mut max = 0;
        for i in 0..n {
            if a[max] < a[i] {
                max = i;
            }
        }

        println!("{}", a[max]);
        println!("{}", n - 1);
        let mut length = n;
        for i in 0..n {
            if i < max {
                println!("1");
                length -= 1;
            } else if i > max {
                println!("{}", length);
                length -= 1;
            }
        }
        return;
    }

    let mut ans = Vec::new();
    let mut q = VecDeque::from(a);

    if odd > even {
        q.pop_front();
        ans.push(1);
    }

    loop {
        let head = q.pop_front().unwrap();
        if head >= 0 {
            q.push_front(head);
            break;
        } else {
            ans.push(1);
            ans.push(1);
            q.pop_front();
        }
    }

    while q.len() >= 3 {
        let head = q.pop_front().unwrap();
        q.pop_front().unwrap();
        let next = q.pop_front().unwrap();
        if next >= 0 {
            ans.push(2);
            q.push_front(head + next);
        } else {
            ans.push(3);
            q.push_front(head);
        }
    }

    if q.len() == 2 {
        q.pop_back();
        ans.push(2);
    }

    println!("{}", q.pop_front().unwrap());
    assert!(q.is_empty());
    println!("{}", ans.len());
    for v in &ans {
        println!("{}", v);
    }
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

impl Scanner {
    fn new() -> Scanner {
        Scanner { ptr: 0, length: 0, buf: vec![0; 1024], small_cache: vec![0; 1024] }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool { b == b'\n' || b == b'\r' || b == b'\t' || b == b' ' }

    fn read<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug, {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)]).parse().unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

