    macro_rules! echo {
        ($iter :expr ) => {
            echo!($iter, "\n")
        };
        ($iter :expr ,$sep :expr ) => {
            let mut iter = $iter;
            if let Some(item) = iter.next() {
                print!("{}", item);
            }
            for item in iter {
                print!("{}{}", $sep, item);
            }
            println!();
        };
    }
    let n = scan!();
    let mut a = scan!([i64; n]);
    let mut ret = vec![false; n];
    let mx1 = (0..n)
        .step_by(2)
        .map(|i| if a[i] > 0 { a[i] } else { 0 })
        .sum::<i64>();
    let mx2 = (1..n)
        .step_by(2)
        .map(|i| if a[i] > 0 { a[i] } else { 0 })
        .sum::<i64>();
    let mut mx = max!(mx1, mx2);
    if a.iter().filter(|&&a| a < 0).count() == n {
        let i = (0..n).max_by_key(|&i| a[i]).unwrap();
        ret[i] = true;
        mx = a[i];
    } else if mx1 > mx2 {
        for i in (0..n).step_by(2) {
            if a[i] >= 0 {
                ret[i] = true;
            }
        }
    } else {
        for i in (1..n).step_by(2) {
            if a[i] >= 0 {
                ret[i] = true;
            }
        }
    }
    println!("{}", mx);
    let mut ans = vec![];
    while a.len() > 1 {
        if !ret[0] {
            ans.push(1);
            a.remove(0);
            ret.remove(0);
            continue;
        }
        if !ret[a.len() - 1] {
            ans.push(a.len());
            a.pop();
            ret.pop();
            continue;
        }
        for i in 1..a.len() - 1 {
            if !ret[i] && ret[i - 1] == ret[i + 1] {
                ans.push(i + 1);
                a.remove(i + 1);
                a.remove(i - 1);
                ret[i] = ret[i - 1];
                ret.remove(i + 1);
                ret.remove(i - 1);
                break;
            }
        }
    }
    println!("{}", ans.len());
    echo!(ans.iter());
}

