    }
    for width in (3..=n).step_by(2) {
        for l in 0..=n-width {
            let r = l + width - 1;
            let prefmaxs: Vec<(usize, i64)> = (0..width/2)
                .map(|li| (li, dp[l][l + 2*li].val))
                .lscan1(|&(acc_li, acc_val), (li, val)| {
                    if val <= acc_val {
                        (acc_li, acc_val)
                    } else {
                        (li, val)
                    }
                })
                .unwrap().collect();
            dbg!((l, width, &prefmaxs));
            dp[l][r] = (0..width/2).map(|ri| {
                let rval = dp[r - ri*2][r].val;
                let (li, lval) = prefmaxs[width/2 - (ri+1)];
                Dp {
                    val: rval + lval,
                    end1: l+1 + 2*li,
                    end2: r - 2*ri
                }
            }).max_by_key(|x| x.val).unwrap();
