        println!("{}", ans);
        let steps: Vec<_> = (*seq.last().unwrap() + 1..n)
            .rev()
            .chain(
                (0..seq.len() - 1)
                    .rev()
                    .map(|i| {
                        let l = seq[i];
                        let r = seq[i + 1];
                        assert!((r - l) % 2 == 0);
                        (l + 2..r)
                            .filter(|&i| i % 2 == 0)
                            .rev()
                            .chain(std::iter::once(l + 1))
                    })
                    .flatten(),
            )
            .chain(std::iter::repeat(0).take(*seq.first().unwrap()))
            .collect();
        println!("{}", steps.len());
        for x in steps {
            println!("{}", x + 1);
        }
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

#[allow(unused_imports)]
use std::cmp::{min, max};

fn main() {
    input!{
        n: usize,
        v: [i64; n]
    }
    let mut odd = 0;
    let mut even = 0;
    let mut fo = true;
    let mut fe = true;
    for i in 0..n {
        if v[i] < 0 {
            continue;
        }
        if i % 2 == 0 {
            fe = false;
            even += v[i];
        } else {
            fo = false;
            odd += v[i];
        }
    }
    if fo && fe {
        let ans = v.iter().cloned().max().unwrap();
        let mut c = 0;
        println!("{}", ans);
        println!("{}", n - 1);
        for &x in &v {
            if x >= ans {
                break;
            }
            println!("1");
            c += 1;
        }
        for i in c + 1..n {
            println!("{}", n - i + 1);
        }
    } else if fo || even >= odd {
        println!("{}", even);
        let mut ans = vec![];
        let mut c = 0;
        for i in (0..(n + 1) / 2).rev() {
            if v[2 * i] < 0 {
                ans.push(2 * i + 1);
                if 2 * i == 0 || 2 * i == n - 1 {
                    c += 1;
                } else {
                    c += 2;
                }
            }
        }
        for _ in 0..(n - c) / 2 {
            ans.push(2);
        }
        println!("{}", ans.len());
        for &a in &ans {
            println!("{}", a);
        }
    } else {
        println!("{}", odd);
        let mut ans = vec![];
        let mut c = 0;
        for i in (0..n / 2).rev() {
            if v[2 * i + 1] < 0 {
                ans.push(2 * i + 2);
                if 2 * i + 1 == n - 1 {
                    c += 1;
                } else {
                    c += 2;
                }
            }
        }
        ans.push(1);
        for _ in 0..(n - c - 1) / 2 {
            ans.push(2);
        }
        println!("{}", ans.len());
        for &a in &ans {
            println!("{}", a);
        }
    }
}
